#include <stdlib.h>
#include <string.h>

typedef struct {
    int timestamp;
    char type[20];
    void* data;
    size_t dataSize;
} TrafficEvent;

typedef struct {
    TrafficEvent* events;
    size_t capacity;
    size_t size;
} TrafficManager;

TrafficManager* createTrafficManager() {
    TrafficManager* manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    manager->events = NULL;
    manager->capacity = 0;
    manager->size = 0;
    return manager;
}

void freeTrafficManager(TrafficManager* manager) {
    for(size_t i = 0; i < manager->size; ++i) {
        free(manager->events[i].data);
    }
    free(manager->events);
    free(manager);
}

void addEvent(TrafficManager* manager, int timestamp, const char* type, void* data, size_t dataSize) {
    if (manager->size >= manager->capacity) {
        manager->capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        manager->events = (TrafficEvent*)realloc(manager->events, manager->capacity * sizeof(TrafficEvent));
    }
    TrafficEvent* event = &manager->events[manager->size++];
    event->timestamp = timestamp;
    strcpy(event->type, type);
    event->dataSize = dataSize;
    event->data = malloc(dataSize);
    memcpy(event->data, data, dataSize);
}

void updateEvent(TrafficManager* manager, int eventId, const char* newType, void* newData, size_t newSize) {
    if (eventId < 0 || eventId >= manager->size) return;
    free(manager->events[eventId].data);
    strcpy(manager->events[eventId].type, newType);
    manager->events[eventId].dataSize = newSize;
    manager->events[eventId].data = realloc(manager->events[eventId].data, newSize);
    memcpy(manager->events[eventId].data, newData, newSize);
}

TrafficEvent* getEventsByTimeRange(TrafficManager* manager, int startTimestamp, int endTimestamp) {
    TrafficManager* result = createTrafficManager();
    for(size_t i = 0; i < manager->size; ++i) {
        if (manager->events[i].timestamp >= startTimestamp && manager->events[i].timestamp <= endTimestamp) {
            addEvent(result, manager->events[i].timestamp, manager->events[i].type, manager->events[i].data, manager->events[i].dataSize);
        }
    }
    return result;
}
