#include <stdlib.h>
#include <stdio.h>

#define INITIAL_CAPACITY 10

typedef struct record {
    int value;
} Record;

typedef struct bucket {
    Record *record;
    struct bucket *next;
} Bucket;

typedef struct hash_table {
    Bucket **buckets;
    size_t capacity;
    size_t size;
} HashTable;

unsigned long hash_function(int key, size_t capacity) {
    return ((unsigned long)key * 2654435769U) % capacity;
}

HashTable* create_hash_table() {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    ht->buckets = (Bucket**)calloc(INITIAL_CAPACITY, sizeof(Bucket*));
    if (!ht->buckets) {
        free(ht);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    ht->capacity = INITIAL_CAPACITY;
    ht->size = 0;
    return ht;
}

void insert_record(HashTable *ht, int key, int value) {
    unsigned long index = hash_function(key, ht->capacity);
    Bucket *bucket = (Bucket*)malloc(sizeof(Bucket));
    if (!bucket) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    bucket->record = (Record*)malloc(sizeof(Record));
    if (!bucket->record) {
        free(bucket);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    bucket->record->value = value;
    bucket->next = ht->buckets[index];
    ht->buckets[index] = bucket;
    ht->size++;
}

int get_record(HashTable *ht, int key) {
    unsigned long index = hash_function(key, ht->capacity);
    Bucket *bucket = ht->buckets[index];
    while (bucket != NULL) {
        if (bucket->record->value == key)
            return bucket->record->value;
        bucket = bucket->next;
    }
    fprintf(stderr, "Key not found\n");
    exit(EXIT_FAILURE);
}

void resize_hash_table(HashTable *ht) {
    size_t new_capacity = ht->capacity * 2;
    Bucket **new_buckets = (Bucket**)calloc(new_capacity, sizeof(Bucket*));
    if (!new_buckets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < ht->capacity; i++) {
        Bucket *bucket = ht->buckets[i];
        while (bucket != NULL) {
            Bucket *next = bucket->next;
            unsigned long new_index = hash_function(bucket->record->value, new_capacity);
            bucket->next = new_buckets[new_index];
            new_buckets[new_index] = bucket;
            bucket = next;
        }
    }

    free(ht->buckets);
    ht->buckets = new_buckets;
    ht->capacity = new_capacity;
}

void update_record(HashTable *ht, int key, int value) {
    unsigned long index = hash_function(key, ht->capacity);
    Bucket *bucket = ht->buckets[index];
    while (bucket != NULL) {
        if (bucket->record->value == key) {
            bucket->record->value = value;
            return;
        }
        bucket = bucket->next;
    }
    fprintf(stderr, "Key not found\n");
    exit(EXIT_FAILURE);
}

void compact_hash_table(HashTable *ht) {
    // Placeholder for compaction logic
    printf("Compacting hash table...\n");
    resize_hash_table(ht);
}
