int process_file(const char *filename, Config config) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    long line_count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        line_count++;
    }
    fclose(file);

    if (config.count_chars) {
        // Count characters in the file
    }

    if (config.output_file) {
        FILE *output = fopen(config.output_file, "w");
        fprintf(output, "Number of lines: %ld\n", line_count);
        fclose(output);
    }

    return 0;
}

int main(int argc, char *argv[]) {
    Config config = parse_config(CONFIG_FILE);

    if (argc < 2) {
        print_usage();
        return 1;
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0 || strcmp(argv[i], "-m") == 0) {
            config.manual = 1;
        } else if (strcmp(argv[i], "-cs") == 0) {
            config.count_chars = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            config.output_file = 1;
            i++;
            config.output_file_name = argv[i];
        }
    }

    if (config.manual) {
        print_usage();
        return 0;
    }

    if (process_file(argv[argc - 1], config) != 0) {
        printf("Error processing file\n");
        return 1;
    }

    return 0;
}
