#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 10000

int* readIntegers(int *size) {
    int* array = (int*)malloc(MAX_SIZE * sizeof(int));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int num;
    *size = 0;
    while (scanf("%d", &num) != EOF && *size < MAX_SIZE) {
        array[(*size)++] = num;
    }

    if (*size == MAX_SIZE) {
        fprintf(stderr, "Too many integers. Maximum allowed size is %d\n", MAX_SIZE);
        exit(EXIT_FAILURE);
    }

    return array;
}

void printLargest(int* array, int size) {
    if (size <= 0) {
        printf("Array is empty\n");
        return;
    }

    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

int main() {
    int size;
    int* numbers = readIntegers(&size);
    printLargest(numbers, size);

    free(numbers); // Free dynamically allocated memory
    return 0;
}
```

This code snippet includes a function `readIntegers` to read integers from standard input and store them in a dynamically allocated array. It also handles the case where the number of integers exceeds the maximum allowed size of 10,000 by printing an error message and exiting gracefully.

The `printLargest` function traverses the array manually to find the largest integer without using any built-in functions for comparison or sorting.

In the `main` function, both functions are called, and then dynamically allocated memory is freed to avoid leaks.']

