#define MAX_LOG_FILES 10
#define THROTTLE_INTERVAL 1000000 // microseconds (1 second)
#define MAX_MESSAGES_PER_SECOND 5

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct {
    int file_descriptors[MAX_LOG_FILES];
    pthread_mutex_t lock;
    LogLevel max_log_level;
    int async_log_enabled;
    char *remote_server_url;
    int retry_attempts;
    int retry_interval;
} LogConfig;

void logCondition(LogConfig *config, LogLevel level, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Throttle logging based on time
    static struct timespec last_log_time = {0};
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);
    if (last_log_time.tv_sec != 0 && 
        current_time.tv_sec == last_log_time.tv_sec &&
        current_time.tv_nsec - last_log_time.tv_nsec < THROTTLE_INTERVAL) {
        va_end(args);
        return;
    }
    last_log_time = current_time;

    // Lock for thread safety
    pthread_mutex_lock(&config->lock);

    if (level <= config->max_log_level) {
        char buffer[256];
        vsnprintf(buffer, sizeof(buffer), format, args);

        // Log to local files
        for (int i = 0; i < MAX_LOG_FILES && config->file_descriptors[i] != -1; i++) {
            write(config->file_descriptors[i], buffer, strlen(buffer));
            write(config->file_descriptors[i], "\n", 1);
        }

        // Log to remote server asynchronously if enabled
        if (config->async_log_enabled) {
            // Simulate async logging with retry logic
            for (int attempt = 0; attempt < config->retry_attempts; attempt++) {
                int result = sendAsyncLog(buffer, config->remote_server_url);
                if (result == 0) break;
                usleep(config->retry_interval * 1000); // Convert to microseconds
            }
        }
    }

    pthread_mutex_unlock(&config->lock);

    va_end(args);
}

