import hashlib
import os
import time
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def calculate_hash(file_path, chunk_size=1024*1024, hash_algo='md5', retries=3):
    def read_file_in_chunks(f, chunk_size):
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            yield data

    for attempt in range(retries + 1):
        try:
            hasher = hashlib.new(hash_algo)
            file_size = os.path.getsize(file_path)
            chunks_read = 0
            with open(file_path, 'rb') as f:
                for chunk in read_file_in_chunks(f, chunk_size):
                    hasher.update(chunk)
                    chunks_read += 1
                    if file_size > 0:
                        progress = (chunks_read / (file_size // chunk_size)) * 100
                        logging.info(f"Hashing progress: {progress:.2f}%")
            return hasher.hexdigest()
        except IOError as e:
            logging.error(f"File I/O error: {e}. Retrying...")
            time.sleep(1)  # Wait before retrying
    raise Exception("Failed to hash file after multiple attempts.")

# Example usage:
try:
    hex_digest = calculate_hash('/path/to/your/file.txt')
    print(f"MD5 hash of the file: {hex_digest}")
except Exception as e:
    print(e)
