bool validate_oauth2_token_response(const char* json_str) {
    struct json_object *parsed_json = json_tokener_parse(json_str);
    if (!parsed_json) return false;

    struct json_object *access_token;
    if (json_object_object_get_ex(parsed_json, "access_token", &access_token)) {
        if (!json_object_is_type(access_token, json_type_string)) goto invalid;
    } else goto invalid;

    struct json_object *expires_in;
    if (json_object_object_get_ex(parsed_json, "expires_in", &expires_in)) {
        if (!json_object_is_type(expires_in, json_type_int) ||
            json_object_get_int(expires_in) <= 0) goto invalid;
    } else goto invalid;

    struct json_object *token_type;
    if (json_object_object_get_ex(parsed_json, "token_type", &token_type)) {
        if (!json_object_is_type(token_type, json_type_string) ||
            strcmp(json_object_get_string(token_type), "Bearer") != 0) goto invalid;
    } else goto invalid;

    struct json_object *refresh_token;
    json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token);

    json_object_put(parsed_json);
    return true;

invalid:
    json_object_put(parsed_json);
    return false;
}
