    private static final ExternalDatabaseService DB_SERVICE = new ExternalDatabaseService();

    public String generateReport(Pokemon pokemon) {
        if (CACHE.containsKey(pokemon.getName())) {
            return CACHE.get(pokemon.getName());
        }

        try {
            String type = PokemonTypeLibrary.getType(pokemon);
            String name = PokemonNameLibrary.getName(pokemon);

            StringBuilder reportBuilder = new StringBuilder();
            reportBuilder.append("Pokemon Name: ").append(name).append("\n");
            reportBuilder.append("Weaknesses:\n");
            reportBuilder.append(getWeaknesses(type)).append("\n");
            reportBuilder.append("Resistances:\n");
            reportBuilder.append(getResistances(type)).append("\n");

            String evolutionChain = DB_SERVICE.getEvolutionChain(pokemon);
            if (evolutionChain != null) {
                reportBuilder.append("Evolution Chain: ").append(evolutionChain).append("\n");
            }

            CACHE.put(name, reportBuilder.toString());
            return reportBuilder.toString();
        } catch (ExternalServiceException e) {
            return "Failed to fetch data from external service. Please try again later.";
        }
    }

    private String getWeaknesses(String type) {
        switch (type) {
            case "Grass":
                return "Fire, Ice, Flying";
            case "Fire":
                return "Water, Ground, Rock";
            // Add cases for other types
            default:
                return "None";
        }
    }

