Algorithm **get_available_algorithms(size_t *count) {
    // Simulate dynamic loading of algorithms
    static Algorithm algorithms[] = {
        {"SHA-256", NULL, 32, 64, 0},
        {"AES-256-CBC", NULL, 32, 128, 1}
    };
    *count = sizeof(algorithms) / sizeof(algorithms[0]);
    Algorithm **list = malloc(*count * sizeof(Algorithm *));
    if (list == NULL) {
        return NULL; // Handle memory allocation failure
    }
    for (size_t i = 0; i < *count; ++i) {
        list[i] = &algorithms[i];
        memset(list[i], 0, sizeof(Algorithm)); // Ensure proper initialization
    }
    return list;
}

// Example usage:
int main() {
    size_t count;
    Algorithm **algorithms = get_available_algorithms(&count);
    if (algorithms == NULL) {
        // Handle error
    }
    for (size_t i = 0; i < count; ++i) {
        printf("Algorithm: %s, Key Size: %zu\n", algorithms[i]->name, algorithms[i]->key_size);
    }
    free(algorithms); // Free the dynamically allocated list
    return 0;
}
