['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct SemaphorePool {
    int *semas;
    int num_semas;
    int max_active;
    pthread_mutex_t mutex;
} SemaphorePool;

SemaphorePool* create_semaphore_pool(int num_semas, int init_value, int max_active) {
    SemaphorePool *pool = (SemaphorePool*)malloc(sizeof(SemaphorePool));
    pool->semas = (int*)calloc(num_semas, sizeof(int));
    for (int i = 0; i < num_semas; i++) {
        pool->semas[i] = init_value;
    }
    pool->num_semas = num_semas;
    pool->max_active = max_active;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_semaphore_pool(SemaphorePool *pool) {
    free(pool->semas);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

int acquire_semaphore(SemaphorePool *pool) {
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->num_semas; i++) {
        if (pool->semas[i] > 0) {
            pool->semas[i]--;
            pthread_mutex_unlock(&pool->mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return -1; // No available semaphores
}

void release_semaphore(SemaphorePool *pool, int index) {
    pthread_mutex_lock(&pool->mutex);
    if (index >= 0 && index < pool->num_semas) {
        pool->semas[index]++;
    }
    pthread_mutex_unlock(&pool->mutex);
}
