#include <vector>
#include <algorithm>

void insertUniqueAfter(std::vector<int>& vec, int find, int insert) {
    auto it = std::find(vec.begin(), vec.end(), find);
    if (it != vec.end()) {
        vec.erase(it + 1, std::unique(it + 1, vec.end()));
        vec.insert(it + 1, insert);
    } else {
        vec.erase(std::unique(vec.begin(), vec.end()), vec.end());
        vec.push_back(insert);
    }
}
