#include <iostream>
#include <fstream>
#include <string>
#include <memory>

namespace LoggingSystem {

    enum class LogLevel { DEBUG, INFO, WARNING, ERROR };

    class Logger {
    public:
        static void Initialize(LogLevel level, const std::string& file = "") {
            logLevel = level;
            if (!file.empty()) {
                outputStream = std::make_unique<std::ofstream>(file);
            }
        }

        static void Log(LogLevel level, const std::string& message) {
            if (level >= logLevel) {
                std::string logMessage = "[" + getLogPrefix(level) + "] " + message;
                std::cout << logMessage << std::endl;
                if (outputStream && outputStream->is_open()) {
                    *outputStream << logMessage << std::endl;
                }
            }
        }

    private:
        static LogLevel logLevel;
        static std::unique_ptr<std::ofstream> outputStream;

        Logger() = delete;
        ~Logger() = default;

        static std::string getLogPrefix(LogLevel level) {
            switch (level) {
                case LogLevel::DEBUG: return "DEBUG";
                case LogLevel::INFO: return "INFO";
                case LogLevel::WARNING: return "WARNING";
                case LogLevel::ERROR: return "ERROR";
                default: return "UNKNOWN";
            }
        }
    };

    LogLevel Logger::logLevel = LogLevel::DEBUG;
    std::unique_ptr<std::ofstream> Logger::outputStream;

}

int main() {
    LoggingSystem::Logger::Initialize(LoggingSystem::LogLevel::INFO, "app.log");
    LoggingSystem::Logger::Log(LoggingSystem::LogLevel::DEBUG, "This is a debug message.");
    LoggingSystem::Logger::Log(LoggingSystem::LogLevel::INFO, "This is an info message.");
    LoggingSystem::Logger::Log(LoggingSystem::LogLevel::WARNING, "This is a warning message.");
    LoggingSystem::Logger::Log(LoggingSystem::LogLevel::ERROR, "This is an error message.");
    return 0;
}
