using System;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;

public class ConfigManager
{
    private static readonly Dictionary<string, object> _configCache = new Dictionary<string, object>();
    private static string _configFilePath = "game_config.json";

    public static void InitializeConfig()
    {
        if (File.Exists(_configFilePath))
        {
            LoadConfig();
        }
        else
        {
            throw new FileNotFoundException("Configuration file not found.");
        }

        // Watch for changes in the config file and reload it automatically
        FileSystemWatcher watcher = new FileSystemWatcher(Path.GetDirectoryName(_configFilePath), Path.GetFileName(_configFilePath));
        watcher.NotifyFilter = NotifyFilters.LastWrite;
        watcher.Changed += OnConfigFileChanged;
        watcher.EnableRaisingEvents = true;
    }

    private static void LoadConfig()
    {
        string configContent = File.ReadAllText(_configFilePath);
        var configData = JsonConvert.DeserializeObject<Dictionary<string, object>>(configContent);

        foreach (var item in configData)
        {
            _configCache[item.Key] = item.Value;
        }
    }

    private static void OnConfigFileChanged(object source, FileSystemEventArgs e)
    {
        LoadConfig();
    }

    public static T GetConfig<T>(string key)
    {
        if (_configCache.ContainsKey(key))
        {
            return (T)_configCache[key];
        }
        else
        {
            throw new KeyNotFoundException($"Configuration key '{key}' not found.");
        }
    }
}

