        _environmentalLightingLevel = ConfigManager.GetConfig<int>("EnvironmentalLightingLevel");
        _enemySpawnPositions = ConfigManager.GetConfig<List<Vector3>>("EnemySpawnPositions");

        InitializeGameEnvironment();
    }

