    {
        // Initialize game environment with the loaded configuration
        Console.WriteLine($"Player Movement Sensitivity: {_playerMovementSensitivity}");
        Console.WriteLine($"Environmental Lighting Level: {_environmentalLightingLevel}");
        foreach (var pos in _enemySpawnPositions)
        {
            Console.WriteLine($"Enemy Spawn Position: {pos}");
        }
    }
}

// Example usage
public class Program
{
