        string testJson = "{\"PlayerMovementSensitivity\": 1.5, \"EnvironmentalLightingLevel\": 80, \"EnemySpawnPositions\": [[10, 20, 30], [40, 50, 60]]}";
        File.WriteAllText(ConfigManager._configFilePath, testJson);
    }
}
