from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///resources.db'
db = SQLAlchemy(app)

class Resource(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), nullable=False)
    attributes = db.Column(db.JSON, nullable=True)

@app.route('/resource', methods=['POST'])
def create_resource():
    data = request.get_json()
    new_resource = Resource(name=data['name'], attributes=data.get('attributes'))
    db.session.add(new_resource)
    db.session.commit()
    return jsonify({'message': 'Resource created successfully'}), 201

@app.route('/resource/<int:id>', methods=['PUT'])
def update_resource(id):
    data = request.get_json()
    resource = Resource.query.get_or_404(id)
    resource.name = data['name']
    resource.attributes = data.get('attributes')
    db.session.commit()
    return jsonify({'message': 'Resource updated successfully'})

@app.route('/resource/<int:id>', methods=['DELETE'])
def delete_resource(id):
    resource = Resource.query.get_or_404(id)
    db.session.delete(resource)
    db.session.commit()
    return jsonify({'message': 'Resource deleted successfully'})

@app.route('/resources', methods=['POST'])
def bulk_update_resources():
    data = request.get_json()
    for item in data:
        resource = Resource.query.filter_by(name=item['name']).first()
        if resource:
            resource.attributes = item.get('attributes')
            db.session.commit()
    return jsonify({'message': 'Resources updated successfully'})

@app.route('/resources', methods=['GET'])
def get_resources_summary():
    summary = []
    for resource in Resource.query.all():
        summary.append({
            'id': resource.id,
            'name': resource.name,
            'attributes': resource.attributes
        })
    return jsonify(summary)

if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
