using System;
using System.Collections.Generic;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    public static List<XElement> FindElements(string xml, string xpathQuery, Dictionary<string, string> namespaces = null)
    {
        if (string.IsNullOrEmpty(xml))
            throw new ArgumentException("The XML string cannot be null or empty.", nameof(xml));

        using (XmlReader reader = XmlReader.Create(new StringReader(xml)))
        {
            XPathDocument document;
            try
            {
                document = new XPathDocument(reader);
            }
            catch (Exception ex)
            {
                throw new InvalidOperationException("Failed to parse the XML document.", ex);
            }

            XPathNavigator navigator = document.CreateNavigator();
            if (namespaces != null)
            {
                foreach (var kvp in namespaces)
                    navigator.SetNamespace(kvp.Key, kvp.Value);
            }

            try
            {
                XPathNodeIterator nodes = navigator.Select(xpathQuery);
                List<XElement> result = new List<XElement>();
                while (nodes.MoveNext())
                {
                    if (!nodes.Current.IsElement)
                        continue;

                    result.Add((XElement)nodes.Current.Clone());
                }
                return result;
            }
            catch (Exception ex)
            {
                throw new InvalidOperationException("Failed to evaluate the XPath query.", ex);
            }
        }
    }
}
