import java.util.Arrays;

public class MD5Hasher {

    public static String getMD5(String input) {
        if (input == null || input.isEmpty()) {
            return "Input cannot be null or empty";
        }

        // Truncate the input to 2048 characters
        input = input.substring(0, Math.min(input.length(), 2048));

        // Remove non-alphanumeric characters except spaces
        StringBuilder filteredInput = new StringBuilder();
        for (char c : input.toCharArray()) {
            if (Character.isLetterOrDigit(c) || c == ' ') {
                filteredInput.append(c);
            }
        }

        // Convert to lowercase
        String lowerCaseInput = filteredInput.toString().toLowerCase();

        // Initialize MD5 hash array
        int[] hash = new int[4];

        // Implement the MD5 hashing process (simplified version)
        for (char c : lowerCaseInput.toCharArray()) {
            int asciiValue = (int) c;
            for (int i = 0; i < 4; i++) {
                hash[i] += asciiValue * (i + 1);
                if (hash[i] > 255) {
                    hash[i] %= 256;
                }
            }
        }

        // Convert the integer array to a hexadecimal string
        StringBuilder hexHash = new StringBuilder();
        for (int h : hash) {
            String hex = Integer.toHexString(h);
            if (hex.length() == 1) {
                hexHash.append('0');
            }
            hexHash.append(hex);
        }

        return hexHash.toString();
    }

    public static void main(String[] args) {
        try {
            System.out.println(getMD5("Hello, World!")); // Example usage
        } catch (Exception e) {
            System.err.println(e.getMessage());
        }
    }
}
