            options.Lockout.MaxFailedAccessAttempts = 5;
        });

        // Configure rate limiting
        services.AddRateLimiting(options =>
        {
            options.GlobalLimiter = PartitionedRateLimiter.Create<ApplicationUser, string>(context => context.User.Id,
                partitionKey => RateLimitPartition.GetFixedWindowLimiter(partitionKey, _ => new FixedWindowRateLimiterOptions
                {
                    AutoReplenishment = true,
                    QueueLimit = 100,
                    Window = TimeSpan.FromSeconds(60),
                    Limit = 5
                }));
        });

        // Configure account recovery with email verification
        services.Configure<IdentityOptions>(options =>
        {
            options.SignIn.RequireConfirmedEmail = true;
        });

        // Custom error handling for validation failures
        services.AddScoped<IValidationErrorHandler, ValidationErrorHandler>();

        // Logging and monitoring
        services.AddLogging(loggingBuilder =>
        {
            loggingBuilder.AddEventLog();
        });

        // Scalability considerations
        services.AddDistributedMemoryCache();

        // Dependency injection for configuration management
        services.AddSingleton<ICustomConfigManager, CustomConfigManager>();

        // Performance optimization with asynchronous methods
        services.AddScoped<IAsyncPasswordValidator<ApplicationUser>, AsyncPasswordValidator>();
    }
}

