["```javascript
import Worker from 'worker_threads';

function runTests(label, f, environment) {
  const tests = [];
  let currentTestIndex = 0;
  const totalWorkers = Math.min(4, navigator.hardwareConcurrency || 1); // Use up to 4 workers or hardware concurrency
  let runningWorkers = 0;

  function nextTest() {
    while (runningWorkers < totalWorkers && currentTestIndex < tests.length) {
      const test = tests[currentTestIndex++];
      runningWorkers++;
      const worker = new Worker(new URL('./worker.js', import.meta.url), { type: 'module' });
      worker.postMessage({ label, test, environment });
      worker.on('message', (result) => {
        handleResult(result);
      });
      worker.on('error', (error) => {
        handleError(error);
      });
      worker.on('exit', () => {
        runningWorkers--;
        nextTest();
      });
    }
  }

  function handleResult(result) {
    console.log(`${label} - ${result.name}: ${result.status}`);
    if (result.error) {
      console.error(result.error);
    }
    nextTest();
  }

  function handleError(error) {
    console.error(`Error running test: ${error.message}`);
    nextTest();
  }

  f((name, testFunction) => {
    tests.push({ name, testFunction });
  });

  nextTest();
}

// Example usage:
runTests('Math Module', (it) => {
  it('should add two numbers correctly', () => {
    const result = Math.add(2, 3);
    return { name: 'add_two_numbers', status: result === 5 ? 'pass' : 'fail' };
  });

  it('should subtract two numbers correctly', () => {
    const result = Math.subtract(5, 3);
    return { name: 'subtract_two_numbers', status: result === 2 ? 'pass' : 'fail' };
  });
}, { skipSlowTests: process.env.NODE_ENV === 'production' });
