// Define regular expressions for Bible book names
const oldTestamentBooksRegex = /(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk/Zephaniah/Haggai/Zechariah/Malachi)/gi;
const newTestamentBooksRegex = /(?:Matthew|Mark|Luke|John|Acts|Romans|1 Corinthians|2 Corinthians|Galatians|Ephesians|Philippians|Colossians|1 Thessalonians|2 Thessalonians|1 Timothy|2 Timothy|Titus|Philemon|Hebrews|James|1 Peter|2 Peter|1 John|2 John|3 John|Jude)/gi;

async function extractAndProcessBooks(text) {
    // Initialize counters
    const bookCounts = {};

    // Search for Old Testament books and count occurrences
    let match;
    while ((match = oldTestamentBooksRegex.exec(text)) !== null) {
        if (bookCounts[match[0]]) {
            bookCounts[match[0]]++;
        } else {
            bookCounts[match[0]] = 1;
        }
    }

    // Search for New Testament books and count occurrences
    while ((match = newTestamentBooksRegex.exec(text)) !== null) {
        if (bookCounts[match[0]]) {
            bookCounts[match[0]]++;
        } else {
            bookCounts[match[0]] = 1;
        }
    }

    // Fetch additional metadata for each book
    try {
        const promises = Object.keys(bookCounts).map(async (bookName) => {
            const response = await fetch(`https://api.example.com/books/${encodeURIComponent(bookName)}`);
            if (!response.ok) {
                throw new Error('Network response was not ok');
            }
            const bookMetadata = await response.json();
            return { name: bookName, ...bookMetadata };
        });

        const results = await Promise.all(promises);
        console.log(results);
    } catch (error) {
        console.error('Error fetching book metadata:', error);
    }

    return bookCounts;
}

// Example usage
const inputText = "In the beginning, God created the heavens and the earth. He spoke and it was done! This is a quote from Matthew 28:18.";
extractAndProcessBooks(inputText).then(console.log);
```

