    this.paused = true;
  };

  this.resume = () => {
    this.paused = false;
    this.processBuffer();
  };

  this.addData = (data) => {
    if (!this.paused) {
      this.buffer.push(data);
    }
  };

  this.processBuffer = () => {
    while (!this.paused && this.buffer.length > 0) {
      const newData = this.buffer.shift();
      // Process newData to add vertices and edges to the graph
