['```javascript
const { Buffer } = require('buffer');

function copyBufferedData(dataChunks, offset, length) {
  const totalLength = dataChunks.reduce((acc, chunk) => acc + chunk.length, 0);

  if (offset + length > totalLength) {
    throw new Error("Requested range exceeds available data");
  }

  let copiedBytes = 0;
  const resultBuffer = Buffer.alloc(length);

  for (const chunk of dataChunks) {
    if (copiedBytes >= offset && copiedBytes < offset + length) {
      const start = Math.max(0, offset - copiedBytes);
      const end = Math.min(chunk.length, offset + length - copiedBytes);

      resultBuffer.write(chunk.slice(start, end).toString('utf8'), copiedBytes - offset, 'utf8');
    }

    copiedBytes += chunk.length;
  }

  return resultBuffer;
}

// Example usage:
const dataChunks = [
  Buffer.from("Hello"),
  Buffer.from(" "),
  Buffer.from("World!"),
];
const offset = 5;
const length = 4;
const copiedData = copyBufferedData(dataChunks, offset, length);
console.log(copiedData.toString('utf8')); // Output: " Wor"

// Tracking successful and failed operations
let successfulCopies = 0;
let failedCopies = 0;

try {
  const data = copyBufferedData(dataChunks, offset, length);
  successfulCopies++;
} catch (error) {
  failedCopies++;
}

console.log(`Successful copies: ${successfulCopies}`); // Output: Successful copies: 1
console.log(`Failed copies: ${failedCopies}`); // Output: Failed copies: 0
```']

['```javascript
function traverseDOM(element, selector, filterFunc, maxDepth = Infinity) {
  if (maxDepth <= 0) return [];

  const matches = [];
  if (element.matches(selector)) {
    if (filterFunc(element)) {
      matches.push(element);
    }
  }

  for (let i = 0; i < element.children.length; i++) {
    matches.push(...traverseDOM(element.children[i], selector, filterFunc, maxDepth - 1));
  }

  return matches;
}
