['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;

public class ConnectionPool {
    private Selector selector;
    private Map<SocketChannel, ByteBuffer> channels = new HashMap<>();

    public ConnectionPool() throws IOException {
        selector = Selector.open();
    }

    public void addConnection(InetSocketAddress address) throws IOException {
        SocketChannel channel = SocketChannel.open(address);
        channel.configureBlocking(false);
        channel.register(selector, SelectionKey.OP_CONNECT);
        channels.put(channel, ByteBuffer.allocate(1024));
    }

    public void connect() throws IOException {
        while (selector.select() > 0) {
            Iterator<SelectionKey> keys = selector.selectedKeys().iterator();
            while (keys.hasNext()) {
                SelectionKey key = keys.next();
                if (key.isConnectable()) {
                    SocketChannel channel = (SocketChannel) key.channel();
                    try {
                        channel.finishConnect();
                        System.out.println("Connected to " + channel.getRemoteAddress());
                        channel.register(selector, SelectionKey.OP_READ);
                    } catch (IOException e) {
                        channel.close();
                    }
                }
                if (key.isReadable()) {
                    SocketChannel channel = (SocketChannel) key.channel();
                    ByteBuffer buffer = channels.get(channel);
                    int bytesRead = channel.read(buffer);
                    if (bytesRead == -1) {
                        channel.close();
                    } else {
                        // Process the data in the buffer
                        processBuffer(buffer);
                    }
                }
                keys.remove();
            }
        }
    }

    private void processBuffer(ByteBuffer buffer) {
        buffer.flip();
        while (buffer.hasRemaining()) {
            System.out.print((char) buffer.get());
        }
        buffer.clear();
    }

    public void close() throws IOException {
        selector.close();
        for (SocketChannel channel : channels.keySet()) {
            channel.close();
        }
    }

    public static void main(String[] args) {
        try {
            ConnectionPool pool = new ConnectionPool();
            pool.addConnection(new InetSocketAddress("example.com", 80));
            pool.connect();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
