['```go
package main

import (
	"encoding/base64"
	"errors"
	"net/http"
	"sync"
	"time"

	"github.com/dgrijalva/jwt-go"
)

var (
	sessionCache = map[string]UserSession{}
	sessionLock  sync.RWMutex
)

type UserSession struct {
	Token      string
	UserID     string
	Roles      []string
	Permissions []string
	ExpiresAt  time.Time
}

func handleSession(w http.ResponseWriter, r *http.Request) {
	sessionToken := r.Header.Get("Authorization")
	if sessionToken == "" {
		http.Error(w, "No session token provided", http.StatusUnauthorized)
		return
	}

	sessionLock.Lock()
	session, found := sessionCache[sessionToken]
	sessionLock.Unlock()

	if !found || session.ExpiresAt.Before(time.Now()) {
		delete(sessionCache, sessionToken)
		setNewSessionCookie(w, r)
		http.Error(w, "Invalid or expired session", http.StatusUnauthorized)
		return
	}

	var jwtClaims Claims
	_, err := jwt.ParseWithClaims(session.Token, &jwtClaims, func(token *jwt.Token) (interface{}, error) {
		// Use the secret key to verify the token signature
		return []byte("your-secret-key"), nil
	})

	if err != nil || !jwtClaims.Valid {
		delete(sessionCache, sessionToken)
		setNewSessionCookie(w, r)
		http.Error(w, "Invalid JWT", http.StatusUnauthorized)
		return
	}

	session.Roles = jwtClaims.Roles
	session.Permissions = jwtClaims.Permissions
	sessionCache[sessionToken] = session

	// Proceed with handling the request based on user roles and permissions
	w.Write([]byte("Session is valid"))
}

func setNewSessionCookie(w http.ResponseWriter, r *http.Request) {
	userID := "user123" // Example user ID
	expiration := time.Now().Add(24 * time.Hour)
	sessionToken := generateSessionToken(userID, expiration)

	http.SetCookie(w, &http.Cookie{
		Name:     "session_token",
		Value:    sessionToken,
		Path:     "/",
		Expires:  expiration,
		HttpOnly: true,
		Secure:   r.URL.Scheme == "https",
	})

	sessionLock.Lock()
	sessionCache[sessionToken] = UserSession{
		Token:      sessionToken,
		UserID:     userID,
		Roles:      []string{"user"},
		Permissions: []string{},
		ExpiresAt:  expiration,
	}
	sessionLock.Unlock()
}

func generateSessionToken(userID string, expiration time.Time) string {
	claims := Claims{
		UserID:    userID,
		Roles:     []string{"user"},
		Permissions: []string{},
		StandardClaims: jwt.StandardClaims{
			ExpiresAt: expiration.Unix(),
		},
	}

	token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
	sessionToken, _ := token.SignedString([]byte("your-secret-key"))
	return base64.StdEncoding.EncodeToString([]byte(sessionToken))
}

type Claims struct {
	UserID     string   `json:"user_id"`
	Roles      []string `json:"roles"`
	Permissions []string `json:"permissions"`
	jwt.StandardClaims
}
```']

