// Configure the application using a multi-stage configuration process
$config = [];
$initialConfigFile = __DIR__ . '/config/config.yaml';
if (file_exists($initialConfigFile)) {
    $yaml = new Symfony\Component\Yaml\Parser();
    $initialConfig = $yaml->parse(file_get_contents($initialConfigFile));
    if ($initialConfig === null) {
        throw new Exception('Failed to parse initial configuration');
    }
    $config = $initialConfig;
}

$schemaFile = __DIR__ . '/config/schema.json';
if (file_exists($schemaFile)) {
    $schema = json_decode(file_get_contents($schemaFile), true);
    if ($schema === null) {
        throw new Exception('Failed to parse schema');
    }
    // Validate the configuration against the schema
    $validator = new Symfony\Component\Validator\Validation();
    $violations = $validator->validate($config, $schema);
    if (count($violations) > 0) {
        throw new Exception('Configuration validation failed: ' . implode(', ', array_map(function ($violation) { return $violation->getMessage(); }, $violations)));
    }
}

// Allow overriding default settings via command-line arguments or environment variables
$commandLineArgs = getopt('', ['env::']);
$currentEnv = isset($commandLineArgs['env']) ? $commandLineArgs['env'] : $_ENV['APP_ENV'] ?? 'development';
if (in_array($currentEnv, ['development', 'staging', 'production'])) {
