    if (file_exists($overrideConfigFile)) {
        $overrideConfig = yaml_parse_file($overrideConfigFile);
        if ($overrideConfig !== null) {
            $config = array_merge($config, $overrideConfig);
        }
    }
}

// Implement a caching mechanism to store configuration data in memory
$configCache = [];
function getConfigFromCache() {
    global $configCache;
    return $configCache ?: null;
}
function setConfigInCache($config) {
    global $configCache;
    $configCache = $config;
}
if (($cachedConfig = getConfigFromCache()) !== null) {
    $config = $cachedConfig;
} else {
    // Store configuration data in memory and cache it
    setConfigInCache($config);
}

// Logs all configuration changes and errors to a central logging service
$logger = new Monolog\Logger('app');
$handler = new Monolog\Handler\RotatingFileHandler(__DIR__ . '/logs/app.log', 30, Monolog\Logger::DEBUG, true, 0644);
$compressor = new Monolog\Processor\DateFormatterProcessor();
$logger->pushHandler($handler)->pushProcessor($compressor);

// Ensure the script can be executed in a production environment with minimal impact
ignore_user_abort(true);
set_time_limit(0);

// Handle multiple environments by loading different configuration files automatically
if (!isset($_ENV['APP_ENV'])) {
    $_ENV['APP_ENV'] = get_current_environment();
}
function get_current_environment() {
    $host = $_SERVER['HTTP_HOST'];
    if (strpos($host, 'staging.') === 0) {
        return 'staging';
    } elseif (strpos($host, 'production.') === 0) {
        return 'production';
    }
    return 'development';
}
