function updateClinicStatus($clinicId, $newStatus) {
    // Establish a connection to the database
    $conn = new mysqli("localhost", "username", "password", "database");

    // Check for connection errors
    if ($conn->connect_error) {
        logError("Database connection failed: " . $conn->connect_error);
        return false;
    }

    // Use a prepared statement to prevent SQL injection and ensure atomic updates
    $stmt = $conn->prepare("UPDATE clinics SET status=?, last_modified_ip=?, last_modified_date=? WHERE clinic_id=? AND status<>?");

    // Get the client's IP address and current date time
    $ipAddress = $_SERVER['REMOTE_ADDR'];
    $dateTime = date('Y-m-d H:i:s');

    // Bind parameters to the prepared statement
    $stmt->bind_param("sssss", $newStatus, $ipAddress, $dateTime, $clinicId, $newStatus);

    // Execute the prepared statement
    if ($stmt->execute()) {
        $stmt->close();
        $conn->close();
        return true;
    } else {
        logError("Failed to update clinic status: " . $stmt->error);
        $stmt->close();
        $conn->close();
        return false;
    }
}

