#include <stdlib.h>

typedef struct State {
    int id;
    struct State* next;
} State;

int construct_sublist(State** states, int num_states, State* fsa, int last_state) {
    if (states == NULL || *states == NULL || fsa == NULL || last_state >= num_states) {
        return -1; // Error code for invalid input
    }

    State* sublist = NULL;
    State* current = fsa;

    while (current != NULL && current->id <= last_state) {
        State* new_state = malloc(sizeof(State));
        if (new_state == NULL) {
            free_sublist(sublist); // Clean up any allocated states
            return -2; // Error code for insufficient memory
        }

        new_state->id = current->id;
        new_state->next = sublist;
        sublist = new_state;

        current = current->next;
    }

    if (*states != NULL) {
        (*states)->next = sublist;
    } else {
        *states = sublist; // Update the head of the list if necessary
    }

    return 0; // Success
}

void free_sublist(State* states) {
    while (states != NULL) {
        State* temp = states;
        states = states->next;
        free(temp);
    }
}
