#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000
#define BATCH_THRESHOLD 10
#define SLIDING_WINDOW_SECONDS 3

typedef struct {
    int id;
    time_t timestamp;
    double value;
    char type;
    int frequency;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int count;
    time_t start_time;
} TransactionWindow;

double calculate_weighted_sum(Transaction *transaction, TransactionWindow *window) {
    // Custom formula for weighted sum
    return transaction->value * transaction->frequency;
}

int process_transactions(Transaction **transactions, int count, double *max_sum, int *max_id) {
    if (count == 0) {
        *max_sum = 0.0;
        *max_id = -1;
        return 0;
    }

    TransactionWindow window;
    time_t current_time = time(NULL);
    int processed_count = 0;

    // Filter and populate the sliding window
    for (int i = 0; i < count && processed_count < BATCH_THRESHOLD; i++) {
        if ((current_time - transactions[i]->timestamp) <= SLIDING_WINDOW_SECONDS) {
            window.transactions[window.count++] = *transactions[i];
            processed_count++;
        }
    }

    // Calculate weighted sums and find the maximum
    double sum = 0.0;
    int id = -1;
    for (int i = 0; i < window.count; i++) {
        double current_sum = calculate_weighted_sum(&window.transactions[i], &window);
        if (current_sum > sum) {
            sum = current_sum;
            id = window.transactions[i].id;
        }
    }

    *max_sum = sum;
    *max_id = id;

    return processed_count;
}

int main() {
    // Example usage
    Transaction transactions[MAX_TRANSACTIONS];
    int count = 5;
    double max_sum;
    int max_id;

    // Populate the transaction array with example data
    for (int i = 0; i < count; i++) {
        transactions[i].id = i + 1;
        transactions[i].timestamp = time(NULL) - i;
        transactions[i].value = rand() % 100;
        transactions[i].type = 'A' + (i % 3);
        transactions[i].frequency = i + 1;
    }

    process_transactions(transactions, count, &max_sum, &max_id);

    printf("Max Weighted Sum: %.2f\n", max_sum);
    printf("Transaction ID: %d\n", max_id);

    return 0;
}
```

