#define ATTACK_ONE 1
#define ATTACK_TWO 2

struct PlayerAction {
    std::chrono::steady_clock::time_point timestamp;
    int attackType;
};

std::queue<PlayerAction> actionQueue;
std::mutex queueMutex;
std::condition_variable cv;
int lastAttackTime = 0;

void randomAttackSelector() {
    std::unique_lock<std::mutex> lock(queueMutex);
    cv.wait(lock, []{ return !actionQueue.empty(); });

    PlayerAction currentAction = actionQueue.front();
    actionQueue.pop();

    while (currentAction.timestamp < std::chrono::steady_clock::now() - std::chrono::seconds(9)) {
        if (!actionQueue.empty()) {
            currentAction = actionQueue.front();
            actionQueue.pop();
        } else {
            break;
        }
    }

    int selectedAttack = currentAction.attackType == ATTACK_ONE ? ATTACK_TWO : ATTACK_ONE;
    std::cout << "Selected Attack: " << selectedAttack << std::endl;

    lastAttackTime = std::chrono::steady_clock::now().time_since_epoch().count();
}

void simulatePlayerActions() {
    for (int i = 0; i < 10; ++i) {
        int attackType = rand() % 2 == 0 ? ATTACK_ONE : ATTACK_TWO;
        PlayerAction action{std::chrono::steady_clock::now(), attackType};
        std::lock_guard<std::mutex> lock(queueMutex);
        actionQueue.push(action);
        cv.notify_one();
    }
}

int main() {
    std::thread playerActionsThread(simulatePlayerActions);

    for (int i = 0; i < 10; ++i) {
        randomAttackSelector();
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    playerActionsThread.join();
    return 0;
}
