public class RandomValueGenerator
{
    private readonly ConcurrentDictionary<string, (float min, float max, bool inclusive)> _ranges = new();
    private readonly ConcurrentQueue<(string rangeName, float value)> _logQueue = new();
    private readonly object _logLock = new();

    // Method to add a range with specified bounds and inclusivity
    public void AddRange(string rangeName, float min, float max, bool inclusive)
    {
        if (min > max)
            throw new ArgumentException("Min value cannot be greater than max value.");

        _ranges[rangeName] = (min, max, inclusive);
    }

    // Method to generate a random value within a specified range
    public float GenerateRandomValue(string rangeName)
    {
        if (!_ranges.ContainsKey(rangeName))
            throw new ArgumentException("Range not found.");

        var (min, max, inclusive) = _ranges[rangeName];
        Random rand = new();
        float value;

        do
        {
            value = inclusive ? (float)(rand.NextDouble() * (max - min + 1) + min) : (float)(rand.NextDouble() * (max - min) + min);
        } while (!inclusive && Math.Abs(value - min) < double.Epsilon || !inclusive && Math.Abs(value - max) < double.Epsilon);

        LogValue(rangeName, value);
        return value;
    }

    // Method to log the generated values
    private void LogValue(string rangeName, float value)
    {
        _logQueue.Enqueue((rangeName, value));

        if (_logQueue.Count > 100) // Assuming a rate limit of 100 logs per second
            ProcessLogQueue();
    }

    // Method to process the log queue and send values to external logging service
    private void ProcessLogQueue()
    {
        lock (_logLock)
        {
            while (_logQueue.Count > 0 && SendToLoggingService(_logQueue.Dequeue()))
            {
                // Continue sending until all logs are sent or rate limit is reached
            }
        }
    }

    // Mock method to simulate logging service interaction
    private bool SendToLoggingService((string rangeName, float value) logEntry)
    {
        try
        {
            // Simulate logging operation with a delay to mimic network latency
            System.Threading.Thread.Sleep(10); 
            Console.WriteLine($"Logged: Range {logEntry.rangeName}, Value {logEntry.value}");
            return true;
        }
        catch (Exception)
        {
            return false; // Handle potential integration failure gracefully
        }
    }

    // Method to retrieve and clear the log queue for testing or auditing purposes
    public void ClearLogQueue()
    {
        _logQueue.Clear();
    }
}
