    if (len + 2 > size_limit) {
        log_error("Input exceeds size limit");
        return NULL;
    }

    // Allocate memory for the new string
    char* result = malloc(len + 2);
    if (result == NULL) {
        log_error("Memory allocation failed");
        return NULL;
    }

    // Copy the input string to the new string
    strcpy(result, input);

    // Append a slash and null terminator
    result[len] = '/';
    result[len + 1] = '\0';

    return result;
}

