#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int bitDepth;
    int samplesPerPixel;
    char* compressionType;
    int extraSamples;
    int profileMetadataSize;
} TIFFInfo;

TIFFInfo parseTIFF(const char* filename) {
    TIFFInfo info = {0};
    FILE* file = fopen(filename, "rb");

    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return info;
    }

    // Check TIFF header for corruption
    uint8_t header[4];
    fread(header, 1, 4, file);
    if (header[0] != 'I' || header[1] != 'I' || header[2] != 0x002a || header[3] != 0x0000) {
        fprintf(stderr, "TIFF header corruption detected.\n");
        fclose(file);
        return info;
    }

    // Parse TIFF tags to extract required information
    uint16_t tagCount;
    fread(&tagCount, sizeof(uint16_t), 1, file);

    for (int i = 0; i < tagCount; i++) {
        uint16_t tagID, dataType, count;
        fread(&tagID, sizeof(uint16_t), 1, file);
        fread(&dataType, sizeof(uint16_t), 1, file);
        fread(&count, sizeof(uint32_t), 1, file);

        switch (tagID) {
            case 0x0100: // Bits per sample
                fread(info.bitDepth, sizeof(uint16_t), count, file);
                break;
            case 0x0111: // Samples per pixel
                fread(&info.samplesPerPixel, sizeof(uint16_t), 1, file);
                break;
            case 0x0201: // Compression
                fseek(file, dataType == 4 ? count * 4 : count, SEEK_CUR);
                break;
            case 0x03FE: // Extra samples
                fread(&info.extraSamples, sizeof(uint16_t), 1, file);
                break;
            case 0x02BC: // Profile metadata size
                fread(&info.profileMetadataSize, sizeof(uint32_t), 1, file);
                break;
        }
    }

    fclose(file);

    return info;
}
