int modify_filename(char *filename) {
    char new_filename[256];
    struct stat st = {0};
    int digits = 0;
    char file_type[4] = ".txt";

    // Extract directory path
    char *dir_path = strtok(filename, "/");
    while (strtok(NULL, "/") != NULL)
        dir_path = strtok(NULL, "/");

    // Count the number of digits in the directory path
    while (*dir_path) {
        if (*dir_path >= '0' && *dir_path <= '9')
            digits++;
        dir_path++;
    }

    // Derive file type from the last word in the filename
    char *last_word = strtok(filename, " ");
    if (last_word != NULL) {
        char *ext = strrchr(last_word, '.');
        if (ext != NULL && strlen(ext) > 1)
            strcpy(file_type, ext);
    }

    // Check and create directory if it does not exist
    if (stat(filename, &st) == -1) {
        mkdir(filename, 0755);
    }

    // Construct the new filename
    sprintf(new_filename, "%s%d%s", filename, digits, file_type);

    // Rename the file
    if (rename(filename, new_filename) != 0) {
        perror("Error renaming file");
        return -1;
    }

    return 0;
}
