EVP_CIPHER_CTX *init_aes_128_gcm(const char *password, const unsigned char *salt, size_t salt_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Set the key derivation function and parameters
    int key_len = 16;
    unsigned char key[key_len];
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len, 10000, EVP_sha256(), key_len, key) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize the AES-128-GCM cipher
    if (EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, key, NULL) != 1) {
        OPENSSL_cleanse(key, key_len);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set the authentication tag length
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG_LENGTH, 16, NULL) != 1) { // Assuming 128-bit tag
        OPENSSL_cleanse(key, key_len);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Generate a random IV
    unsigned char iv[EVP_MAX_IV_LENGTH];
    if (RAND_bytes(iv, EVP_CIPHER_iv_length(EVP_aes_128_gcm())) != 1) {
        OPENSSL_cleanse(key, key_len);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set the IV
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, iv) != 1) {
        OPENSSL_cleanse(key, key_len);
        OPENSSL_cleanse(iv, EVP_MAX_IV_LENGTH);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Clean up the sensitive data
    OPENSSL_cleanse(key, key_len);

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_cleanup(ctx);
        EVP_CIPHER_CTX_free(ctx);
    }
