// Function to validate file paths and permissions
int validateFilePaths(const char *inputPath, const char *outputPath) {
    FILE *file = fopen(inputPath, "r");
    if (!file) return 1;
    fclose(file);

    // Check directory permissions for output path
    DIR *dir = opendir(outputPath);
    if (!dir) {
        if (mkdir(outputPath, 0755) != 0) return 1;
        dir = opendir(outputPath);
        if (!dir) return 1;
    }
    closedir(dir);

    return 0;
}

// Function to convert JPEG to PDF using an external tool
int convertJpegToPdf(const char *jpegFile, const char *pdfFile, int compressionLevel) {
    // Construct the command string
    char command[256];
    snprintf(command, sizeof(command), "convert -density 300 -quality %d %s %s", compressionLevel * 10, jpegFile, pdfFile);

    // Execute the command
    int result = system(command);
    return (result == 0) ? 0 : 1;
}

// Function to log conversion details
void logConversion(const char *jpegFile, const char *pdfFile, int status, time_t startTime) {
    time_t endTime = time(NULL);
    double duration = difftime(endTime, startTime);

    // Log to file and external service
    printf("JPEG: %s, PDF: %s, Status: %d, Duration: %.2f seconds\n", jpegFile, pdfFile, status, duration);
}

// Function to process a single JPEG file
void *processJpeg(void *arg) {
    char *jpegFile = (char *)arg;
    const char *outputDir = "output/";
    const char *pdfFile = outputDir;
    int compressionLevel = 7;

    // Validate file paths and permissions
    if (validateFilePaths(jpegFile, pdfFile)) return NULL;

    // Start the conversion process
    time_t startTime = time(NULL);
    int status = convertJpegToPdf(jpegFile, pdfFile, compressionLevel);

    // Log the conversion details
    logConversion(jpegFile, pdfFile, status, startTime);

    return (void *)(long)status;
}

// Function to process all JPEG files in a directory
void processDirectory(const char *inputDir) {
    DIR *dir = opendir(inputDir);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".jpg")) {
            char jpegFile[256];
            snprintf(jpegFile, sizeof(jpegFile), "%s/%s", inputDir, entry->d_name);

            pthread_t thread;
            pthread_create(&thread, NULL, processJpeg, (void *)jpegFile);
            pthread_join(thread, NULL);
        }
    }

    closedir(dir);
}

int main(int argc, char *argv[]) {
    const char *inputDir = "images/";
    processDirectory(inputDir);

    return 0;
}
```

This code snippet provides a basic implementation of the required functionality. It includes functions to validate file paths, convert JPEG files to PDF using an external tool, log conversion details, and process all JPEG files in a directory concurrently. The `main` function demonstrates how to use these functions with a sample input directory.']

