#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>

int run_command_in_background(const char* command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("Failed to fork");
        return 0;
    } else if (pid == 0) {
        // Child process
        setsid(); // Create a new session
        umask(0); // Reset the file mode creation mask
        close(STDIN_FILENO);
        close(STDOUT_FILENO);
        close(STDERR_FILENO);

        execlp(command, command, NULL);
        perror("Failed to execute command");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        if (waitpid(pid, &status, WNOHANG) == -1) {
            perror("Failed to wait for child process");
            return 0;
        }
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            // Command failed
            fprintf(stderr, "Command '%s' failed\n", command);
            return 0;
        } else {
            // Command succeeded
            printf("Command '%s' executed successfully\n", command);
            return 1;
        }
    }
}

int main() {
    const char* command = "your_command_here";
    if (run_command_in_background(command)) {
        printf("Background task started successfully.\n");
    } else {
        printf("Failed to start background task.\n");
    }
    return 0;
}
```

This code provides a basic structure for running a command in the background while handling some common issues. It forks a new process, redirects standard file descriptors, and attempts to execute the provided command. The parent waits for the child without blocking and checks the exit status. Error handling is included for fork failure, command execution failure, and logging is minimal but can be expanded as needed.']

