    public async Task<string> AddAndStartWebsiteAsync(string directoryPath, string siteName)
    {
        try
        {
            if (!Directory.Exists(directoryPath))
            {
                Log($"Directory {directoryPath} does not exist.");
                return null;
            }

            if (!File.Exists(Path.Combine(directoryPath, "web.config")))
            {
                Log("web.config file is missing. Cannot add website.");
                return null;
            }

            if (!HasSufficientPermissions(directoryPath))
            {
                Log("Insufficient permissions to start website.");
                return null;
            }

            if (await IsConfigValidAsync(directoryPath))
            {
                ProcessStartInfo startInfo = new ProcessStartInfo
                {
                    FileName = "webserver.exe", // Replace with actual web server executable
                    Arguments = $"start {siteName}",
                    WorkingDirectory = directoryPath,
                    RedirectStandardOutput = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };

                using (Process process = Process.Start(startInfo))
                {
                    string output = await process.StandardOutput.ReadToEndAsync();
                    Log($"Website started with output: {output}");
                    return siteName;
                }
            }
            else
            {
                Log("Configuration validation failed. Cannot start website.");
                return null;
            }
        }
        catch (Exception ex)
        {
            Log($"An error occurred: {ex.Message}");
            return null;
        }
    }

    private bool HasSufficientPermissions(string directoryPath)
    {
        // Implement permission check logic here
        return true; // Placeholder
    }

    private async Task<bool> IsConfigValidAsync(string directoryPath)
    {
        using (HttpClient client = new HttpClient())
        {
            string validationUrl = Environment.GetEnvironmentVariable("CONFIG_VALIDATION_URL");
            if (string.IsNullOrEmpty(validationUrl))
            {
                Log("Validation URL is not set.");
                return false;
            }

            try
            {
                HttpResponseMessage response = await client.GetAsync($"{validationUrl}?configPath={directoryPath}");
                return response.IsSuccessStatusCode;
            }
            catch (HttpRequestException ex)
            {
                Log($"Error validating configuration: {ex.Message}");
                return false;
            }
        }
    }

    private void Log(string message)
    {
        using (StreamWriter writer = File.AppendText(_logFilePath))
        {
            writer.WriteLine($"{DateTime.Now}: {message}");
        }
    }
}
