import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Paths;

public class WorkflowManager {

    private static final String TEMP_FILE = "tempData.txt";
    private static final String INPUT_FILE = "/path/to/inputFile.csv";
    private static final String OUTPUT_LOG = "output.log";
    private static final String ERROR_LOG = "error.log";
    private static final String WORKFLOW_LOG = "workflow.log";

    public static void main(String[] args) {
        try {
            manageWorkflow();
        } catch (IOException | InterruptedException e) {
            logError(WORKFLOW_LOG, "Unexpected error occurred: ", e);
        }
    }

    private static void manageWorkflow() throws IOException, InterruptedException {
        // Step 1
        if (Files.exists(Paths.get(TEMP_FILE))) {
            Files.delete(Paths.get(TEMP_FILE));
        }

        // Step 2
        ProcessBuilder pb = new ProcessBuilder("/usr/bin/dataProcessor", "--input", INPUT_FILE, "--output", TEMP_FILE);
        Process process = pb.start();

        // Step 3
        logStream(process.getInputStream(), OUTPUT_LOG);
        logStream(process.getErrorStream(), ERROR_LOG);

        // Step 4
        if (!process.waitFor(60, java.util.concurrent.TimeUnit.SECONDS)) {
            process.destroy();
            logError(WORKFLOW_LOG, "Command execution timed out.");
        }
    }

    private static void logStream(InputStream is, String logFile) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(is))) {
            Files.write(Paths.get(logFile), reader.lines().collect(Collectors.toList()));
        }
    }

    private static void logError(String logFile, String message, Exception e) {
        try (PrintWriter writer = new PrintWriter(Files.newBufferedWriter(Paths.get(logFile), StandardOpenOption.APPEND))) {
            writer.println(message + e.getMessage());
            e.printStackTrace(writer);
        } catch (IOException ex) {
            System.err.println("Failed to log error: " + ex.getMessage());
        }
    }
}
