typedef struct {
    char* password;
} PasswordInfo;

typedef struct {
    char* title;
} ConnectionDetails;

typedef void (*OnSecurityCheckComplete)(int status);

typedef struct {
    PasswordInfo* passwordInfo;
    ConnectionDetails* connectionDetails;
    OnSecurityCheckComplete callback;
} SecurityContext;

int validateSecurityContext(SecurityContext* context) {
    if (context == NULL || 
        context->passwordInfo == NULL || 
        context->connectionDetails == NULL || 
        context->callback == NULL) {
        return -1; // Error: Null pointer
    }

    if (context->passwordInfo->password == NULL || strlen(context->passwordInfo->password) == 0) {
        return -2; // Error: Empty password
    }

    if (context->connectionDetails->title == NULL || strlen(context->connectionDetails->title) == 0) {
        return -3; // Error: Empty title
    }

    if (strlen(context->passwordInfo->password) > 100) {
        return -4; // Error: Password too long
    }

    if (strlen(context->connectionDetails->title) > 100) {
        return -5; // Error: Title too long
    }

    context->callback(0); // Successful validation

    return 0;
}

void onSecurityCheckComplete(int status) {
    if (status == 0) {
        printf("Security check completed successfully.\n");
    } else {
        printf("Security check failed with error code: %d\n", status);
    }
}

int main() {
    SecurityContext context = {
        .passwordInfo = (PasswordInfo*)malloc(sizeof(PasswordInfo)),
        .connectionDetails = (ConnectionDetails*)malloc(sizeof(ConnectionDetails)),
        .callback = onSecurityCheckComplete
    };

    // Initialize password and title
    context.passwordInfo->password = strdup("securePass123");
    context.connectionDetails->title = strdup("Secure Connection");

    validateSecurityContext(&context);

    // Clean up memory
    free(context.passwordInfo->password);
    free(context.connectionDetails->title);
    free(context.passwordInfo);
    free(context.connectionDetails);

    return 0;
}
