using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class MessageDecoder
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public MessageDecoder()
    {
        string keyBase64 = Environment.GetEnvironmentVariable("DECODER_KEY");
        string ivBase64 = Environment.GetEnvironmentVariable("DECODER_IV");

        if (string.IsNullOrEmpty(keyBase64) || string.IsNullOrEmpty(ivBase64))
        {
            throw new InvalidOperationException("Key and IV must be provided as environment variables.");
        }

        _key = Convert.FromBase64String(keyBase64);
        _iv = Convert.FromBase64String(ivBase64);
    }

    public async Task<List<string>> DecodeMessagesAsync(string filePath)
    {
        List<string> decryptedMessages = new List<string>();

        try
        {
            using (StreamReader reader = new StreamReader(filePath))
            {
                string line;
                while ((line = await reader.ReadLineAsync()) != null)
                {
                    byte[] encodedMessage = Convert.FromBase64String(line);
                    string decryptedMessage = DecodeSingleMessage(encodedMessage);
                    decryptedMessages.Add(decryptedMessage);
                }
            }
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("Error reading from file or decoding message.", ex);
        }

        return decryptedMessages;
    }

    private string DecodeSingleMessage(byte[] encodedMessage)
    {
        using (TripleDES des = TripleDES.Create())
        {
            des.Key = _key;
            des.IV = _iv;
            des.Mode = CipherMode.CBC;
            des.Padding = PaddingMode.PKCS7;

            using (MemoryStream msDecrypt = new MemoryStream(encodedMessage))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, des.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                    {
                        return srDecrypt.ReadToEnd();
                    }
                }
            }
        }
    }
}
```

