using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;

public class MessageProcessor
{
    private static readonly byte[] Key = Encoding.UTF8.GetBytes("your-256-bit-key-here");
    private static readonly AesGcm aesGcm = new AesGcm(Key);

    public Dictionary<byte[], byte[]> DecryptMessages(byte[][] ciphertexts, byte[] aad)
    {
        var decryptedMessages = new Dictionary<byte[], byte[]>();
        foreach (var ciphertext in ciphertexts)
        {
            if (ciphertext.Length < 4) continue; // Minimum length for message prefix

            int messageLength = BitConverter.ToInt32(ciphertext, 0);
            if (messageLength + 4 > ciphertext.Length) continue; // Invalid message length

            byte[] encryptedMessage = new byte[messageLength];
            Buffer.BlockCopy(ciphertext, 4, encryptedMessage, 0, messageLength);

            byte[] tag = new byte[AesGcm.TagSize];
            Buffer.BlockCopy(encryptedMessage, messageLength - AesGcm.TagSize, tag, 0, AesGcm.TagSize);
            Buffer.BlockCopy(encryptedMessage, 0, encryptedMessage, 0, messageLength - AesGcm.TagSize);

            byte[] plaintext;
            try
            {
                aesGcm.Decrypt(aad, encryptedMessage, tag, out plaintext);
            }
            catch (CryptographicException)
            {
                continue; // Invalid tag, skip decryption
            }

            if (!decryptedMessages.ContainsKey(plaintext))
            {
                decryptedMessages.Add(plaintext, ciphertext);
            }
        }
        return decryptedMessages;
    }
}
