const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

function generateReport(command, outputDir) {
    const logFile = path.join(outputDir, 'log.txt');
    const reportFile = path.join(outputDir, 'report.pdf');

    if (!fs.existsSync(outputDir)) {
        fs.mkdirSync(outputDir);
    }

    const child = spawn(command, [], { cwd: outputDir });

    child.stdout.on('data', (data) => {
        fs.appendFileSync(logFile, `stdout: ${data}`);
    });

    child.stderr.on('data', (data) => {
        fs.appendFileSync(logFile, `stderr: ${data}`);
    });

    child.on('close', (code) => {
        if (code !== 0) {
            console.error(`Command failed with code ${code}`);
            return;
        }
        fs.renameSync(path.join(outputDir, 'temp_report.pdf'), reportFile);
        console.log('Report generated successfully:', reportFile);
    });

    child.on('error', (err) => {
        console.error('Child process error:', err);
    });
}

generateReport('/path/to/custom/report_generator', '/path/to/output_directory');
