using System;
using System.Collections.Generic;

public class GraphGenerator
{
    public static (Dictionary<int, List<int>> graph, double averageDegree, int vertexCount, int edgeCount) GenerateGraph()
    {
        var graph = new Dictionary<int, List<int>>();
        Random random = new Random();
        int currentVertexId = 1;
        int currentEdgeId = 1;

        while (graph.Count < 1000)
        {
            int degree = random.Next(1, 11);
            int addedEdges = 0;

            while (addedEdges < degree && graph.Count < 1000)
            {
                int targetVertex = random.Next(1, currentVertexId + 1);

                if (targetVertex != currentVertexId && !graph[currentVertexId].Contains(targetVertex))
                {
                    if (!graph.ContainsKey(targetVertex))
                        graph[targetVertex] = new List<int>();

                    graph[currentVertexId].Add(targetVertex);
                    graph[targetVertex].Add(currentVertexId);
                    addedEdges++;
                }
            }

            if (addedEdges == 0)
                break;

            currentVertexId++;
        }

        double averageDegree = CalculateAverageDegree(graph);
        int vertexCount = graph.Count;
        int edgeCount = CalculateEdgeCount(graph);

        return (graph, averageDegree, vertexCount, edgeCount);
    }

    private static double CalculateAverageDegree(Dictionary<int, List<int>> graph)
    {
        if (graph.Count == 0) return 0;

        int totalDegrees = 0;
        foreach (var vertex in graph.Values)
            totalDegrees += vertex.Count;

        return (double)totalDegrees / graph.Count;
    }

    private static int CalculateEdgeCount(Dictionary<int, List<int>> graph)
    {
        int edgeCount = 0;
        foreach (var vertex in graph.Values)
            edgeCount += vertex.Count;

        return edgeCount / 2; // Each edge is counted twice
    }
}
