// Define a thread-safe mutex for concurrent access
static ENV_MUTEX: Mutex<()> = Mutex::new(());

fn create_directory_and_set_env_var(directory_name: &str) -> Result<(), Box<dyn Error>> {
    // Lock the environment variable to ensure exclusive access
    let _guard = ENV_MUTEX.lock().unwrap();

    // Check if the environment variable is already set
    if env::var_os("MY_DIRECTORY").is_some() {
        return Ok(());
    }

    // Validate directory name (simple example)
    if !directory_name.chars().all(|c| c.is_alphanumeric()) {
        return Err("Directory name must be alphanumeric".into());
    }

    // Create a new directory
    let path = Path::new(directory_name);
    fs::create_dir_all(path)?;

    // Set the environment variable to the path of the directory
    env::set_var("MY_DIRECTORY", path.display().to_string());

    Ok(())
}
