#include <queue>
#include <mutex>
#include <condition_variable>
#include <unordered_map>
#include <thread>
#include <chrono>

struct PlayerAction {
    std::chrono::system_clock::time_point timestamp;
    int actionType;
    int priority;
};

class CombatActionManager {
public:
    void addAction(const PlayerAction& action) {
        std::lock_guard<std::mutex> lock(mutex);
        actionQueue.push(action);
        cond.notify_one();
    }

private:
    std::queue<PlayerAction> actionQueue;
    std::mutex mutex;
    std::condition_variable cond;
    std::unordered_map<int, std::chrono::system_clock::time_point> cooldowns;
    int maxActiveActions = 3;

    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cond.wait(lock, [this] { return !actionQueue.empty(); });
            PlayerAction action = actionQueue.front();
            actionQueue.pop();

            if (shouldExecute(action)) {
                executeAction(action);
                cooldowns[action.actionType] = std::chrono::system_clock::now() + std::chrono::seconds(10);
            }
        }
    }

    bool shouldExecute(const PlayerAction& action) {
        auto now = std::chrono::system_clock::now();
        if (cooldowns.find(action.actionType) == cooldowns.end()) {
            return true;
        }
        if (now >= cooldowns[action.actionType]) {
            return true;
        }
        return false;
    }

    void executeAction(const PlayerAction& action) {
        // Implement the logic to execute the action
        std::cout << "Executing action " << action.actionType << " with priority " << action.priority << std::endl;
    }

    void startWorkers() {
        for (int i = 0; i < maxActiveActions; ++i) {
            std::thread(&CombatActionManager::worker, this).detach();
        }
    }
};

int main() {
    CombatActionManager manager;
    manager.startWorkers();

    // Simulate adding actions
    manager.addAction({std::chrono::system_clock::now(), 1, 5});
    manager.addAction({std::chrono::system_clock::now(), 2, 3});
    manager.addAction({std::chrono::system_clock::now(), 1, 8});

    return 0;
}
