#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000
#define BATCH_SIZE 10
#define MAX_SLIDING_WINDOW 3

typedef struct {
    int id;
    time_t timestamp;
    double value;
    char type;
} Transaction;

double calculateWeight(Transaction *transaction, double marketIndex) {
    // Custom weight calculation logic here
    return transaction->value * marketIndex;
}

int processTransactions(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    Transaction transactions[MAX_TRANSACTIONS];
    int transactionCount = 0;

    while (fscanf(file, "%d %ld %lf %c", &transactions[transactionCount].id, 
                   &transactions[transactionCount].timestamp,
                   &transactions[transactionCount].value,
                   &transactions[transactionCount].type) == 4) {
        if (transactionCount >= MAX_TRANSACTIONS) {
            break;
        }
        transactionCount++;
    }

    fclose(file);

    // Process transactions in real-time with sliding window and dynamic weight adjustment
    double marketIndex = fetchMarketIndex(); // External service call
    Transaction *window[MAX_SLIDING_WINDOW];
    int windowStart = 0, windowEnd = -1;

    for (int i = 0; i < transactionCount; i++) {
        if (time(NULL) - transactions[i].timestamp > MAX_SLIDING_WINDOW) {
            continue;
        }

        while (windowStart <= windowEnd && time(NULL) - window[windowStart]->timestamp > MAX_SLIDING_WINDOW) {
            windowStart++;
        }

        if (i - windowStart >= BATCH_SIZE) {
            windowStart = i - BATCH_SIZE + 1;
        }

        window[++windowEnd] = &transactions[i];

        double maxWeightSum = 0;
        int maxTransactionId = -1;

        for (int j = windowStart; j <= windowEnd; j++) {
            double weight = calculateWeight(window[j], marketIndex);
            if (weight > maxWeightSum) {
                maxWeightSum = weight;
                maxTransactionId = window[j]->id;
            }
        }

        printf("Max Weight Sum: %f, Transaction ID: %d\n", maxWeightSum, maxTransactionId);

        // Update weights based on real-time market indices
        if (i % 10 == 0) {
            marketIndex = fetchMarketIndex(); // External service call with retry logic and fallback mechanism
        }
    }

    return 0;
}

double fetchMarketIndex() {
    // Simulated function to fetch market index from an external service
    static double marketIndex = 1.0;
    marketIndex += rand() / (RAND_MAX * 2.0); // Random change for demonstration
    sleep(1); // Simulate delay
    return marketIndex;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    const char *inputFilename = argv[1];
    int newExtensionDigits = countDigits(inputFilename);
    const char *fileType = getFileType(inputFilename);

    if (newExtensionDigits == -1 || fileType == NULL) {
        fprintf(stderr, "Invalid filename\n");
        return 1;
    }

    char outputFilename[MAX_FILENAME_LENGTH];
    sprintf(outputFilename, "%s_%d.%s", inputFilename, newExtensionDigits, fileType);
    printf("New Filename: %s\n", outputFilename);

    return processTransactions(inputFilename);
}

int countDigits(const char *filename) {
    int digits = 0;
    for (int i = strlen(filename) - 1; i >= 0 && isdigit(filename[i]); i--) {
        digits++;
    }
    return digits == 0 ? -1 : digits;
}

const char *getFileType(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (dot != NULL) {
        return dot + 1;
    }
    return "txt";
}
