    pthread_mutex_lock(&lock);
    if (num_events >= max_events) {
        TrafficEvent** new_events = realloc(traffic_events, (max_events + 100) * sizeof(TrafficEvent*));
        if (!new_events) {
            pthread_mutex_unlock(&lock);
            return 1;
        }
        traffic_events = new_events;
        max_events += 100;
    }

    TrafficEvent* new_event = malloc(sizeof(TrafficEvent));
    if (!new_event) {
        pthread_mutex_unlock(&lock);
        return 1;
    }

    new_event->timestamp = timestamp;
    strncpy(new_event->event_type, event_type, sizeof(new_event->event_type) - 1);
    new_event->payload = payload;
    new_event->payload_size = payload_size;

    traffic_events[num_events++] = new_event;
    pthread_mutex_unlock(&lock);
    return 0;
