    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    const EVP_CIPHER *cipher = NULL;
    if (strcmp(algorithm, "AES") == 0 && strcmp(mode, "CBC") == 0) {
        cipher = EVP_aes_256_cbc();
    } else if (strcmp(algorithm, "ChaCha20") == 0 && strcmp(mode, "CTR") == 0) {
        cipher = EVP_chacha20_poly1305();
    } else if (strcmp(algorithm, "Twofish") == 0 && strcmp(mode, "GCM") == 0) {
        cipher = EVP_aes_256_gcm();
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    int key_length = EVP_CIPHER_key_length(cipher);
    unsigned char *key = (unsigned char *)malloc(key_length);
    if (!key) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    // Generate or retrieve the key here

    int iv_length = EVP_CIPHER_iv_length(cipher);
    unsigned char *iv = (unsigned char *)malloc(iv_length);
    if (!iv) {
        free(key);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    // Generate IV using OpenSSL functions likeRAND_bytes()

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv) != 1) {
        free(key);
        free(iv);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (use_hmac) {
        const EVP_MD *md = EVP_sha256();
        int hmac_key_length = EVP_MAX_MD_SIZE;
        unsigned char *hmac_key = (unsigned char *)malloc(hmac_key_length);
        if (!hmac_key) {
            free(key);
            free(iv);
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
        // Generate or retrieve the HMAC key here

        if (EVP_EncryptInit_ex(ctx, NULL, NULL, hmac_key, NULL) != 1) {
            free(hmac_key);
            free(key);
            free(iv);
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }

        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_TAG_LEN, EVP_MAX_MD_SIZE, NULL) != 1) {
            free(hmac_key);
            free(key);
            free(iv);
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    }

    free(key);
    free(iv);

    return ctx;
}
