        $randomString .= $characters[rand(0, strlen($characters) - 1)];
    }
    return $randomString;
}

function addVerticesAndEdgesToGraphDB($numVertices, $graphDBApiUrl) {
    $verticesAdded = 0;
    $edgesAdded = 0;
    $errors = [];

    for ($i = 0; $i < $numVertices; $i++) {
        $randomString = generateRandomString(20);
        if (preg_match('/[a-z]/', $randomString) && preg_match('/[A-Z]/', $randomString) && preg_match('/\d/', $randomString)) {
            $vertexId = substr($randomString, 0, 10);
            $vertexProperties = [
                'type' => 'user',
                'name' => substr($randomString, 10, 5),
                'age' => rand(18, 60)
            ];

            try {
                $response = sendApiRequest("POST", $graphDBApiUrl . "/vertices", json_encode(['id' => $vertexId, 'properties' => $vertexProperties]));
                if ($response->getStatusCode() == 200) {
                    $verticesAdded++;
                } else {
                    $errors[] = "Failed to add vertex $i: " . $response->getBody();
                }
            } catch (Exception $e) {
                $errors[] = "Error adding vertex $i: " . $e->getMessage();
            }

            if ($i > 0) {
                $edgeId = substr($randomString, 15, 5);
                $sourceVertexId = substr($randomString, 0, 5);
                $targetVertexId = substr($randomString, 5, 5);
                $edgeProperties = [
                    'type' => 'friendship',
                    'since' => rand(2010, 2020)
                ];

                try {
                    $response = sendApiRequest("POST", $graphDBApiUrl . "/edges", json_encode(['id' => $edgeId, 'source' => $sourceVertexId, 'target' => $targetVertexId, 'properties' => $edgeProperties]));
                    if ($response->getStatusCode() == 200) {
                        $edgesAdded++;
                    } else {
                        $errors[] = "Failed to add edge $i: " . $response->getBody();
                    }
                } catch (Exception $e) {
                    $errors[] = "Error adding edge $i: " . $e->getMessage();
                }
            }

            // Implement pagination or batch processing for large datasets
            if ($verticesAdded % 100 == 0) {
                gc_collect_cycles(); // Force garbage collection to manage memory efficiently
            }
        } else {
            $errors[] = "Invalid random string generated: $randomString";
        }
    }

    return [
        'vertices_added' => $verticesAdded,
        'edges_added' => $edgesAdded,
        'errors' => $errors
    ];
}

function sendApiRequest($method, $url, $data) {
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_CUSTOMREQUEST, $method);
    curl_setopt($ch, CURLOPT_POSTFIELDS, $data);
    curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-Type: application/json']);

    // Retry logic for potential network errors
    $retryCount = 0;
    while ($retryCount < 3) {
        $response = curl_exec($ch);
        if ($response === false) {
            $error = curl_error($ch);
            curl_close($ch);
            sleep(1); // Wait before retrying
            $retryCount++;
        } else {
            break;
        }
    }

    curl_close($ch);
    return new Response($response, curl_getinfo($ch));
}

class Response {
    private $body;
    private $statusCode;

    public function __construct($body, $statusCode) {
        $this->body = $body;
        $this->statusCode = $statusCode['http_code'];
    }

    public function getBody() {
        return $this->body;
    }

    public function getStatusCode() {
        return $this->statusCode;
    }
}
?>
