char* processString(char *input, int sizeLimit, LogChannel logChannel) {
    if (sizeLimit < 0 || sizeLimit > MAX_SIZE) {
        logError(logChannel, "Invalid size limit");
        return "";
    }

    if (input == NULL) {
        logError(logChannel, "Input string is null");
        return "";
    }

    int inputLen = strlen(input);
    if ((size_t)(inputLen + 1) >= sizeLimit) { // Account for the null terminator
        logError(logChannel, "String exceeds size limit");
        return "";
    }

    // Check for embedded null characters and handle them gracefully
    if (memchr(input, '\0', inputLen)) {
        logError(logChannel, "Embedded null character detected");
        return "";
    }

    char *output = realloc(input, inputLen + 2); // Allocate space for the string plus the slash and null terminator
    if (output == NULL) {
        logError(logChannel, "Memory allocation failed");
        return "";
    }

    output[inputLen] = '/';
    output[inputLen + 1] = '\0';

    return output;
}

