#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Helper function to validate and modify string based on size limit
char* process_string(const char* input, int max_length) {
    if (input == NULL || max_length < 0 || max_length > 1024) {
        return NULL;
    }

    // Allocate memory for the new string
    char* output = (char*)malloc((max_length + 2) * sizeof(char));
    if (output == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    int length = strlen(input);
    if (length > max_length) {
        strncpy(output, input, max_length);
        output[max_length] = '/';
        output[max_length + 1] = '\0';
        return output;
    } else {
        strcpy(output, input);
        return output;
    }
}

// Main function to process text file line by line
int main(int argc, char* argv[]) {
    if (argc != 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    FILE* file = fopen(argv[1], "r");
    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    char* line_buffer = NULL;
    size_t buffer_size = 0;
    ssize_t line_length;

    while ((line_length = getline(&line_buffer, &buffer_size, file)) != -1) {
        // Process each line
        char* tokens[10];
        int token_count = 0;
        char* token = strtok(line_buffer, ",");
        while (token != NULL && token_count < 10) {
            tokens[token_count++] = token;
            token = strtok(NULL, ",");
        }

        if (token_count >= 2) {
            // Calculate average of last two numerical fields
            double num1 = atof(tokens[token_count - 2]);
            double num2 = atof(tokens[token_count - 1]);
            double avg = (num1 + num2) / 2;

            // Construct new line with modified format
            char* modified_line = process_string(line_buffer, 256);
            if (modified_line != NULL) {
                printf("%s,%f\n", modified_line, avg);
                free(modified_line);
            }
        }
    }

    free(line_buffer);
    fclose(file);
    return 0;
}
