using System;
using System.Collections.Generic;

public class CampusWiFiModel
{
    private List<AccessPoint> accessPoints = new List<AccessPoint>();
    private List<WifiConnection> connections = new List<WifiConnection>();

    public AccessPoint CreateAccessPoint(int maxClients)
    {
        if (accessPoints.Count >= 500) throw new InvalidOperationException("Maximum number of APs reached.");
        var ap = new AccessPoint(accessPoints.Count + 1, maxClients);
        accessPoints.Add(ap);
        return ap;
    }

    public WifiConnection CreateConnection(AccessPoint source, AccessPoint destination)
    {
        if (source == null || destination == null) throw new ArgumentNullException("APs cannot be null.");
        if (source.ID == destination.ID) throw new ArgumentException("Source and destination APs must be distinct.");
        if (connections.Count >= 2000) throw new InvalidOperationException("Maximum number of connections reached.");
        var connection = new WifiConnection(connections.Count + 1, source, destination);
        connections.Add(connection);
        return connection;
    }

    public double CalculateAverageThroughputCapacity()
    {
        if (connections.Count == 0) return 0;
        double totalBandwidth = 0;
        foreach (var connection in connections)
        {
            totalBandwidth += connection.Bandwidth;
        }
        return totalBandwidth / connections.Count;
    }

    public class AccessPoint
    {
        public int ID { get; private set; }
        public List<WifiConnection> Connections { get; } = new List<WifiConnection>();
        public int MaxClients { get; }

        public AccessPoint(int id, int maxClients)
        {
            ID = id;
            MaxClients = maxClients;
        }

        public void AddConnection(WifiConnection connection)
        {
            if (Connections.Count >= MaxClients) throw new InvalidOperationException("AP reached maximum client capacity.");
            Connections.Add(connection);
        }
    }

    public class WifiConnection
    {
        public int ID { get; private set; }
        public AccessPoint Source { get; }
        public AccessPoint Destination { get; }
        public double Bandwidth { get; } = 100.0; // Assuming 100 Mbps for each connection

        public WifiConnection(int id, AccessPoint source, AccessPoint destination)
        {
            ID = id;
            Source = source;
            Destination = destination;
        }
    }
}
