        snprintf(edgeId, sizeof(edgeId), "edge_%d", i);

        if (graphdb_addVertex(db, vertexId, randomString[i])) {
            logError("Failed to add vertex");
        }

        if (i > 0) {
            char *edgeLabel = generateEdgeLabel(randomString[i-1], randomString[i]);
            if (graphdb_addEdge(db, edgeId, vertexId, edgeLabel)) {
                logError("Failed to add edge");
            }
        }
    }

    graphdb_disconnect(&db);
}

char* generateRandomString(int length) {
    static const char characters[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    char *string = malloc(length + 1);
    for (int i = 0; i < length; i++) {
        string[i] = characters[rand() % strlen(characters)];
    }
    return string;
}

char* generateEdgeLabel(char start, char end) {
    static const char labels[] = "ABCD";
    int labelIndex = ((start - 'A') * 26 + (end - 'a')) % 4;
    return labels[labelIndex];
}

void logError(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
