int extend_crypto_library(const char *config_file) {
    FILE *fp = fopen(config_file, "r");
    if (!fp) {
        perror("Failed to open configuration file");
        return -1;
    }

    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_256_cbc());

    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest(EVP_sha256());

    EVP_add_digest_alias("MD4", "md4");

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *token = strtok(line, ",");
        while (token) {
            token[strcspn(token, "\r\n")] = 0; // Remove newline characters
            if (strcmp(token, "PBKDF2") == 0) {
                EVP_add_digest(EVP_pbkdf2());
            } else if (strcmp(token, "SCrypt") == 0) {
                EVP_add_digest(EVP_scrypt());
            } else if (strcmp(token, "Argon2") == 0) {
                EVP_add_digest(EVP_argon2i());
            }
            token = strtok(NULL, ",");
        }
    }

    fclose(fp);
    return 0;
}
