#include <iostream>
#include <fstream>
#include <forward_list>
#include <string>
#include <stdexcept>

void insertAfterInForwardList(std::forward_list<std::string>& myList, const std::string& searchString, const std::string& insertString) {
    auto it = myList.begin();
    while (it != myList.end() && *it != searchString) {
        ++it;
    }

    if (it == myList.end()) {
        myList.push_back(insertString);
    } else {
        myList.insert_after(it, insertString);
    }
}

int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    insertAfterInForwardList(myList, "banana", "grape");

    for (const auto& item : myList) {
        std::cout << item << " ";
    }
    return 0;
}
```

