sem_t sem;

double rolling_average_weighted_sum = 0.0;
double rolling_average_age_decay = 1.0;
time_t last_update_time = 0;

void* process_transactions(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);

        for (int i = 0; i < transaction_count; i++) {
            double age = difftime(time(NULL), transactions[i].timestamp);
            if (age > 10) {
                // Filter out old transactions
                continue;
            }

            double weighted_sum = transactions[i].amount * rolling_average_age_decay;
            if (weighted_sum > rolling_average_weighted_sum) {
                rolling_average_weighted_sum = weighted_sum;
                // Update maximum weighted sum and transaction ID
            }
        }

        pthread_mutex_unlock(&mutex);

        sem_post(&sem);
        sleep(1); // Process transactions every second
    }

    return NULL;
}

void update_rolling_average(double new_value, double decay) {
    pthread_mutex_lock(&mutex);
    rolling_average_weighted_sum = (rolling_average_weighted_sum * rolling_average_age_decay + new_value) / decay;
    rolling_average_age_decay = decay;
    last_update_time = time(NULL);
    pthread_mutex_unlock(&mutex);
}

void* fetch_network_data(void* arg) {
