        // Simulate network data fetching
        double new_weighted_sum = 0.0;
        double new_decay_factor = 1.0;

        // Update rolling averages based on fetched data
        update_rolling_average(new_weighted_sum, new_decay_factor);

        sem_wait(&sem);
    }

    return NULL;
}

int main() {
    pthread_t transaction_thread, network_thread;

    pthread_mutex_init(&mutex, NULL);
    sem_init(&sem, 0, 0);

    pthread_create(&transaction_thread, NULL, process_transactions, NULL);
    pthread_create(&network_thread, NULL, fetch_network_data, NULL);

    // Simulate receiving transactions
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        pthread_mutex_lock(&mutex);
        transactions[transaction_count].id = i;
        transactions[transaction_count].amount = rand() % 1000;
        transactions[transaction_count].timestamp = time(NULL);
        transaction_count++;
        pthread_mutex_unlock(&mutex);

        sem_wait(&sem);
    }

    pthread_join(transaction_thread, NULL);
    pthread_join(network_thread, NULL);

    pthread_mutex_destroy(&mutex);
    sem_destroy(&sem);

    return 0;
}
