#include <chrono>
#include <iostream>

struct PlayerAction {
    int timestamp;
    char actionType;
    int priority;
    int id;
};

class CombatActionManager {
public:
    CombatActionManager() : cooldowns(4, std::chrono::seconds(0)), activeActions(3), nextId(0) {}

    void addAction(const PlayerAction& action) {
        std::lock_guard<std::mutex> lock(mutex);
        actions.push(action);
        condition.notify_one();
    }

    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            if (actions.empty()) {
                condition.wait(lock, [this] { return !actions.empty(); });
            }
            PlayerAction currentAction = actions.front();
            actions.pop();

            int index = actionTypeToIndex(currentAction.actionType);
            if (std::chrono::system_clock::now() >= cooldowns[index]) {
                executeAction(currentAction);
                updateCooldown(index, currentAction.timestamp);
            }
        }
    }

private:
    std::mutex mutex;
    std::condition_variable condition;
    std::queue<PlayerAction> actions;
    std::vector<std::chrono::time_point<std::chrono::system_clock>> cooldowns;
    int activeActions;
    int nextId;

    int actionTypeToIndex(char type) {
        // Map action types to their respective indices
        if (type == 'A') return 0;
        if (type == 'B') return 1;
        if (type == 'C') return 2;
        if (type == 'D') return 3;
        throw std::invalid_argument("Invalid action type");
    }

    void executeAction(const PlayerAction& action) {
        // Execute the action
        std::cout << "Executing action " << action.id << " of type " << action.actionType << std::endl;
    }

    void updateCooldown(int index, int timestamp) {
        cooldowns[index] = std::chrono::system_clock::now() + getCooldownDuration(index);
    }

    std::chrono::seconds getCooldownDuration(int index) {
        // Return the cooldown duration for the given action type
        switch (index) {
            case 0: return std::chrono::seconds(10);
            case 1: return std::chrono::seconds(15);
            case 2: return std::chrono::seconds(20);
            case 3: return std::chrono::seconds(25);
        }
        throw std::invalid_argument("Invalid action type index");
    }
};

int main() {
    CombatActionManager manager;
    std::thread t(&CombatActionManager::run, &manager);

    // Simulate adding actions
    for (char type = 'A'; type <= 'D'; ++type) {
        for (int i = 0; i < 10; ++i) {
            manager.addAction({i * 1000, type, i % 3 + 1, i});
        }
    }

    t.join();
    return 0;
}
