#include <stdlib.h>

int load_crypto_primitives(const char *config_file) {
    // Load configuration file and parse algorithm names
    FILE *fp = fopen(config_file, "r");
    if (!fp) return -1;

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), fp)) {
        char algorithms[256] = {0};
        sscanf(buffer, "%255s", algorithms);

        // Split algorithms by comma
        const char *delim = ",";
        const char *token = strtok(algorithms, delim);
        while (token != NULL) {
            // Add cipher or digest to the library
            if (strstr(token, "AES") || strstr(token, "Camellia")) {
                EVP_add_cipher(EVP_aes_256_cbc()); // Example for AES, similar for others
            } else if (strstr(token, "MD5") || strstr(token, "SHA-1") || strstr(token, "SHA-256")) {
                EVP_add_digest(EVP_md5()); // Example for MD5, similar for others
            }

            token = strtok(NULL, delim);
        }
    }

    fclose(fp);

    return 0;
}

void initialize_crypto_primitives() {
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    if (load_crypto_primitives("config.txt") != 0) {
        fprintf(stderr, "Failed to load cryptographic primitives.\n");
        exit(EXIT_FAILURE);
    }

    EVP_cleanup();
}
