    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char *codec_name = strtok(line, ",");
        if (!codec_name) continue;

        AVCodec *codec = avcodec_find_decoder_by_name(codec_name);
        if (!codec) {
            // Handle missing codec
            fprintf(stderr, "Codec not found: %s\n", codec_name);
            continue;
        }

        pthread_mutex_lock(&library->mutex);
        if (library->codec_count < MAX_CODECS) {
            library->codecs[library->codec_count++] = codec;
        } else {
            // Handle maximum codecs reached
            fprintf(stderr, "Maximum codecs reached\n");
        }
        pthread_mutex_unlock(&library->mutex);
    }

    fclose(file);
    return 0;
}

