#define MAX_LOG_LINE_LENGTH 256

typedef struct {
    double timestamp;
    double metricValue;
} LogEntry;

int compareLogEntries(const void *a, const void *b) {
    LogEntry *entryA = (LogEntry *)a;
    LogEntry *entryB = (LogEntry *)b;
    if (entryA->timestamp < entryB->timestamp) return -1;
    if (entryA->timestamp > entryB->timestamp) return 1;
    return 0;
}

double mean(double values[], int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += values[i];
    }
    return sum / count;
}

double standardDeviation(double values[], int count, double mean) {
    double sumOfSquares = 0.0;
    for (int i = 0; i < count; i++) {
        sumOfSquares += (values[i] - mean) * (values[i] - mean);
    }
    return sqrt(sumOfSquares / count);
}

bool monitorAndAnalyzeMetrics(const char *logFilePath, double interval, double upperLimit, double lowerLimit) {
    FILE *file = fopen(logFilePath, "r");
    if (!file) {
        perror("Failed to open log file");
        return false;
    }

    LogEntry entries[1024];
    int count = 0;

    char line[MAX_LOG_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        // Parse the timestamp and metric value from the log entry
        double timestamp, metricValue;
        if (sscanf(line, "%lf %lf", &timestamp, &metricValue) != 2) {
            continue; // Skip invalid lines
        }
        entries[count].timestamp = timestamp;
        entries[count].metricValue = metricValue;
        count++;
    }

    fclose(file);

    qsort(entries, count, sizeof(LogEntry), compareLogEntries);

    double currentWindowStart = entries[0].timestamp;
    double windowSum = 0.0;
    int windowCount = 0;
    bool anyViolation = false;

    for (int i = 0; i < count; i++) {
        if (entries[i].timestamp - currentWindowStart >= interval) {
            double windowMean = mean(windowValues, windowCount);
            double windowDeviation = standardDeviation(windowValues, windowCount, windowMean);

            if (windowMean > upperLimit || windowMean < lowerLimit) {
                anyViolation = true;
            }

            // Reset for the next window
            currentWindowStart = entries[i].timestamp;
            windowSum = 0.0;
            windowCount = 0;
        }
        windowValues[windowCount++] = entries[i].metricValue;
    }

    return !anyViolation;
}
