    }
    for (int i = 0; i < numNodes; i++) {
        array[i] = createNode(i + 1);
        if (i > 0) {
            array[i - 1]->next = array[i];
        }
    }
    return array;
}

void insertNode(Node** array, int position, int key) {
    if (position < 0 || position > numNodes) {
        printf("Invalid position\n");
        return;
    }
    Node* newNode = createNode(key);
    if (position == 0) {
        newNode->next = *array;
        *array = newNode;
    } else {
        newNode->next = array[position - 1]->next;
        array[position - 1]->next = newNode;
    }
}

void freeList(Node** array, int numNodes) {
    for (int i = 0; i < numNodes; i++) {
        free(array[i]);
    }
    free(array);
}
