    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) { // Child process
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        close(pipefd[1]);

        execlp("/bin/sh", "sh", "-c", command, NULL);
        perror("execlp");
        exit(EXIT_FAILURE);
    } else { // Parent process
        close(pipefd[1]);
        char buffer[256];
        read(pipefd[0], buffer, sizeof(buffer) - 1);
        printf("%s\n", buffer);

        close(pipefd[0]);

        free(records);
    }
}
