#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct hash_table_entry {
    Record *record;
    struct hash_table_entry *next;
} HashTableEntry;

typedef struct hash_table {
    size_t size;
    size_t count;
    HashTableEntry **entries;
    pthread_mutex_t mutex;
} HashTable;

unsigned long hash_function(const int key, const size_t size) {
    return (unsigned long)key % size;
}

HashTable *hash_table_create(size_t initial_size) {
    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    if (!ht) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    ht->size = initial_size;
    ht->count = 0;
    ht->entries = (HashTableEntry **)calloc(initial_size, sizeof(HashTableEntry *));
    if (!ht->entries) {
        free(ht);
        perror("Failed to allocate memory for hash table entries");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

void hash_table_insert(HashTable *ht, int key, long offset) {
    pthread_mutex_lock(&ht->mutex);
    size_t index = hash_function(key, ht->size);
    HashTableEntry *entry = (HashTableEntry *)malloc(sizeof(HashTableEntry));
    if (!entry) {
        perror("Failed to allocate memory for hash table entry");
        exit(EXIT_FAILURE);
    }
    entry->record = (Record *)malloc(sizeof(Record));
    if (!entry->record) {
        free(entry);
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }
    entry->record->value = rand() % 100; // Initialize with a random value
    entry->record->offset = (long *)malloc(sizeof(long));
    if (!entry->record->offset) {
        free(entry->record);
        free(entry);
        perror("Failed to allocate memory for offset");
        exit(EXIT_FAILURE);
    }
    *entry->record->offset = offset;
    entry->record->key = (int *)malloc(sizeof(int));
    if (!entry->record->key) {
        free(entry->record->offset);
        free(entry->record);
        free(entry);
        perror("Failed to allocate memory for key");
        exit(EXIT_FAILURE);
    }
    *entry->record->key = key;
    entry->next = ht->entries[index];
    ht->entries[index] = entry;
    ht->count++;
    pthread_mutex_unlock(&ht->mutex);
}

void hash_table_compact(HashTable *ht) {
    if (ht->count / ht->size < 0.25) return; // Only compact when load factor is less than 25%
    HashTableEntry **old_entries = ht->entries;
    size_t old_size = ht->size;
    ht->size *= 2;
    ht->entries = (HashTableEntry **)calloc(ht->size, sizeof(HashTableEntry *));
    if (!ht->entries) {
        perror("Failed to allocate memory for new hash table entries");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < old_size; i++) {
        HashTableEntry *entry = old_entries[i];
        while (entry) {
            hash_table_insert(ht, *(entry->record->key), *(entry->record->offset));
            HashTableEntry *temp = entry;
            entry = entry->next;
            free(temp->record->offset);
            free(temp->record->key);
            free(temp->record);
            free(temp);
        }
    }
    free(old_entries);
}

void hash_table_update(HashTable *ht, int key, long new_offset) {
    pthread_mutex_lock(&ht->mutex);
    size_t index = hash_function(key, ht->size);
    HashTableEntry *entry = ht->entries[index];
    while (entry) {
        if (*(entry->record->key) == key) {
            *(entry->record->offset) = new_offset;
            break;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&ht->mutex);
}

void hash_table_destroy(HashTable *ht) {
    pthread_mutex_lock(&ht->mutex);
    for (size_t i = 0; i < ht->size; i++) {
        HashTableEntry *entry = ht->entries[i];
        while (entry) {
            HashTableEntry *temp = entry;
            entry = entry->next;
            free(temp->record->offset);
            free(temp->record->key);
            free(temp->record);
            free(temp);
        }
    }
    pthread_mutex_unlock(&ht->mutex);
    free(ht->entries);
    pthread_mutex_destroy(&ht->mutex);
    free(ht);
}
