#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define ARCHIVE_THRESHOLD 30 * 24 * 60 * 60 // 30 days in seconds
#define PURGE_THRESHOLD 90 * 24 * 60 * 60   // 90 days in seconds

typedef struct {
    time_t timestamp;
    int eventType;
    char* payload;
} TrafficEvent;

typedef struct {
    TrafficEvent* events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventManager;

EventManager* eventManagerCreate() {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (manager) {
        manager->events = NULL;
        manager->count = 0;
        manager->capacity = 0;
        pthread_mutex_init(&manager->lock, NULL);
    }
    return manager;
}

void eventManagerAddEvent(EventManager* manager, time_t timestamp, int eventType, const char* payload) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity ? manager->capacity * 2 : 1;
        TrafficEvent* newEvents = realloc(manager->events, newCapacity * sizeof(TrafficEvent));
        if (!newEvents) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->events = newEvents;
        manager->capacity = newCapacity;
    }
    manager->events[manager->count].timestamp = timestamp;
    manager->events[manager->count].eventType = eventType;
    manager->events[manager->count].payload = strdup(payload);
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

void eventManagerUpdateEvent(EventManager* manager, int eventId, time_t newTimestamp, int newEventType, const char* newPayload) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (i == eventId) {
            free(manager->events[i].payload);
            manager->events[i].timestamp = newTimestamp;
            manager->events[i].eventType = newEventType;
            manager->events[i].payload = strdup(newPayload);
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

TrafficEvent* eventManagerGetEventsInRange(EventManager* manager, time_t startTime, time_t endTime) {
    pthread_mutex_lock(&manager->lock);
    TrafficEvent* result = NULL;
    size_t resultCount = 0;
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->events[i].timestamp >= startTime && manager->events[i].timestamp <= endTime) {
            resultCount++;
        }
    }
    result = malloc(resultCount * sizeof(TrafficEvent));
    size_t j = 0;
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->events[i].timestamp >= startTime && manager->events[i].timestamp <= endTime) {
            result[j++] = manager->events[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return result;
}

void eventManagerArchiveEvents(EventManager* manager) {
    pthread_mutex_lock(&manager->lock);
    time_t now = time(NULL);
    for (size_t i = 0; i < manager->count; i++) {
        if (now - manager->events[i].timestamp > ARCHIVE_THRESHOLD) {
            // Archive the event to secondary storage
            printf("Archiving event %zu\n", i);
            free(manager->events[i].payload);
            for (size_t j = i + 1; j < manager->count; j++) {
                manager->events[j - 1] = manager->events[j];
            }
            manager->count--;
            i--; // Adjust index after removal
        } else if (now - manager->events[i].timestamp > PURGE_THRESHOLD) {
            free(manager->events[i].payload);
            for (size_t j = i + 1; j < manager->count; j++) {
                manager->events[j - 1] = manager->events[j];
            }
            manager->count--;
            i--; // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void eventManagerDestroy(EventManager* manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; i++) {
            free(manager->events[i].payload);
        }
        free(manager->events);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
