#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int key;
    struct Node* next;
    int type; // 0 for regular node, 1 for special node
} Node;

Node* create_node(int key, int type) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    newNode->key = key;
    newNode->type = type;
    newNode->next = NULL;
    return newNode;
}

void initialize_array(Node** array, int size) {
    for (int i = 0; i < size - 1; i++) {
        array[i] = create_node(i + 1, (i % 2 == 0) ? 0 : 1);
        array[i]->next = array[i + 1];
    }
    array[size - 1] = create_node(size, (size % 2 == 0) ? 0 : 1);
    array[size - 1]->next = NULL;
}

void insert_node(Node** head, int key, int type, int position) {
    Node* newNode = create_node(key, type);
    if (position == 0) {
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* current = *head;
        for (int i = 0; i < position - 1 && current != NULL; i++) {
            current = current->next;
        }
        if (current != NULL) {
            newNode->next = current->next;
            current->next = newNode;
        } else {
            printf("Invalid position\n");
        }
    }
}

void delete_node(Node** head, int key) {
    Node* current = *head;
    Node* previous = NULL;

    if (current != NULL && current->key == key) {
        *head = current->next;
        free(current);
        return;
    }

    while (current != NULL && current->key != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("Node not found\n");
        return;
    }

    previous->next = current->next;
    free(current);
}

void traverse_forward(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%d -> ", current->key);
        current = current->next;
    }
    printf("NULL\n");
}

void traverse_backward(Node* tail) {
    if (tail == NULL) {
        return;
    }

    traverse_backward(tail->next);
    printf("%d -> ", tail->key);

    // Optional: To handle the last node without double arrow
    if (tail->next != NULL) {
        printf("NULL\n");
    }
}

int main() {
    int size = 5;
    Node* array[size];
    initialize_array(array, size);

    printf("Forward Traversal: ");
    traverse_forward(array[0]);

    insert_node(&array[0], 10, 1, 2);
    printf("\nAfter Insertion at position 2: ");
    traverse_forward(array[0]);

    delete_node(&array[0], 3);
    printf("\nAfter Deletion of key 3: ");
    traverse_forward(array[0]);

    Node* tail = array[size - 1];
    printf("\nBackward Traversal: ");
    traverse_backward(tail);

    return 0;
}
