    const elements = traverseDOMTree(document.body, selector);
    return elements;
  } catch (error) {
    console.error('Authentication failed:', error);
    throw error;
  }
}

function traverseDOMTree(element, selector) {
  let matches = [];
  if (element.matches(selector)) {
    matches.push(element);
  }
  for (let child of element.children) {
    matches = matches.concat(traverseDOMTree(child, selector));
  }
  return matches;
}
