#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 50000
#define LOAD_FACTOR 0.7

typedef struct record {
    int id;
    double value;
    char name[256];
} Record;

typedef struct node {
    Record *data;
    struct node *prev, *next;
} Node;

typedef struct hash_table {
    Node **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table() {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->capacity = MAX_RECORDS / LOAD_FACTOR + 1;
    ht->buckets = (Node**)calloc(ht->capacity, sizeof(Node*));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }
    ht->size = 0;
    pthread_mutex_init(&ht->lock, NULL);

    return ht;
}

void destroy_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        Node *curr = ht->buckets[i];
        while (curr) {
            Node *next = curr->next;
            free(curr->data);
            free(curr);
            curr = next;
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

size_t hash_function(int key, size_t capacity) {
    return ((key * 2166136261u) >> (32 - (int)(log2(capacity)))) % capacity;
}

void insert_record(HashTable *ht, Record *record) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(record->id, ht->capacity);

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&ht->lock);
        return;
    }
    new_node->data = record;
    new_node->prev = NULL;
    new_node->next = ht->buckets[index];

    if (ht->buckets[index]) {
        ht->buckets[index]->prev = new_node;
    }
    ht->buckets[index] = new_node;

    ++ht->size;
    pthread_mutex_unlock(&ht->lock);
}

Record* find_record(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key, ht->capacity);
    Node *curr = ht->buckets[index];

    while (curr && curr->data->id != key) {
        curr = curr->next;
    }

    Record *result = (curr) ? curr->data : NULL;
    pthread_mutex_unlock(&ht->lock);
    return result;
}

void delete_record(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key, ht->capacity);
    Node *curr = ht->buckets[index];

    while (curr && curr->data->id != key) {
        curr = curr->next;
    }

    if (curr) {
        if (curr->prev) {
            curr->prev->next = curr->next;
        } else {
            ht->buckets[index] = curr->next;
        }
        if (curr->next) {
            curr->next->prev = curr->prev;
        }
        free(curr->data);
        free(curr);

        --ht->size;
    }

    pthread_mutex_unlock(&ht->lock);
}

void log_size(HashTable *ht) {
    printf("Current size: %zu\n", ht->size);
}

void compress_data_structure(HashTable *ht) {
    pthread_mutex_lock(&ht->lock);
    // Compression logic here
    pthread_mutex_unlock(&ht->lock);
}

void* serialize_data_structure(void *arg) {
    HashTable *ht = (HashTable*)arg;
    FILE *file = fopen("data.bin", "wb");
    if (!file) return NULL;

    fwrite(&ht->size, sizeof(size_t), 1, file);

    pthread_mutex_lock(&ht->lock);
    for (size_t i = 0; i < ht->capacity; ++i) {
        Node *curr = ht->buckets[i];
        while (curr) {
            fwrite(curr->data, sizeof(Record), 1, file);
            curr = curr->next;
        }
    }
    pthread_mutex_unlock(&ht->lock);

    fclose(file);
    return NULL;
}

void deserialize_data_structure(HashTable *ht) {
    FILE *file = fopen("data.bin", "rb");
    if (!file) return;

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    pthread_mutex_lock(&ht->lock);
    for (size_t i = 0; i < ht->capacity; ++i) {
        Node *curr = ht->buckets[i];
        while (curr) {
            Record *record = curr->data;
            fread(record, sizeof(Record), 1, file);
            curr = curr->next;
        }
    }
    pthread_mutex_unlock(&ht->lock);

    fclose(file);
}
