#define MAX_INTS 10000

int* read_integers() {
    int *ints = malloc(MAX_INTS * sizeof(int));
    if (ints == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    char line[256];
    printf("Enter integers separated by spaces: ");
    fgets(line, sizeof(line), stdin);
    int count = 0;
    char *token = strtok(line, " ");
    while (token != NULL && count < MAX_INTS) {
        ints[count] = atoi(token);
        count++;
        token = strtok(NULL, " ");
    }
    if (count >= MAX_INTS) {
        fprintf(stderr, "Too many integers entered. Maximum allowed: %d\n", MAX_INTS);
        exit(EXIT_FAILURE);
    }
    return ints;
}

int find_largest(int *ints, int count) {
    int largest = ints[0];
    for (int i = 1; i < count; i++) {
        if (ints[i] > largest) {
            largest = ints[i];
        }
    }
    return largest;
}

int main() {
    int *ints = read_integers();
    int count = strlen(ints);
    int largest = find_largest(ints, count);
    printf("Largest integer: %d\n", largest);
    free(ints);
    return 0;
}
