EVP_CIPHER* processCipherAndValidateToken(const char* cipherOption, const char* jsonStr) {
    EVP_CIPHER* cipher = NULL;
    if (strcmp(cipherOption, "ECB") == 0) {
        cipher = EVP_aes_128_ecb();
    } else if (strcmp(cipherOption, "EDE") == 0) {
        cipher = EVP_aes_128_cbc();
    } else if (strcmp(cipherOption, "EDE3") == 0) {
        cipher = EVP_aes_192_cbc();
    } else if (strcmp(cipherOption, "CFB") == 0) {
        cipher = EVP_aes_256_cfb128();
    } else if (strcmp(cipherOption, "NULL") == 0) {
        return NULL; // Null encryption
    }

    json_object* jsonObj = json_tokener_parse(jsonStr);
    if (!jsonObj || !json_is_object(jsonObj)) {
        return NULL; // Invalid JSON object
    }

    json_object* accessToken;
    if (json_object_object_get_ex(jsonObj, "access_token", &accessToken) && json_is_string(accessToken)) {
        const char* tokenType;
        json_object* tokenTypeObj;
        if (!json_object_object_get_ex(jsonObj, "token_type", &tokenTypeObj) || !json_is_string(tokenTypeObj)) {
            return NULL; // Missing or invalid token_type
        }
        tokenType = json_object_get_string(tokenTypeObj);
        if (strcmp(tokenType, "Bearer") != 0) {
            return NULL; // Incorrect token_type value
        }

        int expiresIn;
        json_object* expiresObj;
        if (!json_object_object_get_ex(jsonObj, "expires_in", &expiresObj) || !json_is_int(expiresObj)) {
            return NULL; // Missing or invalid expires_in
        }
        expiresIn = json_object_get_int(expiresObj);
        if (expiresIn <= 0) {
            return NULL; // Non-positive expires_in value
        }

        json_object* refreshToken;
        json_object_object_get_ex(jsonObj, "refresh_token", &refreshToken); // Optional field

        return cipher;
    } else {
        return NULL; // Missing or invalid access_token
    }
}
