['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct SemaphorePool {
    sem_t *semas;
    int num_semas;
    int max_active;
    pthread_mutex_t lock;
} SemaphorePool;

SemaphorePool* create_semaphore_pool(int num_semas, int init_value, int max_active) {
    SemaphorePool *pool = (SemaphorePool*)malloc(sizeof(SemaphorePool));
    pool->semas = (sem_t*)malloc(num_semas * sizeof(sem_t));
    pool->num_semas = num_semas;
    pool->max_active = max_active;
    pthread_mutex_init(&pool->lock, NULL);
    for (int i = 0; i < num_semas; i++) {
        sem_init(&pool->semas[i], 0, init_value);
    }
    return pool;
}

void destroy_semaphore_pool(SemaphorePool *pool) {
    for (int i = 0; i < pool->num_semas; i++) {
        sem_destroy(&pool->semas[i]);
    }
    free(pool->semas);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void acquire_semaphore(SemaphorePool *pool, int index) {
    pthread_mutex_lock(&pool->lock);
    while (sem_getvalue(&pool->semas[index], NULL) <= 0 || pool->max_active == get_current_usage(pool)) {
        // Wait for the semaphore to be available or until there is capacity
    }
    sem_wait(&pool->semas[index]);
    pthread_mutex_unlock(&pool->lock);
}

void release_semaphore(SemaphorePool *pool, int index) {
    pthread_mutex_lock(&pool->lock);
    sem_post(&pool->semas[index]);
    pthread_mutex_unlock(&pool->lock);
}

int get_current_usage(SemaphorePool *pool) {
    int usage = 0;
    for (int i = 0; i < pool->num_semas; i++) {
        int value;
        sem_getvalue(&pool->semas[i], &value);
        usage += pool->num_semas - value;
    }
    return usage;
}

int is_semaphore_available(SemaphorePool *pool, int index) {
    int value;
    sem_getvalue(&pool->semas[index], &value);
    return value > 0 && get_current_usage(pool) < pool->max_active;
}
