    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indications(int n, int min_data_rate, int max_data_rate, double probability_range, int* count_set_crcflag) {
    if (n > MAX_ELEMENTS || min_data_rate < MIN_DATA_RATE || max_data_rate > MAX_DATA_RATE || probability_range <= 0 || probability_range >= 1) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    double current_probability = TARGET_RATIO + (probability_range / 2);
    int set_crcflag_count = 0;

    for (int i = 0; i < n; i++) {
        array[i].ue_info.rx_ue_information_tag = rand() % 1000;
        array[i].ue_info.rnti = rand() % 65535;
        if ((double)rand() / RAND_MAX < current_probability) {
            array[i].crc_indication.crc_flag = 1;
            set_crcflag_count++;
        } else {
            array[i].crc_indication.crc_flag = 0;
        }
    }

    *count_set_crcflag = set_crcflag_count;

    // Dynamic adjustment of probability if observed ratio deviates significantly from target
    double observed_ratio = (double)set_crcflag_count / n;
    if (observed_ratio > TARGET_RATIO + PROBABILITY_RANGE) {
        current_probability -= PROBABILITY_RANGE / 2;
    } else if (observed_ratio < TARGET_RATIO - PROBABILITY_RANGE) {
        current_probability += PROBABILITY_RANGE / 2;
    }

    return array;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T* array, int n) {
    free(array);
}

