    NFAPI_CRC_INDICATION_PDU_T* crc_indications = create_crc_indications(5000, 1000, 2000, 0.05, &count_set_crcflag);

    if (crc_indications) {
        printf("Number of structures with set CRCFLAG: %d\n", count_set_crcflag);
        free_crc_indications(crc_indications, 5000);
    }

    return 0;
}
