<?php
session_start();

function authenticateUser($clientId, $clientSecret, $redirectUri, $code) {
    // Set up the cURL session to fetch access token from OAuth server
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, "https://oauth.example.com/token");
    curl_setopt($ch, CURLOPT_POST, 1);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query([
        'grant_type' => 'authorization_code',
        'code' => $code,
        'redirect_uri' => $redirectUri
    ]));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

    $response = curl_exec($ch);
    if ($response === false) {
        error_log('cURL Error: ' . curl_error($ch));
        return 'Network failure';
    }

    $responseData = json_decode($response, true);
    if (!isset($responseData['access_token'])) {
        error_log('Invalid token response');
        return 'Invalid credentials';
    }

    // Store access token in session
    $_SESSION['access_token'] = $responseData['access_token'];

    // Fetch user details using the access token
    $chDetails = curl_init();
    curl_setopt($chDetails, CURLOPT_URL, "https://api.example.com/user");
    curl_setopt($chDetails, CURLOPT_HTTPHEADER, [
        'Authorization: Bearer ' . $_SESSION['access_token']
    ]);
    curl_setopt($chDetails, CURLOPT_RETURNTRANSFER, true);

    $detailsResponse = curl_exec($chDetails);
    if ($detailsResponse === false) {
        error_log('cURL Error: ' . curl_error($chDetails));
        return 'Network failure';
    }

    $userDetails = json_decode($detailsResponse, true);
    return $userDetails;
}

// Example usage
$clientId = 'your_client_id';
$clientSecret = 'your_client_secret';
$redirectUri = 'http://yourdomain.com/callback.php';

if (isset($_GET['code'])) {
    $result = authenticateUser($clientId, $clientSecret, $redirectUri, $_GET['code']);
    print_r($result);
} else {
    echo "No code provided.";
}
?>
