    while ((opt = getopt(argc, argv, "c:m:o:")) != -1) {
        switch (opt) {
            case 'c':
                config_file_path = optarg;
                break;
            case 'm':
                print_usage();
                return 0;
            case 'o':
                // Handle output file option
                break;
            default:
                fprintf(stderr, "Invalid option: %c\n", opt);
                return 1;
        }
    }

    if (optind < argc) {
        num_files = argc - optind;
        file_list = argv + optind;
    } else {
        print_usage();
        return 1;
    }

    parse_arguments(argc, argv);

    for (int i = 0; i < num_files; i++) {
        process_file(file_list[i]);
    }

    // Clean up and exit
    free(file_list);
    return 0;
}

