    char source_ip[16];
    char destination_ip[16];
    char protocol_type[5];
} PacketCaptureEvent;

// Function to dynamically construct and initialize an array of packet capture events
PacketCaptureEvent* create_packet_capture_events(size_t num_elements) {
    if (num_elements == 0 || num_elements > 1000000) {
        return NULL; // Handle unexpected input sizes gracefully
    }

    PacketCaptureEvent* events = malloc(num_elements * sizeof(PacketCaptureEvent));
    if (events == NULL) {
        return NULL; // Gracefully handle cases where memory allocation fails
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_elements; ++i) {
        events[i].timestamp = time(NULL);
        events[i].packet_size = rand() % 1500 + 46; // Random packet size between 46 and 1500 bytes
        snprintf(events[i].source_ip, sizeof(events[i].source_ip), "%d.%d.%d.%d",
                 rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        snprintf(events[i].destination_ip, sizeof(events[i].destination_ip), "%d.%d.%d.%d",
                 rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        const char* protocols[] = {"TCP", "UDP"};
        events[i].protocol_type[0] = '\0';
        strncat(events[i].protocol_type, protocols[rand() % 2], sizeof(events[i].protocol_type) - 1);
    }

    return events;
}

// Example usage
int main() {
    size_t num_events = 50000; // Number of packet capture events to create
    PacketCaptureEvent* events = create_packet_capture_events(num_events);

    if (events != NULL) {
        // Process the packet capture events
        free(events); // Free allocated memory when done
    }

    return 0;
}
```

