    fseek(inputFile, 0L, SEEK_END);
    long fileSize = ftell(inputFile);
    fseek(inputFile, 0L, SEEK_SET);

    // Allocate memory for the entire file content
    char* fileContent = (char*)malloc(fileSize + 1);
    if (!fileContent) {
        perror("Failed to allocate memory");
        fclose(inputFile);
        return;
    }

    // Read the entire file into memory
    size_t bytesRead = fread(fileContent, 1, fileSize, inputFile);
    if (bytesRead != fileSize) {
        perror("Failed to read file");
        free(fileContent);
        fclose(inputFile);
        return;
    }
    fileContent[bytesRead] = '\0';

    // Close the input file
    fclose(inputFile);

    // Transform file content based on rules
    char* transformedContent = transformContent(fileContent, rules);
    if (!transformedContent) {
        free(fileContent);
        return;
    }

    // Write transformed content to output file
    FILE* outputFile = fopen(outputFilePath, "wb");
    if (!outputFile) {
        perror("Failed to open output file");
        free(transformedContent);
        free(fileContent);
        return;
    }

    size_t bytesWritten = fwrite(transformedContent, 1, strlen(transformedContent), outputFile);
    if (bytesWritten != strlen(transformedContent)) {
        perror("Failed to write to output file");
    } else {
        printf("Transformation successful. Output written to %s\n", outputFilePath);
    }

    // Close the output file and free allocated memory
    fclose(outputFile);
    free(transformedContent);
