    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)(memory_pool + next_free);
    pthread_mutex_lock(&pool_lock);
    if (next_free + sizeof(NFAPI_CRC_INDICATION_PDU_T) > POOL_SIZE) {
        // Handle memory allocation failure
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }
