        }
    }
}

// Asynchronous processing using pthreads
typedef struct {
    int UE_connection_id;
    NFAPI_CRC_INDICATION_PDU_T* pdu;
} AsyncData;

void* process_pdu(void* arg) {
    AsyncData* data = (AsyncData*)arg;
    // Simulate processing the PDU
    printf("Processing PDU for UE connection %d\n", data->UE_connection_id);
    // Perform necessary actions based on PDU data

    // Deallocate memory after processing
    deallocate_pdu(data->pdu);
    free(data);

    return NULL;
}

void create_and_process_async_pdus(int N, int* UE_information_tags, int RNTI) {
    pthread_t threads[N];
    for (int i = 0; i < N; i++) {
        AsyncData* data = (AsyncData*)malloc(sizeof(AsyncData));
        if (data == NULL) {
            printf("Failed to allocate memory for async data\n");
            continue;
        }
        data->UE_connection_id = i;
        data->pdu = allocate_pdu();
        if (data->pdu != NULL) {
            data->pdu->RX_UE_INFORMATION_TAG = UE_information_tags[i];
            data->pdu->RNTI = RNTI;
            data->pdu->CRCFLAG = rand() % 2; // Simplified for demonstration
            data->pdu->CRC_INDICATION_REL8_TAG = 1;

            pthread_create(&threads[i], NULL, process_pdu, (void*)data);
        } else {
            printf("Failed to allocate memory for PDU\n");
            free(data);
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Example usage
int main() {
    int UE_information_tags[] = {1, 2, 3, ..., N}; // Replace with actual data
    int N = sizeof(UE_information_tags) / sizeof(UE_information_tags[0]);
    create_and_populate_pdus(N, UE_information_tags, RNTI);
    create_and_process_async_pdus(N, UE_information_tags, RNTI);

    return 0;
}
