use std::fs;
use std::io::{self, Write};
use std::path::Path;

mod grammar;
mod lexer;
mod parser;
mod config;
mod logging;
mod incremental_parsing;
mod parallel_parsing;
mod caching;
mod validation;
mod integration;

fn generate_llvm_ir(file_path: &str, config: &config::Config) -> io::Result<String> {
    // Validate file path
    if !Path::new(file_path).exists() {
        return Err(io::Error::new(io::ErrorKind::NotFound, "File not found"));
    }

    // Read file content
    let content = fs::read_to_string(file_path)?;

    // Tokenize input
    let tokens = lexer::tokenize(&content);

    // Parse input
    let syntax_tree = parser::parse(&tokens, config.parser_mode)?;

    // Generate LLVM IR
    let llvm_ir = grammar::generate_llvm_ir(&syntax_tree, &config.llvm_settings)?;

    // Log parsing process
    logging::log_parsing_process(&tokens, &syntax_tree);

    // Validate generated LLVM IR
    validation::validate_llvm_ir(&llvm_ir, &validation::ReferenceImplementation)?;

    Ok(llvm_ir)
}
