namespace NetworkMonitoring {

class MonitoringSystem {
public:
    enum class OutputDestination { Console, File };

    struct Config {
        std::vector<int> packetSizeThresholds;
        std::vector<double> flowDurationLimits;
        std::vector<std::string> protocolTypes;
        OutputDestination destination;
    };

    MonitoringSystem(const Config& config) : config_(config), dataQueue_(), outputLock_() {}

    ~MonitoringSystem() = default;

    static MonitoringSystem* getInstance(const Config& config) {
        if (instance_ == nullptr) {
            instance_ = new MonitoringSystem(config);
        }
        return instance_;
    }

    void addPacket(int packetSize, double flowDuration, const std::string& protocol) {
        // Implement logic to handle incoming packets
        // Apply thresholds and limits
        if (isThresholdExceeded(packetSize) || isDurationExceeded(flowDuration) || !isProtocolValid(protocol)) {
            return;
        }

        // Rate limiting and data compression can be applied here

        std::lock_guard<std::mutex> lock(outputLock_);
        outputData(packetSize, flowDuration, protocol);
    }

private:
    static MonitoringSystem* instance_;
    Config config_;
    std::queue<std::tuple<int, double, std::string>> dataQueue_;
    std::mutex outputLock_;

    bool isThresholdExceeded(int packetSize) {
        // Check against packet size thresholds
        return std::find(config_.packetSizeThresholds.begin(), config_.packetSizeThresholds.end(), packetSize) != config_.packetSizeThresholds.end();
    }

    bool isDurationExceeded(double flowDuration) {
        // Check against flow duration limits
        return std::find_if(config_.flowDurationLimits.begin(), config_.flowDurationLimits.end(), [flowDuration](double limit){ return flowDuration > limit; }) != config_.flowDurationLimits.end();
    }

    bool isProtocolValid(const std::string& protocol) {
        // Check against protocol types
        return std::find(config_.protocolTypes.begin(), config_.protocolTypes.end(), protocol) != config_.protocolTypes.end();
    }

    void outputData(int packetSize, double flowDuration, const std::string& protocol) {
        switch (config_.destination) {
            case OutputDestination::Console:
                std::cout << "Packet: " << packetSize << ", Duration: " << flowDuration << ", Protocol: " << protocol << std::endl;
                break;
            case OutputDestination::File:
                // Implement file output logic
                break;
        }
    }
};

MonitoringSystem* MonitoringSystem::instance_ = nullptr;

}  // namespace NetworkMonitoring

int main() {
    NetworkMonitoring::Config config = {
        {100, 200},
        {5.0, 10.0},
        {"TCP", "UDP"},
        NetworkMonitoring::OutputDestination::Console
    };

