['```go
package main

import (
	"context"
	"fmt"
	"net/http"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
)

type Resource struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Value int    `json:"value"`
}

var (
	resourceStore = make(map[string]Resource)
)

func updateResource(w http.ResponseWriter, r *http.Request) {
	id := chi.URLParam(r, "id")
	if _, exists := resourceStore[id]; !exists {
		http.Error(w, "resource not found", http.StatusNotFound)
		return
	}

	var updated Resource
	err := json.NewDecoder(r.Body).Decode(&updated)
	if err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	resourceStore[id] = updated
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(updated)
}

func deleteResource(w http.ResponseWriter, r *http.Request) {
	id := chi.URLParam(r, "id")
	if _, exists := resourceStore[id]; !exists {
		http.Error(w, "resource not found", http.StatusNotFound)
		return
	}

	delete(resourceStore, id)
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(Resource{ID: id})
}

func main() {
	r := chi.NewRouter()
	r.Use(middleware.RequestID)
	r.Use(middleware.RealIP)
	r.Use(middleware.Logger)

	r.Put("/resource/{id}", updateResource)
	r.Delete("/resource/{id}", deleteResource)

	http.ListenAndServe(":8080", r)
}
