using System;
using System.Collections.Concurrent;
using System.Linq;

public class ResourceMetadataService
{
    private ConcurrentDictionary<string, int> resourceCache = new ConcurrentDictionary<string, int>();
    private Random random = new Random();
    private const double LoadFactorThreshold = 0.75;
    private const int MemoryChunkSize = 1024; // Example size

    public bool UpdateResourceMetadata(string resourceId, int versionNumber, int[] updatedMetadata)
    {
        if (!resourceCache.ContainsKey(resourceId))
        {
            return false;
        }

        lock (resourceCache)
        {
            resourceCache[resourceId] = versionNumber;

            if (resourceCache.Count / (double)resourceCache.BucketCount > LoadFactorThreshold)
            {
                CompactHashTable();
            }
        }

        // Notify observers about the update
        OnResourceUpdated(resourceId, versionNumber);

        return true;
    }

    private void CompactHashTable()
    {
        int newBucketCount = resourceCache.BucketCount * 2; // Double the bucket count

        try
        {
            var newHash = new ConcurrentDictionary<string, int>(newBucketCount);
            foreach (var kvp in resourceCache)
            {
                newHash.TryAdd(kvp.Key, kvp.Value);
            }
            resourceCache = newHash;
        }
        catch (OutOfMemoryException)
        {
            // Log error and handle gracefully
            Console.WriteLine("Memory allocation failure during hash table compaction.");
        }
    }

    private void OnResourceUpdated(string resourceId, int versionNumber)
    {
        // Notify observers about the update
        Console.WriteLine($"Resource {resourceId} updated to version {versionNumber}");
    }
}
```

