// Redis client setup
const redisClient = createClient({
  url: process.env.REDIS_URL || 'redis://localhost'
});

async function initRedis() {
  try {
    await redisClient.connect();
  } catch (error) {
    logger.error('Failed to connect to Redis', error);
    throw error;
  }
}

// Caching mechanism using Redis
const cache = new Map();

async function getCachedConfig(filePath) {
  if (!cache.has(filePath)) {
    try {
      const config = await fs.readFile(filePath, 'utf8');
      cache.set(filePath, JSON.parse(config));
    } catch (error) {
      logger.error('Failed to read configuration file', error);
      throw error;
    }
  }
  return cache.get(filePath);
}

async function getConfig(filePath) {
  try {
    const config = await getCachedConfig(filePath);
    logger.info(`Successfully read configuration from ${filePath}`);
    return config;
  } catch (error) {
    logger.error('Error occurred while getting configuration', error);
    throw error;
  }
}

// Initialize Redis client
initRedis();

module.exports = getConfig;
