async function runTestsAsync(moduleName, testCases, envConfig) {
  const { numWorkers = 1 } = envConfig;
  let workers = [];

  // Initialize workers if using concurrency
  if (numWorkers > 1) {
    for (let i = 0; i < numWorkers; i++) {
      workers.push(new Worker('test-worker.js'));
    }
  }

  for (const testCase of testCases) {
    try {
      const module = await import(moduleName);
      blueslip.reset(); // Reset mocking library before each test
      let results;

      if (numWorkers > 1) {
        results = await Promise.all(workers.map(worker => {
          return new Promise((resolve, reject) => {
            worker.onmessage = event => resolve(event.data);
            worker.onerror = error => reject(error);
            worker.postMessage({ testCase, module });
          });
        }));
      } else {
        results = [testCase(module)];
      }

      // Log test results
      for (const result of results) {
        if (result.pass) {
          console.log(`Test passed: ${result.description}`);
        } else {
          console.error(`Test failed: ${result.description}`);
        }
      }
    } catch (error) {
      console.error(`Error in running tests for module ${moduleName}:`, error);
    }
  }

  // Close workers if initialized
  if (numWorkers > 1) {
    workers.forEach(worker => worker.terminate());
  }
}
