const fetch = require('node-fetch');
const neo4j = require('neo4j-driver');

// Regular expressions to match book names in the text
const oldTestamentRegex = /(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1\s*Samuel|2\s*Samuel|1\s*Kings|2\s*Kings|1\s*Chronicles|2\s*Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song\s*of\s*Songs|Isaiahu|Jeremiah|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariahh|Malachi)/gi;
const newTestamentRegex = /(?:Matthew|Mark|Luke|John|Acts|Romans|1\s*Corinthians|2\s*Corinthians|Galatians|Ephesians|Philippians|Colossians|1\s*Thessalonians|2\s*Thessalonians|1\s*Timothy|2\s*Timothy|Titus|Philemon|Hebrews|James|1\s*Peter|2\s*Peter|1\s*John|2\s*John|3\s*John|Jude)/gi;

// External API endpoint for book metadata
const apiEndpoint = 'https://api.example.com/books';

// Neo4j database connection details
const neo4jUri = 'bolt://localhost:7687';
const neo4jUser = 'neo4j';
const neo4jPassword = 'password';

// Function to process text and extract book names
async function extractBookNames(text) {
  const oldTestamentBooks = text.match(oldTestamentRegex);
  const newTestamentBooks = text.match(newTestamentRegex);

  const books = { ...countOccurrences(oldTestamentBooks), ...countOccurrences(newTestamentBooks) };

  return books;
}

// Function to count occurrences of each book name
function countOccurrences(array) {
  const counts = {};
  if (array) {
    array.forEach(book => {
      counts[book] = (counts[book] || 0) + 1;
    });
  }
  return counts;
}

// Function to fetch metadata from external API
async function fetchBookMetadata(books) {
  try {
    const response = await fetch(apiEndpoint);
    const data = await response.json();
    const metadataMap = new Map(data.map(book => [book.name, book]));
    const enrichedBooks = Object.keys(books).reduce((acc, key) => {
      if (metadataMap.has(key)) {
        acc[key] = { ...books[key], ...metadataMap.get(key) };
      }
      return acc;
    }, {});
    return enrichedBooks;
  } catch (error) {
    console.error('Error fetching book metadata:', error);
    return books; // Return original book counts on failure
  }
}

// Function to add vertices and edges to Neo4j graph database
async function addToGraphDatabase(books) {
  const driver = neo4j.driver(neo4jUri, neo4j.auth.basic(neo4jUser, neo4jPassword));
  const session = driver.session();

  try {
    await session.writeTransaction(tx => Promise.all(
      Object.keys(books).map(book => tx.run(
        'CREATE (b:Book {name: $bookName, count: $count})',
        { bookName: book, count: books[book] }
      ))
    ));

    for (let i = 0; i < Math.random() * 100; i++) {
      const fromBook = Object.keys(books)[Math.floor(Math.random() * Object.keys(books).length)];
      const toBook = Object.keys(books)[Math.floor(Math.random() * Object.keys(books).length)];

      await session.writeTransaction(tx => tx.run(
        'MATCH (b1:Book {name: $fromBook}), (b2:Book {name: $toBook}) CREATE (b1)-[:CONNECTED]->(b2)',
        { fromBook, toBook }
      ));
    }

    return true;
  } catch (error) {
    console.error('Error adding books to Neo4j database:', error);
    return false;
  } finally {
    await session.close();
    driver.close();
  }
}

// Main function to process text and update graph
async function processTextAndUpdateGraph(text) {
  const books = await extractBookNames(text);
  const enrichedBooks = await fetchBookMetadata(books);
  const result = await addToGraphDatabase(enrichedBooks);

  return result;
}
```

This code snippet defines a comprehensive function `processTextAndUpdateGraph` that processes a given text to extract book names, fetches metadata from an external API, and updates a Neo4j graph database. It uses regular expressions for book name matching, handles network requests with error management, and performs graph operations while respecting the constraints of the underlying data model."]

