#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_CONNECTIONS 500

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_UE_CONNECTIONS];
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int size;
} PDUQueue;

void init_queue(PDUQueue *queue) {
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

int enqueue(PDUQueue *queue, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size >= MAX_UE_CONNECTIONS) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue is full
    }
    queue->pdus[queue->size++] = pdu;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T *dequeue(PDUQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    NFAPI_CRC_INDICATION_PDU_T *pdu = queue->pdus[--queue->size];
    pthread_mutex_unlock(&queue->lock);
    return pdu;
}

void process_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Simulate processing time
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Process the PDU here

    clock_gettime(CLOCK_MONOTONIC, &end);
    long seconds = end.tv_sec - start.tv_sec;
    long nanoseconds = end.tv_nsec - start.tv_nsec;
    double elapsed = seconds + nanoseconds / 1e9;

    printf("Processed tag %d in %.6f seconds\n", pdu->RX_UE_INFORMATION_TAG, elapsed);
}

void *process_thread(void *arg) {
    PDUQueue *queue = (PDUQueue *)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = dequeue(queue);
        if (pdu == NULL) break; // Exit thread
        process_pdu(pdu);
    }
    return NULL;
}

void start_processing(PDUQueue *queue, int num_threads) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, process_thread, queue);
    }
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    PDUQueue queue;
    init_queue(&queue);

    // Simulate enqueueing PDUs
    srand(time(NULL));
    for (int i = 0; i < 1000; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            printf("Memory allocation failed\n");
            continue;
        }
        pdu->RX_UE_INFORMATION_TAG = rand() % 100;
        pdu->RNTI = rand() & 0xFFFF;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 1000;
        pdu->CRCFLAG = rand() % 2;

        if (enqueue(&queue, pdu) != 0) {
            free(pdu);
        }
    }

    start_processing(&queue, 4);

    return 0;
}
