const { Buffer } = require('buffer');

function copyDataFromChunks(chunks, offset, length) {
  try {
    const targetBuffer = Buffer.alloc(length);
    let bytesWritten = 0;

    for (let i = 0; i < chunks.length && bytesWritten < length; i++) {
      const chunk = chunks[i];
      if (offset >= chunk.length) {
        offset -= chunk.length;
        continue;
      }

      const chunkStart = Math.max(0, offset);
      const chunkEnd = Math.min(chunk.length, offset + length - bytesWritten);
      const chunkCopyLength = chunkEnd - chunkStart;

      chunk.copy(targetBuffer, bytesWritten, chunkStart, chunkEnd);
      bytesWritten += chunkCopyLength;
    }

    if (bytesWritten < length) {
      throw new Error('Insufficient data to fulfill the copy request');
    }

    return targetBuffer;
  } catch (error) {
    console.error('Error copying data from chunks:', error);
    throw error;
  }
}
