// DynamicRandomNumberGenerator.js

const fs = require('fs');
const path = require('path');

class DynamicRandomNumberGenerator {
    constructor() {
        this.mt19937 = new MersenneTwister();
    }

    generateRandomNumber(min, max) {
        return Math.floor(this.mt19937.random() * (max - min + 1)) + min;
    }
}

class MersenneTwister {
    constructor(seed = Date.now()) {
        this.state = new Array(624).fill(0);
        this.index = 0;

        for (let i = 0; i < 624; i++) {
            this.state[i] = seed;
            seed = ((seed ^ (seed >>> 30)) * 1664525) + 1;
        }
    }

    random() {
        if (this.index === 0) {
            this.twist();
        }

        const y = this.state[this.index++];
        y ^= (y >>> 11);
        y ^= ((y << 7) & 0x9d2c5680);
        y ^= ((y << 15) & 0xefc60000);
        y ^= (y >>> 18);

        return (y >>> 0) / 4294967296.0;
    }

    twist() {
        const mag01 = [0, 0x9908b0df];

        for (let i = 0; i < 624; i++) {
            let x = this.state[i] & 0x80000000 | (this.state[(i + 1) % 624] & 0x7fffffff);
            this.state[i] = this.state[(i + 397) % 624] ^ (x >>> 1);
            if (x % 2 !== 0) {
                this.state[i] ^= mag01[1];
            }
        }

        this.index = 0;
    }
}

module.exports = DynamicRandomNumberGenerator;
```

