        return 'Error: Input must be an array of script objects.';
    }

    let html = '';
    for (let scriptObj of scriptObjects) {
        if (typeof scriptObj !== 'object' || !scriptObj.hasOwnProperty('key') || typeof scriptObj.key !== 'string' || 
            !scriptObj.hasOwnProperty('innerHTML') || typeof scriptObj.innerHTML !== 'string') {
            return 'Error: Invalid script object.';
        }
        html += `<script id="${scriptObj.key}">${scriptObj.innerHTML}</script>`;
