    for (int i = 0; i < N; i++) {
        // Populate each structure here
        array[i].CRCFLAG = (rand() / (float)RAND_MAX) < probability;
        if (array[i].CRCFLAG) {
            count_set_crcflag++;
        }
    }

    float achieved_ratio = (float)count_set_crcflag / N;
    printf("Achieved CRCFLAG ratio: %.2f\n", achieved_ratio);

    return array;
}

void *thread_function(void *arg) {
    int thread_id = *(int *)arg;
    // Perform operations using the function here
    free(arg); // Don't forget to free dynamically allocated memory
    pthread_exit(NULL);
}

