        // Check if the clinic's current status is different
        if ($clinicData['status'] !== $newStatus) {
            // Update clinic status in distributed database
            $updateQuery = "UPDATE clinics SET status=:newStatus, last_modified_ip=inet_aton(:lastModifiedIP), last_modified_date=NOW() WHERE clinic_id=:clinicID";
            $stmt = $db->prepare($updateQuery);
            $stmt->bindParam(':newStatus', $newStatus);
            $stmt->bindParam(':lastModifiedIP', $_SERVER['REMOTE_ADDR']);
            $stmt->bindParam(':clinicID', $clinicID);

            if (!$stmt->execute()) {
                throw new Exception("Failed to update clinic status in database.");
            }
        }

        // Commit transaction
        $db->commit();
