<?php

session_start();

function authenticateUser($clientId, $clientSecret, $redirectUri) {
    // Implement session management using Redis for persistence
    $redis = new Redis();
    $redis->connect('127.0.0.1', 6379);

    $accessTokenKey = 'access_token';
    $userInfoKey = 'user_info';

    if (!$redis->exists($accessTokenKey)) {
        // Implement OAuth 2.0 client to fetch access token
        $url = "https://oauth.provider.com/oauth/token";
        $data = [
            'grant_type' => 'authorization_code',
            'code' => $_GET['code'],
            'redirect_uri' => $redirectUri,
            'client_id' => $clientId,
            'client_secret' => $clientSecret
        ];

        $options = [
            'http' => [
                'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
                'method'  => 'POST',
                'content' => http_build_query($data),
            ],
        ];

        $context  = stream_context_create($options);
        $response = file_get_contents($url, false, $context);

        if ($response === FALSE) {
            error_log("OAuth request failed");
            return null;
        }

        $tokenResponse = json_decode($response, true);
        $accessToken = $tokenResponse['access_token'];
        $expiresIn = $tokenResponse['expires_in'];

        // Store access token in Redis with expiration time
        $redis->setex($accessTokenKey, $expiresIn, $accessToken);
    }

    $accessToken = $redis->get($accessTokenKey);

    // Implement OAuth 2.0 client to fetch user information
    $url = "https://oauth.provider.com/userinfo";
    $headers = [
        'Authorization: Bearer ' . $accessToken,
    ];

    $options = [
        'http' => [
            'header'  => implode("\r\n", $headers),
            'method'  => 'GET',
        ],
    ];

    $context  = stream_context_create($options);
    $response = file_get_contents($url, false, $context);

    if ($response === FALSE) {
        error_log("User info request failed");
        return null;
    }

    $userInfo = json_decode($response, true);

    // Store user information in Redis
    $redis->set($userInfoKey, json_encode($userInfo));

    return $userInfo;
}

// Example usage
if (isset($_GET['code'])) {
    $userInfo = authenticateUser('your_client_id', 'your_client_secret', urlencode($_SERVER['REQUEST_URI']));
    if ($userInfo) {
        echo "Authenticated user: " . htmlspecialchars($userInfo['name']);
    } else {
        echo "Authentication failed";
    }
} else {
    // Redirect to OAuth provider for authorization
    $authorizationUrl = "https://oauth.provider.com/authorize?response_type=code&client_id=your_client_id&redirect_uri=" . urlencode($_SERVER['REQUEST_URI']) . "&scope=read%20write";
    header("Location: " . $authorizationUrl);
}
