#include <stdlib.h>
#include <time.h>

typedef struct RX_UE_INFORMATION_TAG {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct FSA_State {
    void* tag;
    struct FSA_State* next;
} FSA_State;

FSA_State* createStateList(int* states, int numStates, FSA_State* fsa, int lastState) {
    if (numStates > 10000) return NULL; // Prevent excessive memory consumption
    FSA_State* head = malloc(sizeof(FSA_State));
    if (!head) return NULL; // Handle memory allocation failure

    srand(time(0)); // Seed for random number generation
    int i;
    for (i = 0; i < numStates; i++) {
        FSA_State* newState = malloc(sizeof(FSA_State));
        if (!newState) {
            // Free previously allocated nodes on error
            while (head != NULL) {
                FSA_State* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        RX_UE_INFORMATION_TAG* ueInfo = malloc(sizeof(RX_UE_INFORMATION_TAG));
        if (!ueInfo) {
            // Free previously allocated nodes and newState on error
            while (head != NULL) {
                FSA_State* temp = head;
                head = head->next;
                free(temp);
            }
            free(newState);
            return NULL;
        }
        ueInfo->RNTI = states[i];

        CRC_INDICATION_REL8_TAG* crcTag = malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!crcTag) {
            // Free previously allocated nodes, newState, and ueInfo on error
            while (head != NULL) {
                FSA_State* temp = head;
                head = head->next;
                free(temp);
            }
            free(newState);
            free(ueInfo);
            return NULL;
        }
        crcTag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        newState->tag = ueInfo;
        newState->next = NULL;

        if (lastState != -1) {
            fsa[lastState].next = newState;
        } else {
            head = newState;
        }
    }

    return head;
}
