#include <iostream>
#include <mutex>
#include <vector>

// Define a custom memory pool class for aligned memory allocation
class MemoryPool {
public:
    MemoryPool(size_t minSize, size_t maxSize) : minSize(minSize), maxSize(maxSize), freeList(nullptr) {}

    ~MemoryPool() {
        while (freeList) {
            MemoryBlock* block = freeList;
            freeList = freeList->next;
            delete[] reinterpret_cast<char*>(block);
        }
    }

    void* allocate(size_t size) {
        if (size < minSize || size > maxSize) return nullptr;

        std::lock_guard<std::mutex> lock(mutex);

        MemoryBlock* block = freeList;
        while (block) {
            if (block->size >= size) {
                freeList = block->next;
                return block->data;
            }
            block = block->next;
        }

        // Allocate new memory block
        size_t blockSize = std::max(size, minSize);
        MemoryBlock* newBlock = reinterpret_cast<MemoryBlock*>(new char[sizeof(MemoryBlock) + blockSize]);
        newBlock->size = blockSize;
        newBlock->data = newBlock->blockStart + sizeof(MemoryBlock);
        newBlock->next = freeList;
        freeList = newBlock;

        return newBlock->data;
    }

    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mutex);

        MemoryBlock* block = reinterpret_cast<MemoryBlock*>(reinterpret_cast<char*>(ptr) - sizeof(MemoryBlock));
        block->next = freeList;
        freeList = block;
    }

private:
    struct MemoryBlock {
        size_t size;
        char* data;
        char* blockStart;
        MemoryBlock* next;
    };

    size_t minSize, maxSize;
    MemoryBlock* freeList;
    std::mutex mutex;
};

