public class RandomValueGenerator
{
    private ConcurrentDictionary<int, int> records = new ConcurrentDictionary<int, int>();
    private Random random = new Random();

    public void AddRange(int key, long offsetMin, long offsetMax, bool isExclusive)
    {
        var rangeSize = isExclusive ? (offsetMax - offsetMin + 1) : (offsetMax - offsetMin);
        if (rangeSize <= 0) throw new ArgumentException("Invalid range");

        for (int i = 0; i < rangeSize; i++)
        {
            records.TryAdd(key + i, random.Next(1, int.MaxValue));
        }
    }

    public int GenerateRandomValue(int key)
    {
