public class DynamicRandomValueGenerator
{
    private ConcurrentDictionary<int, Random> _randomGenerators;
    private ConcurrentBag<LogEntry> _logBuffer;
    private IExternalLoggingService _loggingService;
    private int[] _valueRanges;
    private object _syncLock = new object();

    public DynamicRandomValueGenerator(IExternalLoggingService loggingService)
    {
        _randomGenerators = new ConcurrentDictionary<int, Random>();
        _logBuffer = new ConcurrentBag<LogEntry>();
        _loggingService = loggingService;
        // Initialize other configurations and resources here
    }

    public void GenerateAndLogRandomValues(int key, int count)
    {
        if (!_randomGenerators.TryGetValue(key, out var random))
        {
            random = new Random();
            _randomGenerators.TryAdd(key, random);
        }

        for (int i = 0; i < count; i++)
        {
            int value = random.Next(_valueRanges[0], _valueRanges[1]);
            LogEntry logEntry = new LogEntry(value);
            _logBuffer.Add(logEntry);

            // Integrate with external logging service
            if (_logBuffer.Count >= 100)
            {
                _loggingService.LogEntries(_logBuffer.ToArray());
                _logBuffer.Clear();
            }
        }
    }

    public void AdjustParameters(params int[] newRanges)
    {
        lock (_syncLock)
        {
            _valueRanges = newRanges;
        }
    }

    // Other methods and properties for caching, statistical sampling, configuration management, memory allocation, etc.
}

public class LogEntry
{
    public int Value { get; set; }
    public DateTime Timestamp { get; } = DateTime.Now;

    public LogEntry(int value)
    {
        Value = value;
    }
}

public interface IExternalLoggingService
