typedef struct {
    int *data;
    size_t count;
} RandomValueArray;

RandomValueArray* create_and_initialize_random_values(size_t size, int range_start, int range_end) {
    RandomValueArray *array = (RandomValueArray*)malloc(sizeof(RandomValueArray));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    array->data = (int*)calloc(size, sizeof(int));
    if (!array->data) {
        free(array);
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    array->count = size;

    for (size_t i = 0; i < size; i++) {
        // Generate a random value within the specified range
        array->data[i] = rand() % (range_end - range_start + 1) + range_start;
    }

    return array;
}

void free_random_value_array(RandomValueArray *array) {
    if (array && array->data) {
        free(array->data);
    }
    free(array);
}
