void processConfigFile(const char* inputFile, const char* outputFile, const char* rules, const char* sessionId, int recursive) {
    // Open input file for reading
    FILE* inFile = fopen(inputFile, "rb");
    if (inFile == NULL) {
        perror("Error opening input file");
        return;
    }

    // Dynamically allocate memory for reading the entire file
    fseek(inFile, 0, SEEK_END);
    long fileSize = ftell(inFile);
    fseek(inFile, 0, SEEK_SET);

    char* fileContent = (char*)malloc(fileSize + 1);
    if (fileContent == NULL) {
        perror("Error allocating memory for file content");
        fclose(inFile);
        return;
    }

    size_t bytesRead = fread(fileContent, 1, fileSize, inFile);
    if (bytesRead != fileSize) {
        perror("Error reading input file");
        free(fileContent);
        fclose(inFile);
        return;
    }
    fileContent[bytesRead] = '\0';

    // Close input file
    fclose(inFile);

    // Apply transformation rules to the file content
    char* transformedContent = applyTransformationRules(fileContent, rules, recursive);
    if (transformedContent == NULL) {
        free(fileContent);
        return;
    }

    // Open output file for writing
    FILE* outFile = fopen(outputFile, "w");
    if (outFile == NULL) {
        perror("Error opening output file");
        free(transformedContent);
        free(fileContent);
        return;
    }

    // Write transformed content to output file
    size_t bytesWritten = fwrite(transformedContent, 1, strlen(transformedContent), outFile);
    if (bytesWritten != strlen(transformedContent)) {
        perror("Error writing to output file");
    } else {
        printf("Transformation successful. Output written to %s\n", outputFile);
    }

    // Close output file
    fclose(outFile);

    // Free dynamically allocated memory
    free(transformedContent);
    free(fileContent);
}

