typedef struct UserSession {
    int session_id;
    char user_ip[16];
    time_t start_time;
    time_t end_time;
    char metadata[MAX_METADATA_SIZE];
} UserSession;

typedef struct SessionNode {
    UserSession session;
    struct SessionNode *next;
} SessionNode;

typedef struct SessionList {
    SessionNode *head;
    int size;
} SessionList;

void initSessionList(SessionList *list) {
    list->head = NULL;
    list->size = 0;
}

void addSession(SessionList *list, UserSession session) {
    SessionNode *new_node = (SessionNode *)malloc(sizeof(SessionNode));
    new_node->session = session;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
}

void updateSessionById(SessionList *list, int session_id, UserSession new_session) {
    SessionNode *current = list->head;
    while (current != NULL) {
        if (current->session.session_id == session_id) {
            current->session = new_session;
            return;
        }
        current = current->next;
    }
}

UserSession* findSessionsByIpRange(SessionList *list, const char *start_ip, const char *end_ip) {
    // Implementation for finding sessions by IP range
}

UserSession* findSessionsByTimeRange(SessionList *list, time_t start_time, time_t end_time) {
    // Implementation for finding sessions by time range
}

void archiveOldSessions(SessionList *list, time_t max_age) {
    SessionNode *current = list->head;
    while (current != NULL && current->session.end_time + max_age < time(NULL)) {
        SessionNode *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = current;
    list->size = 0; // Recalculate size
}

void destroySessionList(SessionList *list) {
    while (list->head != NULL) {
        SessionNode *temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
}
