#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <openssl/evp.h>
#include <iostream>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <cstring>

class SecureRandomValueGenerator {
public:
    SecureRandomValueGenerator(const std::string& password, const std::string& salt, int keyRangeStart, int keyRangeEnd, long offsetRangeStart, long offsetRangeEnd)
        : keyRange(keyRangeStart, keyRangeEnd), offsetRange(offsetRangeStart, offsetRangeEnd) {
        if (password.empty() || salt.empty()) throw std::invalid_argument("Password and salt must not be empty");
        generateKey(password, salt);
    }

    ~SecureRandomValueGenerator() {
        cleanup();
    }

    int getRandomRecord(int key) {
        validateKey(key);
        int value;
        generateRandomValue(value, key);
        logAccess(key, value);
        return value;
    }

private:
    std::vector<int> records;
    std::vector<long> offsets;
    std::vector<int> keyRange;
    std::vector<long> offsetRange;
    EVP_CIPHER_CTX* cipherCtx = nullptr;

    void generateKey(const std::string& password, const std::string& salt) {
        unsigned char derivedKey[16];
        PKCS5_PBKDF2_HMAC(password.c_str(), password.size(), reinterpret_cast<const unsigned char*>(salt.c_str()), salt.size(), 4096, EVP_sha256(), sizeof(derivedKey), derivedKey);
        cipherCtx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(cipherCtx, EVP_aes_128_gcm(), nullptr, derivedKey, nullptr);
    }

    void cleanup() {
        if (cipherCtx) {
            EVP_CIPHER_CTX_free(cipherCtx);
            cipherCtx = nullptr;
        }
    }

    void validateKey(int key) const {
        if (key < keyRange[0] || key > keyRange[1]) throw std::out_of_range("Invalid key");
    }

    void generateRandomValue(int& value, int key) {
        unsigned char iv[EVP_MAX_BLOCK_LENGTH];
        RAND_bytes(iv, sizeof(iv));
        EVP_EncryptUpdate(cipherCtx, nullptr, nullptr, reinterpret_cast<const unsigned char*>(&key), sizeof(key));
        EVP_EncryptFinal_ex(cipherCtx, nullptr, nullptr);
        EVP_CIPHER_CTX_ctrl(cipherCtx, EVP_CTRL_GCM_GET_TAG, 16, nullptr);

        unsigned char* randomData = new unsigned char[sizeof(value)];
        RAND_bytes(randomData, sizeof(randomData));
        value = *reinterpret_cast<int*>(randomData);
        delete[] randomData;
    }

    void logAccess(int key, int value) const {
        std::cout << "Key: " << key << ", Value: " << value << std::endl;
    }
};

extern "C" {
    SecureRandomValueGenerator* SecureRandomValueGenerator_new(const char* password, const char* salt, int keyRangeStart, int keyRangeEnd, long offsetRangeStart, long offsetRangeEnd) {
        try {
            return new SecureRandomValueGenerator(password, salt, keyRangeStart, keyRangeEnd, offsetRangeStart, offsetRangeEnd);
        } catch (const std::exception& e) {
            std::cerr << "Error creating SecureRandomValueGenerator: " << e.what() << std::endl;
            return nullptr;
        }
    }

    void SecureRandomValueGenerator_delete(SecureRandomValueGenerator* generator) {
        delete generator;
    }

    int SecureRandomValueGenerator_getRandomRecord(SecureRandomValueGenerator* generator, int key) {
        try {
            return generator->getRandomRecord(key);
        } catch (const std::exception& e) {
            std::cerr << "Error getting random record: " << e.what() << std::endl;
            return -1;
        }
    }
}
```

This code provides a C++ class `SecureRandomValueGenerator` that generates secure random values within specified ranges using AES-128-GCM encryption. It includes methods for generating random records based on keys, logging access for auditing purposes, and error handling for invalid inputs. The class utilizes the OpenSSL library for cryptographic operations and manages resource cleanup to ensure data security. A C function interface is provided for creating and deleting instances of the class and retrieving random records.']

