#define MAX_COMMAND_LENGTH 1024
#define LOG_FILE "execution_log.txt"

void logStatus(const char *status) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log != NULL) {
        fprintf(log, "%s\n", status);
        fclose(log);
    }
}

int executeBackgroundCommand(const char *command) {
    pid_t pid;
    int status;

    // Log start of execution
    logStatus("Starting command execution...");

    // Fork the current process to run the command in the background
    if ((pid = fork()) == -1) {
        logStatus("Failed to create new process.");
        return 0; // Return failure
    } else if (pid == 0) {
        // Child process: Execute the command
        execlp("/bin/sh", "sh", "-c", command, NULL);
        // If execlp fails, fall through and log an error
        logStatus("Failed to execute command.");
        exit(EXIT_FAILURE); // Exit with failure
    } else {
        // Parent process: Wait for the child process to finish
        if (waitpid(pid, &status, 0) == -1) {
            logStatus("Waitpid failed.");
            return 0; // Return failure
        }
        // Check the status of the command execution
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            logStatus("Command executed successfully.");
            return 1; // Command successful
        } else {
            logStatus("Command failed with exit code: %d", WEXITSTATUS(status));
            return 0; // Command failed
        }
    }

    // Return success if reached here (should not happen)
    return 1;
}

int main() {
    const char *command = "sleep 5"; // Example command to run in background
    if (executeBackgroundCommand(command)) {
        printf("Command executed successfully.\n");
    } else {
        printf("Command failed.\n");
    }
    return 0;
}
