public class WebsiteManager
{
    private static readonly object lockObject = new object();
    private static Dictionary<string, DateTime> cache = new Dictionary<string, DateTime>();

    public async Task AddAndStartWebsite(string directoryPath, string siteName)
    {
        lock (lockObject)
        {
            if (!Directory.Exists(directoryPath))
            {
                Log("Error: Directory does not exist.");
                return;
            }
        }

        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            Log("Error: web.config file does not exist.");
            return;
        }

        if (!CheckPermissions(directoryPath))
        {
            Log("Error: Insufficient permissions for the directory.");
            return;
        }

        var configValid = await ValidateConfigurationAsync();
        if (!configValid)
        {
            Log("Error: Configuration validation failed.");
            return;
        }

        Process process = null;
        try
        {
            string serverType = DetectServerType(directoryPath);
            switch (serverType)
            {
                case "IIS":
                    process = new Process { StartInfo = new ProcessStartInfo { FileName = "iisreset", Arguments = $"{directoryPath}", RedirectStandardOutput = true, UseShellExecute = false } };
                    break;
                case "Apache":
                    process = new Process { StartInfo = new ProcessStartInfo { FileName = "apachectl", Arguments = $"-k start -DFOREGROUND", WorkingDirectory = directoryPath, RedirectStandardOutput = true, UseShellExecute = false } };
                    break;
                default:
                    Log("Error: Unsupported web server type.");
                    return;
            }

            process.OutputDataReceived += (sender, e) => Console.WriteLine(e.Data);
            process.Start();
            process.BeginOutputReadLine();

            // Monitor website performance
            await MonitorWebsitePerformance(process.Id);

            Log($"Successfully started {siteName} on {serverType}.");
        }
        catch (Exception ex)
        {
            Log($"Error starting website: {ex.Message}");
        }
        finally
        {
            if (process != null && !process.HasExited)
            {
                process.Kill();
            }
        }
    }

    private bool CheckPermissions(string directoryPath)
    {
        try
        {
            Directory.GetFiles(directoryPath);
            return true;
        }
        catch
        {
            return false;
        }
    }

    private async Task<bool> ValidateConfigurationAsync()
    {
        // Implement API validation logic here with retry logic and exponential backoff
        using (var httpClient = new HttpClient())
        {
            var response = await httpClient.GetAsync("https://api.example.com/validate", HttpCompletionOption.ResponseHeadersRead);
            if (response.IsSuccessStatusCode)
            {
                return true;
            }
            else
            {
                Log($"API validation failed with status code: {response.StatusCode}");
                return false;
            }
        }
    }

    private string DetectServerType(string directoryPath)
    {
        // Implement logic to detect server type based on directory structure
        if (Directory.Exists(Path.Combine(directoryPath, "wwwroot")))
        {
            return "IIS";
        }
        else if (Directory.Exists(Path.Combine(directoryPath, "htdocs")))
        {
            return "Apache";
