['```java
import java.io.*;
import java.util.concurrent.*;
import java.util.zip.GZIPInputStream;
import org.json.*;

public class LogAggregator {
    private final BlockingQueue<String> logQueue = new LinkedBlockingQueue<>();
    private final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private final Map<String, Integer> severityCounts = new ConcurrentHashMap<>();

    public LogAggregator(String configFilePath) {
        // Load and initialize with configuration
        loadLogFiles(configFilePath);
        startProcessing();
    }

    public Future<Map<String, Integer>> aggregateLogsAsync(int maxResults) {
        return executor.submit(() -> {
            try {
                List<Map.Entry<String, Integer>> sortedEntries = new ArrayList<>(severityCounts.entrySet());
                Collections.sort(sortedEntries, (e1, e2) -> e2.getValue().compareTo(e1.getValue()));
                int size = Math.min(maxResults, sortedEntries.size());
                Map<String, Integer> result = new LinkedHashMap<>();
                for (int i = 0; i < size; i++) {
                    result.put(sortedEntries.get(i).getKey(), sortedEntries.get(i).getValue());
                }
                return result;
            } catch (Exception e) {
                throw new RuntimeException("Error processing logs", e);
            }
        });
    }

    private void loadLogFiles(String configFilePath) {
        try (BufferedReader reader = new BufferedReader(new FileReader(configFilePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                File logFile = new File(line.trim());
                if (logFile.exists() && !logFile.isDirectory()) {
                    executor.execute(() -> processLogFile(logFile));
                }
            }
        } catch (IOException e) {
            throw new RuntimeException("Error reading configuration file", e);
        }
    }

    private void processLogFile(File logFile) {
        try (GZIPInputStream gzipIn = new GZIPInputStream(new FileInputStream(logFile));
             BufferedReader reader = new BufferedReader(new InputStreamReader(gzipIn))) {
            String line;
            while ((line = reader.readLine()) != null) {
                JSONObject logEntry = new JSONObject(line);
                String severity = logEntry.getString("severity");
                severityCounts.put(severity, severityCounts.getOrDefault(severity, 0) + 1);
            }
        } catch (IOException | JSONException e) {
            System.err.println("Error processing file " + logFile.getName() + ": " + e.getMessage());
        }
    }

    private void startProcessing() {
        executor.execute(() -> {
            while (true) {
                try {
                    String file = logQueue.take();
                    processLogFile(new File(file));
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}
