```javascript
async function loadScript(url) {
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = url;
    script.onload = resolve;
    script.onerror = reject;
    document.head.appendChild(script);
  });
}

async function fetchScripts(urls) {
  for (const url of urls) {
    try {
      await loadScript(url);
    } catch (error) {
      console.error(`Failed to load script: ${url}`, error);
    }
  }
}

function serializeData(data) {
  return JSON.stringify(data, null, 2);
}

async function fetchAndSerialize(urls, cache) {
  const serializedData = {};
  for (const url of urls) {
    if (cache.has(url)) {
      console.log(`Using cached data for ${url}`);
      Object.assign(serializedData, cache.get(url));
    } else {
      try {
        const response = await fetch(url);
        const scriptText = await response.text();
        const content = eval(scriptText); // Be cautious with eval
        serializedData[url] = serializeData(content);
        cache.set(url, { [url]: serializedData[url] });
      } catch (error) {
        console.error(`Failed to load and serialize data for ${url}`, error);
      }
    }
  }
  return JSON.stringify(serializedData, null, 2);
}

async function main() {
  const urls = [
    'http://example.com/script1.js',
    'http://example.com/script2.js'
  ];

  const cache = new Map();

  try {
    await fetchScripts(urls);
    const serializedData = await fetchAndSerialize(urls, cache);
    console.log('Serialized Data:', serializedData);
  } catch (error) {
    console.error('Error during main process:', error);
  }
}

main();
```

