const request = require('request');
const fs = require('fs');
const childProcess = require('child_process');
const Promise = require('bluebird');

function handleFileUploadAndCommand(fileUrl, shellCommand) {
    return new Promise((resolve, reject) => {
        // Step 1: Download the file
        const downloadFile = (url) => {
            return new Promise((resolve, reject) => {
                request.head(url, (err, res, body) => {
                    if (err) return reject(err);
                    if (parseInt(res.headers['content-length'], 10) > 10 * 1024 * 1024)
                        return reject(new Error('File size exceeds the limit of 10 MB'));

                    const file = fs.createWriteStream('/tmp/tempfile');
                    request(url).pipe(file);

                    file.on('finish', () => {
                        file.close(resolve);
                    });

                    file.on('error', (err) => {
                        fs.unlink('/tmp/tempfile'); // Clean up the file
                        reject(err);
                    });
                });
            });
        };

        // Step 2: Execute shell command
        const executeCommand = (command) => {
            return new Promise((resolve, reject) => {
                childProcess.exec(command, { timeout: 5000 }, (error, stdout, stderr) => {
                    if (error) {
                        console.error(`Execution failed: ${error.message}`);
                        reject(error);
                    } else {
                        resolve({ stdout, stderr });
                    }
                });
            });
        };

        // Sequentially handle file download and command execution
        downloadFile(fileUrl)
            .then((filePath) => {
                const output = executeCommand(shellCommand);
                output.then(resolve).catch(reject);
            })
            .catch(reject);
    }).then((result) => {
        return { uploadedFileUrl: fileUrl, commandOutput: result };
    }).catch((error) => {
        console.error('Error during file upload or command execution:', error);
        throw error;
    });
}
