const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');
const express = require('express');
const bodyParser = require('body-parser');
const rateLimit = require('express-rate-limit');
const axios = require('axios');

const app = express();
app.use(bodyParser.json());

// Define directories
const reportDir = path.join(__dirname, 'reports');
const logsDir = path.join(__dirname, 'logs');

// Ensure directories exist
if (!fs.existsSync(reportDir)) fs.mkdirSync(reportDir);
if (!fs.existsSync(logsDir)) fs.mkdirSync(logsDir);

// Custom command-line utility for generating reports
function generateReport(command) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, { shell: true });

    child.stdout.on('data', (data) => {
      resolve(data.toString());
    });

    child.stderr.on('data', (error) => {
      reject(new Error(error.toString()));
    });
  });
}

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use(limiter);

// Error handling middleware
app.use((err, req, res, next) => {
  if (process.env.NODE_ENV === 'development') {
    res.status(500).json({ error: err.message });
  } else {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Generate report endpoint
app.post('/generate-report', async (req, res) => {
  try {
    const { command } = req.body;
    const output = await generateReport(command);
    const filePath = path.join(reportDir, `report_${Date.now()}.txt`);
    fs.writeFileSync(filePath, output);
    res.json({ message: 'Report generated successfully', file: filePath });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Account recovery endpoint
app.post('/recover-account', async (req, res) => {
  try {
    const { email } = req.body;
    const response = await axios.post('https://email-service-provider.com/send-email', {
      to: email,
      subject: 'Account Recovery',
      body: 'Follow the instructions in the attached link to recover your account.'
    });
    res.json({ message: 'Recovery email sent successfully' });
  } catch (error) {
    res.status(500).json({ error: 'Failed to send recovery email' });
  }
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
