use std::fs;
use std::path::{Path, PathBuf};
use serde_json::Value;
use log::{info, error, warn, LevelFilter};
use actix_web::{web, App, HttpResponse, HttpServer, Responder};
use tokio::sync::Mutex;

#[derive(Deserialize)]
struct Config {
    directory: String,
    file_name: String,
}

async fn load_config(path: PathBuf) -> Result<Value, Box<dyn std::error::Error>> {
    let content = fs::read_to_string(&path)?;
    Ok(serde_json::from_str(&content)?)
}

async fn health_check(config: web::Data<Mutex<Config>>) -> impl Responder {
    let config = config.lock().await;
    if Path::new(&config.directory).exists() {
        HttpResponse::Ok().body("Healthy")
    } else {
        warn!("Configuration directory does not exist");
        HttpResponse::InternalServerError().body("Unhealthy")
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::builder()
        .filter(None, LevelFilter::Info)
        .target(env_logger::Target::Stdout)
        .init();

    let config_path = PathBuf::from("config.json");
    let config = web::Data::new(Mutex::new(load_config(config_path).await?));

    HttpServer::new(move || {
        App::new()
            .app_data(config.clone())
            .route("/health", web::get().to(health_check))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
