    LogEntry logs[1000];
    int count;
    pthread_mutex_t lock;
} LogBuffer;

LogBuffer buffer;

void init_buffer() {
    buffer.count = 0;
    pthread_mutex_init(&buffer.lock, NULL);
}

void add_log(const char* message, time_t timestamp, const char* metadata) {
    pthread_mutex_lock(&buffer.lock);
    if (buffer.count < sizeof(buffer.logs) / sizeof(buffer.logs[0])) {
        strncpy(buffer.logs[buffer.count].log_message, message, MAX_LOG_SIZE);
        buffer.logs[buffer.count].timestamp = timestamp;
        strncpy(buffer.logs[buffer.count].metadata_tags, metadata, 512);
        buffer.count++;
    }
    pthread_mutex_unlock(&buffer.lock);
}

void* flush_logs(void* arg) {
    while (1) {
        pthread_mutex_lock(&buffer.lock);
        if (buffer.count > 0) {
            for (int i = 0; i < buffer.count; i++) {
                // Code to persist logs to storage
                printf("Persisting log: %s, Timestamp: %ld, Metadata: %s\n",
                       buffer.logs[i].log_message,
                       buffer.logs[i].timestamp,
                       buffer.logs[i].metadata_tags);
            }
            buffer.count = 0;
        }
        pthread_mutex_unlock(&buffer.lock);
        sleep(5); // Flush every 5 seconds
    }
    return NULL;
}

int main() {
    init_buffer();
    pthread_t flush_thread;
    pthread_create(&flush_thread, NULL, flush_logs, NULL);

    // Simulate log ingestion
