typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    float target_ratio;
    float current_ratio;
    size_t memory_limit;
    size_t allocated_memory;
} NFAPI_Crc_Indication_Array_T;

NFAPI_Crc_Indication_Array_T* create_array(size_t initial_capacity, size_t memory_limit) {
    NFAPI_Crc_Indication_Array_T* array = (NFAPI_Crc_Indication_Array_T*)malloc(sizeof(NFAPI_Crc_Indication_Array_T));
    if (!array) return NULL;

    array->head = array->tail = NULL;
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
    array->target_ratio = 0.1f;
    array->current_ratio = 0.0f;
    array->memory_limit = memory_limit;
    array->allocated_memory = 0;

    return array;
}

void destroy_array(NFAPI_Crc_Indication_Array_T* array) {
    Node* current = array->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void insert_element(NFAPI_Crc_Indication_Array_T* array, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&array->lock);

    // Check for memory fragmentation and adjust capacity if necessary
    size_t new_memory = (array->count + 1) * sizeof(Node);
    if (new_memory > array->allocated_memory) {
        if (new_memory > array->memory_limit) {
            // Handle memory limit exceeded
            pthread_mutex_unlock(&array->lock);
            return;
        }
        array->capacity *= 2; // Double the capacity
        array->allocated_memory = new_memory;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&array->lock);
        return;
    }

    new_node->data = data;
    new_node->next = NULL;

    if (!array->head) {
        array->head = array->tail = new_node;
    } else {
        array->tail->next = new_node;
        array->tail = new_node;
    }
    array->count++;

    // Adjust CRCFLAG based on probability threshold
    double random_value = (double)rand() / RAND_MAX;
    if (random_value < array->target_ratio) {
        new_node->data.crc_flag = true;
    } else {
        new_node->data.crc_flag = false;
    }

    pthread_mutex_unlock(&array->lock);
}

