#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    size_t packet_size;
    char source_ip[16];
    char destination_ip[16];
    char protocol_type[4];
    char interface_name[128];
} PacketEvent;

PacketEvent** create_packet_array(int num_interfaces, int max_packets_per_interface) {
    PacketEvent** array = (PacketEvent**)malloc(num_interfaces * sizeof(PacketEvent*));
    if (!array) return NULL;

    for (int i = 0; i < num_interfaces; ++i) {
        array[i] = (PacketEvent*)calloc(max_packets_per_interface, sizeof(PacketEvent));
        if (!array[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; ++j) free(array[j]);
            free(array);
            return NULL;
        }
    }

    return array;
}

void initialize_packet_array(PacketEvent** array, int num_interfaces, int max_packets_per_interface) {
    for (int i = 0; i < num_interfaces; ++i) {
        for (int j = 0; j < max_packets_per_interface; ++j) {
            time(&array[i][j].timestamp);
            array[i][j].packet_size = rand() % 1500 + 46;
            strcpy(array[i][j].source_ip, "192.168.1." + (rand() % 255));
            strcpy(array[i][j].destination_ip, "10.0.0." + (rand() % 255));
            switch (rand() % 3) {
                case 0: strcpy(array[i][j].protocol_type, "TCP"); break;
                case 1: strcpy(array[i][j].protocol_type, "UDP"); break;
                case 2: strcpy(array[i][j].protocol_type, "ICMP"); break;
            }
            snprintf(array[i][j].interface_name, sizeof(array[i][j].interface_name), "eth%d", rand() % 4);
        }
    }
}

void free_packet_array(PacketEvent** array, int num_interfaces) {
    for (int i = 0; i < num_interfaces; ++i) free(array[i]);
    free(array);
}
