    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
    }
    return ss.str();
}

void traverseDirectory(const fs::path& dirPath, size_t threshold) {
    for (const auto& entry : fs::directory_iterator(dirPath)) {
        if (entry.is_directory()) {
            traverseDirectory(entry.path(), threshold);
        } else {
            auto fileSize = entry.file_size();
            if (fileSize > threshold) {
                std::thread([=]() { processFile(entry.path(), threshold); }).detach();
            }
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <directory_path> <threshold>" << std::endl;
        return 1;
    }

    fs::path dirPath = argv[1];
    size_t threshold = std::stoul(argv[2]);

    traverseDirectory(dirPath, threshold);

    return 0;
}
