#define MAX_CONTEXTS 1024

typedef struct {
    uint16_t rnti;
    uint32_t stmsi;
    uint64_t nas_ue_id;
} LTE_UE_Context;

LTE_UE_Context* ue_contexts[MAX_CONTEXTS];
int context_count = 0;

// Function to add a new UE context
void add_ue_context(uint16_t rnti, uint32_t stmsi, uint64_t nas_ue_id) {
    if (context_count >= MAX_CONTEXTS) return; // Handle overflow

    LTE_UE_Context* new_context = malloc(sizeof(LTE_UE_Context));
    if (!new_context) return; // Handle memory allocation failure

    new_context->rnti = rnti;
    new_context->stmsi = stmsi;
    new_context->nas_ue_id = nas_ue_id;

    ue_contexts[context_count++] = new_context;
}

// Function to update an existing UE context
void update_ue_context(uint16_t rnti, uint32_t stmsi, uint64_t nas_ue_id) {
    for (int i = 0; i < context_count; ++i) {
        if (ue_contexts[i]->rnti == rnti) {
            free(ue_contexts[i]);
            LTE_UE_Context* new_context = malloc(sizeof(LTE_UE_Context));
            if (!new_context) return; // Handle memory allocation failure
            new_context->rnti = rnti;
            new_context->stmsi = stmsi;
            new_context->nas_ue_id = nas_ue_id;
            ue_contexts[i] = new_context;
            break;
        }
    }
}

// Function to delete an existing UE context
void delete_ue_context(uint16_t rnti) {
    for (int i = 0; i < context_count; ++i) {
        if (ue_contexts[i]->rnti == rnti) {
            free(ue_contexts[i]);
            for (int j = i; j < context_count - 1; ++j) {
                ue_contexts[j] = ue_contexts[j + 1];
            }
            --context_count;
            break;
        }
    }
}

// Function to iterate over all UE contexts
void iterate_ue_contexts(void (*callback)(LTE_UE_Context*)) {
    for (int i = 0; i < context_count; ++i) {
        callback(ue_contexts[i]);
    }
}

// Function to validate the integrity of all UE contexts
void validate_ue_contexts() {
    for (int i = 0; i < context_count; ++i) {
        if (!ue_contexts[i]) return; // Handle null pointers
    }
}
