                aes.BlockSize = 128;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                if (!VerifyHmac(ciphertext, hmac))
                    throw new Exception("Invalid HMAC");

                // Determine which key and IV to use based on your logic
                byte[] key = _key1; // Change this logic as needed
                byte[] iv = _iv1;  // Change this logic as needed

                aes.Key = key;
                aes.IV = iv;

                using (var ms = new MemoryStream(ciphertext))
                {
                    using (var cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        return ReadFully(cs);
                    }
                }
            }
        }
        catch
        {
            // Log the exception for debugging purposes
            return null;
        }
    }

    private static bool VerifyHmac(byte[] ciphertext, string hmac)
    {
        using (var hmacSHA256 = HMACSHA256.Create())
        {
            hmacSHA256.Key = Encoding.UTF8.GetBytes("YourHMACKey");
            byte[] computedHmac = hmacSHA256.ComputeHash(ciphertext);
            return Convert.ToBase64String(computedHmac) == hmac;
        }
    }

    private static byte[] ReadFully(Stream input)
    {
        using (var ms = new MemoryStream())
        {
            input.CopyTo(ms);
            return ms.ToArray();
        }
    }
