import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class LogEntryProcessor {

    public static String processLogEntry(String logEntry) {
        if (logEntry == null || logEntry.isEmpty()) {
            return "Invalid input: Log entry cannot be null or empty.";
        }

        try {
            // Normalize the log entry
            String normalizedEntry = normalizeString(logEntry);

            // Truncate to maximum length if necessary
            if (normalizedEntry.length() > 4096) {
                normalizedEntry = normalizedEntry.substring(0, 4096);
            }

            // Generate a unique identifier using SHA-256 hash
            String uniqueIdentifier = generateUniqueIdentifier(normalizedEntry);

            return uniqueIdentifier;
        } catch (Exception e) {
            return "Error processing log entry: " + e.getMessage();
        }
    }

    private static String normalizeString(String input) {
        StringBuilder normalized = new StringBuilder();
        for (char c : input.toCharArray()) {
            if (Character.isLetterOrDigit(c) || c == ' ') {
                normalized.append(Character.toLowerCase(c));
            }
        }
        return normalized.toString();
    }

    private static String generateUniqueIdentifier(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));
        StringBuilder hexString = new StringBuilder();

        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }

        return hexString.toString();
    }

    public static void main(String[] args) {
        // Example usage
        String logEntry = "This is a sample log entry with special characters!@#$$%^&*()_+{}|:<>?";
        System.out.println(processLogEntry(logEntry));
    }
}
