#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MIN_CRC_VALUE 0
#define MAX_CRC_VALUE 1

typedef struct NFAPI_CRC_INDICATION_PDU {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU *next;
    struct NFAPI_CRC_INDICATION_PDU *prev;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (new_node == NULL) {
            printf("Memory allocation failed.\n");
            return head;
        }

        new_node->RX_UE_INFORMATION_TAG = i + 1; // Example tag
        new_node->RNTI = rand() % 1024; // Random RNTI
        new_node->CRCFLAG = (rand() % (MAX_CRC_VALUE - MIN_CRC_VALUE + 1)) + MIN_CRC_VALUE;

        if (head == NULL) {
            head = new_node;
            tail = new_node;
            new_node->next = NULL;
            new_node->prev = NULL;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
            new_node->next = NULL;
        }
    }

    return head;
}

void validate_crc_flags(NFAPI_CRC_INDICATION_PDU_T *head, int min_value, int max_value) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;

    while (current != NULL) {
        if (current->CRCFLAG < min_value || current->CRCFLAG > max_value) {
            printf("Invalid CRCFLAG value: %d\n", current->CRCFLAG);
            // Handle invalid CRCFLAG, e.g., set to default or remove node
        }
        current = current->next;
    }
}

void traverse_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;

    while (current != NULL) {
