}

unsigned char* calculate_md5(const char* str, int length) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX md5;

    if (!MD5_Init(&md5)) {
        printf("Failed to initialize MD5 context\n");
        return NULL;
    }

    if (!MD5_Update(&md5, str, length)) {
        printf("Failed to update MD5 with string data\n");
        return NULL;
    }

    if (!MD5_Final(digest, &md5)) {
        printf("Failed to finalize MD5 computation\n");
        return NULL;
    }

    unsigned char* result = (unsigned char*)malloc(MD5_DIGEST_LENGTH * 2);
    if (!result) {
        printf("Memory allocation failed for MD5 hash\n");
        return NULL;
    }

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf((char*)(result + i * 2), "%02x", digest[i]);
    }

    return result;
}

