#include <stdlib.h>
#include <pthread.h>

#define MIN_CRCFLAG 0
#define MAX_CRCFLAG 1

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
} CRC_LIST;

void generate_crc_linked_list(CRC_LIST *list, int N) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            pthread_mutex_unlock(&list->lock);
            return;
        }
        new_node->RX_UE_INFORMATION_TAG = rand();
        new_node->RNTI = rand() % 4096; // Example RNTI range
        new_node->CRCFLAG = (rand() % (MAX_CRCFLAG - MIN_CRCFLAG + 1)) + MIN_CRCFLAG;
        if (!list->head) {
            list->head = list->tail = new_node;
        } else {
            new_node->prev = list->tail;
            list->tail->next = new_node;
            list->tail = new_node;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void validate_crc_flags(CRC_LIST *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        if (current->CRCFLAG < MIN_CRCFLAG || current->CRCFLAG > MAX_CRCFLAG) {
            // Handle invalid CRCFLAG, e.g., set to a default value or remove the node
            current->CRCFLAG = (MIN_CRCFLAG + MAX_CRCFLAG) / 2;
        }
        current = current->next;
    }
}

void* thread_safe_func(void *arg) {
    CRC_LIST *list = (CRC_LIST *)arg;
    generate_crc_linked_list(list, 100);
    validate_crc_flags(list);
    return NULL;
}
