void process_audio_stream(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    AudioPacketPool pool;
    init_audio_packet_pool(&pool, 1024); // Example initial size

    while (1) {
        pthread_mutex_lock(&lock);
        AudioPacket *packet = allocate_audio_packet(&pool);
        if (!packet) {
            perror("Failed to allocate audio packet");
            pthread_mutex_unlock(&lock);
            break;
        }
        pthread_mutex_unlock(&lock);

        // Read data into the packet
        size_t bytes_read = fread(packet, 1, sizeof(AudioPacket), file);
        if (bytes_read != sizeof(AudioPacket)) {
            deallocate_audio_packet(&pool, packet);
            if (feof(file)) {
                break;
            } else if (ferror(file)) {
                perror("Failed to read audio data");
                deallocate_audio_packet(&pool, packet);
                break;
            }
        }

        // Process the packet
        // ...

        pthread_mutex_lock(&lock);
        deallocate_audio_packet(&pool, packet);
        pthread_mutex_unlock(&lock);
    }

