#include <stdlib.h>
#include <semaphore.h>

typedef struct SemaphorePool {
    sem_t *sems;
    int num_semas;
} SemaphorePool;

SemaphorePool* create_semaphore_pool(int num_semas, int init_value) {
    SemaphorePool *pool = malloc(sizeof(SemaphorePool));
    pool->num_semas = num_semas;
    pool->sems = malloc(num_semas * sizeof(sem_t));
    for (int i = 0; i < num_semas; i++) {
        sem_init(&pool->sems[i], 0, init_value);
    }
    return pool;
}

void destroy_semaphore_pool(SemaphorePool *pool) {
    for (int i = 0; i < pool->num_semas; i++) {
        sem_destroy(&pool->sems[i]);
    }
    free(pool->sems);
    free(pool);
}

int acquire_semaphore(SemaphorePool *pool, int idx) {
    return sem_wait(&pool->sems[idx]);
}

int release_semaphore(SemaphorePool *pool, int idx) {
    return sem_post(&pool->sems[idx]);
}

int get_semaphore_value(SemaphorePool *pool, int idx) {
    int value;
    sem_getvalue(&pool->sems[idx], &value);
    return value;
}
