    struct ACLNode* next;
} ACLNode;

ACLNode* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add an ACL entry to the list (thread-safe)
void addACLEntry(ACLEntry aclEntry) {
    pthread_mutex_lock(&mutex);
    ACLNode* newNode = malloc(sizeof(ACLNode));
    newNode->aclEntry = aclEntry;
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&mutex);
}

// Function to remove an ACL entry from the list (thread-safe)
void removeACLEntry(int userId) {
    pthread_mutex_lock(&mutex);
    ACLNode* current = head;
    ACLNode* previous = NULL;

    while (current != NULL) {
        if (current->aclEntry.userId == userId) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
}

