void transform_and_save(const char* input_file, const char* output_file, const char* rules, const char* session_token) {
    FILE* infile = fopen(input_file, "rb");
    if (!infile) {
        perror("Failed to open input file");
        return;
    }

    // Determine the size of the input file
    fseek(infile, 0, SEEK_END);
    long filesize = ftell(infile);
    fseek(infile, 0, SEEK_SET);

    char* input_data = (char*)malloc(filesize + 1);
    if (!input_data) {
        perror("Failed to allocate memory for input data");
        fclose(infile);
        return;
    }

    size_t bytes_read = fread(input_data, 1, filesize, infile);
    if (bytes_read != filesize) {
        perror("Failed to read input file");
        free(input_data);
        fclose(infile);
        return;
    }
    input_data[filesize] = '\0';

    // Transform data based on rules
    char* transformed_data = apply_rules(input_data, rules);

    // Write transformed data to output file
    FILE* outfile = fopen(output_file, "wb");
    if (!outfile) {
        perror("Failed to open output file");
        free(transformed_data);
        free(input_data);
        fclose(infile);
        return;
    }

    size_t bytes_written = fwrite(transformed_data, 1, strlen(transformed_data), outfile);
    if (bytes_written != strlen(transformed_data)) {
        perror("Failed to write output file");
        free(transformed_data);
        free(input_data);
        fclose(outfile);
        fclose(infile);
        return;
    }

    // Clean up
    free(transformed_data);
    free(input_data);
    fclose outfile);
    fclose infile);
}

