#define MAX_LINE_LENGTH 1024

void process_file(const char *filename, int *total_lines, double *total_length, int *comment_count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file %s\n", filename);
        return;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        (*total_lines)++;
        *total_length += strlen(line);

        if (line[0] == '#') {
            (*comment_count)++;
        }
    }

    fclose(file);
}

void process_files(const char *filenames, int *total_lines, double *total_length, int *comment_count) {
    char *file_list = strdup(filenames);
    char *filename = strtok(file_list, ",");

    while (filename != NULL) {
        process_file(filename, total_lines, total_length, comment_count);
        filename = strtok(NULL, ",");
    }

    free(file_list);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1,file2,...> [--report] [-d <output_directory>]\n", argv[0]);
        return 1;
    }

    const char *filenames = argv[1];
    int total_lines = 0;
    double total_length = 0.0;
    int comment_count = 0;

    process_files(filenames, &total_lines, &total_length, &comment_count);

    if (argc > 2) {
        for (int i = 2; i < argc; i++) {
            if (strcmp(argv[i], "--report") == 0) {
                printf("Total lines: %d\n", total_lines);
                printf("Average line length: %.2f\n", total_length / total_lines);
                printf("Comment count: %d\n", comment_count);
            } else if (strncmp(argv[i], "-d ", 3) == 0) {
                char *output_dir = argv[i] + 3;
                // Handle output directory logic here
                printf("Output directory set to: %s\n", output_dir);
            }
        }
    }

    return 0;
}
