using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public struct UserAccountInfo
{
    public string Username { get; set; }
    public string PasswordHash { get; set; }
    public bool IsLocked { get; set; }
    public DateTime LastLoginAttempt { get; set; }
}

public interface IUserAccountService
{
    Task<bool> RegisterUserAsync(string username, string password);
    Task<bool> LoginAsync(string username, string password);
    Task<bool> LogoutAsync(string username);
    Task<bool> ChangePasswordAsync(string username, string oldPassword, string newPassword);
    Task<string> GenerateRecoveryTokenAsync(string email);
    Task<bool> VerifyRecoveryTokenAsync(string token, string newEmail);
}

public class UserAccountService : IUserAccountService
{
    private readonly ConcurrentDictionary<string, UserAccountInfo> _userAccounts;
    private readonly ConcurrentDictionary<string, DateTime> _loginAttempts;
    private readonly object _lockObject = new object();
    private const int MaxLoginAttempts = 3;
    private const int LockoutDurationMinutes = 15;

    public UserAccountService()
    {
        _userAccounts = new ConcurrentDictionary<string, UserAccountInfo>();
        _loginAttempts = new ConcurrentDictionary<string, DateTime>();
    }

    public async Task<bool> RegisterUserAsync(string username, string password)
    {
        if (_userAccounts.ContainsKey(username))
            return false;

        var user = new UserAccountInfo
        {
            Username = username,
            PasswordHash = await HashPassword(password),
            IsLocked = false
        };

        _userAccounts.TryAdd(username, user);
        Log("User registered", username);
        return true;
    }

    public async Task<bool> LoginAsync(string username, string password)
    {
        if (!_userAccounts.TryGetValue(username, out var user) || user.IsLocked)
            return false;

        lock (_lockObject)
        {
            if (_loginAttempts.ContainsKey(username))
            {
                var lastAttempt = _loginAttempts[username];
                if (DateTime.Now - lastAttempt < TimeSpan.FromMinutes(LockoutDurationMinutes))
                    return false;
            }

            if (!await VerifyPassword(password, user.PasswordHash))
            {
                _loginAttempts.TryAddOrUpdate(username, DateTime.Now, (_, value) => DateTime.Now);
                Log("Login failed", username);

                if (_loginAttempts[username] == DateTime.MinValue)
                    _loginAttempts.TryRemove(username, out _);

                return false;
            }

            _loginAttempts.TryRemove(username, out _);
        }

        user.LastLoginAttempt = DateTime.Now;
        Log("User logged in", username);
        return true;
    }

    public async Task<bool> LogoutAsync(string username)
    {
        if (!_userAccounts.TryGetValue(username, out var user))
            return false;

        // Perform any necessary logout actions
        Log("User logged out", username);
        return true;
    }

    public async Task<bool> ChangePasswordAsync(string username, string oldPassword, string newPassword)
    {
        if (!_userAccounts.TryGetValue(username, out var user) || user.IsLocked)
            return false;

        lock (_lockObject)
        {
            if (!await VerifyPassword(oldPassword, user.PasswordHash))
                return false;
        }

        user.PasswordHash = await HashPassword(newPassword);
        Log("Password changed", username);
        return true;
    }

    public async Task<string> GenerateRecoveryTokenAsync(string email)
    {
        // Implement token generation and emailing logic
        return "GeneratedToken";
    }

    public async Task<bool> VerifyRecoveryTokenAsync(string token, string newEmail)
    {
        // Implement token verification and email validation logic
        return true;
    }

    private static async Task<string> HashPassword(string password)
    {
        using var hasher = System.Security.Cryptography.SHA256.Create();
        return Convert.ToBase64String(hasher.ComputeHash(System.Text.Encoding.UTF8.GetBytes(password)));
    }

    private static async Task<bool> VerifyPassword(string input, string hash)
    {
        return await HashPassword(input) == hash;
    }

    private void Log(string message, string username = null)
    {
        // Implement logging logic
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var userService = new UserAccountService();
        await userService.RegisterUserAsync("user1", "password123");
        await userService.LoginAsync("user1", "password123");
        await userService.LogoutAsync("user1");
        await userService.ChangePasswordAsync("user1", "password123", "newpassword456");
    }
}
