typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t allocated_memory = 0;

bool is_probably_set(float probability) {
    return (rand() / (float)RAND_MAX < probability);
}

void* generate_packets(void* arg) {
    int data_rate = *(int*)arg;
    float target_ratio = 0.10;
    int current_count = 0;

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        pthread_mutex_lock(&mutex);
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        new_node->data.RX_UE_INFORMATION_TAG = rand();
        new_node->data.RNTI = rand() % 65536;
        new_node->data.CRCFLAG = is_probably_set(target_ratio);

        if (new_node->data.CRCFLAG) {
            current_count++;
            target_ratio = ((float)current_count / i + 1.0) * target_ratio - target_ratio;
        }

        new_node->next = head;
        head = new_node;

        pthread_mutex_unlock(&mutex);
    }

    free(arg);
    return NULL;
}

