    pthread_create(&perf_thread, NULL, monitor_performance, NULL);

    pthread_join(packet_thread, NULL);
    pthread_join(perf_thread, NULL);

    Node* current = head;
    while (current) {
        free(current);
        current = current->next;
    }

    return 0;
