typedef union {
    EVP_CIPHER_CTX *cipher_ctx;
    unsigned char ip_address[16];
} DNSResult;

typedef struct {
    AudioPacket *pool;
    size_t pool_size;
    size_t used_packets;
    pthread_mutex_t lock;
} MemoryPool;

void initializeMemoryPool(MemoryPool *pool, size_t initial_size) {
    pool->pool = (AudioPacket *)malloc(initial_size * sizeof(AudioPacket));
    if (!pool->pool) {
        fprintf(stderr, "Failed to allocate memory for audio packet pool.\n");
        exit(EXIT_FAILURE);
    }
    pool->pool_size = initial_size;
    pool->used_packets = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

AudioPacket *allocatePacket(MemoryPool *pool) {
    AudioPacket *packet;
    pthread_mutex_lock(&pool->lock);
    if (pool->used_packets == pool->pool_size) {
        AudioPacket *new_pool = (AudioPacket *)realloc(pool->pool, pool->pool_size * 2 * sizeof(AudioPacket));
        if (!new_pool) {
            fprintf(stderr, "Failed to reallocate memory for audio packet pool.\n");
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->pool = new_pool;
        pool->pool_size *= 2;
    }
    packet = &pool->pool[pool->used_packets++];
    pthread_mutex_unlock(&pool->lock);
    memset(packet, 0, sizeof(AudioPacket));
    return packet;
}

void deallocatePacket(MemoryPool *pool, AudioPacket *packet) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = pool->used_packets - 1; i > 0; --i) {
        if (&pool->pool[i] == packet) {
            memmove(&pool->pool[i], &pool->pool[i + 1], (pool->used_packets - i - 1) * sizeof(AudioPacket));
            break;
        }
    }
    pool->used_packets--;
    pthread_mutex_unlock(&pool->lock);
}

