#include <stdio.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRCFLAG = CRCFLAG;
    new_node->next = NULL;
    new_node->prev = NULL;
    return new_node;
}

void insert_node(NFAPI_CRC_INDICATION_PDU_T** head, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
    if (*head == NULL) {
        *head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
        new_node->prev = temp;
    }
}

void validate_and_update_crcflag(NFAPI_CRC_INDICATION_PDU_T* head, int min_value, int max_value) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        if (current->CRCFLAG < min_value || current->CRCFLAG > max_value) {
            current->CRCFLAG = (min_value + max_value) / 2; // Update to a valid value
        }
        current = current->next;
    }
}

void traverse_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* temp = head;
    while (temp != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", temp->RX_UE_INFORMATION_TAG, temp->RNTI, temp->CRCFLAG);
        temp = temp->next;
    }
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    int num_entries = 100; // Example number of entries

    for (int i = 0; i < num_entries; i++) {
        insert_node(&head, i, i * 10, rand() % 256); // Random CRCFLAG value
    }

    validate_and_update_crcflag(head, 0, 255);

    traverse_list(head);

    free_list(head);

    return 0;
}
