#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct NFAPI_L1_FSM_STATE_T {
    int STATE_ID;
    char* STATE_NAME;
    struct NFAPI_L1_FSM_STATE_T** STATE_TRANSITION_TABLE;
} NFAPI_L1_FSM_STATE_T;

typedef struct StateArray {
    NFAPI_L1_FSM_STATE_T** states;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} StateArray;

StateArray* create_state_array() {
    StateArray* array = (StateArray*)malloc(sizeof(StateArray));
    if (!array) return NULL;

    array->states = (NFAPI_L1_FSM_STATE_T**)calloc(INITIAL_CAPACITY, sizeof(NFAPI_L1_FSM_STATE_T*));
    if (!array->states) {
        free(array);
        return NULL;
    }

    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_state_array(StateArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->states[i]->STATE_NAME);
        free(array->states[i]->STATE_TRANSITION_TABLE);
        free(array->states[i]);
    }

    pthread_mutex_destroy(&array->lock);
    free(array->states);
    free(array);
}

int add_state(StateArray* array, int state_id, const char* state_name) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_L1_FSM_STATE_T** new_states = (NFAPI_L1_FSM_STATE_T**)realloc(array->states, new_capacity * sizeof(NFAPI_L1_FSM_STATE_T*));
        if (!new_states) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        array->states = new_states;
        array->capacity = new_capacity;
    }

    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->states[i]->STATE_NAME, state_name) == 0) {
            pthread_mutex_unlock(&array->lock);
            return -2; // Duplicate state name
        }
    }

    NFAPI_L1_FSM_STATE_T* new_state = (NFAPI_L1_FSM_STATE_T*)malloc(sizeof(NFAPI_L1_FSM_STATE_T));
    if (!new_state) {
        pthread_mutex_unlock(&array->lock);
        return -3;
    }

    new_state->STATE_ID = state_id;
    new_state->STATE_NAME = strdup(state_name);
    if (!new_state->STATE_NAME) {
        free(new_state);
        pthread_mutex_unlock(&array->lock);
        return -4;
    }

    new_state->STATE_TRANSITION_TABLE = (NFAPI_L1_FSM_STATE_T**)calloc(array->capacity, sizeof(NFAPI_L1_FSM_STATE_T*));
    if (!new_state->STATE_TRANSITION_TABLE) {
        free(new_state->STATE_NAME);
        free(new_state);
        pthread_mutex_unlock(&array->lock);
        return -5;
    }

    array->states[array->size++] = new_state;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

void iterate_forward(StateArray* array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        printf("State ID: %d, State Name: %s\n", array->states[i]->STATE_ID, array->states[i]->STATE_NAME);
    }

    pthread_mutex_unlock(&array->lock);
}

void iterate_backward(StateArray* array) {
    pthread_mutex_lock(&array->lock);

    for (ssize_t i = array->size - 1; i >= 0; --i) {
        printf("State ID: %d, State Name: %s\n", array->states[i]->STATE_ID, array->states[i]->STATE_NAME);
    }

    pthread_mutex_unlock(&array->lock);
}
