    MAC_PDU *pdus;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} MacPduList;

void initMacPduList(MacPduList *list) {
    list->pdus = (MAC_PDU *)malloc(INIT_CAPACITY * sizeof(MAC_PDU));
    if (!list->pdus) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = INIT_CAPACITY;
    pthread_mutex_init(&list->mutex, NULL);
}

void resizeMacPduList(MacPduList *list) {
    size_t new_capacity = list->capacity * 2;
    MAC_PDU *new_pdus = (MAC_PDU *)realloc(list->pdus, new_capacity * sizeof(MAC_PDU));
    if (!new_pdus) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    list->pdus = new_pdus;
    list->capacity = new_capacity;
}

void addMacPduToList(MacPduList *list, MAC_PDU pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        resizeMacPduList(list);
    }
    list->pdus[list->size++] = pdu;
    pthread_mutex_unlock(&list->mutex);
}

