    for (size_t i = 0; i < list->size; ++i) {
        if (list->pdus[i].sequence_number == sequence_number) {
            return &list->pdus[i];
        }
    }
    return NULL;
}

void destroyMacPduList(MacPduList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->pdus);
    list->pdus = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
