#define MAX_SIZE 1024

typedef struct {
    int enabled;
    void (*log)(const char*);
} LogChannel;

void defaultLog(const char* message) {
    printf("LOG: %s\n", message);
}

void noOpLog(const char*) {}

void processStringAdvanced(
    const char* input,
    size_t sizeLimit,
    int logFlag,
    void (*callback)(const char*),
    LogChannel* logChannel
) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static int callCount = 0;
    static struct timespec startTime, endTime;

    if (logFlag == 1 && logChannel->enabled) {
        clock_gettime(CLOCK_MONOTONIC, &startTime);
    }

    pthread_mutex_lock(&mutex);

    if (!input || sizeLimit < 1 || sizeLimit > MAX_SIZE) {
        char* errorMessage = "Invalid input or size limit";
        if (logFlag == 1 && logChannel->enabled) {
            logChannel->log(errorMessage);
        }
        pthread_mutex_unlock(&mutex);
        return;
    }

    size_t len = strlen(input);
    if (len >= sizeLimit - 1 || input[len] != '\0') {
        char* result = malloc(2); // Empty string
        if (!result) {
            if (logFlag == 1 && logChannel->enabled) {
                logChannel->log("Memory allocation failed");
            }
            pthread_mutex_unlock(&mutex);
            return;
        }
        result[0] = '\0';
        if (len < sizeLimit - 1) {
            result = realloc(result, len + 2); // Add space for slash and null terminator
            if (!result) {
                if (logFlag == 1 && logChannel->enabled) {
                    logChannel->log("Memory reallocation failed");
                }
                pthread_mutex_unlock(&mutex);
                return;
            }
            strcpy(result, input);
            result[len] = '/';
            result[len + 1] = '\0';
        }
        if (callback && strlen(input) > 50) { // Example threshold
            callback(result);
        }
        free(result);
    }

    pthread_mutex_unlock(&mutex);

    if (logFlag == 1 && logChannel->enabled) {
        clock_gettime(CLOCK_MONOTONIC, &endTime);
        double duration = (endTime.tv_sec - startTime.tv_sec) + (endTime.tv_nsec - startTime.tv_nsec) / 1e9;
        printf("Function called %d times. Total time: %.6f seconds\n", ++callCount, duration);
    }
}

void callbackExample(const char* processedString) {
    printf("Processed String: %s\n", processedString);
}

int main() {
    LogChannel log = {1, &defaultLog};
    const char* testInput = "Hello, World!";
    processStringAdvanced(testInput, 20, 1, callbackExample, &log);
    return 0;
}
