    MAC_HEADER header;
    MAC_PAYLOAD payload;
    uint32_t sequenceNumber;
} MAC_PDU;

typedef struct {
    MAC_PDU *pduList;
    size_t capacity;
    size_t count;
    sem_t lock;
    pthread_mutex_t mutex;
} PDU_LIST;

void initPDUList(PDU_LIST *list, size_t initialCapacity) {
    list->capacity = initialCapacity;
    list->count = 0;
    list->pduList = (MAC_PDU *)malloc(initialCapacity * sizeof(MAC_PDU));
    if (list->pduList == NULL) {
        // Handle memory allocation error
    }
    sem_init(&list->lock, 0, 1);
    pthread_mutex_init(&list->mutex, NULL);
}

void freePDUList(PDU_LIST *list) {
    free(list->pduList);
    sem_destroy(&list->lock);
    pthread_mutex_destroy(&list->mutex);
}

int addPDUToQueue(PDU_LIST *list, MAC_PDU *newPDU) {
    int result = 0;
    if (list->count >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        MAC_PDU *newList = (MAC_PDU *)realloc(list->pduList, newCapacity * sizeof(MAC_PDU));
        if (newList == NULL) {
            // Handle memory allocation error
            return -1;
        }
        list->pduList = newList;
        list->capacity = newCapacity;
    }

    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->pduList[i].sequenceNumber == newPDU->sequenceNumber) {
            list->pduList[i] = *newPDU;
            result = -1; // Duplicate sequence number, updated existing entry
            break;
        }
    }
    if (result != -1) {
        list->pduList[list->count++] = *newPDU;
        result = 0; // Successfully added new PDU
    }
    pthread_mutex_unlock(&list->mutex);

    return result;
}

MAC_PDU* getPDUBySequenceNumber(PDU_LIST *list, uint32_t sequenceNumber) {
    MAC_PDU *pdu = NULL;
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->pduList[i].sequenceNumber == sequenceNumber) {
            pdu = &list->pduList[i];
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return pdu;
}

// Additional functions for managing concurrent access, error checking, logging,
// and asynchronous messaging can be implemented similarly.
