    pthread_mutex_t lock;
} MAC_LIST;

void init_mac_list(MAC_LIST* list) {
    list->array = (MAC_PDU**)malloc(INITIAL_CAPACITY * sizeof(MAC_PDU*));
    if (!list->array) {
        perror("Failed to allocate memory for MAC_LIST array");
        exit(EXIT_FAILURE);
    }
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void free_mac_list(MAC_LIST* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        free(list->array[i]);
    }
    free(list->array);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void grow_mac_list(MAC_LIST* list) {
    size_t new_capacity = list->capacity * 2;
    if (new_capacity > MAX_CAPACITY) {
        new_capacity = MAX_CAPACITY;
    }
    MAC_PDU** new_array = (MAC_PDU**)realloc(list->array, new_capacity * sizeof(MAC_PDU*));
    if (!new_array) {
        perror("Failed to allocate memory for growing MAC_LIST array");
        exit(EXIT_FAILURE);
    }
    list->array = new_array;
    list->capacity = new_capacity;
}

void add_mac_pdu(MAC_LIST* list, MAC_PDU* pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity - 1) {
        grow_mac_list(list);
    }
    for (size_t i = 0; i < list->size; ++i) {
        if (list->array[i]->sequence_number == pdu->sequence_number) {
            free(pdu);
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }
    list->array[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);
}

MAC_PDU* get_mac_pdu(MAC_LIST* list, int sequence_number) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->array[i]->sequence_number == sequence_number) {
            pthread_mutex_unlock(&list->lock);
            return list->array[i];
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

