PDU_LIST* create_pdu_list() {
    PDU_LIST *list = (PDU_LIST*)malloc(sizeof(PDU_LIST));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    list->capacity = INITIAL_CAPACITY;
    return list;
}

void free_pdu_list(PDU_LIST *list) {
    MAC_PDU *current = list->head;
    while (current) {
        MAC_PDU *temp = current;
        current = current->next;
        free(temp);
    }
    free(list);
}

int add_pdu(PDU_LIST *list, const MAC_HEADER *header, const MAC_PAYLOAD *payload, int sequence_number) {
