        size_t new_capacity = list->capacity < MAX_CAPACITY ? list->capacity * 2 : MAX_CAPACITY;
        // Implement dynamic resizing logic here
    }

    MAC_PDU *new_pdu = (MAC_PDU*)malloc(sizeof(MAC_PDU));
    if (!new_pdu) return -1;
    new_pdu->header = *header;
    new_pdu->payload = *payload;
    new_pdu->sequence_number = sequence_number;
    new_pdu->next = NULL;

    if (list->count == 0) {
        list->head = list->tail = new_pdu;
    } else {
        list->tail->next = new_pdu;
        list->tail = new_pdu;
    }
    list->count++;
    return 0;
}

MAC_PDU* get_pdu_by_sequence(PDU_LIST *list, int sequence_number) {
    MAC_PDU *current = list->head;
    while (current) {
        if (current->sequence_number == sequence_number) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

