#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.8

typedef struct record {
    int value;
    long* offset;
    int* key;
    char** description;
} Record;

typedef struct hash_table_entry {
    Record record;
    struct hash_table_entry* next;
} HashTableEntry;

typedef struct hash_table {
    HashTableEntry** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed for hash table\n");
        exit(EXIT_FAILURE);
    }
    table->buckets = (HashTableEntry**)calloc(INITIAL_CAPACITY, sizeof(HashTableEntry*));
    if (!table->buckets) {
        free(table);
        fprintf(stderr, "Memory allocation failed for hash table buckets\n");
        exit(EXIT_FAILURE);
    }
    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableEntry* entry = table->buckets[i];
        while (entry) {
            HashTableEntry* next = entry->next;
            free(entry->record.offset);
            free(entry->record.key);
            free(entry->record.description);
            free(entry);
            entry = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

size_t hash_function(const Record* record) {
    return *(record->key) % table->capacity;
}

void insert_record(HashTable* table, const Record* record) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(record);
    HashTableEntry* new_entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    if (!new_entry) {
        fprintf(stderr, "Memory allocation failed for hash table entry\n");
        exit(EXIT_FAILURE);
    }
    new_entry->record = *record;
    new_entry->next = table->buckets[index];
    table->buckets[index] = new_entry;
    ++table->size;

    // Check and compact if necessary
    if (table->size >= LOAD_FACTOR_THRESHOLD * table->capacity) {
        compact_hash_table(table);
    }
    pthread_mutex_unlock(&table->lock);
}

void update_record(HashTable* table, const Record* record) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(record);
    HashTableEntry* entry = table->buckets[index];
    while (entry && *entry->record.key != *record->key) {
        entry = entry->next;
    }
    if (entry) {
        // Update the record without reallocating
        entry->record.value = record->value;
        free(entry->record.description);
        entry->record.description = strdup(record->description);
    } else {
        fprintf(stderr, "Record not found for update\n");
    }
    pthread_mutex_unlock(&table->lock);
}

void compact_hash_table(HashTable* table) {
    // Implement compaction logic here
    // This is a placeholder for the actual implementation
    printf("Compacting hash table...\n");
    // Rehash all records to minimize fragmentation and optimize storage
}

int main() {
    HashTable* table = create_hash_table();

    // Example usage
    Record record = {42, (long*)malloc(sizeof(long)), (int*)malloc(sizeof(int)), strdup("Example")};
    *record.offset = 100;
    *record.key = 5;

    insert_record(table, &record);

    update_record(table, &record);

    destroy_hash_table(table);
    return 0;
}
