#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 256
#define CONFIG_FILE "files.txt"
#define LOG_FILE "program.log"

typedef struct {
    char **fields;
    int field_count;
} LineData;

LineData parse_line(char *line) {
    LineData data;
    data.fields = NULL;
    data.field_count = 0;

    char *token = strtok(line, " ");
    while (token != NULL) {
        data.field_count++;
        data.fields = realloc(data.fields, data.field_count * sizeof(char *));
        if (data.fields == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        data.fields[data.field_count - 1] = strdup(token);
        token = strtok(NULL, " ");
    }

    return data;
}

void calculate_average(LineData *data) {
    if (data->field_count < 3) {
        fprintf(stderr, "Invalid line format\n");
        exit(EXIT_FAILURE);
    }

    int last_two_sum = atoi(data->fields[data->field_count - 2]) + atoi(data->fields[data->field_count - 1]);
    int average = last_two_sum / 2;

    char new_average[10];
    snprintf(new_average, sizeof(new_average), "%d", average);

    free(data->fields[data->field_count - 1]);
    data->fields[data->field_count - 1] = strdup(new_average);
}

void output_line(LineData *data) {
    for (int i = 0; i < data->field_count; i++) {
        printf("%s ", data->fields[i]);
    }
    printf("\n");
}

void free_data(LineData *data) {
    for (int i = 0; i < data->field_count; i++) {
        free(data->fields[i]);
    }
    free(data->fields);
}

void log_message(const char *message, int level) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "[%d] %s\n", level, message);
        fclose(log_file);
    }
}

int main() {
    FILE *config_file = fopen(CONFIG_FILE, "r");
    if (config_file == NULL) {
        perror("Failed to open configuration file");
        return EXIT_FAILURE;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, config_file)) {
        LineData data = parse_line(line);
        calculate_average(&data);
        output_line(&data);
        free_data(&data);

        log_message("Processed line", 1);
    }

    fclose(config_file);
    return EXIT_SUCCESS;
}
