<?php

class GraphDatabaseManager {
    private $graphDb;
    private $cache = [];
    private $retryLimit = 3;
    private $backoffInterval = 100;

    public function __construct($graphDb) {
        $this->graphDb = $graphDb;
    }

    public function generateRandomString($length, $charset) {
        if (isset($this->cache[$length])) {
            return $this->cache[$length];
        }
        $string = '';
        for ($i = 0; $i < $length; $i++) {
            $string .= $charset[rand(0, strlen($charset) - 1)];
        }
        $this->cache[$length] = $string;
        return $string;
    }

    public function addVerticesAndEdges($numVertices, $vertexCharset, $edgeCharset, $weights) {
        if ($numVertices > 1000 || count($edges) > 5000) {
            throw new Exception("Maximum number of vertices and edges exceeded");
        }
        $properties = [];
        for ($i = 0; $i < $numVertices; $i++) {
            $propValue = $this->generateRandomString(10, $vertexCharset);
            if (in_array($propValue, $properties)) {
                throw new Exception("Redundant vertex property value");
            }
            $properties[] = $propValue;
            $vertexId = 'v' . $i;
            $this->graphDb->addVertex($vertexId, ['property' => $propValue]);
        }

        $edges = [];
        for ($i = 0; $i < count($weights); $i++) {
            $weight = $weights[$i];
            if ($weight == 0) continue;
            while (count($edges) < $weight) {
                $srcVertexId = 'v' . rand(0, $numVertices - 1);
                $dstVertexId = 'v' . rand(0, $numVertices - 1);
                $edgeId = 'e' . count($edges);
                if (!in_array([$srcVertexId, $dstVertexId], $edges)) {
                    $propValue = $this->generateRandomString(10, $edgeCharset);
                    $edges[] = [$srcVertexId, $dstVertexId, $propValue];
                    $this->graphDb->addEdge($edgeId, $srcVertexId, $dstVertexId, ['property' => $propValue]);
                }
            }
        }

        return true;
    }

    public function setRetryLimit($retryLimit) {
        $this->retryLimit = $retryLimit;
    }

    public function setBackoffInterval($backoffInterval) {
        $this->backoffInterval = $backoffInterval;
    }

    private function retryOnFailure(callable $operation, $args) {
        for ($i = 0; $i <= $this->retryLimit; $i++) {
            try {
                return call_user_func_array($operation, $args);
            } catch (Exception $e) {
                if ($i == $this->retryLimit) throw $e;
                usleep($this->backoffInterval * 1000);
            }
        }
    }

    public function addVerticesAndEdgesAsync($numVertices, $vertexCharset, $edgeCharset, $weights) {
        return $this->retryOnFailure([$this, 'addVerticesAndEdges'], [$numVertices, $vertexCharset, $edgeCharset, $weights]);
    }
}

// Usage example
$graphDb = new GraphDatabase(); // Assume this is a valid graph database instance
$manager = new GraphDatabaseManager($graphDb);
$manager->setRetryLimit(5);
$manager->setBackoffInterval(200);

try {
    $manager->addVerticesAndEdgesAsync(50, 'abcdefghijklmnopqrstuvwxyz', '0123456789', [10, 20, 30]);
} catch (Exception $e) {
    echo "Error: " . $e->getMessage();
}
?>
```

