    for (int i = 0; i < N; i++) {
        Node *new_node = malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            continue;
        }
        new_node->data.RX_UE_INFORMATION_TAG = rand() % 1000;
        new_node->data.RNTI = rand() % 1000;
        int crcflag = (rand() % (range_max - range_min + 1)) + range_min;
        if (crcflag < range_min || crcflag > range_max) {
            free(new_node);
            continue; // Skip this node if CRCFLAG is out of range
        }
        new_node->data.CRCFLAG = crcflag;
        new_node->prev = list->tail;
        new_node->next = NULL;
        if (list->tail) {
            list->tail->next = new_node;
        } else {
            list->head = new_node;
        }
        list->tail = new_node;
    }
