typedef struct BufferNode {
    NFAPI_CRC_INDICATION_PDU_T buffer;
    struct BufferNode* next;
} BufferNode;

BufferNode* buffer_pool = NULL;
size_t pool_size = 0;
size_t allocated_count = 0;

void initialize_buffer_pool(size_t initial_size) {
    buffer_pool = (BufferNode*)malloc(initial_size * sizeof(BufferNode));
    if (buffer_pool == NULL) {
        fprintf(stderr, "Failed to allocate initial buffer pool.\n");
        exit(EXIT_FAILURE);
    }
    pool_size = initial_size;
    allocated_count = 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_buffer() {
    if (allocated_count >= pool_size) {
        size_t new_size = (pool_size * 2 <= MAX_BUFFER_POOL_SIZE) ? pool_size * 2 : MAX_BUFFER_POOL_SIZE;
        BufferNode* new_pool = (BufferNode*)realloc(buffer_pool, new_size * sizeof(BufferNode));
        if (new_pool == NULL) {
            fprintf(stderr, "Failed to resize buffer pool.\n");
            exit(EXIT_FAILURE);
        }
        buffer_pool = new_pool;
        pool_size = new_size;
    }

    BufferNode* node = &buffer_pool[allocated_count];
    memset(&node->buffer, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->buffer.crc_indication.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    allocated_count++;
    return &node->buffer;
}

