#include <stdlib.h>
#include <pthread.h>

typedef struct SemaphoreNode {
    int value;
    pthread_mutex_t mutex;
    struct SemaphoreNode *next;
} SemaphoreNode;

typedef struct SemaphoreCollection {
    SemaphoreNode **semaphores;
    size_t capacity;
    size_t count;
    pthread_mutex_t collection_mutex;
} SemaphoreCollection;

SemaphoreCollection* create_semaphore_collection(size_t initial_capacity) {
    SemaphoreCollection *collection = (SemaphoreCollection*)malloc(sizeof(SemaphoreCollection));
    if (!collection) return NULL;

    collection->semaphores = (SemaphoreNode**)calloc(initial_capacity, sizeof(SemaphoreNode*));
    if (!collection->semaphores) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->collection_mutex, NULL);
    return collection;
}

int resize_semaphore_collection(SemaphoreCollection *collection, size_t new_capacity) {
    SemaphoreNode **new_semaphores = (SemaphoreNode**)realloc(collection->semaphores, new_capacity * sizeof(SemaphoreNode*));
    if (!new_semaphores) return -1;

    for (size_t i = collection->capacity; i < new_capacity; ++i) {
        new_semaphores[i] = NULL;
    }

    collection->semaphores = new_semaphores;
    collection->capacity = new_capacity;
    return 0;
}

SemaphoreNode* create_semaphore(int initial_value) {
    SemaphoreNode *node = (SemaphoreNode*)malloc(sizeof(SemaphoreNode));
    if (!node) return NULL;

    node->value = initial_value;
    pthread_mutex_init(&node->mutex, NULL);
    node->next = NULL;
    return node;
}

int add_semaphore(SemaphoreCollection *collection, SemaphoreNode *semaphore) {
    pthread_mutex_lock(&collection->collection_mutex);
    if (collection->count >= collection->capacity && resize_semaphore_collection(collection, collection->capacity * 2) != 0) {
        pthread_mutex_unlock(&collection->collection_mutex);
        return -1;
    }

    size_t index = collection->count++;
    collection->semaphores[index] = semaphore;
    pthread_mutex_unlock(&collection->collection_mutex);
    return 0;
}

int get_semaphore_value(SemaphoreCollection *collection, size_t index) {
    pthread_mutex_lock(&collection->collection_mutex);
    if (index >= collection->count || !collection->semaphores[index]) {
        pthread_mutex_unlock(&collection->collection_mutex);
        return -1; // Invalid index or no semaphore at that index
    }

    SemaphoreNode *node = collection->semaphores[index];
    int value;
    pthread_mutex_lock(&node->mutex);
    value = node->value;
    pthread_mutex_unlock(&node->mutex);
    pthread_mutex_unlock(&collection->collection_mutex);
    return value;
}

int set_semaphore_value(SemaphoreCollection *collection, size_t index, int new_value) {
    pthread_mutex_lock(&collection->collection_mutex);
    if (index >= collection->count || !collection->semaphores[index]) {
        pthread_mutex_unlock(&collection->collection_mutex);
        return -1; // Invalid index or no semaphore at that index
    }

    SemaphoreNode *node = collection->semaphores[index];
    pthread_mutex_lock(&node->mutex);
    node->value += new_value;
    if (node->value < 0) node->value = 0; // Ensure non-negative values
    pthread_mutex_unlock(&node->mutex);
    pthread_mutex_unlock(&collection->collection_mutex);
    return 0;
}

int delete_semaphore(SemaphoreCollection *collection, size_t index) {
    pthread_mutex_lock(&collection->collection_mutex);
    if (index >= collection->count || !collection->semaphores[index]) {
        pthread_mutex_unlock(&collection->collection_mutex);
        return -1; // Invalid index or no semaphore at that index
    }

    SemaphoreNode *node = collection->semaphores[index];
    free(node);
    collection->semaphores[index] = NULL;
    --collection->count;
    pthread_mutex_unlock(&collection->collection_mutex);
    return 0;
}

void destroy_semaphore_collection(SemaphoreCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->semaphores[i]) free(collection->semaphores[i]);
    }
    free(collection->semaphores);
    pthread_mutex_destroy(&collection->collection_mutex);
    free(collection);
}
