if (!empty($args['config-file'])) {
    $cliConfig = include $args['config-file'];
} else {
    $cliConfig = [];
}
$config = array_merge_recursive($defaultConfig, $envConfig, $cliConfig);

// Validate configuration against JSON schema
$jsonSchema = json_decode($schemaFile);
if (json_validate($config, $jsonSchema) === false) {
    throw new Exception('Configuration validation failed');
}

// Implement caching mechanism with support for invalidation strategies
