$cacheTtl = 3600; // 1 hour
$cacheData = apcu_fetch($cacheKey);
if ($cacheData === false || time() - $cacheData['timestamp'] > $cacheTtl) {
    $cacheData = [
        'data' => $config,
        'timestamp' => time(),
    ];
    apcu_store($cacheKey, $cacheData, $cacheTtl);
} else {
    $config = $cacheData['data'];
}

// Log all configuration changes and errors to central logging service
