    if (N > MAX_BUFFER_POOL_SIZE) {
        printf("Error: Exceeded maximum buffer pool size.\n");
        return;
    }
    buffer_pool_size = N;
    for (int i = 0; i < N; i++) {
        buffer_pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!buffer_pool[i]) {
            printf("Error: Failed to allocate memory for buffer %d.\n", i);
            // Handle memory allocation failure
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_buffer() {
    if (next_available_index >= buffer_pool_size) {
        printf("Warning: Buffer pool exhausted. Please resize the pool or free up some buffers.\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* buffer = buffer_pool[next_available_index++];
    memset(buffer, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    buffer->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return buffer;
}

void validate_buffer(NFAPI_CRC_INDICATION_PDU_T* buffer) {
    if (!buffer) {
        printf("Error: Invalid buffer pointer.\n");
        return;
    }
    if (buffer->RX_UE_INFORMATION_TAG == 0 || buffer->RNTI == 0 || buffer->CRCFLAG == -1) {
        printf("Error: Buffer not properly initialized.\n");
        // Handle initialization failure
    }
}

void resize_buffer_pool(int new_size) {
    if (new_size > MAX_BUFFER_POOL_SIZE || new_size <= buffer_pool_size) {
        printf("Error: Invalid new size for buffer pool.\n");
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T* new_buffer_pool[MAX_BUFFER_POOL_SIZE];
    int i = 0;
    for (; i < new_size && i < buffer_pool_size; i++) {
        new_buffer_pool[i] = buffer_pool[i];
    }
    for (; i < new_size; i++) {
        new_buffer_pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_buffer_pool[i]) {
            printf("Error: Failed to allocate memory for new buffer %d.\n", i);
            // Handle memory allocation failure
        }
    }
    for (i = 0; i < buffer_pool_size; i++) {
        free(buffer_pool[i]);
    }
    memcpy(buffer_pool, new_buffer_pool, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * new_size);
    buffer_pool_size = new_size;
}

