struct Action {
    int timestamp;
    char actionType;
    int priority;
    int cooldown;
    std::string id;
};

class CombatActionManager {
public:
    CombatActionManager() : activeActions(0), nextActionId(1) {}

    void addAction(const Action& action) {
        std::unique_lock<std::mutex> lock(mutex);
        actions.push(action);
        condition.notify_one();
    }

    void startProcessing() {
        for (int i = 0; i < 3; ++i) {
            std::thread(&CombatActionManager::processActions, this).detach();
        }
    }

private:
    void processActions() {
        while (true) {
            Action action;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this]() { return !actions.empty(); });
                action = actions.front();
                actions.pop();
            }
            executeAction(action);
        }
    }

    void executeAction(const Action& action) {
        std::lock_guard<std::mutex> lock(mutex);
        if (cooldowns[action.actionType] < currentTimestamp()) {
            performAction(action);
            cooldowns[action.actionType] = currentTimestamp() + action.cooldown;
        } else {
            actions.push(action); // Retry later
        }
    }

    void performAction(const Action& action) {
        std::cout << "Executing action: " << action.id << std::endl; // Placeholder for actual action execution
    }

    int currentTimestamp() {
        return std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count();
    }

    std::queue<Action> actions;
    std::unordered_map<char, int> cooldowns;
    int activeActions;
    int nextActionId;
    std::mutex mutex;
    std::condition_variable condition;
};

int main() {
    CombatActionManager manager;
    manager.startProcessing();

    // Simulate adding actions
    for (int i = 0; i < 10; ++i) {
        Action action = {i, 'A', i % 3 + 1, 10, "Action_" + std::to_string(i)};
        manager.addAction(action);
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    return 0;
}
