typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    size_t allocated_count;
    size_t used_count;
} NFAPI_PDU_POOL;

NFAPI_PDU_POOL* create_pdu_pool(size_t N) {
    if (N > MAX_N) {
        printf("Error: Requested N exceeds maximum allowed (%zu)\n", MAX_N);
        return NULL;
    }

    NFAPI_PDU_POOL *pool = (NFAPI_PDU_POOL*)malloc(sizeof(NFAPI_PDU_POOL));
    if (!pool) {
        perror("Failed to allocate memory for PDU pool");
        return NULL;
    }

    pool->pdu = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pdu) {
        perror("Failed to allocate memory for PDUs");
        free(pool);
        return NULL;
    }

    pool->allocated_count = N;
    pool->used_count = 0;

    return pool;
}

void destroy_pdu_pool(NFAPI_PDU_POOL *pool) {
    if (pool) {
        free(pool->pdu);
        free(pool);
    }
}

int validate_pdus(NFAPI_PDU_POOL *pool) {
    for (size_t i = 0; i < pool->used_count; ++i) {
        if (pool->pdu[i].RX_UE_INFORMATION_TAG == -1 ||
            pool->pdu[i].RNTI == 0 ||
            (pool->pdu[i].CRC_INDICATION_REL8_TAG != 'Y' && pool->pdu[i].CRC_INDICATION_REL8_TAG != 'N')) {
            printf("Error: Invalid PDU at index %zu\n", i);
            return -1;
        }
    }
    return 0;
}

int main() {
    size_t N = 100; // Example value
    NFAPI_PDU_POOL *pool = create_pdu_pool(N);
    if (!pool) {
        return 1;
    }

    for (size_t i = 0; i < pool->allocated_count; ++i) {
        pool->pdu[i].RX_UE_INFORMATION_TAG = i % 256;
        pool->pdu[i].RNTI = i * 100;
        pool->pdu[i].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0 ? 'Y' : 'N');
    }
    pool->used_count = pool->allocated_count;

    if (validate_pdus(pool) != 0) {
        destroy_pdu_pool(pool);
        return 1;
    }

    destroy_pdu_pool(pool);
    return 0;
}
