    if (N > MAX_CONNECTIONS) {
        fprintf(stderr, "Error: Maximum number of connections exceeded.\n");
        return NULL;
    }

    TCPConnection* connections = malloc(N * sizeof(TCPConnection));
    if (connections == NULL) {
        perror("Failed to allocate memory for connection list.");
        return NULL;
    }

    // Initialize all connections to default state
    memset(connections, 0, N * sizeof(TCPConnection));

    return connections;
}

int validate_connections(TCPConnection* connections, int N) {
    for (int i = 0; i < N; i++) {
        if (connections[i].state == 2) {
            fprintf(stderr, "Error: Connection %d is in an invalid state.\n", i);
            return -1;
        }
    }
    return 0;
}

void free_connection_list(TCPConnection* connections) {
    if (connections != NULL) {
        free(connections);
    }
}

int main() {
    int N = 5; // Example number of connections
    TCPConnection* connections = create_connection_list(N);

    if (connections == NULL) {
        return EXIT_FAILURE;
