    FILE* file = fopen(config_file, "r");
    if (!file) {
        printf("Failed to open configuration file: %s\n", config_file);
        return 1;
    }

    VideoConfig configs[10];
    int config_count = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char* token = strtok(line, ";");
        if (token != NULL) {
            configs[config_count].format = strdup(token);
            token = strtok(NULL, ";");
            configs[config_count].width = atoi(token);
            token = strtok(NULL, ";");
            configs[config_count].height = atoi(token);
            token = strtok(NULL, ";");
            configs[config_count].frame_rate = atoi(token);

            load_video_driver(configs[config_count].format);
            process_video_frame(&configs[config_count]);
            config_count++;
        }
