typedef struct {
    char* book_name;
    int count;
} BookCount;

BookCount* extract_book_mentions(int* states, int num_states, const FSA* fsa, int last_state, const char* text, int language_flag) {
    // Allocate memory for the new state list
    int* new_states = (int*)malloc(num_states * sizeof(int));
    if (!new_states) return NULL; // Handle memory allocation failure

    // Update the 'next' pointer of the last state in the original list
    states[last_state + 1] = new_states;

    // Initialize regex pattern for book names
    const char* pattern;
    if (language_flag == LANGUAGE_ENGLISH) {
        pattern = "((Old Testament Book Name))";
    } else if (language_flag == LANGUAGE_HEBREW) {
        pattern = "((Hebrew Old Testament Book Name))";
    } else {
        free(new_states);
        return NULL; // Handle invalid language flag
    }

    regex_t regex;
    if (regcomp(&regex, pattern, REG_EXTENDED | REG_ICASE) != 0) {
        free(new_states);
        return NULL; // Handle regex compilation failure
    }

    BookCount* book_counts = (BookCount*)calloc(100, sizeof(BookCount)); // Assuming max 100 unique books for simplicity
    if (!book_counts) {
        regfree(&regex);
        free(new_states);
        return NULL; // Handle memory allocation failure
    }

    regmatch_t matches[1];
    size_t n_matches = 1;
    char* p = (char*)text;

    while ((p = strstr(p, " ")) != NULL) {
        *p++ = '\0';
        if (regexec(&regex, text, n_matches, matches, 0) == REG_NOERROR && matches[0].rm_so >= 0) {
            // Extract book name from match
            char* book_name = strndup(text + matches[0].rm_so, matches[0].rm_eo - matches[0].rm_so);
            if (!book_name) {
                regfree(&regex);
                free(new_states);
                free(book_counts);
                return NULL; // Handle memory allocation failure
            }

            // Count occurrences of book name
            int i;
            for (i = 0; i < 100; i++) {
                if (book_counts[i].book_name == NULL) break;
                if (strcmp(book_counts[i].book_name, book_name) == 0) {
                    book_counts[i].count++;
                    free(book_name);
                    break;
                }
            }

            if (i == 100) {
                // Resize book_counts array if needed
                BookCount* new_book_counts = realloc(book_counts, 200 * sizeof(BookCount));
                if (!new_book_counts) {
                    regfree(&regex);
                    free(new_states);
                    free(book_name);
                    free(book_counts);
                    return NULL; // Handle memory allocation failure
                }
                book_counts = new_book_counts;
            }
        }
    }

