    int size;
} List;

void initList(List *list) {
    list->head = NULL;
    list->size = 0;
}

Node* createNode(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    Node *newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    newNode->rx_info.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->rx_info.RNTI = RNTI;
    newNode->crc_ind_rel8.CRCFLAG = CRCFLAG;
    newNode->next = NULL;
    return newNode;
}

void insertNode(List *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    Node *newNode = createNode(RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    list->size++;
}

int checkDuplicate(List *list, int CRCFLAG) {
    Node *current = list->head;
    while (current != NULL) {
        if (current->crc_ind_rel8.CRCFLAG == CRCFLAG) {
            return 1; // Duplicate found
        }
        current = current->next;
    }
    return 0; // No duplicate found
}

int populateList(List *list, int N) {
