        int RNTI = rand() % MAX_N + 1;
        int CRCFLAG = rand() % 2; // Binary flag
        while (checkDuplicate(list, CRCFLAG)) {
            CRCFLAG = rand() % 2; // Ensure unique CRCFLAG
        }
        insertNode(list, RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
    }
    return list->size;
}

void freeList(List *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->size = 0;
}

