typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node_T;

typedef struct {
    Node_T* head;
    pthread_mutex_t lock;
} List_T;

List_T* create_list() {
    List_T* list = (List_T*)malloc(sizeof(List_T));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(List_T* list) {
    Node_T* current = list->head;
    while (current != NULL) {
        Node_T* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_crc_indication_rel8_tag_unique(List_T* list, int CRC_INDICATION_REL8_TAG) {
    Node_T* current = list->head;
    while (current != NULL) {
        if (current->data.CRC_INDICATION_REL8_TAG == CRC_INDICATION_REL8_TAG) {
            return 0;
        }
        current = current->next;
    }
    return 1;
}

int add_to_list(List_T* list, RX_UE_INFORMATION_T rx_ue_information, int CRC_INDICATION_REL8_TAG) {
    if (!is_crc_indication_rel8_tag_unique(list, CRC_INDICATION_REL8_TAG)) {
        return -1; // Duplicate CRC_INDICATION_REL8_TAG
    }
    Node_T* new_node = (Node_T*)malloc(sizeof(Node_T));
    if (!new_node) return -2; // Memory allocation failed

    new_node->data.rx_ue_information = rx_ue_information;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->next = list->head;
    list->head = new_node;

    return 0;
}

void* populate_list(void* arg) {
