    int N = 10; // Example value, should be passed as parameter
    for (int i = 0; i < N; i++) {
        RX_UE_INFORMATION_T rx_ue_information = {i, i * 2}; // Example values
        int CRC_INDICATION_REL8_TAG = rand() % 1000; // Random value between 0 and 999
        add_to_list(list, rx_ue_information, CRC_INDICATION_REL8_TAG);
    }
    return NULL;
}

int main() {
    List_T* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return 1;
    }

    pthread_t thread;
    pthread_create(&thread, NULL, populate_list, (void*)list);
    pthread_join(thread, NULL);

    // Validate list
    Node_T* current = list->head;
    int seen_tags[MAX_N] = {0};
    while (current != NULL) {
        if (seen_tags[current->data.CRC_INDICATION_REL8_TAG]) {
            fprintf(stderr, "Duplicate CRC_INDICATION_REL8_TAG found: %d\n", current->data.CRC_INDICATION_REL8_TAG);
            free_list(list);
            return 1;
        }
        seen_tags[current->data.CRC_INDICATION_REL8_TAG] = 1;
