            cache.records[i].status_code = status_code;
            pthread_mutex_unlock(&cache.lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&cache.lock);
    return -1; // Cache full or duplicate entry
}

int validate_cache() {
    pthread_mutex_lock(&cache.lock);

    for (int i = 0; i < CACHE_SIZE; i++) {
        for (int j = i + 1; j < CACHE_SIZE; j++) {
            if (strcmp(cache.records[i].request_id, cache.records[j].request_id) == 0 && strcmp(cache.records[i].request_id, "") != 0) {
                pthread_mutex_unlock(&cache.lock);
                return -1; // Duplicate entry found
            }
        }
    }

    pthread_mutex_unlock(&cache.lock);
    return 0; // No duplicate entries
}

void flush_cache() {
    pthread_mutex_lock(&cache.lock);

    for (int i = 0; i < CACHE_SIZE; i++) {
        memset(&cache.records[i], 0, sizeof(HTTP_REQUEST_LOG_RECORD));
    }

    pthread_mutex_unlock(&cache.lock);
