#include <string.h>
#include <pthread.h>

#define MAX_CACHE_SIZE 1024

typedef struct {
    int REQUEST_ID;
    char METHOD[10];
    char URL[256];
    int STATUS_CODE;
} HTTP_REQUEST_LOG_RECORD;

typedef struct {
    HTTP_REQUEST_LOG_RECORD records[MAX_CACHE_SIZE];
    pthread_mutex_t lock;
} RequestCache;

RequestCache cache;

void init_cache() {
    pthread_mutex_init(&cache.lock, NULL);
}

int add_record(HTTP_REQUEST_LOG_RECORD record) {
    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (cache.records[i].REQUEST_ID == 0) { // Assuming 0 is an invalid REQUEST_ID
            cache.records[i] = record;
            pthread_mutex_unlock(&cache.lock);
            return i; // Return the index where the record was added
        }
    }
    pthread_mutex_unlock(&cache.lock);
    return -1; // Return -1 if no space is available
}

int find_record(int REQUEST_ID) {
    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (cache.records[i].REQUEST_ID == REQUEST_ID) {
            pthread_mutex_unlock(&cache.lock);
            return i; // Return the index of the record
        }
    }
    pthread_mutex_unlock(&cache.lock);
    return -1; // Return -1 if no such record exists
}

void remove_record(int REQUEST_ID) {
    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (cache.records[i].REQUEST_ID == REQUEST_ID) {
            cache.records[i].REQUEST_ID = 0; // Mark the record as free
            break;
        }
    }
    pthread_mutex_unlock(&cache.lock);
}

void flush_cache() {
    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        cache.records[i].REQUEST_ID = 0; // Clear the cache
    }
    pthread_mutex_unlock(&cache.lock);
}

int main() {
    init_cache();

    HTTP_REQUEST_LOG_RECORD record1 = {1, "GET", "http://example.com", 200};
    int index = add_record(record1);
    if (index != -1) {
        printf("Record added at index: %d\n", index);
    } else {
        printf("No space available in the cache.\n");
    }

    HTTP_REQUEST_LOG_RECORD record2 = {2, "POST", "http://example.com", 404};
    index = add_record(record2);
    if (index != -1) {
        printf("Record added at index: %d\n", index);
    } else {
        printf("No space available in the cache.\n");
    }

    int found_index = find_record(1);
    if (found_index != -1) {
        printf("Record with REQUEST_ID 1 found at index: %d\n", found_index);
    } else {
        printf("No record with REQUEST_ID 1 found.\n");
    }

    remove_record(1);
    found_index = find_record(1);
    if (found_index != -1) {
        printf("Record with REQUEST_ID 1 still found at index: %d\n", found_index);
    } else {
        printf("No record with REQUEST_ID 1 found after removal.\n");
    }

    flush_cache();
    found_index = find_record(2);
    if (found_index != -1) {
        printf("Record with REQUEST_ID 2 still found at index: %d\n", found_index);
    } else {
        printf("No record with REQUEST_ID 2 found after cache flush.\n");
    }

    return 0;
}
