    int num_threads = 0;

    char line[256];
    while (fgets(line, sizeof(line), log_file)) {
        if (num_threads >= 100) { // Resize thread pool dynamically as needed
            pthread_t *new_threads = (pthread_t*)realloc(threads, 200 * sizeof(pthread_t));
            if (!new_threads) {
                perror("Failed to resize thread pool");
                break;
            }
            threads = new_threads;
        }

        LogEntry entry = {line, num_threads};
        if (pthread_create(&threads[num_threads++], NULL, process_log, &entry)) {
            perror("Failed to create thread");
            continue;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);

    Stats csv_stats = process_csv(csv_file_path);
    printf("Valid log entries processed: %d\n", valid_entries);
    printf("CSV stats - Average: %.2f, Min: %.2f, Max: %.2f, Error count: %d\n",
           csv_stats.average, csv_stats.minimum, csv_stats.maximum, csv_stats.error_count);

    fclose(log_file);
}
