#define MAX_REQUESTS 1000
#define BUFFER_SIZE 256

typedef struct {
    int REQUEST_ID;
    char METHOD[BUFFER_SIZE];
    char URL[BUFFER_SIZE];
    int STATUS_CODE;
} HTTP_REQUEST_LOG_RECORD;

HTTP_REQUEST_LOG_RECORD cache[MAX_REQUESTS];

int initialize_cache(int M) {
    if (M > MAX_REQUESTS) {
        return -1; // Exceeds maximum capacity
    }
    for (int i = 0; i < M; i++) {
        cache[i].REQUEST_ID = 0;
        memset(cache[i].METHOD, 0, BUFFER_SIZE);
        memset(cache[i].URL, 0, BUFFER_SIZE);
        cache[i].STATUS_CODE = 0;
    }
    return 0;
}

int add_to_cache(HTTP_REQUEST_LOG_RECORD record) {
    for (int i = 0; i < MAX_REQUESTS; i++) {
        if (cache[i].REQUEST_ID == record.REQUEST_ID) {
            return -1; // Duplicate REQUEST_ID
        }
        if (cache[i].REQUEST_ID == 0) { // Find an empty slot
            cache[i] = record;
            return 0;
        }
    }
    return -1; // Cache is full
}

int resolve_dns(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &(ipv4->sin_addr), ip_address, INET_ADDRSTRLEN);

    freeaddrinfo(res);
    return 0;
}

void validate_cache() {
    for (int i = 0; i < MAX_REQUESTS; i++) {
        if (cache[i].REQUEST_ID == 0) break; // End of populated entries
        for (int j = i + 1; j < MAX_REQUESTS; j++) {
            if (cache[j].REQUEST_ID == cache[i].REQUEST_ID) {
                printf("Duplicate REQUEST_ID found: %d\n", cache[i].REQUEST_ID);
                return;
            }
        }
    }
    printf("Cache validation successful.\n");
}

