// Define log structure
typedef struct {
    time_t timestamp;
    int event_id;
    int severity_level;
    char message[256];
    int status_flag;
} EventLog;

// Global variables for buffer pool management
EventLog* buffer_pool = NULL;
int pool_size = 0;
int current_index = 0;

// Function to initialize the buffer pool
void init_buffer_pool(int N) {
    if (N <= 0) return;

    buffer_pool = (EventLog*)malloc(N * sizeof(EventLog));
    if (buffer_pool == NULL) {
        fprintf(stderr, "Failed to allocate memory for buffer pool.\n");
        exit(1);
    }
    pool_size = N;
    current_index = 0;
}

// Function to add a log entry
void add_log_entry(int event_id, int severity_level, const char* message) {
    if (current_index >= pool_size) {
        // Handle buffer exhaustion by resizing or other strategies
        fprintf(stderr, "Buffer pool exhausted.\n");
        return;
    }

    EventLog* log = &buffer_pool[current_index++];
    time_t now = time(NULL);
    log->timestamp = now;
    log->event_id = event_id;
    log->severity_level = severity_level;
    strncpy(log->message, message, sizeof(log->message) - 1);
    log->status_flag = rand() % 2; // Randomly set status flag

    // Log the addition for performance monitoring
    printf("Log added at index: %d\n", current_index - 1);
}

// Function to validate buffer pool entries
void validate_buffer_pool() {
    for (int i = 0; i < current_index; i++) {
        EventLog* log = &buffer_pool[i];
        if (log->timestamp == 0 || log->event_id <= 0 || strlen(log->message) == 0) {
            fprintf(stderr, "Invalid log entry at index: %d\n", i);
        }
    }
}

// Function to clean up the buffer pool
void cleanup_buffer_pool() {
    if (buffer_pool != NULL) {
        free(buffer_pool);
        buffer_pool = NULL;
        pool_size = 0;
        current_index = 0;
    }
}
