    uint32_t sequence_number;
} MAC_PDU;

typedef struct node {
    union {
        NFAPI_CRC_INDICATION_PDU_T *crc_pdu;
        MAC_PDU *mac_pdu;
    } data;
    struct node *next;
} Node;

typedef struct {
    Node *head;
    Node *tail;
    pthread_mutex_t mutex;
    size_t count;
    size_t capacity;
} DynamicList;

void initializeNfarTileConfig(int N, uint8_t *buffer) {
    DynamicList list;
    list.head = NULL;
    list.tail = NULL;
    pthread_mutex_init(&list.mutex, NULL);
    list.count = 0;
    list.capacity = 100; // Initial capacity

    Node *current_node = (Node *)buffer;
    for (int i = 0; i < N && current_node != NULL; i++) {
        current_node->data.crc_pdu = (NFAPI_CRC_INDICATION_PDU_T *)(current_node + 1);
        current_node->next = (i == N - 1) ? NULL : (Node *)((char *)current_node + sizeof(Node) + sizeof(NFAPI_CRC_INDICATION_PDU_T));
        current_node = (Node *)((char *)current_node + sizeof(Node) + sizeof(NFAPI_CRC_INDICATION_PDU_T));

        list.head = list.head ? list.head : &list;
        if (list.tail) {
            list.tail->next = current_node;
        }
        list.tail = current_node;

        // Populate with valid data
        list.tail->data.crc_pdu->rx_tag = getValidRXTag();
        list.tail->data.crc_pdu->rnti = generateRNTI();
        list.tail->data.crc_pdu->crc_tag.CRCFLAG = (i % 2 == 0) ? 1 : 0;
    }

    // Dynamic resizing logic
    if (N > list.capacity) {
        // Re-allocate buffer and resize list
        uint8_t *new_buffer = realloc(buffer, N * sizeof(Node) + N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_buffer == NULL) {
            perror("Failed to reallocate memory");
            return;
        }
        buffer = new_buffer;

        // Update list with new buffer
        current_node = (Node *)buffer + list.count;
        for (int i = list.count; i < N && current_node != NULL; i++) {
            current_node->data.crc_pdu = (NFAPI_CRC_INDICATION_PDU_T *)(current_node + 1);
            current_node->next = (i == N - 1) ? NULL : (Node *)((char *)current_node + sizeof(Node) + sizeof(NFAPI_CRC_INDICATION_PDU_T));
            current_node = (Node *)((char *)current_node + sizeof(Node) + sizeof(NFAPI_CRC_INDICATION_PDU_T));

            list.head = list.head ? list.head : &list;
            if (list.tail) {
                list.tail->next = current_node;
            }
            list.tail = current_node;

            // Populate with valid data
            list.tail->data.crc_pdu->rx_tag = getValidRXTag();
            list.tail->data.crc_pdu->rnti = generateRNTI();
            list.tail->data.crc_pdu->crc_tag.CRCFLAG = (i % 2 == 0) ? 1 : 0;
        }

        list.capacity = N;
    }
}

