#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 256

typedef struct {
    char *key;
    char *value;
} ConfigEntry;

typedef struct {
    ConfigEntry *entries;
    int size;
    int capacity;
    pthread_mutex_t lock;
} ConfigData;

void init_config(ConfigData *config) {
    config->entries = NULL;
    config->size = 0;
    config->capacity = 0;
    pthread_mutex_init(&config->lock, NULL);
}

void destroy_config(ConfigData *config) {
    for (int i = 0; i < config->size; ++i) {
        free(config->entries[i].key);
        free(config->entries[i].value);
    }
    free(config->entries);
    pthread_mutex_destroy(&config->lock);
}

int load_config(ConfigData *config, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    pthread_mutex_lock(&config->lock);

    while (config->size >= config->capacity) {
        config->capacity += 10;
        config->entries = realloc(config->entries, config->capacity * sizeof(ConfigEntry));
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        char *key_value = strchr(line, '=');
        if (key_value) {
            *key_value++ = '\0';
            key_value[strcspn(key_value, "\r\n")] = '\0';

            ConfigEntry entry;
            entry.key = strdup(line);
            entry.value = strdup(key_value);

            config->entries[config->size++] = entry;
        }
    }

    pthread_mutex_unlock(&config->lock);
    fclose(file);
    return 0;
}

void update_config(ConfigData *config, const char *key, const char *value) {
    pthread_mutex_lock(&config->lock);
    for (int i = 0; i < config->size; ++i) {
        if (strcmp(config->entries[i].key, key) == 0) {
            free(config->entries[i].value);
            config->entries[i].value = strdup(value);
            pthread_mutex_unlock(&config->lock);
            return;
        }
    }
    // Handle error: key not found
    pthread_mutex_unlock(&config->lock);
}

const char *get_config(ConfigData *config, const char *key) {
    pthread_mutex_lock(&config->lock);
    for (int i = 0; i < config->size; ++i) {
        if (strcmp(config->entries[i].key, key) == 0) {
            const char *value = config->entries[i].value;
            pthread_mutex_unlock(&config->lock);
            return value;
        }
    }
    // Handle error: key not found
    pthread_mutex_unlock(&config->lock);
    return NULL;
}
