#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ARRAY_SIZE 10000
#define DEFAULT_MEMORY_POOL_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[5];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_memory_pool(size_t size) {
    memory_pool.pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memory_pool.pool) {
        fprintf(stderr, "Failed to allocate memory for memory pool\n");
        exit(EXIT_FAILURE);
    }
    memory_pool.pool_size = size;
}

void* allocate_from_memory_pool() {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.used_count == memory_pool.pool_size) {
        pthread_mutex_unlock(&memory_pool.lock);
        return NULL; // Pool is full
    }
    void* ptr = &memory_pool.pool[memory_pool.used_count++];
    pthread_mutex_unlock(&memory_pool.lock);
    return ptr;
}

void deallocate_to_memory_pool(void* ptr, size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    for (size_t i = 0; i < memory_pool.used_count; ++i) {
        if (&memory_pool.pool[i] == ptr) {
            memmove(&memory_pool.pool[i], &memory_pool.pool[i + 1], (memory_pool.used_count - i - 1) * size);
            --memory_pool.used_count;
            break;
        }
    }
    pthread_mutex_unlock(&memory_pool.lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_memory_pool();
    if (!pdu) {
        fprintf(stderr, "Failed to allocate memory for CRC indication PDU\n");
        return NULL;
    }
    // Initialize fields with valid data
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 256;
    snprintf(pdu->CRC_INDICATION_REL8_TAG, sizeof(pdu->CRC_INDICATION_REL8_TAG), "%d", rand() % 10);
    return pdu;
}

void destroy_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    deallocate_to_memory_pool(pdu, sizeof(*pdu));
}

int validate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Check if fields are valid
    if (pdu->RX_UE_INFORMATION_TAG < 0 || pdu->RNTI < 0 || strlen(pdu->CRC_INDICATION_REL8_TAG) != 1) {
        return 0; // Invalid field found
    }
    return 1; // All fields are valid
}

void* create_crc_indication_array(size_t size, void (*error_callback)(const char*, int)) {
    if (size > MAX_ARRAY_SIZE) {
        error_callback("Error: Size exceeds maximum allowed", __LINE__);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        error_callback("Error: Failed to allocate memory for array", __LINE__);
        return NULL;
    }

    size_t i;
    for (i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_crc_indication_pdu();
        if (!pdu) {
            error_callback("Error: Failed to create CRC indication PDU", __LINE__);
            break;
        }
        array[i] = pdu;

        if (!validate_crc_indication_pdu(pdu)) {
            error_callback("Error: Invalid CRC indication PDU created", __LINE__);
            for (size_t j = 0; j < i; ++j) {
                destroy_crc_indication_pdu(array[j]);
            }
            free(array);
            return NULL;
        }
    }

    if (i != size) {
        // Free partially filled array
        for (size_t j = 0; j < i; ++j) {
            destroy_crc_indication_pdu(array[j]);
        }
        free(array);
        error_callback("Error: Array creation aborted due to errors", __LINE__);
        return NULL;
    }

    return array;
}

int main() {
    // Initialize memory pool
    initialize_memory_pool(DEFAULT_MEMORY_POOL_SIZE);

    // Create array of CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)create_crc_indication_array(10, (void (*)(const char*, int))fprintf);
    if (!array) {
        fprintf(stderr, "Failed to create CRC indication array\n");
        return EXIT_FAILURE;
    }

    // Clean up
    for (size_t i = 0; i < 10; ++i) {
        destroy_crc_indication_pdu(array[i]);
    }
    free(array);

    return EXIT_SUCCESS;
