#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

#define MAX_POOL_SIZE 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    NFAPI_CRC_INDICATION_PDU_T* pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool = { NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER };

void init_memory_pool(size_t size) {
    if (memory_pool.pool != NULL) {
        free(memory_pool.pool);
    }
    memory_pool.size = size;
    memory_pool.used = 0;
    memory_pool.pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    pthread_mutex_init(&memory_pool.lock, NULL);
}

void* allocate_from_pool() {
    void* result = NULL;
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.used < memory_pool.size) {
        result = &memory_pool.pool[memory_pool.used++];
    }
    pthread_mutex_unlock(&memory_pool.lock);
    return result;
}

void free_to_pool(void* ptr) {
    pthread_mutex_lock(&memory_pool.lock);
    for (size_t i = 0; i < memory_pool.used; ++i) {
        if ((char*)ptr == (char*)&memory_pool.pool[i]) {
            --memory_pool.used;
            memmove((char*)&memory_pool.pool[i], (char*)&memory_pool.pool[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (memory_pool.size - i - 1));
            break;
        }
    }
    pthread_mutex_unlock(&memory_pool.lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfapi_pdu_array(size_t size, int pool_size) {
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    if (size > 0 && size <= MAX_POOL_SIZE) {
        init_memory_pool(pool_size);
        array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
        for (size_t i = 0; i < size; ++i) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_from_pool();
            if (pdu != NULL) {
                pdu->RX_UE_INFORMATION_TAG = rand() % 100;
                pdu->RNTI = rand() % 256;
                pdu->CRC_INDICATION_REL8_TAG = rand() % 2;
            } else {
                free(array);
                array = NULL;
                break;
            }
        }
    }
    return array;
}

void destroy_nfaip_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t size) {
    if (array != NULL) {
        for (size_t i = 0; i < size; ++i) {
            free_to_pool(&array[i]);
        }
        free(array);
    }
}

void log_error(int index, int field, const char* message) {
    time_t now;
    struct tm* timeinfo;
    char buffer[80];

    time(&now);
    timeinfo = localtime(&now);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Error: Index=%d, Field=%d, Message=%s\n", buffer, index, field, message);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* array = create_nfaip_pdu_array(1000, MAX_POOL_SIZE);
    if (array != NULL) {
        // Use the array...
        destroy_nfaip_pdu_array(array, 1000);
    }
    return 0;
}
