    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} CRC_POOL;

CRC_POOL* create_crc_pool(size_t initial_capacity) {
    CRC_POOL *pool = (CRC_POOL *)malloc(sizeof(CRC_POOL));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->size = 0;
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_crc_pool(CRC_POOL *pool) {
    if (pool) {
        if (pool->pool) {
            free(pool->pool);
        }
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

int add_to_crc_pool(CRC_POOL *pool, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        // Handle error and log detailed information
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }
    pool->pool[pool->size++] = entry;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T get_from_crc_pool(CRC_POOL *pool, size_t index) {
    NFAPI_CRC_INDICATION_PDU_T entry = {0};
    pthread_mutex_lock(&pool->lock);
    if (index < pool->size) {
        entry = pool->pool[index];
    }
    pthread_mutex_unlock(&pool->lock);
    return entry;
}

void resize_crc_pool(CRC_POOL *pool, size_t new_capacity) {
    pthread_mutex_lock(&pool->lock);
    NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pool->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pool) {
        // Handle error and log detailed information
        pthread_mutex_unlock(&pool->lock);
        return;
    }
    pool->pool = new_pool;
    pool->capacity = new_capacity;
    pthread_mutex_unlock(&pool->lock);
}
