import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class SensorDataProcessor {
    private final BlockingQueue<SensorData> dataQueue;
    private final ConcurrentHashMap<String, MovingAverage> movingAverages;
    private final ExecutorService executorService;

    public SensorDataProcessor(int queueCapacity) {
        this.dataQueue = new ArrayBlockingQueue<>(queueCapacity);
        this.movingAverages = new ConcurrentHashMap<>();
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public void startProcessing() {
        executorService.submit(() -> processSensorData());
    }

    private void processSensorData() {
        while (true) {
            try {
                SensorData data = dataQueue.take();
                updateMovingAverage(data);
                handleNetworkCommunication(data);
                sendToStorageService(data);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    private void updateMovingAverage(SensorData data) {
        movingAverages.putIfAbsent(data.sensorId, new MovingAverage());
        MovingAverage average = movingAverages.get(data.sensorId);
        average.update(data.timestamp, data.value);
    }

    private void handleNetworkCommunication(SensorData data) {
        try (Socket socket = new Socket("weatherapi.com", 80)) {
            // Fetch weather data and update moving average
        } catch (IOException e) {
            // Log error and retry later
        }
    }

    private void sendToStorageService(SensorData data) {
        try (Socket socket = new Socket("storage.service.com", 9000)) {
            OutputStream out = socket.getOutputStream();
            DataOutputStream dos = new DataOutputStream(out);
            dos.write(data.toByteArray());
            dos.flush();
        } catch (IOException e) {
            // Log error and retry later
        }
    }

    public Cursor queryStorageService(String query) {
        try (Socket socket = new Socket("storage.service.com", 9001)) {
            OutputStream out = socket.getOutputStream();
            DataOutputStream dos = new DataOutputStream(out);
            dos.write(query.getBytes());
            dos.flush();

            InputStream in = socket.getInputStream();
            DataInputStream dis = new DataInputStream(in);
            int size = dis.readInt();
            byte[] bytes = new byte[size];
            dis.readFully(bytes);

            return new Cursor(bytes);
        } catch (IOException e) {
            // Log error and retry later
            return null;
        }
    }

    public void stopProcessing() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    private static class MovingAverage {
        private final LinkedList<Double> values;
        private double sum;

        public MovingAverage() {
            this.values = new LinkedList<>();
            this.sum = 0.0;
        }

        public void update(double timestamp, double value) {
            long now = System.currentTimeMillis();
            while (!values.isEmpty() && now - values.getFirst().timestamp > 60000) {
                sum -= values.removeFirst().value;
            }
            values.add(new DataPoint(timestamp, value));
            sum += value;

            // Calculate moving average and decay factor
        }

        private static class DataPoint {
            double timestamp;
            double value;

            public DataPoint(double timestamp, double value) {
                this.timestamp = timestamp;
                this.value = value;
            }
        }
    }

    private static class Cursor {
        byte[] data;

        public Cursor(byte[] data) {
            this.data = data;
        }

        // Implement methods to interact with the cursor
    }

