#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    size_t count;
    pthread_mutex_t lock;
    time_t last_purge_time;
} NFAPI_CRC_POOL_T;

void nfapi_crc_pool_init(NFAPI_CRC_POOL_T *pool) {
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pool->last_purge_time = time(NULL);
}

void nfapi_crc_pool_insert(NFAPI_CRC_POOL_T *pool, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= MAX_ENTRIES) {
        printf("Error: Pool capacity exceeded\n");
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    pool->entries[pool->count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pool->entries[pool->count].RNTI = RNTI;
    pool->entries[pool->count].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    pool->count++;

    pthread_mutex_unlock(&pool->lock);
}

void nfapi_crc_pool_purge(NFAPI_CRC_POOL_T *pool) {
    pthread_mutex_lock(&pool->lock);

    time_t current_time = time(NULL);
    if (current_time - pool->last_purge_time < 60) { // Purge every minute
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    size_t new_count = 0;
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->entries[i].RNTI != 0) { // Assuming RNTI of 0 indicates an expired entry
            pool->entries[new_count++] = pool->entries[i];
        }
    }

    for (size_t i = new_count; i < pool->count; i++) {
        memset(&pool->entries[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pool->count = new_count;
