#include <pthread.h>

typedef struct {
    int SESSION_ID;
    char REMOTE_IP[16];
    int PORT;
    int CONNECTION_STATUS;
} TCP_CONNECTION_RECORD_T;

typedef struct {
    TCP_CONNECTION_RECORD_T *pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} TCP_POOL_T;

TCP_POOL_T* tcp_pool_init(size_t initial_capacity) {
    TCP_POOL_T *pool = (TCP_POOL_T*)malloc(sizeof(TCP_POOL_T));
    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->pool = (TCP_CONNECTION_RECORD_T*)malloc(initial_capacity * sizeof(TCP_CONNECTION_RECORD_T));
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
    return pool;
}

void tcp_pool_insert(TCP_POOL_T *pool, TCP_CONNECTION_RECORD_T record) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        TCP_CONNECTION_RECORD_T *new_pool = (TCP_CONNECTION_RECORD_T*)realloc(pool->pool, new_capacity * sizeof(TCP_CONNECTION_RECORD_T));
        if (!new_pool) {
            pthread_mutex_unlock(&pool->lock);
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        pool->pool = new_pool;
        pool->capacity = new_capacity;
    }
    pool->pool[pool->count++] = record;
    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->lock);
}

TCP_CONNECTION_RECORD_T* tcp_pool_retrieve(TCP_POOL_T *pool) {
    TCP_CONNECTION_RECORD_T *record = NULL;
    pthread_mutex_lock(&pool->lock);
    while (pool->count == 0) {
        pthread_cond_wait(&pool->cond, &pool->lock);
    }
    if (pool->count > 0) {
        record = &pool->pool[--pool->count];
    }
    pthread_mutex_unlock(&pool->lock);
    return record;
}

void tcp_pool_close_inactive(TCP_POOL_T *pool, int inactivity_threshold) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ) {
        if ((time(NULL) - pool->pool[i].SESSION_ID) > inactivity_threshold) {
            size_t last_index = pool->count - 1;
            pool->pool[i] = pool->pool[last_index];
            pool->count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void tcp_pool_pause(TCP_POOL_T *pool) {
    // Pause implementation
}

void tcp_pool_resume(TCP_POOL_T *pool) {
    // Resume implementation
}

void tcp_pool_destroy(TCP_POOL_T *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->pool);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond);
    free(pool);
}
