#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void* memory;
    size_t size;
    size_t element_size;
    size_t allocated_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t pool_size, size_t element_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->memory = malloc(pool_size * element_size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }

    pool->size = pool_size;
    pool->element_size = element_size;
    pool->allocated_count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    if (!pool) return NULL;

    void* block = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->allocated_count < pool->size) {
        block = ((char*)pool->memory) + (pool->element_size * pool->allocated_count);
        pool->allocated_count++;
    }
    pthread_mutex_unlock(&pool->lock);

    return block;
}

void free_to_pool(MemoryPool* pool, void* block) {
    if (!pool || !block) return;

    pthread_mutex_lock(&pool->lock);
    size_t index = ((char*)block - (char*)pool->memory) / pool->element_size;
    if (index < pool->allocated_count) {
        pool->allocated_count--;
    }
    pthread_mutex_unlock(&pool->lock);
}

void destroy_memory_pool(MemoryPool* pool) {
    if (!pool) return;

    free(pool->memory);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}
