#include <pthread.h>
#include <time.h>

#define MAX_NFAPIS 10000
#define DEFAULT_MEMORY_POOL_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef void (*ErrorCallback)(const char* message, int index, int value);

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool;
    int poolSize;
    int currentIndex;
    pthread_mutex_t lock;
    ErrorCallback errorCallback;
} MemoryPool;

MemoryPool memoryPool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER, NULL};

void initializeMemoryPool(int size) {
    if (size > MAX_NFAPIS) {
        printf("Error: Pool size exceeds maximum allowed.\n");
        return;
    }
    memoryPool.pool = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memoryPool.pool) {
        printf("Memory allocation failed for pool.\n");
        return;
    }
    memoryPool.poolSize = size;
    pthread_mutex_lock(&memoryPool.lock);
    memoryPool.currentIndex = 0;
    pthread_mutex_unlock(&memoryPool.lock);
}

void* allocateFromPool() {
    pthread_mutex_lock(&memoryPool.lock);
    if (memoryPool.currentIndex >= memoryPool.poolSize) {
        pthread_mutex_unlock(&memoryPool.lock);
        return NULL; // Pool is full
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = &memoryPool.pool[memoryPool.currentIndex++];
    pthread_mutex_unlock(&memoryPool.lock);
    return pdu;
}

void freeMemoryPool() {
    if (memoryPool.pool) {
        free(memoryPool.pool);
        memoryPool.pool = NULL;
        memoryPool.poolSize = 0;
        memoryPool.currentIndex = 0;
    }
}

int randomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void logError(LogLevel level, const char* message, int index, int value) {
    time_t now = time(NULL);
    struct tm* timeInfo = localtime(&now);
    printf("%s [%d] %s: Index=%d, Value=%d\n", asctime(timeInfo), level, message, index, value);
}

void* populateArray(int size, LogLevel logLevel, ErrorCallback errorCallback) {
    if (size <= 0 || size > MAX_NFAPIS) {
        printf("Invalid array size.\n");
        return NULL;
    }

    initializeMemoryPool(memoryPool.poolSize);

    for (int i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocateFromPool();
        if (!pdu) {
            printf("Failed to allocate memory for element %d.\n", i);
            return NULL;
        }

        pdu->RX_UE_INFORMATION_TAG = randomInt(0, 1000);
        pdu->RNTI = randomInt(1, 4096);
        pdu->CRC_INDICATION_REL8_TAG = randomInt(0, 1);

        if (errorCallback) {
            if (!pdu->RX_UE_INFORMATION_TAG || !pdu->RNTI || !pdu->CRC_INDICATION_REL8_TAG) {
                errorCallback("Invalid field value", i, pdu->RX_UE_INFORMATION_TAG ? pdu->RNTI : pdu->CRC_INDICATION_REL8_TAG);
                freeMemoryPool();
                return NULL;
            }
        }

        if (logLevel <= LOG_DEBUG) {
            printf("Element %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n", i, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
        }
    }

    return memoryPool.pool;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)populateArray(5, LOG_INFO, logError);
    if (array) {
        printf("Array populated successfully.\n");
        freeMemoryPool();
    }
    return 0;
}
