#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000

typedef struct {
    int RNTI;
    // Other fields as needed
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint8_t CRCFLAG;
    // Other fields as needed
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
    time_t last_purge_time;
} CRC_POOL;

CRC_POOL* crc_pool_init(size_t initial_capacity) {
    CRC_POOL *pool = (CRC_POOL*)malloc(sizeof(CRC_POOL));
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->not_full, NULL);
    pthread_cond_init(&pool->not_empty, NULL);
    pool->last_purge_time = time(NULL);
    return pool;
}

void crc_pool_insert(CRC_POOL *pool) {
    pthread_mutex_lock(&pool->mutex);
    while (pool->size == pool->capacity) {
        pthread_cond_wait(&pool->not_full, &pool->mutex);
    }
    // Insert new entry
    pool->pool[pool->size].ue_info.RNTI = rand() % 1000; // Example RNTI generation
    pool->pool[pool->size].CRCFLAG = rand() % 256; // Random CRCFLAG
    pool->size++;
    pthread_cond_signal(&pool->not_empty);
    pthread_mutex_unlock(&pool->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* crc_pool_get(CRC_POOL *pool) {
    NFAPI_CRC_INDICATION_PDU_T *entry = NULL;
    pthread_mutex_lock(&pool->mutex);
    while (pool->size == 0) {
        pthread_cond_wait(&pool->not_empty, &pool->mutex);
    }
    // Retrieve and process entry based on RNTI
    size_t min_rnti_index = 0;
    for (size_t i = 1; i < pool->size; i++) {
        if (pool->pool[i].ue_info.RNTI < pool->pool[min_rnti_index].ue_info.RNTI) {
            min_rnti_index = i;
        }
    }
    entry = &pool->pool[min_rnti_index];
    // Process the entry
    printf("Processing entry with RNTI: %d\n", entry->ue_info.RNTI);
    pool->size--;
    pthread_cond_signal(&pool->not_full);
    pthread_mutex_unlock(&pool->mutex);
    return entry;
}

void crc_pool_purge(CRC_POOL *pool) {
    time_t current_time = time(NULL);
    if (current_time - pool->last_purge_time > 3600) { // Purge every hour
        pthread_mutex_lock(&pool->mutex);
        size_t new_size = 0;
        for (size_t i = 0; i < pool->size; i++) {
            if (/* condition to determine if entry is expired */) {
                free(pool->pool[i].ue_info.RNTI); // Free any dynamically allocated memory
            } else {
                pool->pool[new_size] = pool->pool[i];
                new_size++;
            }
        }
        pool->size = new_size;
        pthread_mutex_unlock(&pool->mutex);
        pool->last_purge_time = current_time;
    }
}

void crc_pool_free(CRC_POOL *pool) {
    for (size_t i = 0; i < pool->size; i++) {
        free(pool->pool[i].ue_info.RNTI); // Free any dynamically allocated memory
    }
    free(pool->pool);
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->not_full);
    pthread_cond_destroy(&pool->not_empty);
    free(pool);
}

int main() {
    srand(time(NULL));
    CRC_POOL *pool = crc_pool_init(100);

    // Example usage
    for (size_t i = 0; i < 50; i++) {
        crc_pool_insert(pool);
    }

    for (size_t i = 0; i < 25; i++) {
        NFAPI_CRC_INDICATION_PDU_T *entry = crc_pool_get(pool);
        if (entry) {
            // Process the entry
        }
    }

    crc_pool_purge(pool);
    crc_pool_free(pool);

    return 0;
}
```

This code snippet provides a basic implementation of a CRC pool with thread-safe operations and dynamic resizing. It includes functions for inserting new entries, retrieving and processing existing entries based on RNTI values, purging expired entries, and freeing the pool. The code also includes synchronization mechanisms to handle concurrent access and prevent race conditions.']

