    if (n_elements > MAX_NFAPI_ELEMENTS) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* elements = NULL;
    if (type == ARRAY_TYPE) {
        elements = pool ? pool->data[pool->size++] : malloc(n_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!elements) return NULL;
    } else {
        // For linked list, allocate pointers and initialize them to NULL
        NFAPI_CRC_INDICATION_PDU_T** elements_ptr = pool ? (NFAPI_CRC_INDICATION_PDU_T**)pool->data[pool->size++] : malloc(n_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!elements_ptr) return NULL;
        memset(elements_ptr, 0, n_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        elements = (NFAPI_CRC_INDICATION_PDU_T*)elements_ptr;
    }

    for (size_t i = 0; i < n_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* element = type == ARRAY_TYPE ? &elements[i] : *(NFAPI_CRC_INDICATION_PDU_T**)&elements[i];
        element->RX_UE_INFORMATION_TAG = rand();
        element->RNTI = rand() % 65536;
        element->CRC_INDICATION_REL8_TAG = rand() % 256;
        element->CRCFLAG = rand() % 2;

        if (element->CRCFLAG > 1) {
            char error_message[256];
            snprintf(error_message, sizeof(error_message), "Invalid CRCFLAG value: %d at index %zu", element->CRCFLAG, i);
            error_handler(error_message, i, element->CRCFLAG);
        }
    }

    if (type == ARRAY_TYPE && !pool) {
        *last_modified_time = time(NULL);
    }

    return elements;
}

void log_error(const char* message, int index, uint8_t field_value) {
