#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000

typedef struct {
    // Define your structure fields here
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_ind_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} DynamicListT;

DynamicListT* dynamic_list_create() {
    DynamicListT* list = (DynamicListT*)malloc(sizeof(DynamicListT));
    if (!list) return NULL;

    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->not_full, NULL);
    pthread_cond_init(&list->not_empty, NULL);

    list->count = 0;
    list->capacity = MAX_ENTRIES;

    return list;
}

void dynamic_list_destroy(DynamicListT* list) {
    if (!list) return;

    free(list->entries);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->not_full);
    pthread_cond_destroy(&list->not_empty);

    free(list);
}

int dynamic_list_push(DynamicListT* list, const NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (!list || !entry) return -1;

    pthread_mutex_lock(&list->lock);

    while (list->count == list->capacity) {
        pthread_cond_wait(&list->not_full, &list->lock);
    }

    list->entries[list->count++] = *entry;
    pthread_cond_signal(&list->not_empty);

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int dynamic_list_pop(DynamicListT* list, NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (!list || !entry) return -1;

    pthread_mutex_lock(&list->lock);

    while (list->count == 0) {
        pthread_cond_wait(&list->not_empty, &list->lock);
    }

    *entry = list->entries[--list->count];
    pthread_cond_signal(&list->not_full);

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void dynamic_list_log(const DynamicListT* list) {
    if (!list) return;

    printf("Current count: %zu, Capacity: %zu\n", list->count, list->capacity);
}
