#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t timestamp;
    int sequence_number;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedList {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t size;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    return list;
}

void freeLinkedList(LinkedList *list) {
    while (list->head) {
        NFAPI_CRC_INDICATION_PDU_T *temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T* createNode(int rx_tag, int rnti, int crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;
    node->RX_UE_INFORMATION_TAG = rx_tag;
    node->RNTI = rnti;
    node->CRC_INDICATION_REL8_TAG = crc_flag;
    node->timestamp = time(NULL);
    node->sequence_number = rand();
    node->next = NULL;
    return node;
}

void insertNode(LinkedList *list, int rx_tag, int rnti, int crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = createNode(rx_tag, rnti, crc_flag);
    if (!new_node) return;

    if (list->head == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
}

void dumpToFile(LinkedList *list, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    for (NFAPI_CRC_INDICATION_PDU_T *node = list->head; node != NULL; node = node->next) {
        fprintf(file, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, Timestamp: %ld, Sequence Number: %d\n",
                node->RX_UE_INFORMATION_TAG, node->RNTI, node->CRC_INDICATION_REL8_TAG, (long)node->timestamp, node->sequence_number);
    }

    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T** createAndPopulateList(size_t N) {
    if (N == 0) return NULL;

    LinkedList *list = createLinkedList();
    if (!list) return NULL;

    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        insertNode(list, rand(), rand(), rand() % 2);
    }

    NFAPI_CRC_INDICATION_PDU_T **array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        freeLinkedList(list);
        return NULL;
    }

    size_t index = 0;
    for (NFAPI_CRC_INDICATION_PDU_T *node = list->head; node != NULL; node = node->next) {
        array[index++] = node;
    }

    freeLinkedList(list);
    return array;
}
