    LTE_UE_Context_Info *current = list->head;
    while (current) {
        fprintf(file, "UE_ID: %d, MAC_ID: %d, State: %s\n", current->UE_ID, current->MAC_entity_id, 
                current->state == ACTIVE ? "ACTIVE" : (current->state == INACTIVE ? "INACTIVE" : "SLEEP"));
        current = current->next;
    }
    fclose(file);
    pthread_mutex_unlock(&list->lock);
}
