#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_CONTEXTS 10000
#define LOG_FILE "ue_context.log"
#define MEM_THRESHOLD 5 * 1024 * 1024 // 5MB

typedef enum {
    ACTIVE,
    INACTIVE,
    SLEEP
} LTE_MacEntityState;

typedef struct LTE_UEContextInfo {
    int UE_ID;
    int MAC_Entity_ID;
    LTE_MacEntityState state;
    time_t last_update;
    unsigned long seq_number;
    struct LTE_UEContextInfo *next;
} LTE_UEContextInfo;

typedef struct {
    pthread_mutex_t lock;
    LTE_UEContextInfo *head;
} UE_ContextList;

void initialize_list(UE_ContextList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

void add_UE_context(UE_ContextList *list, int UE_ID, int MAC_Entity_ID, LTE_MacEntityState state, unsigned long seq_number) {
    pthread_mutex_lock(&list->lock);
    LTE_UEContextInfo *new_context = (LTE_UEContextInfo *)malloc(sizeof(LTE_UEContextInfo));
    if (new_context == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_context->UE_ID = UE_ID;
    new_context->MAC_Entity_ID = MAC_Entity_ID;
    new_context->state = state;
    new_context->last_update = time(NULL);
    new_context->seq_number = seq_number;
    new_context->next = list->head;
    list->head = new_context;
    pthread_mutex_unlock(&list->lock);
}

void update_UE_context(UE_ContextList *list, int UE_ID, LTE_MacEntityState state, unsigned long seq_number) {
    pthread_mutex_lock(&list->lock);
    LTE_UEContextInfo *current = list->head;
    while (current != NULL) {
        if (current->UE_ID == UE_ID) {
            current->state = state;
            current->last_update = time(NULL);
            current->seq_number = seq_number;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_UE_context(UE_ContextList *list, int UE_ID) {
    pthread_mutex_lock(&list->lock);
    LTE_UEContextInfo *current = list->head;
    LTE_UEContextInfo *prev = NULL;
    while (current != NULL) {
        if (current->UE_ID == UE_ID) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void dump_list_to_file(UE_ContextList *list) {
    pthread_mutex_lock(&list->lock);
    FILE *file = fopen(LOG_FILE, "w");
    if (file == NULL) {
        perror("Failed to open log file");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    LTE_UEContextInfo *current = list->head;
    while (current != NULL) {
        fprintf(file, "UE_ID: %d, MAC_Entity_ID: %d, State: %s, Last_Update: %ld, Seq_Number: %lu\n",
                current->UE_ID, current->MAC_Entity_ID,
                (current->state == ACTIVE) ? "ACTIVE" : ((current->state == INACTIVE) ? "INACTIVE" : "SLEEP"),
                current->last_update, current->seq_number);
        current = current->next;
    }
    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

void free_list(UE_ContextList *list) {
    pthread_mutex_lock(&list->lock);
    LTE_UEContextInfo *current = list->head;
    while (current != NULL) {
        LTE_UEContextInfo *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

int main() {
    UE_ContextList list;
    initialize_list(&list);

    add_UE_context(&list, 1, 1001, ACTIVE, 123456);
    update_UE_context(&list, 1, INACTIVE, 123457);
    delete_UE_context(&list, 1);
    dump_list_to_file(&list);

    free_list(&list);
    return 0;
}
