#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    // Define the structure of TX_STREAM_RECORD_T
} TX_STREAM_RECORD_T;

#define RING_BUFFER_SIZE 1024

typedef struct RingBuffer {
    TX_STREAM_RECORD_T buffer[RING_BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} RingBuffer;

void initRingBuffer(RingBuffer *rb) {
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    pthread_mutex_init(&rb->mutex, NULL);
    pthread_cond_init(&rb->not_full, NULL);
    pthread_cond_init(&rb->not_empty, NULL);
}

int enqueue(RingBuffer *rb, TX_STREAM_RECORD_T *record) {
    pthread_mutex_lock(&rb->mutex);
    while (rb->count == RING_BUFFER_SIZE) {
        pthread_cond_wait(&rb->not_full, &rb->mutex);
    }
    rb->buffer[rb->tail] = *record;
    rb->tail = (rb->tail + 1) % RING_BUFFER_SIZE;
    rb->count++;
    pthread_cond_signal(&rb->not_empty);
    pthread_mutex_unlock(&rb->mutex);
    return 0;
}

int dequeue(RingBuffer *rb, TX_STREAM_RECORD_T *record) {
    pthread_mutex_lock(&rb->mutex);
    while (rb->count == 0) {
        pthread_cond_wait(&rb->not_empty, &rb->mutex);
    }
    *record = rb->buffer[rb->head];
    rb->head = (rb->head + 1) % RING_BUFFER_SIZE;
    rb->count--;
    pthread_cond_signal(&rb->not_full);
    pthread_mutex_unlock(&rb->mutex);
    return 0;
}

void process_and_store_data_stream(RingBuffer *rb, void (*store_function)(TX_STREAM_RECORD_T *)) {
    TX_STREAM_RECORD_T record;
    while (1) {
        dequeue(rb, &record);
        store_function(record);
    }
}
