#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Session {
    int id;
    char ip[16];
    time_t last_active;
    struct Session *next;
} Session;

Session *sessions = NULL;

// Function to add or update a session
void manage_session(int id, const char *ip) {
    Session *session = sessions;
    while (session != NULL) {
        if (session->id == id) {
            strcpy(session->ip, ip);
            session->last_active = time(NULL);
            return;
        }
        session = session->next;
    }

    // If session not found, create a new one
    session = malloc(sizeof(Session));
    if (session == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    session->id = id;
    strcpy(session->ip, ip);
    session->last_active = time(NULL);
    session->next = sessions;
    sessions = session;
}

// Function to delete a session
void delete_session(int id) {
    Session *session = sessions;
    Session *prev = NULL;

    while (session != NULL) {
        if (session->id == id) {
            if (prev == NULL) {
                sessions = session->next;
            } else {
                prev->next = session->next;
            }
            free(session);
            return;
        }
        prev = session;
        session = session->next;
    }
}

// Function to iterate over sessions
void iterate_sessions() {
    Session *session = sessions;
    while (session != NULL) {
        printf("Session ID: %d, IP: %s, Last Active: %ld\n", session->id, session->ip, session->last_active);
        session = session->next;
    }
}

// Function to validate session integrity
void validate_sessions() {
    Session *session = sessions;
    while (session != NULL) {
        if (time(NULL) - session->last_active > 3600) { // Check for inactive sessions
            printf("Inactive session found: %d\n", session->id);
            delete_session(session->id);
        }
        session = session->next;
    }
}

int main() {
    manage_session(1, "192.168.1.1");
    manage_session(2, "10.0.0.1");
    iterate_sessions();
    validate_sessions();
    delete_session(1);
    iterate_sessions();
    return 0;
}
```

