#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int sessionId;
    char userIP[16];
    time_t lastActive;
    void* userData;
} Session;

typedef struct Node {
    Session session;
    struct Node* next;
} Node;

Node* sessionsHead = NULL;

int addSession(int sessionId, char* userIP, void* userData) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return 0; // Memory allocation failed

    newNode->session.sessionId = sessionId;
    strcpy(newNode->session.userIP, userIP);
    newNode->session.lastActive = time(NULL);
    newNode->session.userData = userData;
    newNode->next = sessionsHead;
    sessionsHead = newNode;

    return 1;
}

int updateSession(int sessionId, char* userIP, void* userData) {
    Node* current = sessionsHead;
    while (current != NULL) {
        if (current->session.sessionId == sessionId) {
            strcpy(current->session.userIP, userIP);
            current->session.lastActive = time(NULL);
            current->session.userData = userData;
            return 1;
        }
        current = current->next;
    }
    return 0; // Session not found
}

int deleteSession(int sessionId) {
    Node* current = sessionsHead;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->session.sessionId == sessionId) {
            if (prev == NULL) {
                sessionsHead = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            return 1;
        }
        prev = current;
        current = current->next;
    }
    return 0; // Session not found
}

void iterateSessions(void (*callback)(Session)) {
    Node* current = sessionsHead;
    while (current != NULL) {
        callback(current->session);
        current = current->next;
    }
}

// Additional functions for logging, validation, expiration, and distributed locking would go here

int main() {
    // Example usage
    addSession(1, "192.168.1.1", NULL);
    updateSession(1, "192.168.1.1", (void*)123);
    iterateSessions((void (*)(Session))printf);

    return 0;
}
