#define MAX_QM_VALUE 100

typedef struct {
    uint32_t MEASUREMENT_TIMESTAMP;
    uint8_t RB_ID;
    uint8_t PHY_MEASUREMENT_TAG;
    uint8_t QM_VALUE;
} LTE_PHY_MEASUREMENTS;

typedef struct {
    LTE_PHY_MEASUREMENTS* measurements;
    size_t size;
    size_t capacity;
} MeasurementArray;

MeasurementArray* create_measurement_array(size_t initial_capacity) {
    MeasurementArray* array = (MeasurementArray*)malloc(sizeof(MeasurementArray));
    if (array == NULL) return NULL;
    array->measurements = (LTE_PHY_MEASUREMENTS*)calloc(initial_capacity, sizeof(LTE_PHY_MEASUREMENTS));
    if (array->measurements == NULL) {
        free(array);
        return NULL;
    }
    array->size = 0;
    array->capacity = initial_capacity;
    return array;
}

void destroy_measurement_array(MeasurementArray* array) {
    free(array->measurements);
    free(array);
}

int resize_measurement_array(MeasurementArray* array, size_t new_capacity) {
    LTE_PHY_MEASUREMENTS* new_measurements = (LTE_PHY_MEASUREMENTS*)realloc(array->measurements, new_capacity * sizeof(LTE_PHY_MEASUREMENTS));
    if (new_measurements == NULL) return -1;
    array->measurements = new_measurements;
    array->capacity = new_capacity;
    return 0;
}

int add_measurement(MeasurementArray* array, LTE_PHY_MEASUREMENTS measurement) {
    if (array->size >= array->capacity) {
        if (resize_measurement_array(array, array->capacity * 2) != 0) return -1;
    }
    array->measurements[array->size++] = measurement;
    if (measurement.QM_VALUE < MIN_QM_VALUE || measurement.QM_VALUE > MAX_QM_VALUE) {
        // Update the QM_VALUE to be within the valid range
        array->measurements[array->size - 1].QM_VALUE = (measurement.QM_VALUE > MAX_QM_VALUE) ? MAX_QM_VALUE : MIN_QM_VALUE;
    }
    return 0;
}

void iterate_forward(MeasurementArray* array, void (*callback)(LTE_PHY_MEASUREMENTS*)) {
    for (size_t i = 0; i < array->size; i++) {
        callback(&array->measurements[i]);
    }
}

void iterate_backward(MeasurementArray* array, void (*callback)(LTE_PHY_MEASUREMENTS*)) {
    for (ssize_t i = array->size - 1; i >= 0; i--) {
        callback(&array->measurements[i]);
    }
}
