#include <time.h>

#define MAX_POOL_SIZE 1000
#define LOG_FILE "crc_indication_log.log"

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct MemoryPool {
    Node* pool[MAX_POOL_SIZE];
    int size;
    int (*find_fit)(struct MemoryPool*, int);
} MemoryPool;

void log_message(const char* message) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

MemoryPool* create_memory_pool(int (*find_fit)(MemoryPool*, int)) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (pool) {
        memset(pool->pool, 0, sizeof(Node*) * MAX_POOL_SIZE);
        pool->size = 0;
        pool->find_fit = find_fit;
    }
    return pool;
}

int best_fit(MemoryPool* pool, int size) {
    for (int i = 0; i < pool->size; ++i) {
        if (!pool->pool[i]) {
            return i;
        }
    }
    return -1;
}

int worst_fit(MemoryPool* pool, int size) {
    int idx = -1;
    for (int i = 0; i < pool->size; ++i) {
        if (!pool->pool[i] && (idx == -1 || pool->pool[idx]->data.RX_UE_INFORMATION_TAG < pool->pool[i]->data.RX_UE_INFORMATION_TAG)) {
            idx = i;
        }
    }
    return idx;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool* pool, int size) {
    int idx = pool->find_fit(pool, size);
    if (idx != -1) {
        Node* node = pool->pool[idx];
        pool->pool[idx] = NULL;
        return &node->data;
    }
    return NULL;
}

void deallocate_to_pool(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* data) {
    for (int i = 0; i < pool->size; ++i) {
        if (!pool->pool[i]) {
            pool->pool[i] = malloc(sizeof(Node));
            pool->pool[i]->data = *data;
            pool->pool[i]->next = NULL;
            return;
        }
    }
}

void* allocate_memory(MemoryPool* pool, int size, int is_array) {
    NFAPI_CRC_INDICATION_PDU_T* data = allocate_from_pool(pool, size);
    if (!data && !is_array) {
        data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    return (void*)data;
}

void free_memory(MemoryPool* pool, void* data, int is_array) {
    if (!is_array) {
        free(data);
    } else {
        NFAPI_CRC_INDICATION_PDU_T* curr = (NFAPI_CRC_INDICATION_PDU_T*)data;
        while (curr) {
            NFAPI_CRC_INDICATION_PDU_T* next = curr->next;
            deallocate_to_pool(pool, curr);
            free(curr);
            curr = next;
        }
    }
}

void create_and_populate_crc_indication_storage(int N, int pool_size, char* storage_type, char* memory_strategy) {
