using System;
using System.Collections.Generic;
using UnityEngine;

public struct Record
{
    public int Value;
    public long Offset;
}

public class RandomValueGenerator : IDisposable
{
    private int minRange;
    private int maxRange;
    private List<Record> records = new List<Record>();
    private UnityRandom random = new UnityRandom();

    public RandomValueGenerator(int min, int max)
    {
        if (min >= max) throw new ArgumentException("Min range must be less than max range.");
        minRange = min;
        maxRange = max;
        InitializeRecords();
    }

    private void InitializeRecords()
    {
        for (int i = 0; i < 10000; i++)
        {
            int value = random.Range(minRange, maxRange + 1);
            while (i > 0 && records[i - 1].Value == value)
                value = random.Range(minRange, maxRange + 1);
            records.Add(new Record { Value = value, Offset = i });
        }
    }

    public int GetRandomInt()
    {
        return random.Range(minRange, maxRange + 1);
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(0f, 1f);
    }

    public override string ToString()
    {
        return $"Range: {minRange}-{maxRange}, Records Count: {records.Count}";
    }

    public void CompressRecords()
    {
        for (int i = records.Count - 2; i >= 0; i--)
        {
            if (records[i].Value == records[i + 1].Value)
            {
                records.RemoveAt(i + 1);
            }
        }
    }

    public void Dispose()
    {
        records.Clear();
    }
}
