using System.Runtime.Serialization.Formatters.Binary;

[Serializable]
public class CustomDataStructure { }

public static object DecryptAndDeserialize(byte[] ciphertext, byte[] encryptionKey, byte[] IV)
{
    try
    {
        Aes aes = Aes.Create();
        aes.Key = encryptionKey;
        aes.IV = IV;
        aes.Mode = CipherMode.CBC;

        ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
        {
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
            {
                BinaryFormatter formatter = new BinaryFormatter();
                return formatter.Deserialize(csDecrypt);
            }
        }
    }
    catch (Exception ex)
    {
        throw new Exception("Decryption or deserialization failed.", ex);
    }
}
