        exit(EXIT_FAILURE);
    }
    new_record->value = value;
    new_record->next = head;
    head = new_record;
}

void delete_record(int key) {
    Record *current = head;
    Record *prev = NULL;

    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }

