#define MAX_LINE_LENGTH 1024
#define CONFIG_FILE "config.txt"
#define LOG_FILE "application.log"

typedef struct {
    FILE *input_file;
    FILE *log_file;
} Config;

Config* load_config() {
    Config *config = (Config*)malloc(sizeof(Config));
    config->input_file = fopen(CONFIG_FILE, "r");
    if (!config->input_file) {
        perror("Failed to open input configuration file");
        exit(EXIT_FAILURE);
    }
    config->log_file = fopen(LOG_FILE, "a+");
    if (!config->log_file) {
        perror("Failed to open log file");
        fclose(config->input_file);
        exit(EXIT_FAILURE);
    }
    return config;
}

void close_config(Config *config) {
    fclose(config->input_file);
    fclose(config->log_file);
    free(config);
}

void log_message(FILE *log_file, const char *message) {
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
}

double calculate_average(int field1, int field2) {
    return round((field1 + field2) / 2.0);
}

void process_line(Config *config, char *line) {
    char *token = strtok(line, " ");
    int fields[100];
    int field_count = 0;

    while (token != NULL && field_count < 100) {
        fields[field_count++] = atoi(token);
        token = strtok(NULL, " ");
    }

    if (field_count >= 3) {
        int last_field = fields[field_count - 1];
        int second_last_field = fields[field_count - 2];
        double average = calculate_average(last_field, second_last_field);

        // Simulate external data processing service integration
        // For demonstration purposes, we'll just log the average
        log_message(config->log_file, "Average of last two fields: %d", (int)average);
    }
}

void* process_thread(void *arg) {
    Config *config = (Config*)arg;
    char line[MAX_LINE_LENGTH];

    while (fgets(line, sizeof(line), config->input_file)) {
        process_line(config, line);
    }

    pthread_exit(NULL);
}

int main() {
    Config *config = load_config();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, process_thread, config) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    close_config(config);

    return 0;
}
