#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024

typedef struct ConnectionState {
    int conn_id;
    char remote_addr[INET6_ADDRSTRLEN];
    char local_addr[INET6_ADDRSTRLEN];
    time_t last_active_time;
} ConnectionState;

ConnectionState connection_pool[MAX_CONNECTIONS];

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

int allocate_connection_state(int* conn_id) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (connection_pool[i].conn_id == -1) {
            *conn_id = connection_pool[i].conn_id = i + 1;
            memset(&connection_pool[i], 0, sizeof(ConnectionState));
            pthread_mutex_unlock(&pool_lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return -1; // No available connections
}

void free_connection_state(int conn_id) {
    pthread_mutex_lock(&pool_lock);
    if (conn_id >= 1 && conn_id <= MAX_CONNECTIONS) {
        connection_pool[conn_id - 1].conn_id = -1;
    }
    pthread_mutex_unlock(&pool_lock);
}

int main() {
    int conn_id;
    if (allocate_connection_state(&conn_id) == 0) {
        printf("Connection %d allocated successfully.\n", conn_id);
        // Use the connection state
        free_connection_state(conn_id);
        printf("Connection %d freed successfully.\n", conn_id);
    } else {
        printf("Failed to allocate a connection state.\n");
    }
    return 0;
}
