public class StreamingDataAggregator {
    private ExecutorService executorService;
    private BlockingQueue<DataPacket> queue;
    private volatile boolean running;

    public StreamingDataAggregator(int bufferSize) {
        this.queue = new ArrayBlockingQueue<>(bufferSize);
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.running = true;

        // Start processing thread
        executorService.submit(this::processData);
    }

    private void processData() {
        while (running) {
            try {
                DataPacket packet = queue.take();
                processPacket(packet);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    public void submit(DataPacket data) throws InterruptedException {
        queue.put(data);
    }

