#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <time.h>
#include <string.h>

#define MAX_TRANSACTIONS 1000
#define WINDOW_SIZE 10

typedef struct {
    int id;
    time_t timestamp;
    double amount;
} Transaction;

typedef struct {
    sem_t lock;
    Transaction transactions[MAX_TRANSACTIONS];
    int count;
    double weighted_sum;
    double age_decay_factor;
    time_t last_updated;
} TransactionProcessor;

void* process_transactions(void* arg) {
    TransactionProcessor* processor = (TransactionProcessor*)arg;

    while (true) {
        sem_wait(&processor->lock);

        if (processor->count > 0) {
            // Filter transactions based on age, number of transactions in the last 10 seconds, and weighted sum
            double max_weighted_sum = processor->weighted_sum;
            int max_transaction_id = -1;

            for (int i = 0; i < processor->count; i++) {
                time_t current_time = time(NULL);
                if ((current_time - processor->transactions[i].timestamp) > 10) {
                    // Remove transactions older than 10 seconds
                    continue;
                }

                double transaction_age = (double)(current_time - processor->transactions[i].timestamp) / 60.0;
                double weighted_transaction = processor->transactions[i].amount * transaction_age;

                if (weighted_transaction > max_weighted_sum) {
                    max_weighted_sum = weighted_transaction;
                    max_transaction_id = processor->transactions[i].id;
                }
            }

            // Update rolling average of weighted sum and age decay factor
            processor->weighted_sum = max_weighted_sum;
            processor->age_decay_factor *= 0.99; // Decay factor of 1% per second

            // Log the transaction ID with the maximum weighted sum
            printf("Transaction ID %d has the maximum weighted sum %.2f\n", max_transaction_id, max_weighted_sum);
        }

        sem_post(&processor->lock);

        // Sleep for a short period to reduce CPU usage
        usleep(1000 * 10); // Sleep for 10 milliseconds
    }

    return NULL;
}

int main() {
    TransactionProcessor processor;
    pthread_t thread;

    // Initialize the transaction processor
    sem_init(&processor.lock, 0, 1);
    processor.count = 0;
    processor.weighted_sum = 0.0;
    processor.age_decay_factor = 1.0;
    processor.last_updated = time(NULL);

    // Start a thread to process transactions
    pthread_create(&thread, NULL, process_transactions, &processor);

    // Simulate transaction processing
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        sem_wait(&processor.lock);

        Transaction transaction;
        transaction.id = i + 1;
        transaction.timestamp = time(NULL);
        transaction.amount = rand() % 100.0;

        processor.transactions[processor.count++] = transaction;

        sem_post(&processor.lock);

        // Sleep for a short period to simulate transaction processing
        usleep(1000 * 5); // Sleep for 5 milliseconds
    }

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    // Clean up
    sem_destroy(&processor.lock);

    return 0;
}
