#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNS 1024

typedef struct {
    int CONN_ID;
    char REMOTE_ADDR[INET6_ADDRSTRLEN];
    char LOCAL_ADDR[INET6_ADDRSTRLEN];
    time_t LAST_ACTIVE_TIME;
    size_t CURRENT_REQUEST_SIZE;
} ConnectionState;

ConnectionState *conn_pool = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
int conn_count = 0;
int max_conn_count = MAX_CONNS;

void init_connection_pool(int initial_size) {
    if (initial_size > max_conn_count) {
        max_conn_count = initial_size;
        conn_pool = realloc(conn_pool, max_conn_count * sizeof(ConnectionState));
        if (!conn_pool) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
    memset(conn_pool, 0, max_conn_count * sizeof(ConnectionState));
}

ConnectionState* allocate_connection() {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < max_conn_count; i++) {
        if (conn_pool[i].CONN_ID == 0) {
            conn_pool[i].LAST_ACTIVE_TIME = time(NULL);
            conn_count++;
            pthread_mutex_unlock(&pool_lock);
            return &conn_pool[i];
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return NULL;
}

void deallocate_connection(ConnectionState *conn) {
    pthread_mutex_lock(&pool_lock);
    conn->CONN_ID = 0;
    conn_count--;
    pthread_mutex_unlock(&pool_lock);
}

void expand_connection_pool(int new_size) {
    if (new_size > max_conn_count) {
        int old_size = max_conn_count;
        max_conn_count = new_size;
        conn_pool = realloc(conn_pool, max_conn_count * sizeof(ConnectionState));
        if (!conn_pool) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        memset(conn_pool + old_size, 0, (max_conn_count - old_size) * sizeof(ConnectionState));
    }
}

void shrink_connection_pool(int new_size) {
    if (new_size < max_conn_count && new_size >= conn_count) {
        int old_size = max_conn_count;
        max_conn_count = new_size;
        conn_pool = realloc(conn_pool, max_conn_count * sizeof(ConnectionState));
        if (!conn_pool) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
}
