#include <stdio.h>
#include <stdarg.h>
#include <pthread.h>

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_ERROR
} LogLevel;

typedef struct {
    FILE *log_file;
    LogLevel current_level;
    pthread_mutex_t log_lock;
} Logger;

void init_logger(Logger *logger, const char *filename, LogLevel level) {
    logger->log_file = fopen(filename, "a");
    if (!logger->log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
    logger->current_level = level;
    pthread_mutex_init(&logger->log_lock, NULL);
}

void log_message(Logger *logger, LogLevel level, const char *format, ...) {
    if (level < logger->current_level) {
        return;
    }

    pthread_mutex_lock(&logger->log_lock);

    va_list args;
    va_start(args, format);
    vfprintf(logger->log_file, format, args);
    va_end(args);

    fprintf(logger->log_file, "\n");
    fflush(logger->log_file);

    pthread_mutex_unlock(&logger->log_lock);
}

void flush_logs(Logger *logger) {
    pthread_mutex_lock(&logger->log_lock);
    if (fflush(logger->log_file)) {
        fprintf(stderr, "Failed to flush logs\n");
    }
    pthread_mutex_unlock(&logger->log_lock);
}

void destroy_logger(Logger *logger) {
    pthread_mutex_destroy(&logger->log_lock);
    fclose(logger->log_file);
}
```

This code provides a basic structure for a thread-safe logger in C. It includes functions to initialize the logger, log messages with variable arguments, flush logs, and clean up resources. The logger can be configured with different logging levels and supports appending logs to a file.']

