#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define MAX_ENDPOINTS 10
#define MAX_URL_LENGTH 256
#define MAX_ALERTS_PER_MINUTE 3

typedef struct {
    char url[MAX_URL_LENGTH];
    int priority;
    time_t last_sent_time;
} Endpoint;

typedef struct {
    Endpoint endpoints[MAX_ENDPOINTS];
    size_t num_endpoints;
    double thresholds[MAX_ENDPOINTS];
    pthread_mutex_t lock;
} NotificationConfig;

void initializeNotificationConfig(NotificationConfig *config, size_t num_endpoints) {
    config->num_endpoints = num_endpoints;
    for (size_t i = 0; i < num_endpoints; ++i) {
        snprintf(config->endpoints[i].url, MAX_URL_LENGTH, "http://endpoint%d.com", i);
        config->endpoints[i].priority = i + 1;
        config->endpoints[i].last_sent_time = 0;
    }
    pthread_mutex_init(&config->lock, NULL);
}

void sendNotification(NotificationConfig *config, int condition, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);

    for (size_t i = 0; i < config->num_endpoints; ++i) {
        pthread_mutex_lock(&config->lock);
        if (time(NULL) - config->endpoints[i].last_sent_time > 60 / MAX_ALERTS_PER_MINUTE && condition >= config->thresholds[i]) {
            // Simulate sending notification
            printf("Sending alert to %s\n", config->endpoints[i].url);
            config->endpoints[i].last_sent_time = time(NULL);
        }
        pthread_mutex_unlock(&config->lock);
    }
}

int main() {
    NotificationConfig config;
    initializeNotificationConfig(&config, 5);

    sendNotification(&config, 5, "Threshold condition met: %d\n", 5);
    sleep(2);
    sendNotification(&config, 3, "Condition not met\n");
    sleep(60);
    sendNotification(&config, 7, "New threshold condition met: %d\n", 7);

    pthread_mutex_destroy(&config.lock);
    return 0;
}
