#define MAX_RETRIES 3

typedef struct {
    int tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int RNTI;
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int generate_unique_rx_ue_info_tag(RX_UE_INFORMATION_TAG *tags, int count) {
    int tag = rand() % 1000; // Simplified for example purposes
    for (int i = 0; i < count; i++) {
        if (tags[i].tag == tag) {
            return generate_unique_rx_ue_info_tag(tags, count);
        }
    }
    return tag;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_array(int N) {
    srand(time(0));
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array == NULL) {
            printf("Memory allocation failed. Retrying...\n");
            retries++;
            continue;
        }

        RX_UE_INFORMATION_TAG unique_tags[N];
        memset(unique_tags, 0, N * sizeof(RX_UE_INFORMATION_TAG));

        for (int i = 0; i < N; i++) {
            array[i].RNTI = rand() % 1000; // Simplified for example purposes
            array[i].rx_ue_info_tag.tag = generate_unique_rx_ue_info_tag(unique_tags, i);
            array[i].CRCFLAG = (rand() % 2) ? 0 : 1;
        }

        int unique_count = 0;
        for (int i = 0; i < N; i++) {
            if (unique_tags[i].tag != 0) {
                unique_count++;
            }
        }

        if (unique_count == N) {
            break;
        } else {
            printf("Unique RX_UE_INFORMATION_TAG generation failed. Retrying...\n");
            retries++;
            free(array);
        }
    }

    if (retries == MAX_RETRIES) {
        printf("Failed to create array after %d retries.\n", MAX_RETRIES);
        return NULL;
    }

    return array;
}

void free_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array, int N) {
    free(array);
}
