    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    uint64_t *tag_set = NULL;
    bool tag_unique;

    for (int retry = 0; retry < MAX_RETRIES; ++retry) {
        array_size = malloc(sizeof(*array_size));
        if (!array_size) {
            return NULL;
        }
        *array_size = N;

        array = realloc(array, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array) {
            free(array_size);
            return NULL;
        }

        tag_set = calloc(N, sizeof(*tag_set));
        if (!tag_set) {
            free(array);
            free(array_size);
            return NULL;
        }

        tag_unique = true;
        for (size_t i = 0; i < N; ++i) {
            uint64_t new_tag;
            do {
                new_tag = rand();
            } while (tag_set[new_tag % N]);

            array[i].RX_UE_INFORMATION_TAG = new_tag;
            array[i].RNTI = rand() % 16384;
            array[i].CRCFLAG = rand() % 256;

            tag_set[new_tag % N] = 1;
        }

        free(tag_set);
        return array;
    }

    *array_size = 0;
    free(array);
    free(array_size);
    return NULL;
