#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RETRIES 3
#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t size;
    size_t free_count;
    pthread_mutex_t mutex;
} MemoryPool;

void init_memory_pool(MemoryPool *pool, size_t initial_size) {
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->size = initial_size;
    pool->free_count = initial_size;
    pthread_mutex_init(&pool->mutex, NULL);
}

void destroy_memory_pool(MemoryPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_struct(MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->free_count == 0) {
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *ptr = pool->pool + (pool->size - pool->free_count);
    pool->free_count--;
    pthread_mutex_unlock(&pool->mutex);
    return ptr;
}

void free_struct(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *ptr) {
    pthread_mutex_lock(&pool->mutex);
    ptr->RX_UE_INFORMATION_TAG = 0; // Reset tag to indicate it's free
    pool->free_count++;
    pthread_mutex_unlock(&pool->mutex);
}

int allocate_nfas(NFAPI_CRC_INDICATION_PDU_T **array, size_t N, int max_structures, unsigned int seed) {
    if (N > max_structures) return -1; // Insufficient resources

    MemoryPool pool;
    init_memory_pool(&pool, N);

    srand(seed);
    for (size_t i = 0; i < N; ) {
        NFAPI_CRC_INDICATION_PDU_T *ptr = allocate_struct(&pool);
        if (!ptr) break; // Retry if allocation fails

        ptr->RX_UE_INFORMATION_TAG = rand() % max_structures + 1;
        do {
            ptr->CRCFLAG = rand();
        } while (check_for_duplicates(array, i, ptr));

        array[i++] = ptr;
    }

    destroy_memory_pool(&pool);
    return (i == N) ? 0 : -1; // Return number of successfully allocated structures
}

int check_for_duplicates(NFAPI_CRC_INDICATION_PDU_T **array, size_t N, NFAPI_CRC_INDICATION_PDU_T *new_struct) {
    for (size_t i = 0; i < N; i++) {
        if (array[i]->RX_UE_INFORMATION_TAG == new_struct->RX_UE_INFORMATION_TAG)
            return 1;
    }
    return 0;
}

void log_random_numbers(unsigned int seed, size_t count) {
    srand(seed);
    for (size_t i = 0; i < count; i++) {
        printf("Random number %zu: %u\n", i, rand());
    }
}
