#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ITERATIONS 5
#define SNR_MIN 0
#define SNR_MAX 30
#define CRCFLAG_SUCCESS 1
#define CRCFLAG_FAILURE 2

typedef struct {
    int TX_UE_INFORMATION_TAG;
    int RNTI;
    L1_STATISTICS_REL8_TAG l1_stats;
} NFAPI_L1_STATS_PDU_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    // Define the structure fields here
    int SNR_DB;
    float BER;
} L1_STATISTICS_REL8_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

int generate_random_tag(int *tags, int size) {
    int tag = rand() % 10000; // Random tag between 0 and 9999
    for (int i = 0; i < size; i++) {
        if (tags[i] == tag) {
            return generate_random_tag(tags, size); // Recursively try again
        }
    }
    return tag;
}

void initialize_structures(NFAPI_L1_STATS_PDU_T *stats_pdu, NFAPI_CRC_INDICATION_PDU_T *crc_pdu, int num_elements) {
    srand(time(NULL));
    int tags[num_elements];
    for (int i = 0; i < num_elements; i++) {
        stats_pdu[i].TX_UE_INFORMATION_TAG = generate_random_tag(tags, num_elements);
        tags[i] = stats_pdu[i].TX_UE_INFORMATION_TAG;
        stats_pdu[i].RNTI = rand() % 1024; // Random RNTI between 0 and 1023
        stats_pdu[i].l1_stats.SNR_DB = SNR_MIN + (rand() % (SNR_MAX - SNR_MIN + 1));
        stats_pdu[i].l1_stats.BER = (float)rand() / RAND_MAX;

        crc_pdu[i].RX_UE_INFORMATION_TAG = generate_random_tag(tags, num_elements);
        tags[i] = crc_pdu[i].RX_UE_INFORMATION_TAG;
        crc_pdu[i].crc_indication.CRCFLAG = rand() % 2 == 0 ? CRCFLAG_SUCCESS : CRCFLAG_FAILURE;
    }
}

int validate_structures(NFAPI_L1_STATS_PDU_T *stats_pdu, NFAPI_CRC_INDICATION_PDU_T *crc_pdu, int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        if (i > 0 && stats_pdu[i].TX_UE_INFORMATION_TAG == stats_pdu[i - 1].TX_UE_INFORMATION_TAG ||
            crc_pdu[i].RX_UE_INFORMATION_TAG == crc_pdu[i - 1].RX_UE_INFORMATION_TAG) {
            return -1; // Duplicates detected
        }
        if (stats_pdu[i].l1_stats.SNR_DB < SNR_MIN || stats_pdu[i].l1_stats.SNR_DB > SNR_MAX) {
            return -2; // SNR out of bounds
        }
    }
    return 0;
}

int process_pdus(int num_elements, NFAPI_L1_STATS_PDU_T **stats_pdu, NFAPI_CRC_INDICATION_PDU_T **crc_pdu) {
    int iterations = 0;
    while (iterations < MAX_ITERATIONS) {
        *stats_pdu = realloc(*stats_pdu, sizeof(NFAPI_L1_STATS_PDU_T) * num_elements);
        *crc_pdu = realloc(*crc_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);

        if (*stats_pdu == NULL || *crc_pdu == NULL) {
            free(*stats_pdu); // Free previously allocated memory
            free(*crc_pdu);
            return -3; // Memory allocation failed
        }

        initialize_structures(*stats_pdu, *crc_pdu, num_elements);

        int result = validate_structures(*stats_pdu, *crc_pdu, num_elements);
        if (result == 0) {
            return 0; // Structures are valid and initialized successfully
        } else if (result == -1 || result == -2) {
            free(*stats_pdu); // Free memory before retrying
            free(*crc_pdu);
        }

        iterations++;
    }
    return -4; // Exceeded maximum iterations without success
}

int main() {
    int num_elements = 500;
    NFAPI_L1_STATS_PDU_T *stats_pdu = NULL;
    NFAPI_CRC_INDICATION_PDU_T *crc_pdu = NULL;

    int result = process_pdus(num_elements, &stats_pdu, &crc_pdu);
    if (result == 0) {
        printf("PDUs initialized and validated successfully.\n");
    } else {
        printf("Error initializing or validating PDUs: %d\n", result);
    }

    free(stats_pdu); // Free allocated memory
    free(crc_pdu);

    return 0;
}
