import hashlib
import requests
from urllib.parse import urlparse
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class FileHasher:
    def __init__(self, algorithms=['md5', 'sha256'], chunk_size=1024*1024):
        self.algorithms = [getattr(hashlib, algo)() for algo in algorithms]
        self.chunk_size = chunk_size
        self.retry_limit = 3

    def hash_file(self, file_path_or_url):
        if urlparse(file_path_or_url).scheme:
            return self.hash_url(file_path_or_url)
        else:
            return self.hash_local_file(file_path_or_url)

    def hash_local_file(self, file_path):
        try:
            with open(file_path, 'rb') as f:
                for chunk in iter(lambda: f.read(self.chunk_size), b''):
                    for h in self.algorithms:
                        h.update(chunk)
            return {h.name: h.hexdigest() for h in self.algorithms}
        except Exception as e:
            logging.error(f"Error hashing file: {e}")
            raise

    def hash_url(self, url):
        try:
            response = requests.get(url, stream=True)
            response.raise_for_status()
            total_length = int(response.headers.get('content-length', 0))
            processed_length = 0
            start_time = time.time()

            for chunk in iter(lambda: response.raw.read(self.chunk_size), b''):
                if not chunk:
                    break
                for h in self.algorithms:
                    h.update(chunk)
                processed_length += len(chunk)

                # Update progress
                percent_completed = processed_length / total_length * 100
                elapsed_time = time.time() - start_time
                rate = processed_length / elapsed_time if elapsed_time > 0 else 0
                logging.info(f"Progress: {percent_completed:.2f}% | Rate: {rate:.2f} bytes/s")

            return {h.name: h.hexdigest() for h in self.algorithms}
        except requests.RequestException as e:
            logging.error(f"Error downloading or hashing URL: {e}")
            raise

# Example usage
hasher = FileHasher(algorithms=['md5', 'sha256'], chunk_size=1024*1024)
local_hash_result = hasher.hash_file('path/to/local/file.txt')
url_hash_result = hasher.hash_url('https://example.com/largefile.zip')
