import hashlib
import requests
from concurrent.futures import ThreadPoolExecutor
from time import time

class HashUtility:
    def __init__(self, algorithms=['md5', 'sha256'], chunk_size=1024*1024):
        self.algorithms = {name: hashlib.new(name) for name in algorithms}
        self.chunk_size = chunk_size
        self.executor = ThreadPoolExecutor(max_workers=3)

    def hash_file(self, file_path):
        with open(file_path, 'rb') as f:
            while True:
                data = f.read(self.chunk_size)
                if not data:
                    break
                for algo in self.algorithms.values():
                    algo.update(data)
        return {name: algo.hexdigest() for name, algo in self.algorithms.items()}

    def hash_url(self, url):
        try:
            response = requests.get(url, stream=True)
            response.raise_for_status()
            return self.hash_file(response.raw)
        except Exception as e:
            print(f"Error fetching URL: {e}")
            raise

    def process_files_concurrently(self, file_paths):
        results = []
        for result in self.executor.map(self.hash_file, file_paths):
            results.append(result)
        return results

# Example usage
hash_utility = HashUtility(algorithms=['md5', 'sha256'], chunk_size=1024*1024)
file_path = 'path/to/large/file.txt'
print(hash_utility.hash_file(file_path))

url = 'http://example.com/large/file.txt'
print(hash_utility.hash_url(url))
```

