void print_usage() {
    printf("Usage: ./file_processor [--manpage] [-cs] [-o output_file] input_file\n");
}

int main(int argc, char *argv[]) {
    if (argc == 1) {
        print_usage();
        return 0;
    }

    int opt_manpage = 0;
    int opt_cs = 0;
    const char *output_file = NULL;
    const char *input_file = NULL;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0) {
            opt_manpage = 1;
        } else if (strcmp(argv[i], "-cs") == 0) {
            opt_cs = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (input_file == NULL) {
            input_file = argv[i];
        }
    }

    if (opt_manpage) {
        printf("Manpage information here\n");
        return 0;
    }

    if (input_file == NULL) {
        print_usage();
        return 1;
    }

    FILE *file = fopen(input_file, "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    size_t line_len = 0;
    char *line = NULL;
    ssize_t read;

    long long lines_count = 0;
    while ((read = getline(&line, &line_len, file)) != -1) {
        ++lines_count;
    }

    free(line);
    fclose(file);

    printf("Number of lines: %lld\n", lines_count);

    return 0;
}
