typedef struct {
    int USER_ID;
    int SESSION_ID;
    int LOG_LEVEL;
    union {
        struct {
            int MESSAGE_ID;
            time_t timestamp;
            char* payload;
        } CUSTOM_MESSAGE_PDU_T;
        struct {
            time_t event_timestamp;
            char* log_message;
        } LOG_EVENT_PDU_T;
    };
} PDUTypes;

typedef enum {
    INFO,
    WARNING,
    ERROR
} LogLevel;

PDUTypes* allocate_and_process_pdu(int user_id, int session_id, int log_level, void* data, size_t data_size) {
    static PDUTypes* pdu_array = NULL;
    static size_t array_size = 0;
    static size_t count = 0;
    const size_t max_count = 20000;
    const size_t max_retries = 3;

    if (count >= max_count) {
        return NULL; // Reached maximum capacity
    }

    for (size_t attempt = 0; attempt < max_retries; ++attempt) {
        if (count == array_size) {
            array_size = count + 1024; // Grow by a factor of 1.5
            pdu_array = realloc(pdu_array, array_size * sizeof(PDUTypes));
            if (!pdu_array) {
                return NULL; // Memory allocation failed
            }
        }

        PDUTypes* new_pdu = &pdu_array[count];
        new_pdu->USER_ID = user_id;
        new_pdu->SESSION_ID = session_id;
        new_pdu->LOG_LEVEL = log_level;

        if (log_level == INFO) {
            new_pdu->CUSTOM_MESSAGE_PDU_T.MESSAGE_ID = rand();
            new_pdu->CUSTOM_MESSAGE_PDU_T.timestamp = time(NULL);
            new_pdu->CUSTOM_MESSAGE_PDU_T.payload = (char*)data;
        } else if (log_level == WARNING || log_level == ERROR) {
            new_pdu->LOG_EVENT_PDU_T.event_timestamp = time(NULL);
            new_pdu->LOG_EVENT_PDU_T.log_message = (char*)malloc(data_size + 1);
            if (!new_pdu->LOG_EVENT_PDU_T.log_message) {
                return NULL; // Memory allocation failed
            }
            strncpy(new_pdu->LOG_EVENT_PDU_T.log_message, data, data_size);
        } else {
            free(pdu_array); // Free partially allocated memory
            pdu_array = NULL;
            array_size = 0;
            count = 0;
            return NULL; // Invalid log level
        }

        // Check for uniqueness of USER_ID and SESSION_ID
        for (size_t i = 0; i < count; ++i) {
            if ((pdu_array[i].USER_ID == user_id && pdu_array[i].SESSION_ID == session_id)) {
                free(pdu_array[count].LOG_EVENT_PDU_T.log_message);
                continue; // Duplicate detected, retry
            }
        }

        ++count;
        return new_pdu;
    }

    return NULL; // Exceeded maximum retries without success
}

void free_pdu(PDUTypes* pdu) {
    if (pdu->LOG_LEVEL == WARNING || pdu->LOG_LEVEL == ERROR) {
        free(pdu->LOG_EVENT_PDU_T.log_message);
    }
}
