    time_t LAST_ACTIVE_TIME;
    size_t CURRENT_REQUEST_SIZE;
} ConnectionState;

ConnectionState connection_pool[MAX_CONNECTIONS];
int pool_size = 0;

int allocate_connection() {
    if (pool_size >= MAX_CONNECTIONS) {
        return -1; // Pool is full
    }
    memset(&connection_pool[pool_size], 0, sizeof(ConnectionState));
    return pool_size++;
}

void deallocate_connection(int conn_id) {
    if (conn_id < 0 || conn_id >= pool_size) {
        return; // Invalid connection ID
    }
    memset(&connection_pool[conn_id], 0, sizeof(ConnectionState));
}

void resize_connection_pool(int new_size) {
    if (new_size > MAX_CONNECTIONS) {
        return; // New size exceeds maximum allowed
    }
    pool_size = new_size;
}

int get_current_connections() {
    return pool_size;
}
