#include <stdlib.h>
#include <stdio.h>

// Define record structure
typedef struct {
    int value;
    long *offset;
    int *key;
    char **description;
    char **metadata;
} Record;

// Define hash table structure
typedef struct {
    Record **records;
    size_t capacity;
    size_t size;
    double load_factor;
} HashTable;

// Function to initialize hash table
HashTable* init_hash_table(size_t initial_capacity) {
    // Allocate memory for hash table
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize hash table properties
    table->capacity = initial_capacity;
    table->size = 0;
    table->load_factor = 0.75;

    // Allocate memory for records array
    table->records = malloc(initial_capacity * sizeof(Record*));
    if (!table->records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(table);
        exit(EXIT_FAILURE);
    }

    // Initialize all entries to NULL
    for (size_t i = 0; i < initial_capacity; ++i) {
        table->records[i] = NULL;
    }

    return table;
}

// Function to hash a key
size_t hash_key(int key, size_t capacity) {
    return abs(key) % capacity;
}

// Function to insert or update record in hash table
void insert_or_update_record(HashTable *table, int key, int value, long offset, char *description, char *metadata) {
    // Resize if load factor exceeds threshold
    if (table->size >= table->capacity * table->load_factor) {
        size_t new_capacity = table->capacity * 2;
        HashTable *new_table = init_hash_table(new_capacity);
        for (size_t i = 0; i < table->capacity; ++i) {
            Record *record = table->records[i];
            if (record) {
                insert_or_update_record(new_table, *record->key, record->value, *record->offset, *record->description, *record->metadata);
            }
        }
        free(table->records);
        table->records = new_table->records;
        table->capacity = new_capacity;
    }

    // Insert/update record
    size_t index = hash_key(key, table->capacity);
    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_record->value = value;
    new_record->offset = &offset;
    new_record->key = &key;
    new_record->description = description ? strdup(description) : NULL;
    new_record->metadata = metadata ? strdup(metadata) : NULL;

    table->records[index] = new_record;
    table->size++;
}

// Function to compact hash table
void compact_hash_table(HashTable *table) {
    // Calculate new capacity (e.g., 50% of current capacity)
    size_t new_capacity = table->capacity / 2;
    HashTable *new_table = init_hash_table(new_capacity);

    // Rehash all records
    for (size_t i = 0; i < table->capacity; ++i) {
        Record *record = table->records[i];
        if (record) {
            insert_or_update_record(new_table, *record->key, record->value, *record->offset, *record->description, *record->metadata);
        }
    }

    // Free old records and swap tables
    for (size_t i = 0; i < table->capacity; ++i) {
        Record *record = table->records[i];
        if (record) {
            free(record->description);
            free(record->metadata);
            free(record);
        }
    }
    free(table->records);
    table->records = new_table->records;
    table->capacity = new_capacity;
}

// Function to update record value
void update_record_value(HashTable *table, int key, int new_value) {
    size_t index = hash_key(key, table->capacity);
    Record *record = table->records[index];
    if (record && *record->key == key) {
        record->value = new_value;
    }
}

// Function to update record description
void update_record_description(HashTable *table, int key, char *new_description) {
    size_t index = hash_key(key, table->capacity);
    Record *record = table->records[index];
    if (record && *record->key == key) {
        free(record->description);
        record->description = strdup(new_description);
    }
}

// Function to update record metadata
void update_record_metadata(HashTable *table, int key, char *new_metadata) {
    size_t index = hash_key(key, table->capacity);
    Record *record = table->records[index];
    if (record && *record->key == key) {
        free(record->metadata);
        record->metadata = strdup(new_metadata);
    }
}

// Function to remove expired records
void remove_expired_records(HashTable *table, int (*is_expired)(int)) {
    size_t new_capacity = table->capacity;
    HashTable *new_table = init_hash_table(new_capacity);

    // Rehash non-expired records
    for (size_t i = 0; i < table->capacity; ++i) {
        Record *record = table->records[i];
        if (record && !is_expired(*record->key)) {
            insert_or_update_record(new_table, *record->key, record->value, *record->offset, *record->description, *record->metadata);
        }
    }

    // Free old records and swap tables
    for (size_t i = 0; i < table->capacity; ++i) {
        Record *record = table->records[i];
        if (record) {
            free(record->description);
            free(record->metadata);
            free(record);
        }
    }
    free(table->records);
    table->records = new_table->records;
    table->capacity = new_capacity;
}

// Function to free hash table
void free_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Record *record = table->records[i];
        if (record) {
            free(record->description);
            free(record->metadata);
            free(record);
        }
    }
    free(table->records);
    free(table);
}
