#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value;
    long offset;
    int key;
} Record;

typedef struct HashNode {
    Record *record;
    struct HashNode *next;
} HashNode;

typedef struct HashTable {
    int size;
    int threshold;
    double load_factor;
    pthread_mutex_t mutex;
    HashNode **buckets;
} HashTable;

HashTable* create_hash_table(int initial_size, int threshold) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->size = initial_size;
    table->threshold = threshold;
    table->load_factor = 0.75;
    pthread_mutex_init(&table->mutex, NULL);
    table->buckets = (HashNode**)calloc(table->size, sizeof(HashNode*));
    return table;
}

void destroy_hash_table(HashTable *table) {
    for (int i = 0; i < table->size; i++) {
        HashNode *node = table->buckets[i];
        while (node != NULL) {
            HashNode *next = node->next;
            free(node);
            node = next;
        }
    }
    pthread_mutex_destroy(&table->mutex);
    free(table->buckets);
    free(table);
}

void insert_record(HashTable *table, Record *record) {
    pthread_mutex_lock(&table->mutex);
    int index = record->key % table->size;
    HashNode *node = table->buckets[index];
    while (node != NULL) {
        if (node->record->key == record->key) {
            free(node->record);
            node->record = record;
            pthread_mutex_unlock(&table->mutex);
            return;
        }
        node = node->next;
    }
    HashNode *new_node = (HashNode*)malloc(sizeof(HashNode));
    new_node->record = record;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    pthread_mutex_unlock(&table->mutex);
}

void compact_hash_table(HashTable *table) {
    // Implement compaction logic here
}

Record* find_record(HashTable *table, int key) {
    pthread_mutex_lock(&table->mutex);
    int index = key % table->size;
    HashNode *node = table->buckets[index];
    while (node != NULL) {
        if (node->record->key == key) {
            Record *result = node->record;
            pthread_mutex_unlock(&table->mutex);
            return result;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->mutex);
    return NULL;
}

int main() {
    // Example usage of the hash table
    HashTable *table = create_hash_table(100, 80);
    Record *record = (Record*)malloc(sizeof(Record));
    record->value = 42;
    record->offset = 12345;
    record->key = 7;
    insert_record(table, record);

    Record *found_record = find_record(table, 7);
    if (found_record != NULL) {
        printf("Found record with value: %d\n", found_record->value);
    }

    destroy_hash_table(table);
    return 0;
}
```

