#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure members here
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t count;
    pthread_mutex_t mutex;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void insertPDU(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= 10000) {
        printf("Error: Maximum size reached.\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    newNode->pdu = pdu;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

// Add more functions for testing and extension as needed
