#define MAX_THREADS 10

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *cache[MAX_THREADS];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* get_cached_crc_flag(RNTI rnti) {
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_mutex_lock(&cache_lock);
        if (cache[i] && cache[i]->rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *result = cache[i];
            cache[i] = NULL;
            pthread_mutex_unlock(&cache_lock);
            return result;
        }
        pthread_mutex_unlock(&cache_lock);
    }
    return NULL;
}

void set_cached_crc_flag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    for (int i = 0; i < MAX_THREADS; i++) {
        if (!cache[i]) {
            pthread_mutex_lock(&cache_lock);
            if (!cache[i]) {
                cache[i] = pdu;
                pthread_mutex_unlock(&cache_lock);
                return;
            }
            pthread_mutex_unlock(&cache_lock);
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu(RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
