    pdu->rnti = rnti;
    pdu->crc_flag.crcflag = (rand() % 2 == 0); // Randomly set CRCFLAG
    if (pdu->crc_flag.crcflag) {
        NFAPI_CRC_INDICATION_PDU_T *cached_pdu = get_cached_crc_flag(rnti);
        if (cached_pdu) {
            free(pdu);
            return cached_pdu;
        }
        set_cached_crc_flag(pdu);
    }
    return pdu;
}

int main() {
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, create_crc_pdu, (void*)&ue_info, (void*)rnti);
    }
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
