typedef struct AudioPacketBuffer {
    unsigned char data[MAX_AUDIO_PACKET_SIZE];
    size_t length;
    struct AudioPacketBuffer *next;
} AudioPacketBuffer;

typedef struct MemoryPool {
    AudioPacketBuffer *free_list;
    AudioPacketBuffer *current_buffer;
    size_t buffer_size;
    size_t total_allocated;
    size_t peak_usage;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool *pool, size_t initial_size) {
    pool->free_list = NULL;
    pool->current_buffer = NULL;
    pool->buffer_size = initial_size;
    pool->total_allocated = 0;
    pool->peak_usage = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

AudioPacketBuffer* allocate_audio_packet(MemoryPool *pool) {
    AudioPacketBuffer *packet = (AudioPacketBuffer*)malloc(sizeof(AudioPacketBuffer));
    if (packet == NULL) return NULL;

    pthread_mutex_lock(&pool->lock);
    pool->total_allocated += sizeof(AudioPacketBuffer);
    if (pool->peak_usage < pool->total_allocated) {
        pool->peak_usage = pool->total_allocated;
    }
    pthread_mutex_unlock(&pool->lock);

    packet->length = 0;
    packet->next = NULL;

    return packet;
}

void free_audio_packet(MemoryPool *pool, AudioPacketBuffer *packet) {
    pthread_mutex_lock(&pool->lock);
    pool->total_allocated -= sizeof(AudioPacketBuffer);
    packet->next = pool->free_list;
    pool->free_list = packet;
    pthread_mutex_unlock(&pool->lock);
}

