    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t mutex;
} Linked_List;

int init_linked_list(Linked_List* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return pthread_mutex_init(&list->mutex, NULL);
}

void destroy_linked_list(Linked_List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}

bool insert_element(Linked_List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= MAX_ELEMENTS) {
        // Handle full list
        Node* to_remove = list->head;
        list->head = list->head->next;
        free(to_remove);
        list->tail->next = NULL;
        list->tail = list->tail->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    new_node->pdu = pdu;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }
    list->tail = new_node;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(Linked_List* list, int index) {
    if (index < 0 || index >= list->size) {
        // Handle invalid index
        return NULL;
    }

    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = &current->pdu;

    pthread_mutex_unlock(&list->mutex);
    return pdu;
}

