void print_usage() {
    printf("Usage: program_name [options] input_file\n");
    printf("Options:\n");
    printf("  --manpage      Display the man page.\n");
    printf("  -cs            Enable checksum mode.\n");
    printf("  -o output_file Specify the output file.\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage();
        return 1;
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            // Display man page
            printf("Man page content here.\n");
        } else if (strcmp(argv[i], "-cs") == 0) {
            // Enable checksum mode
            printf("Checksum mode enabled.\n");
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            // Specify output file
            char *output_file = argv[i] + 3;
            printf("Output file: %s\n", output_file);
        } else {
            // Input file
            FILE *file = fopen(argv[i], "r");
            if (file == NULL) {
                perror("Error opening file");
                return 1;
            }

            int line_count = 0;
            char line[MAX_LINE_LENGTH];
            while (fgets(line, MAX_LINE_LENGTH, file)) {
                line_count++;
            }
            printf("Number of lines: %d\n", line_count);

            fclose(file);
        }
    }

    return 0;
}
