#include <stdlib.h>
#include <pthread.h>

#define MAX_ALLOC_LIMIT 1024

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    int error_code;
} NFAPI_CRC_ARRAY;

NFAPI_CRC_ARRAY* create_crc_array(size_t initial_capacity) {
    if (initial_capacity > MAX_ALLOC_LIMIT) {
        // Log error
        return NULL;
    }

    NFAPI_CRC_ARRAY *array = malloc(sizeof(NFAPI_CRC_ARRAY));
    if (!array) {
        // Log allocation failure
        return NULL;
    }

    array->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        // Log allocation failure
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
    array->error_code = 0;

    return array;
}

void destroy_crc_array(NFAPI_CRC_ARRAY *array) {
    if (array->array) {
        free(array->array);
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int insert_crc_indication(NFAPI_CRC_ARRAY *array, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_ind_tag) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            array->error_code = -1; // Log allocation failure
            pthread_mutex_unlock(&array->lock);
            return array->error_code;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    for (size_t i = 0; i < array->size; i++) {
        if (array->array[i].rnti == rnti) {
            // Log duplicate RNTI error
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
    }

    array->array[array->size].ue_info_tag = ue_info_tag;
    array->array[array->size].rnti = rnti;
    array->array[array->size].crc_ind_tag = crc_ind_tag;
    array->size++;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

int remove_crc_indication(NFAPI_CRC_ARRAY *array, RNTI rnti) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; i++) {
        if (array->array[i].rnti == rnti) {
            memmove(array->array + i, array->array + i + 1, (array->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            array->size--;
            pthread_mutex_unlock(&array->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&array->lock);
    // Log removal of non-existent RNTI error
    return -1;
}

void iterate_reverse_crc_array(NFAPI_CRC_ARRAY *array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = array->size; i > 0; i--) {
        callback(&array->array[i - 1]);
    }

    pthread_mutex_unlock(&array->lock);
}
