public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddDbContext<ApplicationDbContext>(options =>
            options.UseSqlServer(Configuration.GetConnectionString("DefaultConnection")));

        services.AddIdentity<ApplicationUser, IdentityRole>()
            .AddEntityFrameworkStores<ApplicationDbContext>()
            .AddDefaultTokenProviders();

        services.Configure<IdentityOptions>(options =>
        {
            // Configure user and password requirements.
            options.User.RequireUniqueEmail = true;
            options.Password.RequiredLength = 8;
            options.Password.RequireNonAlphanumeric = false;
            options.Password.RequireDigit = false;
            options.Lockout.MaxFailedAccessAttempts = 5;
            options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(15);
        });

        // Add rate limiting middleware.
        services.AddRateLimiting(options =>
        {
            options.GlobalLimiter = PartitionedRateLimiter.Create<ApplicationUser>(
                db => db.GetUserByIdAsync(),
                (userId, cancellationToken) => Task.FromResult(RateLimitPartition.GetFixedWindowLimiter("LoginAttempts", 10, TimeSpan.FromMinutes(5))));
        });

        // Add account recovery services.
        services.AddScoped<IEmailSender, EmailSender>();
        services.AddScoped<IAccountRecoveryService, AccountRecoveryService>();

        // Add custom error handling.
        services.ConfigureApplicationCookie(options =>
        {
            options.Events.OnRedirectToAccessDenied = context =>
            {
                if (context.Request.IsAjaxRequest())
                {
                    context.Response.StatusCode = StatusCodes.Status403Forbidden;
                    return Task.CompletedTask;
                }
                context.Redirect(context.Options.AccessDeniedPath);
                return Task.CompletedTask;
            };
        });

        // Add logging and monitoring.
        services.AddLogging(loggingBuilder =>
        {
            loggingBuilder.AddEventLog();
            loggingBuilder.AddConsole(Configuration.GetSection("Logging"));
        });

        // Add dependency injection for configuration management.
        services.AddSingleton<IConfiguration>(Configuration);

        // Add performance optimization strategies.
        services.Configure<IdentityOptions>(options =>
        {
            options.ClaimsIdentity.UserIdClaimType = ClaimTypes.NameIdentifier;
            options.ClaimsIdentity.UserNameClaimType = ClaimTypes.Email;
        });
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }
        else
        {
            app.UseExceptionHandler("/Home/Error");
            app.UseHsts();
        }

        app.UseHttpsRedirection();
        app.UseStaticFiles();

        app.UseRouting();

        app.UseAuthentication();
        app.UseAuthorization();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllerRoute(
                name: "default",
                pattern: "{controller=Home}/{action=Index}/{id?}");
        });
    }
}

