// Function to validate OAuth token
int validateOAuthToken(const char* jsonStr) {
    struct json_object *parsed_json;
    struct json_object *access_token, *expires_in, *token_type, *refresh_token;

    parsed_json = json_tokener_parse(jsonStr);
    if (!json_object_object_get_ex(parsed_json, "access_token", &access_token)) {
        return 0;
    }
    if (!json_object_object_get_ex(parsed_json, "expires_in", &expires_in)) {
        return 0;
    }
    if (!json_object_object_get_ex(parsed_json, "token_type", &token_type)) {
        return 0;
    }

    // Check token type
    if (strcmp(json_object_get_string(token_type), "Bearer") != 0) {
        return 0;
    }

    // Check expires in
    int expires = json_object_get_int(expires_in);
    if (expires <= 0) {
        return 0;
    }

    // Optional refresh token check
    json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token);

    // If all checks pass, return true
    return 1;
}

// Example usage
int main() {
    const char* validToken = "{\"access_token\":\"abc123\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    const char* invalidToken = "{\"access_token\":\"xyz789\",\"expires_in\":-1,\"token_type\":\"Bearer\"}";

    printf("Valid token: %d\n", validateOAuthToken(validToken));
    printf("Invalid token: %d\n", validateOAuthToken(invalidToken));

    return 0;
}
```

