bool validateSize(int size, int max_size) {
    return size >= 0 && size <= max_size;
}

char* processStringAdvanced(char* input, int size_limit, int log_channel, CallbackFunction callback) {
    if (!validateSize(size_limit, MAX_SIZE)) {
        if (log_channel) {
            logError("Invalid size limit");
        }
        return "";
    }

    if (input == NULL) {
        if (log_channel) {
            logError("Null input pointer");
        }
        return "";
    }

    int len = strlen(input);
    char* result = malloc(len + 2); // Extra space for the slash and null terminator
    if (result == NULL) {
        if (log_channel) {
            logError("Memory allocation failed");
        }
        return "";
    }

    memcpy(result, input, len);
    if ((len + 1) <= size_limit) {
        result[len] = '/';
        result[len + 1] = '\0';
        if (callback != NULL) {
            callback(result);
        }
        return result;
    } else {
        free(result);
        if (log_channel) {
            logError("String too long");
        }
        return "";
    }
}

void myCallback(char* str) {
    printf("Processed string: %s\n", str);
}

int main() {
    char input[] = "Hello";
    char* result = processStringAdvanced(input, 10, 1, myCallback);
    if (result != NULL) {
        printf("Result: %s\n", result);
    } else {
        printf("Error processing string\n");
    }
    free(result);
    return 0;
}
