// Define structures for FSA and state
typedef struct State {
    int id;
    struct State* next;
} State;

typedef struct FSA {
    State* states;
    int numStates;
} FSA;

// Function to dynamically construct a sublist of book names from an FSA
int constructSublist(State** stateList, int* size, FSA* fsa, int lastState) {
    if (lastState >= fsa->numStates || *stateList == NULL) {
        return -1; // Invalid state index or null pointer
    }

    State* newState = malloc(sizeof(State));
    if (!newState) {
        return -2; // Insufficient memory
    }
    newState->id = lastState;
    newState->next = NULL;

    (*stateList)->next = newState;
    *size += 1;

    return 0; // Success
}

// Function to process a large string of text and identify book mentions
regex_t* loadRegex() {
    regex_t* regexArray = malloc(32 * sizeof(regex_t)); // Assuming up to 32 book names
    if (!regexArray) {
        return NULL;
    }

    // Load regular expressions for Old Testament books
    const char* oldTestament[] = {"Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy"};
    for (int i = 0; i < 5; i++) {
        if (regcomp(&regexArray[i], oldTestament[i], REG_EXTENDED | REG_ICASE) != 0) {
            free(regexArray);
            return NULL;
        }
    }

    // Load regular expressions for New Testament books
    const char* newTestament[] = {"Matthew", "Mark", "Luke", "John"};
    for (int i = 0; i < 4; i++) {
        if (regcomp(&regexArray[5 + i], newTestament[i], REG_EXTENDED | REG_ICASE) != 0) {
            regfree(regexArray);
            free(regexArray);
            return NULL;
        }
    }

    return regexArray;
}

void processText(FSA* fsa, const char* text, regex_t** regexes, int numRegexes) {
    regex_t* regexArray = *regexes;

    // Process the text and count book mentions
    for (int i = 0; i < numRegexes; i++) {
        regmatch_t match;
        if (regexec(&regexArray[i], text, 1, &match, REG_EXTENDED) == 0) {
            printf("Found book: %.*s\n", (int)(match.rm_eo - match.rm_so), text + match.rm_so);
        }
    }

    // Free regexes and regex array
    for (int i = 0; i < numRegexes; i++) {
        regfree(&regexArray[i]);
    }
    free(regexArray);
}

// Example usage
int main() {
    FSA fsa;
    State* stateList = malloc(sizeof(State));
    if (!stateList) {
        return -1; // Insufficient memory
    }

    stateList->id = 0;
    stateList->next = NULL;

    int size = 1;
    if (constructSublist(&stateList, &size, &fsa, 2) != 0) {
        free(stateList);
        return -1; // Error in constructing sublist
    }

    regex_t* regexes = loadRegex();
    if (!regexes) {
        free(stateList);
        return -1; // Insufficient memory for regexes
    }

    processText(&fsa, "The Old Testament begins with Genesis.", &regexes, 9);

    free(regexes);
    free(stateList);

    return 0;
}
