    list->interfaces = malloc(initial_capacity * sizeof(NetworkInterface *));
    if (list->interfaces == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
}

void add_interface(InterfaceList *list, const NetworkInterface *interface) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        NetworkInterface **new_interfaces = realloc(list->interfaces, new_capacity * sizeof(NetworkInterface *));
        if (new_interfaces == NULL) {
            // Handle memory allocation failure
            exit(EXIT_FAILURE);
        }
        list->interfaces = new_interfaces;
        list->capacity = new_capacity;
    }
    list->interfaces[list->count] = malloc(sizeof(NetworkInterface));
    if (list->interfaces[list->count] == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    memcpy(list->interfaces[list->count], interface, sizeof(NetworkInterface));
    list->count++;
}

void free_interface_list(InterfaceList *list) {
    for (size_t i = 0; i < list->count; i++) {
        free(list->interfaces[i]);
    }
    free(list->interfaces);
    list->interfaces = NULL;
    list->count = 0;
    list->capacity = 0;
}

void iterate_interfaces(InterfaceList *list, void (*callback)(NetworkInterface *)) {
    for (size_t i = 0; i < list->count; i++) {
        callback(list->interfaces[i]);
    }
}
