// Define a function to recursively traverse the DOM tree
function recursiveTraverse(node, selector, filterFn, depth = 0, maxDepth) {
  const result = [];

  // Check if we've reached the maximum depth limit
  if (maxDepth !== undefined && depth > maxDepth) return result;

  // Use a query selector to find matching elements
  const matchingElements = node.querySelectorAll(selector);

  for (let element of matchingElements) {
    // Apply the filter function dynamically based on attributes
    if (filterFn(element)) {
      result.push(element);
    }

    // Recursively traverse child nodes
    result = result.concat(recursiveTraverse(element, selector, filterFn, depth + 1, maxDepth));
  }

  return result;
}

