    private ConcurrentBag<NFAPI_CRC_INDICATION_PDU_T> _networkFunctionArray;
    private object _lockObject;

    public DynamicNetworkFunctionManager()
    {
        _networkFunctionArray = new ConcurrentBag<NFAPI_CRC_INDICATION_PDU_T>();
        _lockObject = new object();
    }

    public void LoadConfiguration(string xmlFilePath)
    {
        XDocument xmlDoc = XDocument.Load(xmlFilePath);
        var tileConfigurations = xmlDoc.Descendants("Tile");

        foreach (var config in tileConfigurations)
        {
            int size = int.Parse(config.Attribute("Size").Value);
            int xPosition = int.Parse(config.Attribute("X").Value);
            int yPosition = int.Parse(config.Attribute("Y").Value);
            bool canMove = bool.Parse(config.Attribute("CanMove").Value);

            // Validate tile configuration
            if (size <= 0 || xPosition < 0 || yPosition < 0)
