                    RNTI = GenerateUniqueRNTI(),
                    CRC_INDICATION_REL8_TAG = new CRC_INDICATION_REL8_TAG { CRCFLAG = RandomValue() }
                };

                if (CheckMemoryUsage())
                {
                    lock (_lockObject)
                    {
                        _networkFunctionArray.Add(pdu);
                    }
                }
            }
        }
    }

    private int GenerateUniqueRNTI()
    {
        // Generate a unique RNTI
        return new Random().Next(1, 65536);
    }

    private bool CheckMemoryUsage()
    {
        // Check if allocated memory does not exceed the maximum limit
        return _networkFunctionArray.Count * sizeof(NFAPI_CRC_INDICATION_PDU_T) <= MAX_MEMORY_LIMIT;
    }

    private bool RandomValue()
    {
        // Randomly set CRCFLAG
        return new Random().Next(2) == 0;
