function traverseDOM(node, selector, filterFn, maxDepth = Infinity, depth = 0, cache = new Map()) {
  if (depth >= maxDepth) return [];

  const matches = [];
  const element = node.querySelector(selector);

  if (element && filterFn(element)) {
    matches.push(element);
  }

  for (let i = 0; i < node.children.length; i++) {
    matches.push(...traverseDOM(node.children[i], selector, filterFn, maxDepth, depth + 1, cache));
  }

  return matches;
}

async function fetchAndCacheData(element, cache) {
  const url = element.getAttribute('data-api-url');

  if (cache.has(url)) {
    return cache.get(url);
  } else {
    const response = await fetch(url);
    const data = await response.json();
    cache.set(url, data);
    return data;
