public class DistributedStorageConfig {
    private static final int MAX_MEMORY_LIMIT = 1024; // in MB
    private static final int NUM_THREADS = 20;

    private StorageNode[] nodes;
    private ConcurrentHashMap<Integer, Lock> nodeLocks;
    private long allocatedMemory;
    private boolean isResizing;

    public DistributedStorageConfig(int M) {
        nodes = new StorageNode[M];
        nodeLocks = new ConcurrentHashMap<>();
        for (int i = 0; i < M; i++) {
            nodeLocks.put(i, new ReentrantLock());
        }
        allocatedMemory = 0;
    }

    public void loadConfiguration(String jsonFilePath) {
        // Load JSON configuration and populate the nodes array
        try (FileReader reader = new FileReader(jsonFilePath)) {
            // Assume there's a method to parse JSON and create StorageNode objects
            nodes = parseJsonToStorageNodes(reader);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public boolean addNode(StorageNode node, int index) {
        if (isResizing || index < 0 || index >= nodes.length) return false;

        Lock lock = nodeLocks.get(index);
        lock.lock();
        try {
            if (nodes[index] != null || allocatedMemory + node.getDiskCapacity() > MAX_MEMORY_LIMIT) return false;

            nodes[index] = node;
            allocatedMemory += node.getDiskCapacity();
            return true;
        } finally {
            lock.unlock();
        }
    }

    public boolean removeNode(int index) {
        if (isResizing || index < 0 || index >= nodes.length) return false;

        Lock lock = nodeLocks.get(index);
        lock.lock();
        try {
            if (nodes[index] == null) return false;

            allocatedMemory -= nodes[index].getDiskCapacity();
            nodes[index] = null;
            return true;
        } finally {
            lock.unlock();
        }
    }

    public void reverseIterator() {
        // Implement a reverse iterator mechanism
    }

