int main() {
    int *array = (int *)malloc(MAX_INTS * sizeof(int));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    int count = 0;
    while (scanf("%d", &array[count]) == 1 && count < MAX_INTS) {
        count++;
    }

    if (count >= MAX_INTS) {
        fprintf(stderr, "Too many integers. Maximum allowed is %d\n", MAX_INTS);
        free(array);
        return EXIT_FAILURE;
    }

    int max_value = array[0];
    for (int i = 1; i < count; i++) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }

    printf("Largest integer: %d\n", max_value);
    free(array);

    return EXIT_SUCCESS;
}
