#include <vector>
#include <algorithm>

void removeDuplicates(std::vector<int>& vec) {
    auto last = std::unique(vec.begin(), vec.end());
    vec.erase(last, vec.end());
}

void modifyVector(std::vector<int>& vec, int targetValue, int insertionValue, int limit) {
    if (vec.size() >= limit) return;

    removeDuplicates(vec);

    auto it = std::find(vec.begin(), vec.end(), targetValue);
    if (it != vec.end()) {
        if (it + 1 < vec.end() && vec[it + 1] == insertionValue) {
            vec.erase(it + 1);
        } else {
            vec.insert(it + 1, insertionValue);
        }
    } else {
        vec.push_back(insertionValue);
    }

    if (vec.size() > limit) {
        vec.pop_back();
    }
}
