package com.messageframework;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MessageProcessingFramework {
    private static final MessageProcessingFramework INSTANCE = new MessageProcessingFramework();
    private ExecutorService executorService;
    private Map<String, OutputDestination> outputDestinations;
    private FilterCriteria filterCriteria;

    private MessageProcessingFramework() {
        this.outputDestinations = new HashMap<>();
        this.executorService = Executors.newCachedThreadPool();
        initializeFilterCriteria();
    }

    public static MessageProcessingFramework getInstance() {
        return INSTANCE;
    }

    @Override
    protected void finalize() throws Throwable {
        try {
            executorService.shutdown();
            for (OutputDestination destination : outputDestinations.values()) {
                destination.close();
            }
        } finally {
            super.finalize();
        }
    }

    public void addOutputDestination(String name, OutputDestination destination) {
        outputDestinations.put(name, destination);
    }

    public void removeOutputDestination(String name) {
        outputDestinations.remove(name);
        ((AbstractOutputDestination) outputDestinations.get(name)).close();
    }

    public void setFilterCriteria(FilterCriteria criteria) {
        this.filterCriteria = criteria;
    }

    public void processEvent(Event event) {
        if (filterCriteria.matches(event)) {
            for (OutputDestination destination : outputDestinations.values()) {
                executorService.submit(() -> destination.send(event));
            }
        }
    }

    private void initializeFilterCriteria() {
        filterCriteria = new DefaultFilterCriteria();
    }

    // Additional methods and classes can be added here as needed
}
