        System.out.println("Edge detection sensitivity: " + edgeDetectionSensitivity);
        System.out.println("Input directory: " + inputDirectory);
        System.out.println("Output directory: " + outputDirectory);
        System.out.println("Histogram equalization settings: " + histogramEqualizationSettings);
    }

    public static void main(String[] args) {
