using System;
using System.Collections.Generic;
using Microsoft.AspNetCore.Mvc;

[Route("api/[controller]")]
public class RoleController : ControllerBase
{
    private static Dictionary<string, string> roles = new Dictionary<string, string>();
    private static readonly object lockObject = new object();

    [HttpPost]
    public IActionResult CreateRole([FromBody] RoleModel role)
    {
        if (roles.ContainsKey(role.Name))
            return BadRequest("Role already exists.");

        lock (lockObject)
        {
            roles[role.Name] = role.Description;
            LogChange($"Created role: {role.Name}");
        }

        return Ok();
    }

    [HttpPut]
    public IActionResult UpdateRole([FromBody] RoleModel role)
    {
        if (!roles.ContainsKey(role.Name))
            return NotFound("Role not found.");

        lock (lockObject)
        {
            roles[role.Name] = role.Description;
            LogChange($"Updated role: {role.Name}");
        }

        return Ok();
    }

    [HttpDelete("{name}")]
    public IActionResult DeleteRole(string name)
    {
        if (!roles.ContainsKey(name))
            return NotFound("Role not found.");

        lock (lockObject)
        {
            roles.Remove(name);
            LogChange($"Deleted role: {name}");
        }

        return Ok();
    }

    [HttpPost("bulk")]
    public IActionResult BulkUpdateRoles([FromBody] List<RoleModel> rolesToUpdate)
    {
        foreach (var role in rolesToUpdate)
        {
            if (!roles.ContainsKey(role.Name))
