    return jsonify({"message": "Resource deleted"}), 204

# Route for bulk update of resources
@app.route('/resources/bulk', methods=['PUT'])
def update_bulk_resources():
    data = request.json
    updated_ids = []
    for resource in data:
        if validate_resource(resource):
            redis_client.setex(f"resource:{resource['id']}", 3600, json.dumps(resource))
            updated_ids.append(resource['id'])
    return jsonify({"updated_ids": updated_ids}), 200

# Route for getting a summary of all resources
@app.route('/resources/summary', methods=['GET'])
def get_resource_summary():
    keys = redis_client.keys("resource:*")
    summary = []
    for key in keys:
        resource_data = json.loads(redis_client.get(key))
        summary.append({"id": resource_data['id'], "name": resource_data['name']})
    return jsonify(summary), 200

