    private ConcurrentDictionary<int, Record> resourceCache = new ConcurrentDictionary<int, Record>();
    private int loadFactorThreshold = 0.75f;
    private int maxCacheSize = 1000;
    private Random random = new Random();
    private bool isCompacting = false;

    public void UpdateResourceMetadata(int resourceId, int version, ResourceMetadata metadata)
    {
        if (resourceId < 0 || version < 0 || metadata == null)
        {
            throw new ArgumentException("Invalid input parameters.");
        }

        lock (resourceCache)
        {
            while (isCompacting)
            {
                // Wait for compaction to complete
                System.Threading.Thread.Sleep(100);
            }

            if (loadFactorThreshold > GetLoadFactor())
            {
                CompactHashTable();
            }
        }

        Record existingRecord;
        if (resourceCache.TryGetValue(resourceId, out existingRecord))
        {
            existingRecord.Value = version;
            existingRecord.Offset = metadata.Offset;
            existingRecord.Key = metadata.Key;

            // Notify observers about the update
            OnResourceUpdated(resourceId);
        }
        else
        {
            Record newRecord = new Record { Value = version, Offset = metadata.Offset, Key = metadata.Key };
            resourceCache.TryAdd(resourceId, newRecord);

            // Retrieve latest version from external data store and cache it locally
            if (resourceCache.Count > maxCacheSize)
            {
                CompactHashTable();
            }

            // Notify observers about the new record
            OnResourceAdded(resourceId);
        }
    }

    private float GetLoadFactor()
    {
        return (float)resourceCache.Count / resourceCache.ConcurrentDictionary<int, Record>.GetBucketCount();
    }

    private void CompactHashTable()
    {
        if (isCompacting)
        {
            return;
        }

        isCompacting = true;

        try
        {
            // Perform compaction logic here
            // ...

            // Notify observers about the compaction
            OnHashCompacted();
        }
        finally
        {
            isCompacting = false;
        }
