const fs = require('fs').promises;
const path = require('path');
const Ajv = require('ajv');
const { promisify } = require('util');
const sleep = promisify(setTimeout);

const ajv = new Ajv();

// Define the configuration schema
const configSchema = {
  type: 'object',
  properties: {
    port: { type: 'number' },
    database: {
      type: 'object',
      properties: {
        host: { type: 'string' },
        port: { type: 'number' },
        name: { type: 'string' }
      },
      required: ['host', 'port', 'name'],
      additionalProperties: false
    }
  },
  required: ['port', 'database'],
  additionalProperties: false
};

// Create a cache for configuration files
const configCache = {};

// Function to validate the configuration file against the schema
function validateConfig(config) {
  const validator = ajv.compile(configSchema);
  return validator(config);
}

// Function to read and parse the configuration file
async function readConfig(filePath) {
  try {
    const content = await fs.readFile(filePath, 'utf8');
    const config = JSON.parse(content);
    if (!validateConfig(config)) {
      throw new Error('Invalid configuration file format');
    }
    return config;
  } catch (error) {
    console.error(`Error reading or parsing configuration file: ${error.message}`);
    throw error;
  }
}

// Function to fetch the configuration with caching and validation
async function getConfig(filePath) {
  if (!configCache[filePath] || Date.now() - configCache[filePath].timestamp > 60 * 1000) {
    configCache[filePath] = { timestamp: Date.now(), data: await readConfig(filePath) };
  }
  return configCache[filePath].data;
}

// Function to start the background worker for updating the cache
async function startBackgroundWorker(interval) {
  setInterval(async () => {
    const filePath = process.env.CONFIG_FILE_PATH || path.resolve(__dirname, 'config.json');
    try {
      await getConfig(filePath);
      console.log('Configuration updated successfully');
    } catch (error) {
      console.error(`Failed to update configuration: ${error.message}`);
    }
  }, interval);
}

// Start the background worker with a 5-minute interval
startBackgroundWorker(5 * 60 * 1000);

module.exports = { getConfig };
```

