function updateContentSection(sectionId, newBlocks) {
    const section = document.getElementById(sectionId);
    if (!section) return;

    const batchUpdate = [];
    newBlocks.forEach(block => {
        switch (block.type) {
            case 'text':
                batchUpdate.push(`<p id="${block.id}">${block.content}</p>`);
                break;
            case 'image':
                batchUpdate.push(`<img id="${block.id}" src="${block.content}" alt="Image" loading="lazy">`);
                break;
            case 'link':
                batchUpdate.push(`<a id="${block.id}" href="${block.content}">${block.content}</a>`);
                break;
            case 'customHTML':
                batchUpdate.push(block.content);
                break;
            default:
                console.warn(`Unsupported content type: ${block.type}`);
        }
    });

    const newHtml = batchUpdate.join('');
    section.innerHTML += newHtml;

    // Handle asynchronous image loading
    const images = section.querySelectorAll(`#${newBlocks.filter(b => b.type === 'image').map(b => b.id).join(',')}`);
    images.forEach(img => {
        img.onload = () => {
            // Image loaded, can perform additional actions if needed
        };
    });
}

// Example usage:
