import threading
import queue
import time

class VideoProcessor:
    def __init__(self, max_frames_in_memory=100):
        self.frame_queue = queue.Queue(maxsize=max_frames_in_memory)
        self.processed_frames = []
        self.skipped_frames = 0
        self.lock = threading.Lock()
        self.error_count = 0

    def add_frame(self, frame):
        try:
            self.frame_queue.put(frame, timeout=1)  # Non-blocking put with timeout
        except queue.Full:
            print("Frame queue is full, skipping frame")

    def process_frames(self):
        while True:
            try:
                with self.lock:
                    if not self.frame_queue.empty():
                        frame = self.frame_queue.get_nowait()
                        processed_frame = self._process_frame(frame)
                        self.processed_frames.append(processed_frame)
                    else:
                        time.sleep(0.1)  # Avoid busy-waiting
            except queue.Empty:
                break

    def _process_frame(self, frame):
        # Simulate frame processing
        return f"Processed {frame}"

    def get_processed_frames(self):
        with self.lock:
            frames = self.processed_frames.copy()
            self.processed_frames.clear()
        return frames

    def get_skipped_frames(self):
        return self.skipped_frames

    def handle_error(self, error_type):
        self.error_count += 1
        print(f"Error occurred: {error_type}")

# Example usage:
if __name__ == "__main__":
    processor = VideoProcessor()
    threads = [threading.Thread(target=processor.process_frames) for _ in range(4)]

    for thread in threads:
        thread.start()

    # Simulate adding frames
    for i in range(200):
        processor.add_frame(i)
        time.sleep(0.05)  # Simulate frame arrival rate

    for thread in threads:
        thread.join()

    print(f"Processed {len(processor.processed_frames)} frames")
    print(f"Skipped {processor.get_skipped_frames()} frames")
```

