// DynamicRandomNumberGenerator.js

import { loadScript } from './scriptLoader.js';

class MersenneTwister {
    constructor(seed) {
        // Initialize Mersenne Twister algorithm here
    }

    destructor() {}

    static generator = null;
}

export default class DynamicRandomNumberGenerator {
    constructor(filePaths, dependencyGraph) {
        this.filePaths = filePaths;
        this.dependencyGraph = dependencyGraph;
        this.cachedScripts = {};
        this.isRunning = false;
        this.errorLog = [];
    }

    async loadScripts() {
        try {
            for (const file of this.filePaths) {
                if (!this.dependencyGraph[file] || this.checkDependencies(file)) {
                    await loadScript(file, this);
                    this.cachedScripts[file] = true;
                }
            }
        } catch (error) {
            this.errorLog.push({ time: new Date(), error });
            console.error('Failed to load script:', error);
        }
    }

    checkDependencies(file) {
        const dependencies = this.dependencyGraph[file];
        if (!dependencies) return false;

        for (const dependency of dependencies) {
            if (!this.cachedScripts[dependency]) return true;
        }

        return false;
    }

    initializeRandomNumberGenerator() {
        if (!MersenneTwister.generator) {
            MersenneTwister.generator = new MersenneTwister(Date.now());
        }
    }

    generateRandomNumber() {
        return MersenneTwister.generator.random();
    }

    start() {
        this.isRunning = true;
        this.loadScripts().then(() => {
            this.initializeRandomNumberGenerator();
        }).catch((error) => {
            console.error('Failed to start generator:', error);
        });
    }

    stop() {
        this.isRunning = false;
    }
}

// scriptLoader.js

export async function loadScript(path, moduleInstance) {
    return new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = path;
        script.onload = () => resolve();
        script.onerror = (error) => reject(error);
        document.head.appendChild(script);

        script.onbeforeunload = () => {
            if (!moduleInstance.isRunning) {
                moduleInstance.errorLog.push({ time: new Date(), error: 'Script was interrupted' });
            }
        };
    });
}
