import java.io.File;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

public class FilePathProcessor {

    private final Map<String, Algorithm> algorithms = new ConcurrentHashMap<>();
    private final List<Algorithm> activeAlgorithms = new ArrayList<>();

    public FilePathProcessor(String configFilePath) {
        loadConfigurations(configFilePath);
        initializeAlgorithms();
    }

    private void loadConfigurations(String configFilePath) {
        try {
            List<String> lines = Files.readAllLines(Paths.get(configFilePath));
            for (String line : lines) {
                String[] parts = line.split(",");
                if (parts.length == 2 && "ALGORITHMS".equals(parts[0])) {
                    Arrays.stream(parts[1].split(";"))
                            .filter(algorithm -> isAlgorithmSupported(algorithm))
                            .forEach(activeAlgorithms::add);
                }
            }
        } catch (IOException e) {
            System.err.println("Error reading configuration file: " + e.getMessage());
        }
    }

    private boolean isAlgorithmSupported(String algorithm) {
        return Arrays.asList("AES", "Camellia", "MD5", "SHA-1", "SHA-256").contains(algorithm)
                || algorithm.startsWith("CUSTOM:");
    }

    private void initializeAlgorithms() {
        for (String name : activeAlgorithms.stream()
                .map(Algorithm::getName)
                .collect(Collectors.toList())) {
            Algorithm algo = createAlgorithmInstance(name);
            if (algo != null) {
                algorithms.put(name, algo);
            }
        }
    }

    private Algorithm createAlgorithmInstance(String name) {
        try {
            switch (name) {
                case "AES":
                    return new AES();
                case "Camellia":
                    return new Camellia();
                case "MD5":
                    return new MD5();
                case "SHA-1":
                    return new SHA1();
                case "SHA-256":
                    return new SHA256();
                default:
                    String[] parts = name.split(":");
                    if (parts.length == 3 && "CUSTOM".equals(parts[0])) {
                        Class<?> clazz = Class.forName(parts[2]);
                        return (Algorithm) clazz.getDeclaredConstructor().newInstance();
                    }
            }
        } catch (Exception e) {
            System.err.println("Error creating algorithm instance: " + e.getMessage());
        }
        return null;
    }

    public int countUniqueFiles(List<String> filePaths) {
        Map<FileKey, Integer> fileMap = new ConcurrentHashMap<>();
        long startTime = System.currentTimeMillis();

        for (String path : filePaths) {
            File file = new File(path);
            if (!file.isSymbolicLink()) {
                try {
                    FileKey key = generateFileKey(file);
                    fileMap.merge(key, 1, Integer::sum);
                } catch (Exception e) {
                    System.err.println("Error processing file: " + path + " - " + e.getMessage());
                }
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Processing time: " + (endTime - startTime) + " ms");
        return fileMap.size();
    }

    private FileKey generateFileKey(File file) throws IOException {
        BasicFileAttributes attrs = Files.readAttributes(file.toPath(), BasicFileAttributes.class);
        byte[] hash = generateHash(file);
        return new FileKey(attrs.lastModifiedTime().toMillis(), attrs.size(), hash);
    }

    private byte[] generateHash(File file) throws IOException {
        MessageDigest digest = algorithms.get("SHA-256").getDigest();
        try (InputStream is = Files.newInputStream(file.toPath())) {
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }
        return digest.digest();
    }

    private static class FileKey {
        final long lastModifiedTime;
        final long size;
        final byte[] hash;

        public FileKey(long lastModifiedTime, long size, byte[] hash) {
            this.lastModifiedTime = lastModifiedTime;
            this.size = size;
            this.hash = hash;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof FileKey)) return false;
            FileKey fileKey = (FileKey) o;
            return lastModifiedTime == fileKey.lastModifiedTime &&
                    size == fileKey.size &&
                    Arrays.equals(hash, fileKey.hash);
        }

        @Override
        public int hashCode() {
            int result = Long.hashCode(lastModifiedTime);
            result = 31 * result + Long.hashCode(size);
            result = 31 * result + Arrays.hashCode(hash);
            return result;
        }
    }

    interface Algorithm {
        MessageDigest getDigest();
    }

    private static class AES implements Algorithm {
        @Override
        public MessageDigest getDigest() {
            try {
                return MessageDigest.getInstance("AES");
            } catch (NoSuchAlgorithmException e) {
                throw new RuntimeException(e);
            }
        }
    }

    // Implement other algorithms similarly...

    public static void main(String[] args) {
        FilePathProcessor processor = new FilePathProcessor("config.txt");
        List<String> filePaths = Arrays.asList(
                "/path/to/file1",
                "/path/to/file2",
                "/path/to/file3"
        );
        int uniqueFileCount = processor.countUniqueFiles(filePaths);
        System.out.println("Number of unique files: " + uniqueFileCount);
    }
}
