import java.util.HashMap;
import java.util.Map;

public class ServiceManager {
    private Map<String, Service> services = new HashMap<>();
    private ThirdPartyCloudService cloudService;
    private RetryMechanism retryMechanism;

    public ServiceManager(ThirdPartyCloudService cloudService, RetryMechanism retryMechanism) {
        this.cloudService = cloudService;
        this.retryMechanism = retryMechanism;
    }

    public void addService(String id, Service service) {
        services.put(id, service);
        startService(id);
    }

    public void removeService(String id) {
        stopService(id);
        services.remove(id);
    }

    public void modifyService(String id, Service newService) {
        stopService(id);
        services.replace(id, newService);
        startService(id);
    }

    private void startService(String id) {
        retryMechanism.retry(() -> {
            services.get(id).start();
            cloudService.logEvent(id, "Started", System.currentTimeMillis());
        });
    }

    private void stopService(String id) {
        retryMechanism.retry(() -> {
            services.get(id).stop();
            cloudService.logEvent(id, "Stopped", System.currentTimeMillis());
        });
    }
}

