class RetryMechanism {
    private int maxRetries;
    private double backoffFactor;

    public RetryMechanism(int maxRetries, double backoffFactor) {
        this.maxRetries = maxRetries;
        this.backoffFactor = backoffFactor;
    }

    public void retry(Runnable task) {
        for (int i = 0; i <= maxRetries; i++) {
            try {
                task.run();
                return;
            } catch (Exception e) {
                if (i == maxRetries) throw new RuntimeException("Failed after " + maxRetries + " attempts", e);
                long backoffTime = (long) (Math.pow(backoffFactor, i) * 100);
                try {
                    Thread.sleep(backoffTime);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }
}

// Configuration setup in main method
public class Main {
    public static void main(String[] args) {
        ThirdPartyCloudService cloudService = new ThirdPartyCloudService();
        RetryMechanism retryMechanism = new RetryMechanism(3, 2);
        ServiceManager manager = new ServiceManager(cloudService, retryMechanism);

        // Add services, modify them, and remove them
    }
}
