function renderServices(services) {
    if (!services || !Array.isArray(services)) return "Invalid input: Expected an array of service objects";
    if (services.length === 0) return "";

    const cacheKey = services.map(service => `${service.id}-${service.state}-${service.lastUpdated}`).join('-');
    const cachedHtml = localStorage.getItem(cacheKey);
    if (cachedHtml) return cachedHtml;

    const tableRows = services.map(service => `
        <tr>
            <td>${service.id}</td>
            <td>${service.state}</td>
            <td>${new Date(service.lastUpdated).toLocaleString()}</td>
        </tr>
    `).join('');

    localStorage.setItem(cacheKey, tableRows);
    return tableRows;
}

// Example usage:
const services = [
    { id: "1", state: "Active", lastUpdated: new Date().getTime() },
    { id: "2", state: "Stopped", lastUpdated: new Date().getTime() }
];
console.log(renderServices(services));
