// Define a RequestBuilder struct with necessary fields for HTTP/HTTPS requests
pub struct RequestBuilder {
    url: String,
    method: String,
    headers: Vec<(String, String)>,
    body: Option<String>,
}

impl RequestBuilder {
    // Create a new instance of RequestBuilder
    pub fn new(url: &str) -> Self {
        RequestBuilder {
            url: url.to_string(),
            method: "GET".to_string(),
            headers: vec![],
            body: None,
        }
    }

    // Set the HTTP method for the request
    pub fn method(mut self, method: &str) -> Self {
        self.method = method.to_string();
        self
    }

    // Add a header to the request
    pub fn header(mut self, key: &str, value: &str) -> Self {
        self.headers.push((key.to_string(), value.to_string()));
        self
    }

    // Set the body of the request
    pub fn body(mut self, body: &str) -> Self {
        self.body = Some(body.to_string());
        self
    }

    // Execute the HTTP/HTTPS request and return the response
    pub async fn send(self) -> Result<reqwest::Response, reqwest::Error> {
        let client = reqwest::Client::new();
        match self.method.as_str() {
            "GET" => client.get(&self.url).headers(self.headers).send().await,
            "POST" => client.post(&self.url).headers(self.headers).body(self.body.unwrap()).send().await,
            "PUT" => client.put(&self.url).headers(self.headers).body(self.body.unwrap()).send().await,
            "DELETE" => client.delete(&self.url).headers(self.headers).send().await,
            _ => Err(reqwest::Error::new(reqwest::StatusCode::METHOD_NOT_ALLOWED, "Unsupported HTTP method")),
        }
    }
}

// Example usage of the RequestBuilder
#[tokio::main]
async fn main() {
    let response = RequestBuilder::new("https://api.example.com/data")
        .method("GET")
        .header("Authorization", "Bearer your_token_here")
        .send()
        .await;

    match response {
        Ok(res) => println!("Response: {}", res.text().await.unwrap()),
        Err(e) => eprintln!("Error: {}", e),
    }
}
```

