<?php
class ClinicUpdater {
    private $dbConnection;
    private $apiClient;

    public function __construct($dbConfig, $apiConfig) {
        // Initialize database connection
        $this->dbConnection = new PDO("mysql:host={$dbConfig['host']};dbname={$dbConfig['database']}", $dbConfig['username'], $dbConfig['password']);
        $this->dbConnection->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Initialize API client
        $this->apiClient = new APIClient($apiConfig);
    }

    public function updateClinicStatus($clinicId, $newStatus) {
        try {
            // Begin transaction
            $this->dbConnection->beginTransaction();

            // Fetch current clinic data
            $stmt = $this->dbConnection->prepare("SELECT last_modified_ip, last_modified_date FROM clinics WHERE id = :id FOR UPDATE");
            $stmt->execute(['id' => $clinicId]);
            $currentData = $stmt->fetch(PDO::FETCH_ASSOC);

            if (!$currentData) {
                throw new Exception("Clinic not found.");
            }

            // Verify status via external API
            $apiResponse = $this->apiClient->verifyStatus($clinicId);
            if ($apiResponse['status'] !== $newStatus) {
                throw new Exception("API verification failed.");
            }

            // Update clinic data
            $stmt = $this->dbConnection->prepare("UPDATE clinics SET status = :newStatus, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :id");
            $stmt->execute([
                'newStatus' => $newStatus,
                'ip' => $_SERVER['REMOTE_ADDR'],
                'id' => $clinicId
            ]);

            // Commit transaction
            $this->dbConnection->commit();

            return "Update successful.";
        } catch (Exception $e) {
            // Rollback in case of error
            if ($this->dbConnection->inTransaction()) {
                $this->dbConnection->rollback();
            }
            return "Error: " . $e->getMessage();
        }
    }
}

// Example usage:
$dbConfig = [
    'host' => 'localhost',
    'database' => 'healthcare_db',
    'username' => 'user',
    'password' => 'pass'
];

$apiConfig = [
    'url' => 'https://api.example.com/verify',
    'apiKey' => 'your_api_key'
];

$updater = new ClinicUpdater($dbConfig, $apiConfig);
$result = $updater->updateClinicStatus(123, 'active');
echo $result;
?>
