#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ARRAY_SIZE 50000
#define MAX_RETRIES 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    int size;
    int head;
    int tail;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} RingBuffer;

RingBuffer* create_ring_buffer(int size) {
    RingBuffer *buffer = (RingBuffer*)malloc(sizeof(RingBuffer));
    buffer->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    buffer->size = size;
    buffer->head = 0;
    buffer->tail = 0;
    pthread_mutex_init(&buffer->lock, NULL);
    pthread_cond_init(&buffer->not_full, NULL);
    pthread_cond_init(&buffer->not_empty, NULL);
    return buffer;
}

void destroy_ring_buffer(RingBuffer *buffer) {
    free(buffer->array);
    free(buffer);
}

int enqueue(RingBuffer *buffer, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&buffer->lock);
    while ((buffer->tail + 1) % buffer->size == buffer->head)
        pthread_cond_wait(&buffer->not_full, &buffer->lock);
    buffer->array[buffer->tail] = item;
    buffer->tail = (buffer->tail + 1) % buffer->size;
    pthread_cond_signal(&buffer->not_empty);
    pthread_mutex_unlock(&buffer->lock);
    return 0;
}

int dequeue(RingBuffer *buffer, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&buffer->lock);
    while (buffer->head == buffer->tail)
        pthread_cond_wait(&buffer->not_empty, &buffer->lock);
    *item = buffer->array[buffer->head];
    buffer->head = (buffer->head + 1) % buffer->size;
    pthread_cond_signal(&buffer->not_full);
    pthread_mutex_unlock(&buffer->lock);
    return 0;
}

void* payment_transaction_thread(void *arg) {
    RingBuffer *buffer = (RingBuffer*)arg;
    NFAPI_CRC_INDICATION_PDU_T item;

    while (1) {
        dequeue(buffer, &item);

        // Process transaction
        if (!process_transaction(&item)) {
            // Retry mechanism
            for (int i = 0; i < MAX_RETRIES; i++) {
                if (process_transaction(&item))
                    break;
                sleep(1);
            }
            if (!process_transaction(&item))
                log_error(&item);
        }

        // Log transaction history
        log_transaction_history(&item);
    }

    return NULL;
}

int main() {
    RingBuffer *buffer = create_ring_buffer(MAX_ARRAY_SIZE);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++)
        pthread_create(&threads[i], NULL, payment_transaction_thread, buffer);

    // Simulate transaction requests
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T item;
        generate_random_item(&item);
        enqueue(buffer, item);
    }

    for (int i = 0; i < 10; i++)
        pthread_join(threads[i], NULL);

    destroy_ring_buffer(buffer);

    return 0;
}
