        pthread_mutex_unlock(&pdu_mutex);

        // Simulate time delay
        usleep(60000000); // 1 minute
    }
    return NULL;
}

int main() {
    srand(time(NULL));

    pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * max_pdu_count);

