    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    CRC_INDICATION_REL8_TAG key;
    int value;
    UT_hash_handle hh;
} CacheEntry;

CacheEntry *cache = NULL;
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdu(int N) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        pdus[i].ue_info = generate_random_rx_ue_information_tag();
        pdus[i].rnti = generate_random_rnti();
        pdus[i].crc_indication.crcflag = (rand() % 2) ? 1 : 0;

        CacheEntry *entry;
        pthread_mutex_lock(&cache_mutex);
        HASH_FIND(hh, cache, &(pdus[i].crc_indication), sizeof(CRC_INDICATION_REL8_TAG), entry);
        if (!entry) {
            entry = (CacheEntry*)malloc(sizeof(CacheEntry));
            entry->key = pdus[i].crc_indication;
            entry->value = 1;
            HASH_ADD(hh, cache, key, sizeof(CRC_INDICATION_REL8_TAG), entry);
        } else {
            entry->value++;
        }
        pthread_mutex_unlock(&cache_mutex);
    }

    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, int N) {
    for (int i = 0; i < N; i++) {
        // Perform any necessary cleanup on individual PDUs
    }
    free(pdus);
}

void destroy_cache() {
    CacheEntry *entry, *tmp;
    pthread_mutex_lock(&cache_mutex);
    HASH_ITER(hh, cache, entry, tmp) {
        HASH_DEL(cache, entry);
        free(entry);
    }
    pthread_mutex_unlock(&cache_mutex);
}
