void initialize_connection_pool(int K) {
    num_connections = K;
    pthread_mutex_init(&pool_lock, NULL);
}

void add_connection(int client_id, const char* server_address, int timeout_duration) {
    if (num_connections >= MAX_CONNECTIONS) {
        printf("Connection pool is full\n");
        return;
    }
    TCP_CONNECTION_T new_connection = {client_id, strcpy((char*)server_address, server_address), timeout_duration};
    pthread_mutex_lock(&pool_lock);
    connection_pool[num_connections++] = new_connection;
    pthread_mutex_unlock(&pool_lock);
}

void* manage_connections(void* arg) {
