import asyncio
from typing import Optional

class PasswordUpdateService:
    def __init__(self, auth_service, rate_limiter, db_client, cache):
        self.auth_service = auth_service
        self.rate_limiter = rate_limiter
        self.db_client = db_client
        self.cache = cache

    async def update_password(self, user_id: str, new_password: str, mfa_enrolled: Optional[bool] = None) -> bool:
        try:
            # Check rate limit and quota enforcement
            if not await self.rate_limiter.allow_request():
                return False  # Rate limit exceeded

            # Validate password complexity
            if not self.auth_service.validate_password_complexity(new_password):
                return False  # Password does not meet requirements

            # Check for multi-factor authentication enrollment
            mfa_enabled = self.cache.get(f"mfa_status:{user_id}", None)
            if mfa_enrolled is not None and mfa_enrolled != mfa_enabled:
                self.cache.set(f"mfa_status:{user_id}", mfa_enrolled)

            # Update password in database with retry logic
            for _ in range(3):
                try:
                    await self.db_client.update_password(user_id, new_password)
                    break  # Success
                except Exception as e:
                    await asyncio.sleep(0.5)  # Retry after half-second delay

            return True  # Password updated successfully
        except Exception as e:
            print(f"Error updating password for user {user_id}: {e}")
            return False  # Failed to update password
