def process_file(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = sorted(file.readlines())
            last_line = lines[-1].strip()
            sequence_number = re.search(r'\d+', last_line).group() if re.search(r'\d+', last_line) else None
            return {file_path: sequence_number}
