        print(f"Error processing {file_path}: {e}")
        return {file_path: None}

def process_files_in_directory(directory, max_workers=5, file_pattern='.*', max_retries=3, retry_delay=2, chunk_size=None):
    files = [os.path.join(directory, f) for f in os.listdir(directory) if re.match(file_pattern, f)]
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        future_to_file = {executor.submit(process_file, file): file for file in files}
        results = {}
        for future in as_completed(future_to_file):
            file_path = future_to_file[future]
            try:
                sequence_number = future.result()
                results.update(sequence_number)
            except Exception as e:
                print(f"Exception: {e}")
                if max_retries > 0:
                    time.sleep(retry_delay * (2 ** len(results)))
                    return process_files_in_directory(directory, max_workers, file_pattern, max_retries - 1, retry_delay, chunk_size)
    report = f"Processed files:\n{results}"
    print(report)

# Example usage
process_files_in_directory('/path/to/directory', file_pattern='*.txt')
```

This code defines a `process_file` function that reads a file, sorts its lines, extracts a sequence number from the last line, and handles exceptions. The `process_files_in_directory` function uses a thread pool to process multiple files concurrently, limits the number of concurrent tasks, retries failed operations with exponential backoff, filters files by name patterns, processes large files in chunks, supports configurable maximum retries and retry delay, handles varying line lengths and formats, manages file size, and provides a report summarizing processed sequence numbers.']

