#include <mutex>

// Define an enum for node types
enum class NodeType { Leaf, Internal };

// Define a struct for octree nodes
struct OctreeNode {
    NodeType type;
    std::vector<OctreeNode*> children; // Only used in internal nodes
    void* data;                         // Pointer to user data or child nodes

    OctreeNode(NodeType t) : type(t), data(nullptr) {}
};

// Define a class for the octree
class Octree {
private:
    int featureSize;
    int numLeafNodes;
    int dataCapacity;

    std::vector<OctreeNode*> nodes;
    std::mutex nodeMutex;

public:
    Octree(int size, int leaves, int capacity)
        : featureSize(size), numLeafNodes(leaves), dataCapacity(capacity) {
        // Initialize the octree with root and leaf nodes
        nodes.reserve(numLeafNodes + 1);
        nodes.push_back(new OctreeNode(NodeType::Internal)); // Root node
        for (int i = 0; i < numLeafNodes; ++i) {
            nodes.push_back(new OctreeNode(NodeType::Leaf));
        }
    }

    ~Octree() {
        // Clean up all nodes
        for (auto& node : nodes) {
            delete node;
        }
    }

    void insertData(const void* data, int index) {
        std::lock_guard<std::mutex> lock(nodeMutex);
        if (index < 0 || index >= numLeafNodes) {
            std::cerr << "Error: Invalid leaf node index" << std::endl;
            return;
        }
        nodes[index]->data = const_cast<void*>(data); // Unsafe cast, for demonstration
    }

    void traverse() {
        std::lock_guard<std::mutex> lock(nodeMutex);
        // Simple in-order traversal of the octree
        traverseNode(nodes[0], 0);
    }

private:
    void traverseNode(OctreeNode* node, int depth) {
        if (node->type == NodeType::Internal) {
            for (auto& child : node->children) {
                traverseNode(child, depth + 1);
            }
        } else {
            // Process leaf node data
            std::cout << "Leaf node at depth " << depth << ": " << node->data << std::endl;
        }
    }
};

int main() {
    Octree octree(8, 4, 32); // Feature size of 8, 4 leaf nodes, and a data capacity of 32
    octree.insertData("Data1", 0);
    octree.insertData("Data2", 1);
    octree.insertData("Data3", 2);
    octree.insertData("Data4", 3);

    octree.traverse();

    return 0;
}
```

