// Define error codes
#define SUCCESS 0
#define FILE_NOT_FOUND -1
#define DIRECTORY_ERROR -2
#define PERMISSIONS_ERROR -3

// Mutex for thread safety
pthread_mutex_t file_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to update file metadata
int update_file_metadata(const char *filename) {
    pthread_mutex_lock(&file_lock); // Lock the mutex for thread safety

    struct stat file_stat;
    if (stat(filename, &file_stat) == -1) {
        pthread_mutex_unlock(&file_lock);
        return FILE_NOT_FOUND;
    }

    const char *parent_dir = dirname((char *)filename);
    if (mkdir(parent_dir, 0755) == -1 && errno != EEXIST) {
        pthread_mutex_unlock(&file_lock);
        return DIRECTORY_ERROR;
    }

    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);

    if (utimensat(AT_FDCWD, filename, &current_time, 0) == -1) {
        pthread_mutex_unlock(&file_lock);
        return PERMISSIONS_ERROR;
    }

    // Set ownership to effective user and group
    if (chown(filename, geteuid(), getegid()) == -1) {
        pthread_mutex_unlock(&file_lock);
        return PERMISSIONS_ERROR;
    }

    // Log the change for auditing purposes
    printf("Updated metadata for file: %s\n", filename);

    pthread_mutex_unlock(&file_lock); // Unlock the mutex after updating metadata
    return SUCCESS;
}
```

