#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>

class SecureRandomValueGenerator {
private:
    EVP_CIPHER_CTX* cipherCtx;
    std::string password;
    std::string salt;
    std::mutex mtx;

public:
    SecureRandomValueGenerator(const std::string& pwd, const std::string& s)
        : password(pwd), salt(s) {}

    EVP_CIPHER_CTX* getSecureCipher() {
        std::lock_guard<std::mutex> lock(mtx);
        if (cipherCtx == nullptr) {
            cipherCtx = EVP_CIPHER_CTX_new();
            if (!EVP_EncryptInit_ex(cipherCtx, EVP_aes_128_gcm(), NULL, NULL, NULL)) {
                throw std::runtime_error("Failed to initialize AES-128-GCM cipher");
            }
        }
        return cipherCtx;
    }

    void cleanUpCipher() {
        std::lock_guard<std::mutex> lock(mtx);
        if (cipherCtx != nullptr) {
            EVP_CIPHER_CTX_free(cipherCtx);
            cipherCtx = nullptr;
        }
    }

    int generateRandomValue(int min, int max) {
        if (min > max) {
            throw std::invalid_argument("Invalid range");
        }
        std::lock_guard<std::mutex> lock(mtx);
        unsigned char iv[AES_GCM_IVLEN];
        if (!RAND_bytes(iv, sizeof(iv))) {
            throw std::runtime_error("Failed to generate IV");
        }

        int keySize = EVP_CIPHER_key_length(EVP_aes_128_gcm());
        unsigned char key[keySize];
        if (PBKDF2_HMAC(SHA256_DIGEST_LENGTH, reinterpret_cast<const unsigned char*>(password.c_str()), password.size(),
                       reinterpret_cast<const unsigned char*>(salt.c_str()), salt.size(), 10000, SHA256_DIGEST_LENGTH, key) != keySize) {
            throw std::runtime_error("PBKDF2_HMAC failed");
        }

        if (!EVP_EncryptInit_ex(cipherCtx, EVP_aes_128_gcm(), NULL, key, iv)) {
            throw std::runtime_error("Failed to set up cipher for encryption");
        }

        int tagLen = EVP_CIPHER_getAADlen(EVP_aes_128_gcm());
        unsigned char tag[tagLen];
        if (!EVP_EncryptUpdate(cipherCtx, NULL, &tagLen, NULL, 0)) {
            throw std::runtime_error("Failed to update cipher with AAD");
        }

        int ciphertext_len;
        unsigned char* ciphertext = new unsigned char[max - min + 1];
        if (!EVP_EncryptUpdate(cipherCtx, ciphertext, &ciphertext_len, reinterpret_cast<unsigned char*>(&min), sizeof(min))) {
            delete[] ciphertext;
            throw std::runtime_error("Failed to encrypt data");
        }

        int final_len;
        if (!EVP_EncryptFinal_ex(cipherCtx, ciphertext + ciphertext_len, &final_len)) {
            delete[] ciphertext;
            throw std::runtime_error("Failed to finalize encryption");
        }

        ciphertext_len += final_len;

        int randomValue = *reinterpret_cast<int*>(ciphertext);
        randomValue = (randomValue - min) % (max - min + 1) + min;
        delete[] ciphertext;
        return randomValue;
    }
};

extern "C" {
    void initSecureRandomValueGenerator(const char* pwd, const char* salt, SecureRandomValueGenerator** gen) {
        try {
            *gen = new SecureRandomValueGenerator(pwd, salt);
        } catch (const std::exception& e) {
            std::cerr << "Error initializing SecureRandomValueGenerator: " << e.what() << std::endl;
            *gen = nullptr;
        }
    }

    void cleanupSecureRandomValueGenerator(SecureRandomValueGenerator* gen) {
        delete gen;
    }

    int generateRandomValue(SecureRandomValueGenerator* gen, int min, int max) {
        try {
            return gen->generateRandomValue(min, max);
        } catch (const std::exception& e) {
            std::cerr << "Error generating random value: " << e.what() << std::endl;
            return -1; // Error code
        }
    }
}

static void createHttpClient(const char* url, bool verifyCert = true) {
