#include <signal.h>

#define LOG_FILE "execution.log"
#define MAX_COMMAND_LENGTH 256

void log_status(const char *status) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log != NULL) {
        fprintf(log, "%s\n", status);
        fclose(log);
    }
}

int executeBackgroundCommand(const char *command) {
    int pid;
    int status;

    pid = fork();
    if (pid == -1) {
        log_status("Failed to create process");
        return 0;
    } else if (pid == 0) {
        // Child process
        execlp(command, command, NULL);
        perror("execlp failed");
        exit(1);
    } else {
        // Parent process
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            int exit_code = WEXITSTATUS(status);
            if (exit_code == 0) {
                log_status("Command executed successfully");
                return 1;
            } else {
                log_status("Command execution failed with code: ");
                char exit_code_str[16];
                snprintf(exit_code_str, sizeof(exit_code_str), "%d", exit_code);
                log_status(exit_code_str);
                return 0;
            }
        } else {
            log_status("Command execution terminated abnormally");
            return 0;
        }
    }
}

int main() {
    // Example usage
    const char *command = "sleep 10";
    if (executeBackgroundCommand(command) == 1) {
        printf("Command executed successfully.\n");
    } else {
        printf("Command execution failed.\n");
    }
    return 0;
}
```

