    public async Task<bool> AddAndStartWebServiceAsync(string deploymentDirectory)
    {
        const int maxRetries = 3;
        for (int attempt = 0; attempt < maxRetries; attempt++)
        {
            try
            {
                if (!File.Exists(Path.Combine(deploymentDirectory, "service.yaml")) ||
                    !File.Exists(Path.Combine(deploymentDirectory, "config.yaml")))
                {
                    Console.WriteLine("Warning: Missing configuration files. Please check the deployment directory.");
                    return false;
                }

                // Assuming AddWebServiceAsync and StartWebServiceAsync are defined elsewhere
                await AddWebServiceAsync(deploymentDirectory);
                await StartWebServiceAsync();

                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error: {ex.Message}");
                if (attempt == maxRetries - 1) throw;

                // Exponential backoff before retrying
                await Task.Delay((int)Math.Pow(2, attempt) * 100);
            }
