#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

typedef struct {
    char *filePath;
    unsigned long fileSize;
    char *fileExtension;
} TransferInfo;

typedef struct {
    char *sourceIP;
    char *destinationIP;
    int sourcePort;
    int destinationPort;
    int timeout;
} NetworkSettings;

typedef enum {
    FILE_NOT_FOUND,
    INVALID_FILE_PATH,
    INVALID_IP_ADDRESS,
    NULL_CALLBACK,
    EXCEEDS_MAX_SIZE,
    PORT_OUT_OF_RANGE,
    UNALLOWED_FILE_EXTENSION,
    UNREACHABLE_SOURCE,
    MEMORY_ALLOCATION_FAILED,
    CHECKSUM_VERIFICATION_FAILED,
    TRANSFER_SUCCESS,
    TRANSFER_FAILURE
} ErrorCode;

typedef void (*TransferCallback)(ErrorCode status);

typedef struct {
    TransferInfo *transferInfo;
    NetworkSettings *networkSettings;
    TransferCallback onTransferComplete;
} FileTransferContext;

int isIPValid(const char *ip) {
    struct sockaddr_in sa;
    int result = inet_pton(AF_INET, ip, &(sa.sin_addr));
    return (result != 0);
}

bool isValidExtension(const char *extension, const char **allowedExtensions, size_t numExtensions) {
    for (size_t i = 0; i < numExtensions; ++i) {
        if (strcmp(extension, allowedExtensions[i]) == 0) {
            return true;
        }
    }
    return false;
}

int validateFileTransfer(FileTransferContext *context) {
    TransferInfo *ti = context->transferInfo;
    NetworkSettings *ns = context->networkSettings;

    if (!ti || !ns || !context->onTransferComplete) {
        return NULL_CALLBACK;
    }

    if (strlen(ti->filePath) == 0 || access(ti->filePath, F_OK) != 0) {
        return FILE_NOT_FOUND;
    }

    if (!isIPValid(ns->sourceIP) || !isIPValid(ns->destinationIP)) {
        return INVALID_IP_ADDRESS;
    }

    if (ti->fileSize > MAX_FILE_SIZE || ns->port < 0 || ns->port > 65535) {
        return EXCEEDS_MAX_SIZE || PORT_OUT_OF_RANGE;
    }

    const char *allowedExtensions[] = {".txt", ".csv", ".pdf"};
    size_t numExtensions = sizeof(allowedExtensions) / sizeof(allowedExtensions[0]);
    if (!isValidExtension(ti->fileExtension, allowedExtensions, numExtensions)) {
        return UNALLOWED_FILE_EXTENSION;
    }

    // Simulate checking reachability (for simplicity)
    struct sockaddr_in source_addr, dest_addr;
    inet_pton(AF_INET, ns->sourceIP, &source_addr.sin_addr);
    inet_pton(AF_INET, ns->destinationIP, &dest_addr.sin_addr);
    if ((connect(socket(AF_INET, SOCK_STREAM, 0), (struct sockaddr *)&dest_addr, sizeof(dest_addr)) == -1)) {
        return UNREACHABLE_SOURCE;
    }

    // Allocate memory if not already allocated
    if (!ti->transferInfo) {
        ti->transferInfo = malloc(sizeof(TransferInfo));
        if (!ti->transferInfo) {
            return MEMORY_ALLOCATION_FAILED;
        }
    }
    if (!ns->networkSettings) {
        ns->networkSettings = malloc(sizeof(NetworkSettings));
        if (!ns->networkSettings) {
            free(ti->transferInfo);
            return MEMORY_ALLOCATION_FAILED;
        }
    }

    // Simulate retry mechanism
    int retries = MAX_RETRIES;
    while (retries > 0) {
        // Perform transfer here
        if (/* Transfer successful */) {
            context->onTransferComplete(TRANSFER_SUCCESS);
            return TRANSFER_SUCCESS;
        } else {
            retries--;
        }
    }

    context->onTransferComplete(TRANSFER_FAILURE);
    return TRANSFER_FAILURE;
}
