        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _marketIndexServiceUrl = marketIndexServiceUrl ?? throw new ArgumentNullException(nameof(marketIndexServiceUrl));
    }

    public async Task<string> ProcessTransactionsAsync(byte[] transactionData, string transactionFormat)
    {
        // Implement transaction processing logic here
        // Convert byte array to a list of transactions based on the format
        var transactions = ParseTransactions(transactionData, transactionFormat);

        // Apply filtering criteria and maintain up-to-date metrics within the sliding window interval
        var recentTransactions = FilterTransactions(transactions, DateTime.UtcNow.AddMilliseconds(-SlidingWindowInterval));

        // Calculate weighted sum for each transaction
        var weightedSums = recentTransactions.Select(CalculateWeightedSum).ToList();

        // Determine the maximum weighted sum and return the corresponding transaction ID
        var maxWeightedSumIndex = weightedSums.IndexOf(weightedSums.Max());
        var maxWeightedSumTransaction = recentTransactions[maxWeightedSumIndex];
        _logger.LogInformation($"Max Weighted Sum Transaction: {maxWeightedSumTransaction.Id} with Sum: {weightedSums[maxWeightedSumIndex]}");

        // Fetch current market indices and handle service failures/retries
        try
        {
            var marketIndices = await GetMarketIndicesAsync();
            _logger.LogInformation("Fetched Market Indices: " + string.Join(", ", marketIndices));
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to fetch market indices");
            // Retry logic can be implemented here
        }

        return maxWeightedSumTransaction.Id;
    }

    private List<Transaction> FilterTransactions(List<Transaction> transactions, DateTime startTime)
    {
        return transactions.Where(t => t.Timestamp >= startTime).ToList();
    }

    private double CalculateWeightedSum(Transaction transaction)
    {
        // Implement custom formula for calculating weighted sum
        // Example: value * 0.6 + typeFactor * 0.3 + frequency * 0.1
        var typeFactor = GetTransactionTypeFactor(transaction.Type);
        var frequencyFactor = GetFrequencyFactor(transaction.Frequency);

        return transaction.Value * 0.6 + typeFactor * 0.3 + frequencyFactor * 0.1;
    }

    private async Task<List<double>> GetMarketIndicesAsync()
    {
        if (_cache.TryGetValue("marketIndices", out List<double> marketIndices))
        {
            return marketIndices;
        }

        try
        {
            var response = await _httpClient.GetAsync(_marketIndexServiceUrl);
            response.EnsureSuccessStatusCode();
            marketIndices = await response.Content.ReadAsAsync<List<double>>();
            _cache.Set("marketIndices", marketIndices, TimeSpan.FromMinutes(1));
            return marketIndices;
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to fetch market indices");
            throw;
        }
    }

    private double GetTransactionTypeFactor(string transactionType)
    {
        // Implement logic for determining type factor
        switch (transactionType)
        {
            case "HighRisk":
                return 1.5;
            case "MediumRisk":
                return 1.0;
            default:
                return 0.5;
        }
    }

    private double GetFrequencyFactor(int frequency)
    {
        // Implement logic for determining frequency factor
        if (frequency > 100)
            return 1.2;
        else if (frequency > 50)
            return 1.0;
        else
            return 0.8;
    }

