import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import org.json.*;

public class LogAggregator {
    private Path logDirectory;
    private ExecutorService executorService = Executors.newFixedThreadPool(10);
    private BlockingQueue<String> logEvents = new LinkedBlockingQueue<>();
    private Semaphore semaphore = new Semaphore(10);

    public LogAggregator(String directoryPath) {
        this.logDirectory = Paths.get(directoryPath);
    }

    public void aggregateLogsAsync() {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(logDirectory, "*.gz")) {
            for (Path file : stream) {
                executorService.submit(() -> processLog(file));
            }
        } catch (IOException e) {
            System.err.println("Error reading log directory: " + e.getMessage());
        }
    }

    private void processLog(Path file) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                new GZIPInputStream(Files.newInputStream(file))))) {
            String line;
            while ((line = reader.readLine()) != null) {
                JSONObject json = new JSONObject(line);
                if (shouldInclude(json.getString("severity"))) {
                    logEvents.offer(json.toString());
                    semaphore.release();
                }
            }
        } catch (IOException e) {
            System.err.println("Error processing log file: " + file.getFileName() + " - " + e.getMessage());
        }
    }

    private boolean shouldInclude(String severity) {
        // Define your filtering logic here
        return severity.equals("ERROR") || severity.equals("WARNING");
    }

    public String getSummary() throws InterruptedException {
        semaphore.acquire();
        StringBuilder summary = new StringBuilder();
        while (!logEvents.isEmpty()) {
            summary.append(logEvents.poll()).append("\n");
        }
        return summary.toString();
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
