using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class HashProcessor : IDisposable
{
    private readonly ConcurrentDictionary<string, byte[]> _hashCache = new ConcurrentDictionary<string, byte[]>();
    private readonly object _lockObject = new object();
    private bool _disposed = false;

    public void ProcessStream(Stream inputStream, string hashAlgorithm)
    {
        using (var reader = new StreamReader(inputStream, Encoding.UTF8))
        {
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                ProcessLine(line, hashAlgorithm);
            }
        }
    }

    private void ProcessLine(string line, string hashAlgorithm)
    {
        if (string.IsNullOrEmpty(line)) return;

        byte[] hashBytes;
        if (!_hashCache.TryGetValue(line, out hashBytes))
        {
            lock (_lockObject)
            {
                if (!_hashCache.TryGetValue(line, out hashBytes))
                {
                    hashBytes = ComputeHash(line, hashAlgorithm);
                    _hashCache.TryAdd(line, hashBytes);
                }
            }
        }

        // Process and return the hash
        Console.WriteLine(Convert.ToBase64String(hashBytes));
    }

    private byte[] ComputeHash(string input, string algorithm)
    {
        using (var hashProvider = HashAlgorithm.Create(algorithm))
        {
            return hashProvider.ComputeHash(Encoding.UTF8.GetBytes(input));
        }
    }

    public void Dispose()
    {
        _disposed = true;
        _hashCache.Clear();
        GC.SuppressFinalize(this);
    }

    ~HashProcessor()
    {
        Dispose();
    }
}
```

