      const newKeyPath = [...keyPath, key];
      if (typeof data[key] === 'object' && data[key] !== null) {
        result[newKeyPath.join('.')] = serializeToJson(data[key], newKeyPath);
      } else {
        result[newKeyPath.join('.')] = data[key];
      }
    }
  }
