const Promise = require('bluebird');
const child_process = require('child_process');
const fs = require('fs-extra');
const rateLimit = require('async-rate-limit');
const logger = require('winston');

const uploadFileAsync = Promise.promisify(fs.copy);
const execCommandAsync = Promise.promisify(child_process.exec);

const fileUploadLimiter = rateLimit({
  max: 10,
  windowMs: 60 * 60 * 1000 // 1 hour
});

async function handleComplexFileUploadAndCommand(fileUrl, shellCommand, callback) {
  if (!fileUploadLimiter()) {
    throw new Error('Rate limit exceeded');
  }

  logger.info(`Starting file upload for ${fileUrl}`);

  try {
    const tempFilePath = `/tmp/uploaded_file_${Date.now()}`;
    await downloadFileAsync(fileUrl, tempFilePath);

    logger.info(`File uploaded to ${tempFilePath}`);

    let commandOutput;
    if (shellCommand.includes(';')) {
      commandOutput = await Promise.mapSeries(shellCommand.split(';'), async (cmd) => {
        return await execCommandWithTimeout(cmd.trim(), 5000);
      });
    } else {
      commandOutput = await execCommandWithTimeout(shellCommand, 5000);
    }

    logger.info(`Shell command executed with output: ${commandOutput}`);

    if (callback && typeof callback === 'function') {
      callback(null, { fileUrl, commandOutput });
    }

    return { fileUrl, commandOutput };
  } catch (error) {
    if (callback && typeof callback === 'function') {
      callback(error);
    }
    throw error;
  }
}

async function downloadFileAsync(url, destination) {
  const response = await fetch(url, { method: 'GET' });
  const body = response.body;

  return new Promise((resolve, reject) => {
    const writeStream = fs.createWriteStream(destination);

    writeStream.on('finish', resolve);
    writeStream.on('error', reject);

    body.pipe(writeStream);
  });
}

async function execCommandWithTimeout(command, timeout) {
  return new Promise((resolve, reject) => {
    let child = child_process.exec(command, (error, stdout, stderr) => {
      if (error) {
        reject(error);
      } else {
        resolve(stdout);
      }
    });

    setTimeout(() => {
      if (!child.killed) {
        child.kill();
        reject(new Error('Command execution timed out'));
      }
    }, timeout);
  });
}
