function handleErrors(error, developmentMode) {
  if (developmentMode) {
    return error;
  }
  return new Error('Internal server error');
}

async function main() {
  const command = 'your_custom_command_here';
  const outputDir = path.join(os.tmpdir(), crypto.randomBytes(16).toString('hex'));

  try {
    await fs.promises.mkdir(outputDir, { recursive: true });
    logger.info(`Report directory created at ${outputDir}`);

    await generateReport(command, outputDir);

    const reportPath = path.join(outputDir, 'report.pdf');
    logger.info(`Report saved to ${reportPath}`);

    return reportPath;
  } catch (error) {
    logger.error('Error processing report generation:', error);
    throw handleErrors(error, process.env.NODE_ENV === 'development');
  }
}

main()
  .then((reportPath) => console.log(`Report available at: ${reportPath}`))
  .catch((error) => console.error(error));
