use std::env;
use std::fs;
use std::io::{self, Write};
use std::sync::{Arc, Mutex};
use uuid::Uuid;

fn create_directory_and_set_env_var(directory_name: &str) -> io::Result<()> {
    static ENV_VAR_KEY: &str = "MY_DIRECTORY_ENV";
    static MUTEX: Mutex<()> = Mutex::new(());

    let mut state = MUTEX.lock().unwrap();

    if env::var(ENV_VAR_KEY).is_ok() {
        let unique_id = Uuid::new_v4();
        let new_directory_name = format!("{}-{}", directory_name, unique_id);
        create_and_set_env_var(new_directory_name)?;
    } else {
        create_and_set_env_var(directory_name.to_string())?;
    }

    Ok(())
}

fn create_and_set_env_var(directory_name: String) -> io::Result<()> {
    let temp_dir = env::temp_dir();
    let directory_path = temp_dir.join(&directory_name);

    fs::create_dir_all(&directory_path)?;

    env::set_var("MY_DIRECTORY_ENV", &directory_path.display());

    Ok(())
}

fn main() -> io::Result<()> {
    // Example usage
    create_directory_and_set_env_var("my_new_directory")?;

    println!("Directory and environment variable set successfully.");

    Ok(())
}
