// Define media formats
typedef enum { MP3, FLAC, WAV } MediaFormat;

// Define media packet structure
typedef struct {
    MediaFormat format;
    unsigned char *data;
    size_t length;
} MediaPacket;

// Define thread pool structure
typedef struct {
    pthread_t *threads;
    sem_t task_queue_mutex;
    MediaPacket **task_queue;
    int queue_size;
    int head, tail;
    int count;
    int shutdown;
} ThreadPool;

// Function to initialize media packet buffer
MediaPacket* create_media_packet(MediaFormat format, unsigned char *data, size_t length) {
    MediaPacket *packet = (MediaPacket*)malloc(sizeof(MediaPacket));
    packet->format = format;
    packet->data = data;
    packet->length = length;
    return packet;
}

// Function to destroy media packet buffer
void destroy_media_packet(MediaPacket *packet) {
    free(packet->data);
    free(packet);
}

// Function to initialize thread pool
ThreadPool* init_thread_pool(int num_threads, int queue_size) {
    ThreadPool *pool = (ThreadPool*)malloc(sizeof(ThreadPool));
    pool->threads = (pthread_t*)malloc(num_threads * sizeof(pthread_t));
    sem_init(&pool->task_queue_mutex, 0, 1);
    pool->task_queue = (MediaPacket**)malloc(queue_size * sizeof(MediaPacket*));
    pool->queue_size = queue_size;
    pool->head = pool->tail = pool->count = 0;
    pool->shutdown = 0;
    return pool;
}

// Function to destroy thread pool
void destroy_thread_pool(ThreadPool *pool) {
    sem_destroy(&pool->task_queue_mutex);
    for (int i = 0; i < pool->queue_size; i++) {
        if (pool->task_queue[i]) {
            destroy_media_packet(pool->task_queue[i]);
        }
    }
    free(pool->threads);
    free(pool->task_queue);
    free(pool);
}

// Function to enqueue media packet
int enqueue_media_packet(ThreadPool *pool, MediaPacket *packet) {
    sem_wait(&pool->task_queue_mutex);
    if (pool->count == pool->queue_size) {
        sem_post(&pool->task_queue_mutex);
        return -1; // Queue is full
    }
    pool->task_queue[pool->tail] = packet;
    pool->tail = (pool->tail + 1) % pool->queue_size;
    pool->count++;
    sem_post(&pool->task_queue_mutex);
    return 0;
}

// Function to dequeue media packet
MediaPacket* dequeue_media_packet(ThreadPool *pool) {
    sem_wait(&pool->task_queue_mutex);
    if (pool->count == 0) {
        sem_post(&pool->task_queue_mutex);
        return NULL; // Queue is empty
    }
    MediaPacket *packet = pool->task_queue[pool->head];
    pool->head = (pool->head + 1) % pool->queue_size;
    pool->count--;
    sem_post(&pool->task_queue_mutex);
    return packet;
}

// Function to process media packets
void* process_media_packets(void *arg) {
    ThreadPool *pool = (ThreadPool*)arg;
    while (!pool->shutdown) {
        MediaPacket *packet = dequeue_media_packet(pool);
        if (packet) {
            // Process the media packet here
            // ...
            destroy_media_packet(packet);
        }
    }
    return NULL;
}

// Function to initialize media processing thread pool
void init_media_processing_thread_pool(ThreadPool *pool, int num_threads, int queue_size) {
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&pool->threads[i], NULL, process_media_packets, pool);
    }
}

// Function to shutdown media processing thread pool
void shutdown_media_processing_thread_pool(ThreadPool *pool) {
    pool->shutdown = 1;
    for (int i = 0; i < pool->queue_size; i++) {
        enqueue_media_packet(pool, NULL); // Signal threads to exit
    }
    for (int i = 0; i < pool->num_threads; i++) {
        pthread_join(pool->threads[i], NULL);
    }
}

// Main function to demonstrate usage
int main() {
    ThreadPool *pool = init_thread_pool(10, 20);

    // Simulate media packet processing
    for (int i = 0; i < 50; i++) {
        MediaPacket *packet = create_media_packet(MP3, (unsigned char*)malloc(1024), 1024);
        enqueue_media_packet(pool, packet);
    }

    shutdown_media_processing_thread_pool(pool);
    destroy_thread_pool(pool);

    return 0;
}
```

This code provides a basic structure for the media processing and metadata management function. It includes functions to create and destroy media packets, initialize and destroy thread pools, enqueue and dequeue media packets, process media packets in separate threads, and simulate usage of the media processing thread pool. The actual media processing logic is left as an exercise for the junior developer to implement based on the specific requirements and media formats involved.']

