#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

typedef struct Config {
    int count_words;
    const char* output_file;
} Config;

void print_usage() {
    printf("Usage: program [options] input_file\n");
    printf("Options:\n");
    printf("  --manpage     Display comprehensive help information.\n");
    printf("  -cs           Count words instead of lines.\n");
    printf("  -o output_file Redirect output to a specified file.\n");
}

Config parse_config(int argc, char *argv[]) {
    Config config = {0};
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0) {
            print_usage();
            exit(0);
        } else if (strcmp(argv[i], "-cs") == 0) {
            config.count_words = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            config.output_file = argv[++i];
        }
    }
    return config;
}

void process_file(const char* input_file, Config config) {
    FILE *file = fopen(input_file, "r");
    if (!file) {
        perror("Failed to open file");
        exit(1);
    }

    long file_size = fseek(file, 0, SEEK_END), prev_pos = 0;
    char* buffer = (char*)mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fileno(file), 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to map file");
        fclose(file);
        exit(1);
    }

    int line_count = 0, word_count = 0;
    char* token = strtok(buffer + prev_pos, "\n");
    while (token != NULL) {
        if (config.count_words) {
            char *word = strtok(token, " \t.,;:!?\"'()[]{}<>|`~\n\r\t\v\f ");
            while (word != NULL) {
                ++word_count;
                word = strtok(NULL, " \t.,;:!?\"'()[]{}<>|`~\n\r\t\v\f ");
            }
        } else {
            ++line_count;
        }

        prev_pos += strlen(token) + 1;
        token = strtok(buffer + prev_pos, "\n");
    }

    if (config.count_words) {
        printf("Word count: %d\n", word_count);
    } else {
        printf("Line count: %d\n", line_count);
    }

    munmap(buffer, file_size);
    fclose(file);
}

int main(int argc, char *argv[]) {
    Config config = parse_config(argc, argv);
    if (argc < 2) {
        print_usage();
        return 1;
    }
    process_file(argv[1], config);
    return 0;
}
