#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 100

typedef struct {
    sem_t *sem_array[MAX_SEMAPHORES];
    int initialized;
} SemaphorePool;

SemaphorePool semaphore_pool = { .initialized = 0 };

void init_semaphore_pool(int num_semaphores, int initial_value) {
    if (num_semaphores > MAX_SEMAPHORES || semaphore_pool.initialized) return;
    for (int i = 0; i < num_semaphores; i++) {
        semaphore_pool.sem_array[i] = sem_open("/sem", O_CREAT, 0644, initial_value);
        if (semaphore_pool.sem_array[i] == SEM_FAILED) {
            perror("Failed to create semaphore");
            return;
        }
    }
    semaphore_pool.initialized = 1;
}

void destroy_semaphore_pool(int num_semaphores) {
    if (!semaphore_pool.initialized || num_semaphores > MAX_SEMAPHORES) return;
    for (int i = 0; i < num_semaphores; i++) {
        sem_close(semaphore_pool.sem_array[i]);
        sem_unlink("/sem");
    }
    semaphore_pool.initialized = 0;
}

void use_semaphore(int index) {
    if (!semaphore_pool.initialized || index >= MAX_SEMAPHORES) return;
    sem_wait(semaphore_pool.sem_array[index]);
}

void release_semaphore(int index) {
    if (!semaphore_pool.initialized || index >= MAX_SEMAPHORES) return;
    sem_post(semaphore_pool.sem_array[index]);
}

