    if (!pdu_list) {
        perror("Failed to allocate memory for NFAPI CRC indication PDU list");
        return NULL;
    }

    FILE* private_key_file = fopen(oauth_request, "r");
    if (!private_key_file) {
        perror("Failed to open private key file from OAuth request");
        free(pdu_list);
        return NULL;
    }

    // Read private key and certificate from file
    char buffer[1024];
    size_t bytes_read = fread(buffer, 1, sizeof(buffer), private_key_file);
    fclose(private_key_file);

    if (bytes_read == sizeof(buffer)) {
        fprintf(stderr, "Private key file is too large\n");
        free(pdu_list);
        return NULL;
    }

    // Combine private key and certificate into a single PEM file
    FILE* pem_file = fopen("certificate.pem", "w");
    if (!pem_file) {
        perror("Failed to create PEM file");
        free(pdu_list);
        return NULL;
    }

    fwrite(buffer, 1, bytes_read, pem_file);
    fclose(pem_file);

    // Generate NFAPI CRC indication PDU structures
    for (int i = 0; i < N; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand();
        pdu_list[i].RNTI = rand() % 1024;
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
