#include <queue>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <atomic>
#include <chrono>

struct Action {
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    char type;
    int priority;
    int cooldown;
    int id;
};

class CombatActionManager {
private:
    std::queue<Action> actionQueue;
    std::unordered_map<char, std::chrono::time_point<std::chrono::system_clock>> lastExecuted;
    std::mutex queueMutex;
    std::condition_variable cv;
    std::atomic<bool> running{true};
    std::vector<std::thread> workers;

public:
    CombatActionManager() {
        for (int i = 0; i < 3; ++i) {
            workers.emplace_back([this]() { workerThread(); });
        }
    }

    ~CombatActionManager() {
        running.store(false);
        cv.notify_all();
        for (auto& t : workers) {
            t.join();
        }
    }

    void addAction(const Action& action) {
        std::lock_guard<std::mutex> lock(queueMutex);
        actionQueue.push(action);
        cv.notify_one();
    }

private:
    void workerThread() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !actionQueue.empty(); });
            Action nextAction = actionQueue.front();
            actionQueue.pop();

            if (canExecute(nextAction)) {
                executeAction(nextAction);
            }
        }
    }

    bool canExecute(const Action& action) {
        auto now = std::chrono::system_clock::now();
        return lastExecuted.find(action.type) == lastExecuted.end() ||
               (lastExecuted[action.type] + std::chrono::seconds(action.cooldown)) < now;
    }

    void executeAction(const Action& action) {
        // Simulate action execution
        std::cout << "Executing action " << action.id << " of type " << action.type << std::endl;
        lastExecuted[action.type] = std::chrono::system_clock::now();
    }
};
