        try {
            // Apply structured logging and convert to a format suitable for external systems
            String formattedMessage = formatLog(message, level);

            // Send the log entry to all configured backends using the aggregator
            aggregator.send(formattedMessage);
        } catch (Exception e) {
            handleLogError(e);
        }
    }

    private String formatLog(String message, LogLevel level) {
