    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* array[MAX_ELEMENTS];
int size = 0;
pthread_mutex_t mutex;

void* process_transaction(void* arg) {
    pthread_mutex_lock(&mutex);
    if (size < MAX_ELEMENTS) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Initialize_pdu(pdu);
        array[size++] = pdu;
    } else {
        printf("Array is full\n");
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void init_system() {
    pthread_mutex_init(&mutex, NULL);
    srand(time(NULL));
}

void cleanup() {
    for (int i = 0; i < size; i++) {
        free(array[i]);
    }
    pthread_mutex_destroy(&mutex);
}

int main() {
    init_system();
    // Simulate concurrent transactions
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, process_transaction, NULL);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }
    cleanup();
    return 0;
}
