#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct {
    int value;
    long *offset;
    int *key;
    char **description;
    void *metadata;
} Record;

typedef struct Node {
    Record record;
    struct Node *next;
} Node;

typedef struct {
    Node **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

unsigned long hash(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

void initHashTable(HashTable *table, size_t initialCapacity) {
    table->capacity = initialCapacity;
    table->size = 0;
    table->buckets = malloc(initialCapacity * sizeof(Node*));
    for (size_t i = 0; i < initialCapacity; ++i) {
        table->buckets[i] = NULL;
    }
    pthread_mutex_init(&table->lock, NULL);
}

void freeHashTable(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node *node = table->buckets[i];
        while (node != NULL) {
            Node *next = node->next;
            free(node->record.description);
            free(node);
            node = next;
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
}

void insertRecord(HashTable *table, Record record) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash(*record.key, table->capacity);
    Node *newNode = malloc(sizeof(Node));
    newNode->record = record;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    ++table->size;

    if (table->size / (double)table->capacity > LOAD_FACTOR_THRESHOLD) {
        // Implement compaction logic here
    }

    pthread_mutex_unlock(&table->lock);
}

Record getRecord(HashTable *table, int key) {
    Record result = {0};
    pthread_mutex_lock(&table->lock);
    size_t index = hash(key, table->capacity);
    Node *node = table->buckets[index];
    while (node != NULL) {
        if (*node->record.key == key) {
            result = node->record;
            break;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);
    return result;
}

