import java.util.concurrent.*;
import org.yaml.snakeyaml.Yaml;

class NetworkNode {
    String NodeID;
    int Bandwidth;
    double Latency;
    String ProtocolVersion;
}

class NetworkConfigManager {
    private final ConcurrentHashMap<String, NetworkNode> nodeMap = new ConcurrentHashMap<>();
    private final Semaphore semaphore = new Semaphore(30);
    private final int maxMemoryLimit;

    public NetworkConfigManager(int maxMemoryLimit) {
        this.maxMemoryLimit = maxMemoryLimit;
    }

    public boolean addNode(NetworkNode node) throws InterruptedException {
        if (nodeMap.size() >= maxMemoryLimit) {
            throw new IllegalStateException("Memory limit exceeded");
        }
        if (!semaphore.tryAcquire()) {
            throw new InterruptedException("Too many concurrent operations");
        }
        try {
            if (nodeMap.containsKey(node.NodeID)) {
                return false;
            }
            nodeMap.put(node.NodeID, node);
            return true;
        } finally {
            semaphore.release();
        }
    }

    public boolean removeNode(String NodeID) throws InterruptedException {
        if (!semaphore.tryAcquire()) {
            throw new InterruptedException("Too many concurrent operations");
        }
        try {
            return nodeMap.remove(NodeID) != null;
        } finally {
            semaphore.release();
        }
    }

    public Iterable<NetworkNode> getNodesInReverse() {
        List<NetworkNode> nodes = new ArrayList<>(nodeMap.values());
        Collections.reverse(nodes);
        return Collections.unmodifiableList(nodes);
    }

    // Additional methods for handling routing table, dynamic resizing, congestion detection,
    // recovery, multi-core optimization, failover policies, caching, and logging.
}

