        *valid_count = *invalid_count = 0;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        *valid_count = *invalid_count = 0;
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand();
        pdu_array[i].RNTI = rand() % whitelist_size + 1; // Simulate random RNTI within a reasonable range
        pdu_array[i].CRC_INDICATION_REL8_TAG = rand();
        pdu_array[i].CRCFLAG = rand() % 2;

        if (validateRNTI(pdu_array[i].RNTI, whitelist, whitelist_size)) {
            (*valid_count)++;
        } else {
            (*invalid_count)++;
        }
    }

    return pdu_array;
}

// Example usage
int main() {
