    size_t N = 100000; // Number of elements in the array
    size_t valid_count = 0;
    size_t invalid_count = 0;

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = manageNFAPICRCIndications(N, whitelist, sizeof(whitelist) / sizeof(whitelist[0]), &valid_count, &invalid_count);
    if (pdu_array) {
        printf("Valid RNTI count: %zu\n", valid_count);
        printf("Invalid RNTI count: %zu\n", invalid_count);
        free(pdu_array);
    }

    return 0;
}
