typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* pdu_array[MAX_ELEMENTS];
int current_size = 0;
pthread_mutex_t array_lock;
pthread_cond_t memory_pressure_cv;
int memory_usage = 0;
time_t last_memory_check;

void* process_data(void* arg) {
    while (1) {
        pthread_mutex_lock(&array_lock);
        while (current_size == 0 && !memory_pressure_detected()) {
            pthread_cond_wait(&memory_pressure_cv, &array_lock);
        }
        if (memory_pressure_detected()) {
            perform_garbage_collection();
        } else if (current_size > 0) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = pdu_array[--current_size];
            // Process the pdu
            pthread_mutex_unlock(&array_lock);
        }
    }
}

int memory_pressure_detected() {
    struct sysinfo mem_info;
    sysinfo(&mem_info);
    return (mem_info.mem_unit * mem_info.totalram * MEMORY_THRESHOLD) / 100 <= mem_info.freeram;
}

void perform_garbage_collection() {
    // Implement garbage collection logic here
    pthread_mutex_unlock(&array_lock);
    pthread_cond_signal(&memory_pressure_cv);
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, process_data, NULL);

    while (1) {
        if (current_size < MAX_ELEMENTS && !memory_pressure_detected()) {
            NFAPI_CRC_INDICATION_PDU_T* new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            // Populate the new_pdu with valid data
            pthread_mutex_lock(&array_lock);
            pdu_array[current_size++] = new_pdu;
            pthread_cond_signal(&memory_pressure_cv);
            pthread_mutex_unlock(&array_lock);
        }
        sleep(1); // Simulate random intervals
    }

    return 0;
}
