async function traverseDOM(selector, filterCriteria, priorityWeights) {
    const elements = [];

    // Helper function to handle asynchronous operations
    async function traverse(node) {
        if (node.nodeType === 1 && node.matches(selector)) {
            // Apply filter criteria
            if (await applyFilterCriteria(node, filterCriteria)) {
                elements.push(node);
            }
        }

        for (let child of node.childNodes) {
            await traverse(child);
        }
    }

    // Helper function to apply filter criteria asynchronously
    async function applyFilterCriteria(element, criteria) {
        for (let criterion in criteria) {
            if (!criteria[criterion](element)) {
                return false;
            }
        }
        return true;
    }

    // Start traversal from the document root
    await traverse(document.documentElement);

    // Prioritize elements based on weights
    elements.sort((a, b) => priorityWeights[a] - priorityWeights[b]);

    return elements;
}

// Example usage:
const selector = 'div.some-class';
const filterCriteria = {
    hasText: (element) => element.textContent.trim().length > 0,
    hasClass: (element) => element.classList.contains('important')
};
const priorityWeights = {
    [document.querySelector('div.some-class').id]: 1
};

traverseDOM(selector, filterCriteria, priorityWeights).then(elements => {
    console.log(elements);
});
