}

int is_rnti_unique(CRCListContext* context, RNTI rnti) {
    pthread_mutex_lock(&context->lock);
    ThreadSafeQueueElement* element = thread_safe_queue_get_first(context->queue);
    while (element != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)element->data;
        if (pdu->rnti == rnti) {
            pthread_mutex_unlock(&context->lock);
            return 0; // RNTI is not unique
        }
        element = thread_safe_queue_get_next(element);
    }
    pthread_mutex_unlock(&context->lock);
    return 1; // RNTI is unique
}

void add_to_crc_list(CRCListContext* context, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (is_rnti_unique(context, pdu->rnti)) {
        pthread_mutex_lock(&context->lock);
        thread_safe_queue_enqueue(context->queue, pdu);
        if (context->logging_enabled) {
            fprintf(context->log_file, "Added PDU with RNTI %d\n", pdu->rnti);
        }
        pthread_mutex_unlock(&context->lock);
    } else {
        log_error("RNTI %d is not unique and will not be added to the list.", pdu->rnti);
    }
}

CRCListContext* create_crc_list_context(int logging_enabled) {
    CRCListContext* context = (CRCListContext*)malloc(sizeof(CRCListContext));
    pthread_mutex_init(&context->lock, NULL);
    context->queue = thread_safe_queue_create();
    context->logging_enabled = logging_enabled;
    if (logging_enabled) {
        context->log_file = fopen("crc_list.log", "w");
    } else {
        context->log_file = NULL;
    }
    return context;
}

void destroy_crc_list_context(CRCListContext* context) {
    pthread_mutex_lock(&context->lock);
    ThreadSafeQueueElement* element = thread_safe_queue_get_first(context->queue);
    while (element != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)element->data;
        free(pdu);
        element = thread_safe_queue_get_next(element);
    }
    pthread_mutex_unlock(&context->lock);
    if (context->log_file != NULL) {
        fclose(context->log_file);
    }
    thread_safe_queue_destroy(context->queue);
    pthread_mutex_destroy(&context->lock);
    free(context);
}
