#include <time.h>

typedef struct {
    char sourceIP[16];
    char destinationIP[16];
    int protocol;
    int payloadSize;
    unsigned short checksum;
} NetworkFrameHeader;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NetworkFrameHeader* allocate_network_frames(int M) {
    if (M <= 0) {
        perror("Invalid value for M");
        return NULL;
    }

    NetworkFrameHeader *headers = (NetworkFrameHeader*)malloc(M * sizeof(NetworkFrameHeader));
    if (!headers) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < M; ++i) {
        // Populate with random data
        snprintf(headers[i].sourceIP, 16, "192.168.%d.%d", rand() % 256, rand() % 256);
        snprintf(headers[i].destinationIP, 16, "10.0.%d.%d", rand() % 256, rand() % 256);
        headers[i].protocol = rand() % 6 + 1; // TCP/UDP/ICMP/Ethernet/IP/Raw
        headers[i].payloadSize = rand() % 1400;
        // Calculate a simple checksum for demonstration purposes
        unsigned short *ptr = (unsigned short*)headers;
        unsigned int sum = 0;
        for (int j = 0; j < M * sizeof(NetworkFrameHeader) / 2; ++j) {
            sum += ptr[j];
        }
        headers[i].checksum = (sum >> 16) + (sum & 0xFFFF);
    }

    return headers;
}

void free_network_frames(NetworkFrameHeader* headers, int M) {
    if (headers) {
        free(headers);
    }
}

void verify_checksums(NetworkFrameHeader* headers, int M) {
    for (int i = 0; i < M; ++i) {
        unsigned short *ptr = (unsigned short*)(&headers[i]);
        unsigned int sum = 0;
        for (int j = 0; j < sizeof(NetworkFrameHeader) / 2; ++j) {
            sum += ptr[j];
        }
        if ((sum >> 16) + (sum & 0xFFFF) != headers[i].checksum) {
            fprintf(stderr, "Checksum error in frame %d\n", i);
        }
    }
}

void* monitor_network_frames(void* arg) {
    int M = *(int*)arg;
    NetworkFrameHeader *headers = allocate_network_frames(M);
    if (headers) {
        verify_checksums(headers, M);
        free_network_frames(headers, M);
    } else {
        fprintf(stderr, "Failed to allocate network frames\n");
    }
    return NULL;
}

int main() {
    int M = 100; // Example value
    pthread_t thread;

    if (pthread_create(&thread, NULL, monitor_network_frames, &M) != 0) {
        perror("Thread creation failed");
        return 1;
    }

    pthread_join(thread, NULL);

    return 0;
}
