import os
import csv
import asyncio
from concurrent.futures import ThreadPoolExecutor, as_completed
from collections import defaultdict
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def process_file(file_path):
    data = defaultdict(list)
    try:
        with open(file_path, mode='r', newline='') as file:
            reader = csv.DictReader(file)
            for row in reader:
                for key, value in row.items():
                    if key in data:
                        data[key].append(float(value))
    except Exception as e:
        logging.error(f"Error processing file {file_path}: {e}")
        return None
    return data

async def process_files_concurrently(file_paths, concurrency_limit):
    results = []
    with ThreadPoolExecutor(max_workers=concurrency_limit) as executor:
        future_to_file = {executor.submit(process_file, path): path for path in file_paths}
        for future in as_completed(future_to_file):
            file_path = future_to_file[future]
            try:
                data = future.result()
                if data is not None:
                    results.append(data)
            except Exception as e:
                logging.error(f"Error processing files concurrently: {e}")
    return results

def aggregate_data(results):
    aggregated_data = defaultdict(list)
    for result in results:
        for key, values in result.items():
            aggregated_data[key].extend(values)
    return {key: sorted(values) for key, values in aggregated_data.items()}

def calculate_medians(aggregated_data):
    medians = {}
    for key, values in aggregated_data.items():
        if values:
            medians[key] = values[len(values) // 2]
        else:
            logging.warning(f"No data available for key: {key}")
    return medians

async def main(directory_path, concurrency_limit):
    file_paths = [os.path.join(directory_path, f) for f in os.listdir(directory_path) if f.endswith('.csv')]
    results = await process_files_concurrently(file_paths, concurrency_limit)
    aggregated_data = aggregate_data(results)
    medians = calculate_medians(aggregated_data)

    # Generate report
    report = {
        "total_files_processed": len(file_paths),
        "medians": medians,
        "concurrency_limit": concurrency_limit
    }
    logging.info("Processing complete. Report generated.")
    return report

# Example usage
directory_path = 'path/to/csv/files'
concurrency_limit = 5
report = asyncio.run(main(directory_path, concurrency_limit))
print(report)
```

