import time
import psutil
from multiprocessing import Pool, Queue, cpu_count
from schema import Schema, And

def validate_data(data):
    # Define your schema here
    pass

def process_file(file_path, queue):
    try:
        with open(file_path, 'r') as file:
            data = json.load(file)
            if not validate_data(data):
                raise ValueError(f"Invalid data in {file_path}")
            queue.put(data)
    except Exception as e:
        print(f"Error processing {file_path}: {e}")

def process_files(directory, chunk_size=100000, concurrency_level=None):
    files = [os.path.join(directory, f) for f in os.listdir(directory) if f.endswith('.json')]
    chunk_size = chunk_size or len(files)
    concurrency_level = concurrency_level or cpu_count()

    queue = Queue(maxsize=concurrency_level * 2)
    pool = Pool(concurrency_level, initializer=lambda q: globals().__setitem__('queue', q), initargs=(queue,))

    start_time = time.time()
    total_records = 0

    for i in range(0, len(files), chunk_size):
        pool.starmap(process_file, [(f, queue) for f in files[i:i+chunk_size]])
        while not queue.empty():
            queue.get_nowait()
            total_records += 1

    pool.close()
    pool.join()

    end_time = time.time()
    average_time = (end_time - start_time) / total_records if total_records else 0
    memory_usage = psutil.virtual_memory().percent

    print(f"Records processed: {total_records}")
    print(f"Average processing time per record: {average_time:.2f} seconds")
    print(f"Memory usage: {memory_usage}%")

# Example usage
process_files('/path/to/json/directory', chunk_size=100000, concurrency_level=4)
