['```python
import os
import threading
from queue import Queue, Empty
import time
import logging

# Setup basic configuration for logging
logging.basicConfig(level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

def process_file(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = [line.strip() for line in file]
            lines.sort()
            last_line = lines[-1]
            sequence_number = int(last_line.split()[1])  # Assuming the format is "ID <sequence_number>"
            return sequence_number
    except Exception as e:
        logging.error(f"Error processing {file_path}: {e}")
        return None

def worker(queue, results):
    while True:
        try:
            file_path = queue.get(timeout=5)
            result = process_file(file_path)
            if result is not None:
                results.append((file_path, result))
            queue.task_done()
        except Empty:
            break
        except Exception as e:
            logging.error(f"Worker error: {e}")

def process_files(directory, num_workers):
    files_queue = Queue(maxsize=10)  # Adjust max size based on system resources
    results = []

    threads = []
    for i in range(num_workers):
        thread = threading.Thread(target=worker, args=(files_queue, results))
        thread.start()
        threads.append(thread)

    try:
        for filename in os.listdir(directory):
            file_path = os.path.join(directory, filename)
            if os.path.isfile(file_path) and file_path.endswith('.txt'):
                files_queue.put(file_path)
        files_queue.join()
    except Exception as e:
        logging.error(f"Main thread error: {e}")

    for thread in threads:
        thread.join()

    return results

if __name__ == "__main__":
    directory = 'path/to/your/directory'
    num_workers = 5  # Adjust based on system capabilities
    results = process_files(directory, num_workers)
    print("Processing complete. Results:")
    for file_path, result in results:
        print(f"{file_path}: {result}")
```

