#define MAX_IP_LEN 16
#define MAX_PAYLOAD_SIZE 2048

typedef struct {
    char sourceIP[MAX_IP_LEN];
    char destinationIP[MAX_IP_LEN];
    int protocol;
    int payloadSize;
    unsigned short checksum;
} NetworkFrameHeader;

unsigned short computeChecksum(NetworkFrameHeader *header) {
    // Simplified checksum computation for demonstration purposes
    return header->protocol + header->payloadSize;
}

void* allocateNetworkFrames(void* arg) {
    int M = *(int*)arg;
    NetworkFrameHeader** headers = (NetworkFrameHeader**)malloc(M * sizeof(NetworkFrameHeader*));
    if (!headers) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < M; i++) {
        headers[i] = (NetworkFrameHeader*)malloc(sizeof(NetworkFrameHeader));
        if (!headers[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated structures
            for (int j = 0; j < i; j++) {
                free(headers[j]);
            }
            free(headers);
            return NULL;
        }

        // Initialize structure fields here
        pthread_mutex_lock(&lock);
        headers[i]->checksum = computeChecksum(headers[i]);
        pthread_mutex_unlock(&lock);
    }

    // Periodic integrity check
    for (int i = 0; i < M; i++) {
        pthread_mutex_lock(&lock);
        if (headers[i]->checksum != computeChecksum(headers[i])) {
            fprintf(stderr, "Integrity check failed for frame %d\n", i);
        }
        pthread_mutex_unlock(&lock);
    }

    // Free allocated memory
    for (int i = 0; i < M; i++) {
        free(headers[i]);
    }
    free(headers);

    pthread_mutex_destroy(&lock);
    return NULL;
}

unsigned char* decryptAES(const unsigned char *ciphertext, int ciphertext_len, const unsigned char *key, const unsigned char *iv, unsigned char *plaintext) {
    AES_KEY enc_key;
    AES_set_decrypt_key(key, 128, &enc_key);
    AES_cbc_encrypt(ciphertext, plaintext, ciphertext_len, &enc_key, iv, AES_DECRYPT);

    return plaintext;
}

