    array->frames = (LTE_DL_FRAME_MSG *)malloc(MAX_TRANSACTIONS * sizeof(LTE_DL_FRAME_MSG));
    array->count = 0;
}

void freeFrameArray(FrameArray *array) {
    free(array->frames);
    array->frames = NULL;
    array->count = 0;
}

double calculateWeightedSum(LTE_DL_FRAME_MSG frame, double marketIndex) {
    return (frame.value + frame.frequency) * marketIndex * ((frame.type == 'A') ? 1.2 : 0.8);
}

int processTransactions(FrameArray *array, double marketIndex, int *maxId, double *maxWeightSum) {
    *maxId = -1;
    *maxWeightSum = 0.0;

    for (int i = array->count - 1; i >= 0 && i > array->count - BATCH_THRESHOLD - 1; i--) {
        LTE_DL_FRAME_MSG frame = array->frames[i];
        double weightSum = calculateWeightedSum(frame, marketIndex);

        if (weightSum > *maxWeightSum) {
            *maxId = frame.transaction_id;
            *maxWeightSum = weightSum;
        }
    }

    return 0;
}

int main() {
    FrameArray frameArray;
    initFrameArray(&frameArray);

    // Simulate loading transactions into the array
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        LTE_DL_FRAME_MSG frame;
