        frame.timestamp = time(NULL) - i * 2; // Example timestamp calculation
        frame.value = rand() % 100;
        frame.type = (i % 2 == 0) ? 'A' : 'B';
        frame.frequency = rand() % 10;

        array->frames[array->count++] = frame;
    }

