typedef struct {
    int ue_id;
    // Other session-related data
} Session;

typedef struct {
    int *ue_ids;
    Session **sessions;
    time_t *timestamps;
    size_t count;
    size_t capacity;
} UEContextArray;

UEContextArray* create_UEContext_array(size_t initial_capacity) {
    UEContextArray *array = (UEContextArray*)malloc(sizeof(UEContextArray));
    array->ue_ids = (int*)calloc(initial_capacity, sizeof(int));
    array->sessions = (Session**)calloc(initial_capacity, sizeof(Session*));
    array->timestamps = (time_t*)calloc(initial_capacity, sizeof(time_t));
    array->count = 0;
    array->capacity = initial_capacity;
    return array;
}

void add_session(UEContextArray *array, int ue_id, Session *session) {
    if (array->count >= array->capacity) {
        array->capacity *= 2;
        array->ue_ids = (int*)realloc(array->ue_ids, array->capacity * sizeof(int));
        array->sessions = (Session**)realloc(array->sessions, array->capacity * sizeof(Session*));
        array->timestamps = (time_t*)realloc(array->timestamps, array->capacity * sizeof(time_t));
    }
    array->ue_ids[array->count] = ue_id;
    array->sessions[array->count] = session;
    array->timestamps[array->count++] = time(NULL);
}

void remove_inactive_sessions(UEContextArray *array, time_t inactivity_threshold) {
    size_t i = 0, j = 0;
    while (i < array->count) {
        if (time(NULL) - array->timestamps[i] > inactivity_threshold) {
            free(array->sessions[i]);
            continue;
        }
        array->ue_ids[j] = array->ue_ids[i];
        array->sessions[j++] = array->sessions[i++];
    }
    array->count = j;
}

void update_session_timestamp(UEContextArray *array, int ue_id) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->ue_ids[i] == ue_id) {
            array->timestamps[i] = time(NULL);
            break;
        }
    }
}

void free_UEContext_array(UEContextArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->sessions[i]);
    }
    free(array->ue_ids);
    free(array->sessions);
    free(array->timestamps);
    free(array);
}
```

