typedef struct {
    void* pool;
    size_t pool_size;
    size_t pool_used;
} MemoryPool;

void initialize_memory_pool(MemoryPool* pool, size_t initial_size) {
    pool->pool = malloc(initial_size);
    pool->pool_size = initial_size;
    pool->pool_used = 0;
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    if (pool->pool_used + size > pool->pool_size) {
        // Grow the pool dynamically
        size_t new_size = pool->pool_size * 2;
        void* new_pool = realloc(pool->pool, new_size);
        if (!new_pool) {
            return NULL; // Handle memory allocation failure
        }
        pool->pool = new_pool;
        pool->pool_size = new_size;
    }
    void* block = (char*)pool->pool + pool->pool_used;
    pool->pool_used += size;
    return block;
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdus(int N, MemoryPool* pool) {
    if (!pool) {
        initialize_memory_pool(&default_pool, N * NFAPI_CRC_INDICATION_PDU_T_SIZE);
        pool = &default_pool;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(pool, N * NFAPI_CRC_INDICATION_PDU_T_SIZE);
    if (!pdus) {
        return NULL; // Handle memory allocation failure
