#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define INITIAL_CAPACITY 1024
#define LOAD_FACTOR 0.75

typedef struct Record {
    int value;
    long offset;
    int key;
    char* description;
    char* metadata;
    time_t last_access;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

unsigned long hash_function(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

HashTable* create_hash_table() {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    table->buckets = calloc(INITIAL_CAPACITY, sizeof(Node*));
    if (!table->buckets) {
        perror("Failed to allocate memory for buckets");
        free(table);
        exit(EXIT_FAILURE);
    }
    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insert_record(HashTable* table, int key, Record record) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&table->lock);
        return;
    }
    new_node->record = record;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    table->size++;
    if ((double)table->size / table->capacity > LOAD_FACTOR) {
        // Trigger compaction
    }
    pthread_mutex_unlock(&table->lock);
}

// ... (Implement other functions as per the requirements)

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; i++) {
        Node* node = table->buckets[i];
        while (node) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int main() {
    srand(time(NULL));
    HashTable* table = create_hash_table();
    // Insert records
    destroy_hash_table(table);
    return 0;
}
