import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;

public class XMLProcessor {

    public static void processXMLFiles(String directoryPath, int concurrencyLevel) {
        ExecutorService executor = Executors.newFixedThreadPool(concurrencyLevel);
        BlockingQueue<File> fileQueue = new LinkedBlockingQueue<>();

        try {
            Files.walk(Paths.get(directoryPath))
                .filter(Files::isRegularFile)
                .map(Path::toFile)
                .forEach(file -> fileQueue.add(file));

            while (!fileQueue.isEmpty()) {
                for (int i = 0; i < concurrencyLevel && !fileQueue.isEmpty(); i++) {
                    File file = fileQueue.poll();
                    executor.submit(() -> processXMLFile(file));
                }
                Thread.sleep(100); // Adjust sleep time based on system load
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
            try {
                if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException ex) {
                executor.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }
    }

    private static void processXMLFile(File file) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document document = builder.parse(file);
            // Validate and parse XML logic here

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        String directoryPath = "path/to/xml/files";
        int concurrencyLevel = 10;
        processXMLFiles(directoryPath, concurrencyLevel);
    }
}
