public class RandomValueGenerator
{
    private ConcurrentDictionary<string, (float min, float max, bool inclusive)> _ranges = new();
    private readonly object _logLock = new();

    public void AddRange(string name, float min, float max, bool inclusive)
    {
        if (_ranges.ContainsKey(name))
            throw new InvalidOperationException("Range already exists.");

        _ranges[name] = (min, max, inclusive);
    }

    public float GenerateRandomFloat(string rangeName)
    {
        if (!_ranges.ContainsKey(rangeName))
            throw new ArgumentException("Invalid range name.");

        var (min, max, inclusive) = _ranges[rangeName];
        float value;

        do
        {
            value = (float)(new Random().NextDouble() * (max - min)) + min;
        } while (!inclusive && value == max);

        LogGeneratedValue(rangeName, value);
        return value;
    }

    public int GenerateRandomInt(string rangeName)
    {
        if (!_ranges.ContainsKey(rangeName))
            throw new ArgumentException("Invalid range name.");

        var (min, max, inclusive) = _ranges[rangeName];
        int value;

        do
        {
            value = new Random().Next((int)min, (int)(max + 1));
        } while (!inclusive && value == (int)max);

        LogGeneratedValue(rangeName, value);
        return value;
    }

    private void LogGeneratedValue(string rangeName, object value)
    {
        lock (_logLock)
        {
            // Simulate logging to an external service
            Console.WriteLine($"Range: {rangeName}, Value: {value}");
        }
    }
}

public class FsaBookNameExtractor
{
    public void ExtractBookNames(int[] states, int numStates, byte* fsa, int lastStateIndex)
    {
        if (states == null || fsa == null)
            throw new ArgumentNullException(nameof(fsa));

        // Allocate memory for the new state list
        var newStateList = new State[numStates];
        Buffer.BlockCopy(states, 0, newStateList, 0, numStates * sizeof(State));

        // Update the 'next' pointer of the last state in the original list to point to this new sublist
        ((State*)fsa + lastStateIndex)->next = (byte*)newStateList;
    }

    public ConcurrentDictionary<string, int> ProcessText(string text)
    {
        var bookNames = new ConcurrentDictionary<string, int>();
        var oldTestamentRegex = new Regex(@"\b(?:Old Testament|New Testament)\b", RegexOptions.Compiled | RegexOptions.IgnoreCase);
        var bookRegex = new Regex(@"\b(?:[A-Za-z]+)\b", RegexOptions.Compiled);

        foreach (Match match in oldTestamentRegex.Matches(text))
        {
            string testaments = match.Value;
            string[] books = bookRegex.Matches(testaments).Cast<Match>().Select(m => m.Value.Trim()).ToArray();

            foreach (string book in books)
            {
                if (!bookNames.ContainsKey(book))
                    bookNames.TryAdd(book, 0);

                bookNames[book]++;
            }
        }

        return bookNames;
    }
}

public struct State
{
    public byte* next;
}
