#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    unsigned int data;
    struct Node* next;
} Node;

unsigned int generate_crc(unsigned char *data, size_t length) {
    unsigned int crc = 0xFFFFFFFF;
    for (size_t i = 0; i < length; ++i) {
        crc ^= (unsigned int)data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 1) {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    return ~crc;
}

Node* generate_crc_linked_list(unsigned char *data, size_t length) {
    Node *head = NULL;
    Node *tail = NULL;

    for (size_t i = 0; i < length; ++i) {
        Node *new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Failed to allocate memory\n");
            return head;
        }
        new_node->data = data[i];
        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
        } else {
            tail->next = new_node;
        }
        tail = new_node;
    }

    return head;
}

int main() {
    unsigned char data[] = "Hello, world!";
    size_t length = sizeof(data);
    unsigned int crc = generate_crc(data, length);
    printf("CRC: 0x%08X\n", crc);

    Node *list = generate_crc_linked_list(data, length);
    while (list != NULL) {
        printf("%d -> ", list->data);
        Node *temp = list;
        list = list->next;
        free(temp);
    }
    printf("NULL\n");

    return 0;
}
