        LogGenerationEvent(value, min, max, inclusive);
    }

    public void GenerateAndLog(int min, int max, bool inclusive)
    {
        int value = GenerateRandomInt(min, max, inclusive);
        LogGenerationEvent(value, min, max, inclusive);
    }

    private float GenerateRandomFloat(float min, float max, bool inclusive)
    {
        return inclusive ? random.NextFloat(min, max + 1) : random.NextFloat(min, max);
    }

    private int GenerateRandomInt(int min, int max, bool inclusive)
    {
        return inclusive ? random.Next(min, max + 1) : random.Next(min, max);
    }

    private void LogGenerationEvent(object value, float orIntMin, float orIntMax, bool inclusive)
    {
        string logMessage = $"Generated {value} between {orIntMin}-{orIntMax} with inclusivity {inclusive}";
        // Log to external service here
        Console.WriteLine(logMessage);
    }

    public void Dispose()
    {
        random.Dispose();
    }
}
