import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DataProcessor {
    private ExecutorService executorService;
    private int maxThreads;

    public DataProcessor(int maxThreads) {
        this.maxThreads = maxThreads;
        this.executorService = Executors.newFixedThreadPool(maxThreads);
    }

    // Method to handle data ingestion from various sources
    public void ingestData(String source, String format) {
        Runnable task = () -> {
            try {
                // Simulate data ingestion process
                System.out.println("Ingesting data from " + source + " in format " + format);
                Thread.sleep(100); // Simulating delay
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.err.println("Data ingestion interrupted");
            }
        };
        executorService.submit(task);
    }

    // Method to transform data
    public void transformData(String source, String targetFormat) {
        Runnable task = () -> {
            try {
                // Simulate data transformation process
                System.out.println("Transforming data from " + source + " to format " + targetFormat);
                Thread.sleep(200); // Simulating delay
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.err.println("Data transformation interrupted");
            }
        };
        executorService.submit(task);
    }

    // Method to store data in various storage systems
    public void storeData(String source, String destination) {
        Runnable task = () -> {
            try {
                // Simulate data storage process
                System.out.println("Storing data from " + source + " to " + destination);
                Thread.sleep(150); // Simulating delay
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.err.println("Data storage interrupted");
            }
        };
        executorService.submit(task);
    }

    // Method to monitor the processing pipeline for errors
    public void monitorPipeline() {
        if (executorService.isShutdown()) {
            System.out.println("Processing pipeline is shut down");
        } else {
            System.out.println("Processing pipeline is active");
        }
    }

    // Method to optimize resource usage based on workload
    public void adjustResources(int newMaxThreads) {
        executorService.shutdownNow();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdown();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
        this.maxThreads = newMaxThreads;
        this.executorService = Executors.newFixedThreadPool(maxThreads);
    }

    // Method to handle graceful shutdown
    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
