char* handle_oauth_request() {
    FILE *key_file = fopen("private_key.pem", "r");
    FILE *cert_file = fopen("certificate.pem", "r");
    if (!key_file || !cert_file) return NULL;

    fseek(key_file, 0, SEEK_END);
    long key_size = ftell(key_file);
    fseek(key_file, 0, SEEK_SET);

    fseek(cert_file, 0, SEEK_END);
    long cert_size = ftell(cert_file);
    fseek(cert_file, 0, SEEK_SET);

    char *pem_buffer = (char*)malloc(key_size + cert_size + 1);
    if (!pem_buffer) {
        fclose(key_file);
        fclose(cert_file);
        return NULL;
    }

    fread(pem_buffer, 1, key_size, key_file);
    fread(pem_buffer + key_size, 1, cert_size, cert_file);
    fclose(key_file);
    fclose(cert_file);

    pem_buffer[key_size + cert_size] = '\0';

    return pem_buffer;
}

