package com.dataprocessor;

import java.util.*;
import java.io.*;
import org.apache.commons.lang3.tuple.ImmutablePair;
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Bucket4j;
import io.github.bucket4j.Refill;
import java.time.Duration;

public class DataProcessor {
    private Map<String, Object> config;
    private List<TransformationStep> pipeline;
    private Map<String, Bucket> rateLimiters;
    private Cache cache;
    private SecurityManager securityManager;

    public DataProcessor(Map<String, Object> config) {
        this.config = config;
        this.pipeline = new ArrayList<>();
        this.rateLimiters = new HashMap<>();
        this.cache = new Cache();
        this.securityManager = new SecurityManager();

        // Initialize rate limiters based on configuration
        for (Map.Entry<String, Object> entry : config.entrySet()) {
            if ("rateLimits".equals(entry.getKey())) {
                @SuppressWarnings("unchecked")
                Map<String, Integer> limits = (Map<String, Integer>) entry.getValue();
                for (Map.Entry<String, Integer> rateLimit : limits.entrySet()) {
                    Refill refill = Refill.intervally(rateLimit.getValue(), Duration.ofMinutes(1));
                    Bucket bucket = Bucket4j.builder()
                            .addLimit(refill)
                            .build();
                    rateLimiters.put(rateLimit.getKey(), bucket);
                }
            }
        }

        // Initialize pipeline from configuration
        if (config.containsKey("pipeline")) {
            @SuppressWarnings("unchecked")
            List<Map<String, String>> steps = (List<Map<String, String>>) config.get("pipeline");
            for (Map<String, String> step : steps) {
                TransformationStep transformationStep = new TransformationStep(step);
                pipeline.add(transformationStep);
            }
        }

        // Load security policies from configuration
        if (config.containsKey("securityPolicies")) {
            @SuppressWarnings("unchecked")
            Map<String, Object> policies = (Map<String, Object>) config.get("securityPolicies");
            for (Map.Entry<String, Object> policy : policies.entrySet()) {
                String role = policy.getKey();
                @SuppressWarnings("unchecked")
                List<String> permissions = (List<String>) policy.getValue();
                securityManager.addPolicy(role, permissions);
            }
        }
    }

    public void process(InputStream data) {
        if (!securityManager.isAccessAllowed(Thread.currentThread().getName())) {
            throw new SecurityException("Access denied for current user");
        }

        for (TransformationStep step : pipeline) {
            try {
                if (rateLimiters.containsKey(step.getType())) {
                    Bucket bucket = rateLimiters.get(step.getType());
                    boolean isConsumed = bucket.tryConsume(1);
                    if (!isConsumed) {
                        throw new RateLimitExceededException("Rate limit exceeded for " + step.getType());
                    }
                }

                data = step.transform(data);
            } catch (Exception e) {
                // Handle transformation errors, log them and continue processing
                System.err.println("Transformation error: " + e.getMessage());
            }
        }

        // Store final data in cache
        if (cache.isEnabled()) {
            try {
                cache.store(data);
            } catch (IOException e) {
                // Log or handle cache storage failure
                System.err.println("Cache store error: " + e.getMessage());
            }
        }
    }

    public void monitor() {
        for (TransformationStep step : pipeline) {
            if (step.getPerformanceData().getAverageLatency() > config.getDouble("alertThreshold")) {
                sendAlert("High latency detected in " + step.getType());
            }
        }

        // Monitor resource usage and scale as needed
        if (config.getBoolean("autoScaleEnabled") && cache.isOverloaded()) {
            autoScale();
        }
    }

    private void sendAlert(String message) {
        // Code to integrate with external monitoring system
    }

    private void autoScale() {
        // Code to dynamically adjust worker threads and redistribute workload
    }

    // Inner class for transformation steps
    public static class TransformationStep {
        private String type;
        private Map<String, Object> parameters;
        private PerformanceData performanceData;

        public TransformationStep(Map<String, String> stepConfig) {
            this.type = stepConfig.get("type");
            this.parameters = new HashMap<>();
            for (Map.Entry<String, String> param : stepConfig.entrySet()) {
                if (!"type".equals(param.getKey())) {
                    parameters.put(param.getKey(), param.getValue());
                }
            }
            this.performanceData = new PerformanceData();
