NFAPI_CRC_INDICATION_PDU_T* create_napi_crc_indication_pdu(int nitems) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(nitems * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;
    for (int i = 0; i < nitems; i++) {
        pdus[i].rnti = rand() % 1024; // Example random RNTI generation
        pdus[i].crc_indication_rel8_tag = rand() % 2; // Random CRC indication tag
    }
