void update_session_timestamp(UEContext *ue_context, int session_id) {
    for (int i = 0; i < ue_context->session_list.nitems; i++) {
        if (ue_context->session_list.sessions[i]->session_id == session_id) {
            ue_context->session_list.sessions[i]->last_update_time = time(NULL);
            break;
        }
    }
}

void remove_inactive_sessions(UEContext *ue_context, time_t inactivity_threshold) {
    for (int i = 0; i < ue_context->session_list.nitems; ) {
        if (time(NULL) - ue_context->session_list.sessions[i]->last_update_time > inactivity_threshold) {
            // Remove inactive session
            memmove(&ue_context->session_list.sessions[i], &ue_context->session_list.sessions[i + 1],
                    (ue_context->session_list.nitems - i - 1) * sizeof(Session*));
            ue_context->session_list.nitems--;
        } else {
            i++;
        }
    }
}

void add_session(UEContext *ue_context, int session_id) {
    if (ue_context->session_list.nitems >= MAX_UE_SESSIONS) return;
    Session *new_session = (Session*)malloc(sizeof(Session));
    new_session->session_id = session_id;
    new_session->last_update_time = time(NULL);
    ue_context->session_list.sessions[ue_context->session_list.nitems++] = new_session;
}

char* fetch_private_key_certificate(const char *location) {
    FILE *file = fopen(location, "rb");
    if (!file) return NULL;
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);
    char *pem_buffer = (char*)malloc(file_size + 1);
    if (!pem_buffer) {
        fclose(file);
        return NULL;
    }
    fread(pem_buffer, 1, file_size, file);
    fclose(file);
    pem_buffer[file_size] = '\0';
    return pem_buffer;
}

void* send_session_updates_to_nms(UEContext *ue_context, void (*send_function)(UEContext*)) {
    // Simulate sending session updates to NMS
    send_function(ue_context);
    return NULL;
}

void* manage_dynamic_array(void (*update_function)(UEContext*, int), void (*remove_inactive_function)(UEContext*, time_t), void (*add_session_function)(UEContext*, int), const char *location, int max_sessions_per_ue, time_t inactivity_threshold) {
    UEContext ue_context = {0};
    NFAPI_CRC_INDICATION_PDU_T *pdus = create_napi_crc_indication_pdu(max_sessions_per_ue);
    if (!pdus) return NULL;

    // Simulate adding and updating sessions
    for (int i = 0; i < max_sessions_per_ue; i++) {
        add_session_function(&ue_context, rand() % max_sessions_per_ue);
        update_function(&ue_context, rand() % max_sessions_per_ue);
    }

    remove_inactive_function(&ue_context, inactivity_threshold);

    // Simulate sending session updates to NMS
    send_session_updates_to_nms(&ue_context, update_function);

    char *pem_buffer = fetch_private_key_certificate(location);
    if (!pem_buffer) {
        free(pdus);
        return NULL;
    }

    // Return the generated PDUs and PEM buffer
    return (void*)pdus; // Returning only PDUs for simplicity
}
