using System;

public class RandomValueGenerator
{
    private int minValue;
    private int maxValue;

    public RandomValueGenerator(int newMin, int newMax)
    {
        SetRange(newMin, newMax);
    }

    public float GetRandomFloat()
    {
        if (minValue == maxValue) return 0f;
        return (float)(minValue + (maxValue - minValue) * Math.Random());
    }

    public int GetRandomInt()
    {
        if (minValue == maxValue) return 0;
        Random random = new Random();
        return random.Next(minValue, maxValue + 1);
    }

    public float GetRandomExclusiveFloat()
    {
        if (minValue == maxValue) return 0f;
        return (float)(minValue + Math.Random() * (maxValue - minValue));
    }

    public int GetRandomExclusiveInt()
    {
        if (minValue == maxValue) return 0;
        Random random = new Random();
        return random.Next(minValue, maxValue);
    }

    public void SetRange(int newMin, int newMax)
    {
        minValue = newMin;
        maxValue = newMax > newMin ? newMax : 1;
    }

    public override string ToString()
    {
        if (minValue == maxValue) return "Invalid Range";
        return $"Range: [{minValue}, {maxValue}]";
    }
}
