using System;
using System.Collections.Generic;
using System.Linq;

public class AdvancedRandomValueGenerator
{
    private float minValue;
    private float maxValue;
    private Random random;

    public AdvancedRandomValueGenerator(int newMin, int newMax)
    {
        SetRange(newMin, newMax);
        random = new Random();
    }

    private void SetRange(int newMin, int newMax)
    {
        if (newMax > newMin)
        {
            minValue = newMin;
            maxValue = newMax;
        }
        else
        {
            minValue = 0;
            maxValue = 1;
        }
    }

    public float GetRandomFloat()
    {
        return (float)random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public int GetRandomInt()
    {
        return random.Next((int)minValue, (int)(maxValue + 1));
    }

    public float GetRandomExclusiveFloat()
    {
        return (float)random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public int GetRandomExclusiveInt()
    {
        return random.Next((int)minValue + 1, (int)(maxValue));
    }

    public Vector2 GetRandomVector2D(bool exclusive)
    {
        float x = exclusive ? GetRandomExclusiveFloat() : GetRandomFloat();
        float y = exclusive ? GetRandomExclusiveFloat() : GetRandomFloat();
        return new Vector2(x, y);
    }

    public float[,] GetRandomMatrix(int rows, int cols, bool exclusive)
    {
        float[,] matrix = new float[rows, cols];
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                matrix[i, j] = exclusive ? GetRandomExclusiveFloat() : GetRandomFloat();
            }
        }
        return matrix;
    }

    public T[] GetRandomSample<T>(T[] array, int sampleSize)
    {
        if (sampleSize > array.Length) sampleSize = array.Length;
        List<T> sampleList = new List<T>(array);
        for (int i = 0; i < sampleSize; i++)
        {
            int index = random.Next(i, sampleList.Count);
            T temp = sampleList[i];
            sampleList[i] = sampleList[index];
            sampleList[index] = temp;
        }
        return sampleList.Take(sampleSize).ToArray();
    }

    public override string ToString()
    {
        if (maxValue > minValue)
        {
            return $"Range: [{minValue}, {maxValue}]";
        }
        else
        {
            return "Invalid Range";
        }
    }

    public static AdvancedRandomValueGenerator GenerateSeededInstance(long seed)
    {
        return new AdvancedRandomValueGenerator((int)seed, (int)(seed * 2));
    }
}

public struct Vector2
{
    public float X;
    public float Y;

    public Vector2(float x, float y)
    {
        X = x;
        Y = y;
    }

    public override string ToString()
    {
        return $"({X}, {Y})";
    }
}
