#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_UE_CONTEXTS 1024

typedef struct {
    int ue_id;
    char session_list[128];
    time_t last_updated;
} UEContext;

UEContext* dynamic_array[MAX_UE_CONTEXTS];
int array_size = 0;

void add_session(int ue_id, const char* session) {
    for (int i = 0; i < array_size; ++i) {
        if (dynamic_array[i]->ue_id == ue_id) {
            strcat(dynamic_array[i]->session_list, session);
            dynamic_array[i]->last_updated = time(NULL);
            return;
        }
    }
    if (array_size >= MAX_UE_CONTEXTS) {
        fprintf(stderr, "Dynamic array is full\n");
        return;
    }
    dynamic_array[array_size] = (UEContext*)malloc(sizeof(UEContext));
    dynamic_array[array_size]->ue_id = ue_id;
    strcpy(dynamic_array[array_size]->session_list, session);
    dynamic_array[array_size]->last_updated = time(NULL);
    array_size++;
}

void remove_inactive_sessions(time_t threshold) {
    for (int i = 0; i < array_size; ++i) {
        if (time(NULL) - dynamic_array[i]->last_updated > threshold) {
            free(dynamic_array[i]);
            for (int j = i; j < array_size - 1; ++j) {
                dynamic_array[j] = dynamic_array[j + 1];
            }
            array_size--;
            i--;
        }
    }
}

void update_session(int ue_id, const char* session) {
    for (int i = 0; i < array_size; ++i) {
        if (dynamic_array[i]->ue_id == ue_id) {
            strcpy(dynamic_array[i]->session_list, session);
            dynamic_array[i]->last_updated = time(NULL);
            return;
        }
    }
}

void log_event(const char* event) {
