#include <openssl/md5.h>

unsigned long long compute_network_flow_hash(const char* source_ip, const char* destination_ip, int source_port, int destination_port)
{
    unsigned char hash[MD5_DIGEST_LENGTH];
    unsigned char buffer[128];
    snprintf((char*)buffer, sizeof(buffer), "%s:%d:%s:%d", source_ip, source_port, destination_ip, destination_port);
    MD5(buffer, strlen((const char*)buffer), hash);

    unsigned long long result = 0;
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++)
    {
        result = (result << 8) | hash[i];
    }

    return result;
}
