#define MAX_LINE_LENGTH 1024
#define CACHE_SIZE 1000

typedef struct {
    char *key;
    int count;
} CacheItem;

CacheItem cache[CACHE_SIZE];

int hash(char *key) {
    int hash = 0;
    for (int i = 0; key[i]; i++) {
        hash = hash * 31 + key[i];
    }
    return abs(hash % CACHE_SIZE);
}

void addToCache(char *key, int count) {
    int index = hash(key);
    if (cache[index].key == NULL) {
        cache[index].key = strdup(key);
        cache[index].count = count;
    } else if (strcmp(cache[index].key, key) == 0) {
        cache[index].count += count;
    } else {
        // Collision handling can be improved
        printf("Collision occurred in cache.\n");
    }
}

int getCachedCount(char *key) {
    int index = hash(key);
    if (cache[index].key != NULL && strcmp(cache[index].key, key) == 0) {
        return cache[index].count;
    } else {
        return 0;
    }
}

void freeCache() {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].key != NULL) {
            free(cache[i].key);
        }
    }
}

