void* ThreadedContentGenerator(void *arg) {
    int thread_id = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_PDUS];
    ContentGenerator(pdus, MAX_PDUS);
    // Process PDUs
