    int thread_ids[10];

    for (int i = 0; i < 10; ++i) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, ThreadedContentGenerator, &thread_ids[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

