#include <time.h>

// Define necessary structures
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} RX_UE_INFORMATION_T;

typedef struct {
    RX_UE_INFORMATION_T rxUeInfo;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate random integers within a range
int generateRandomInt(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to generate random floats within a range
float generateRandomFloat(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

// Function to initialize NFAPI_CRC_INDICATION_PDU_T structures
void ContentGenerator(NFAPI_CRC_INDICATION_PDU_T *pduArray, int size, int numRxUeInfos, int rntiMin, int rntiMax) {
    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < size; ++i) {
        pduArray[i].rxUeInfo.RX_UE_INFORMATION_TAG = generateRandomInt(1, numRxUeInfos);
        pduArray[i].rxUeInfo.RNTI = generateRandomInt(rntiMin, rntiMax);
        pduArray[i].CRCFLAG = generateRandomInt(0, 1); // Assuming CRCFLAG is a boolean
    }
}

// Example usage
int main() {
    const int size = 5;
    NFAPI_CRC_INDICATION_PDU_T pduArray[size];

    ContentGenerator(pduArray, size, 3, 10, 20);

    for (int i = 0; i < size; ++i) {
        printf("PDU %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n",
               i, pduArray[i].rxUeInfo.RX_UE_INFORMATION_TAG, 
               pduArray[i].rxUeInfo.RNTI, pduArray[i].CRCFLAG);
    }

    return 0;
}
