void addSession(UEContext *ue, int sessionId) {
    for (int i = 0; i < MAX_UE_SESSIONS; i++) {
        if (ue->session_list[i] == 0) {
            ue->session_list[i] = sessionId;
            ue->last_session_update = time(NULL);
            return;
        }
    }
}

void removeInactiveSessions(UEContext *ue, int inactivityThreshold) {
    for (int i = 0; i < MAX_UE_SESSIONS; i++) {
        if (ue->session_list[i] != 0 && difftime(time(NULL), ue->last_session_update) > inactivityThreshold) {
            ue->session_list[i] = 0;
        }
    }
}

void updateSessionTimestamp(UEContext *ue, int sessionId) {
    for (int i = 0; i < MAX_UE_SESSIONS; i++) {
        if (ue->session_list[i] == sessionId) {
            ue->last_session_update = time(NULL);
            break;
        }
    }
}

