public class ContentGenerator : IContentGenerator
{
    private readonly Random _random = new Random();
    private readonly ILogger _logger;

    public ContentGenerator(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public int GenerateRandomInt(int min, int max, bool inclusive)
    {
        return GenerateRandomValue(min, max, inclusive);
    }

    public float GenerateRandomFloat(float min, float max, bool inclusive)
    {
        return (float)GenerateRandomValue(min, max, inclusive);
    }

    private double GenerateRandomValue(double min, double max, bool inclusive)
    {
        double value = _random.NextDouble() * (max - min) + min;
        if (!inclusive && value == max)
            value -= 1e-9; // Ensure exclusivity for floats
        return value;
    }

    public void LogGenerationEvent(string methodName, params object[] parameters)
    {
        var timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff");
        string logMessage = $"{timestamp} - {methodName}({string.Join(", ", parameters.Select(p => p?.ToString() ?? "null"))})";
        _logger.Log(logMessage);
    }

    public List<ContentItem> GetContentSublist(int[] states, FSA fsa, int lastState)
    {
        if (states == null || fsa == null || lastState < 0)
            throw new ArgumentException("Invalid arguments");

        List<ContentItem> sublist = new List<ContentItem>();
        // Simulate constructing a sublist of content items
        for (int i = 0; i < states.Length; i++)
        {
            sublist.Add(new ContentItem { State = states[i], Value = GenerateRandomInt(1, 100, true) });
        }

        return sublist;
    }

    public void ProcessTextForContentMentions(string text, Language language)
    {
        if (string.IsNullOrEmpty(text))
            throw new ArgumentException("Invalid input");

        // Simulate processing text for content mentions
        var regexPatterns = GetRegexPatterns(language);
        foreach (var pattern in regexPatterns)
        {
            var matches = Regex.Matches(text, pattern);
            foreach (Match match in matches)
            {
                // Process each match
                LogGenerationEvent("ProcessTextForContentMentions", text, pattern, match.Value);
            }
        }
    }

    private List<string> GetRegexPatterns(Language language)
    {
        // Simulate retrieving regex patterns based on language
        return new List<string>
        {
            language == Language.English ? @"\bcontent\b" : @"[\u05E1-\u05EA]+"
        };
    }
}

public interface ILogger
{
    void Log(string message);
}

public class ConsoleLogger : ILogger
{
    public void Log(string message)
    {
        Console.WriteLine(message);
    }
}

