    private readonly List<Tuple<DateTime, string>> _logs = new List<Tuple<DateTime, string>>();
    private readonly object _lockObject = new object();

    public void GenerateRandomFloat(float min, float max, bool inclusive)
    {
        lock (_lockObject)
        {
            var value = inclusive ? (float)_random.NextDouble() * (max - min) + min : _random.Next((int)(min * 1000), (int)(max * 1000)) / 1000f;
            Log($"Generated random float: {value} between {min} and {max}");
        }
    }

    public void GenerateRandomInt(int min, int max, bool inclusive)
    {
        lock (_lockObject)
        {
            var value = inclusive ? _random.Next(min, max + 1) : _random.Next(min, max);
            Log($"Generated random integer: {value} between {min} and {max}");
        }
    }

    private void Log(string message)
    {
        _logs.Add(Tuple.Create(DateTime.Now, message));
        LogToExternalService(message);
    }

    private void LogToExternalService(string message)
    {
        // Simulate external logging service call
        try
        {
            // External service logic here
            Debug.WriteLine($"Logged to external service: {message}");
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"Failed to log to external service: {ex.Message}");
        }
    }

    public void ProcessTextForContentMentions(string[] states, int stateCount, FSA fsa, int lastStateIndex, string text, bool isHebrew)
    {
        lock (_lockObject)
        {
            // Implement regex pattern handling for different languages
            var patterns = isHebrew ? new[] { @"\bשָׁם\b", @"\bיהוּדיהוֹ\b" } : new[] { @"\bAmerica\b", @"\bCanada\b" };

            foreach (var pattern in patterns)
            {
                var matches = Regex.Matches(text, pattern);
                if (matches.Count > 0)
                {
                    Log($"Content mention found: {pattern} - Count: {matches.Count}");
                }
            }

            // Update FSA state list
            var newStateList = new List<int>(stateCount * 2); // Simplified example
            for (int i = 0; i < stateCount; i++)
            {
                newStateList.Add(states[i]);
            }

            states[lastStateIndex] = newStateList.ToArray();
        }
    }
}

