void add_session(UEContextArray *array, int ue_id) {
    pthread_mutex_lock(&array->lock);
    if (array->size < MAX_UE_CONTEXTS) {
        array->ue_contexts[array->size++] = (UEContext *)malloc(sizeof(UEContext));
        array->ue_contexts[array->size - 1]->ue_id = ue_id;
        // Initialize other fields
    }
    pthread_mutex_unlock(&array->lock);
}

void remove_inactive_sessions(UEContextArray *array, time_t current_time) {
    pthread_mutex_lock(&array->lock);
    for (int i = array->size - 1; i >= 0; i--) {
        if ((current_time - array->ue_contexts[i]->timestamp) > INACTIVITY_THRESHOLD) {
            free(array->ue_contexts[i]);
            for (; i < array->size - 1; i++) {
                array->ue_contexts[i] = array->ue_contexts[i + 1];
            }
            array->size--;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

