int add_ue_context(SessionManager *manager, int ue_id) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_UE_CONTEXTS) {
        log_allocation_failure("Maximum number of UE contexts reached");
        return -1;
    }
    manager->contexts[manager->count].ue_id = ue_id;
    // Initialize other QoS flow information tags
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

