    public function generateRandomValue($type) {
        if (!isset($this->contentTypes[$type])) {
            throw new Exception("Invalid content type");
        }

        $typeInfo = $this->contentTypes[$type];
        $min = $typeInfo['min'];
        $max = $typeInfo['max'];
        $inclusive = $typeInfo['inclusive'];

        if ($inclusive) {
            return rand($min, $max);
        } else {
            return mt_rand($min + 1, $max - 1);
        }
    }

