static pthread_mutex_t context_lock = PTHREAD_MUTEX_INITIALIZER;
static int num_active_contexts = 0;

// Implement other functions and data structures as per the problem statement

int allocate_session_context(const char *ue_id, QoSFlowInfo qos_info) {
    pthread_mutex_lock(&context_lock);
    if (num_active_contexts >= MAX_UE_CONTEXTS || num_active_contexts >= MAX_CONCURRENT_ALLOCATIONS) {
        pthread_mutex_unlock(&context_lock);
        return -1;
    }
    // Find an empty slot and populate it
    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        if (session_contexts[i].ue_id[0] == '\0') {
            strncpy(session_contexts[i].ue_id, ue_id, sizeof(session_contexts[i].ue_id));
            session_contexts[i].qos_info = qos_info;
            num_active_contexts++;
            pthread_mutex_unlock(&context_lock);
            return i;
        }
    }
    pthread_mutex_unlock(&context_lock);
    return -1;
}

int free_session_context(const char *ue_id) {
    pthread_mutex_lock(&context_lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        if (strcmp(session_contexts[i].ue_id, ue_id) == 0) {
            session_contexts[i].ue_id[0] = '\0';
            // Clear other fields
            num_active_contexts--;
            pthread_mutex_unlock(&context_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&context_lock);
    return -1;
}

