typedef struct {
    uint64_t ue_id;
    uint32_t qos_tags[MAX_QOS_TAGS];
    NFAPI_CRC_INDICATION_PDU_T pdu;
} SessionContext;

SessionContext** session_pool = NULL;
int pool_size = 0;
int next_index = 0;

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* manage_session_context(uint64_t ue_id, uint32_t* qos_tags, int num_tags, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pool_lock);

    if (next_index >= pool_size || session_pool[next_index] == NULL) {
        if (next_index >= MAX_CONCURRENT_ALLOCATIONS) {
            // Handle allocation failure and log
            fprintf(stderr, "Allocation failed: maximum concurrent allocations reached\n");
            return NULL;
        }

        if (session_pool[next_index] == NULL) {
            session_pool[next_index] = (SessionContext*)malloc(sizeof(SessionContext));
        }

        pool_size++;
    }

    SessionContext* ctx = session_pool[next_index];
    ctx->ue_id = ue_id;
    memcpy(ctx->qos_tags, qos_tags, num_tags * sizeof(uint32_t));
    memcpy(&ctx->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    next_index++;

    pthread_mutex_unlock(&pool_lock);

    return &ctx->pdu;
}

