using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Text.RegularExpressions;

public class ContentManager
{
    private ConcurrentDictionary<string, Random> _randomGenerators = new ConcurrentDictionary<string, Random>();
    private ILoggerService _logger;
    private IDataSourceService _dataService;
    private ICdnService _cdnService;

    public ContentManager(ILoggerService logger, IDataSourceService dataService, ICdnService cdnService)
    {
        _logger = logger;
        _dataService = dataService;
        _cdnService = cdnService;
    }

    public int GenerateRandomValue(string contentType, int minRange, int maxRange)
    {
        if (!_randomGenerators.ContainsKey(contentType))
        {
            _randomGenerators[contentType] = new Random();
        }
        return _randomGenerators[contentType].Next(minRange, maxRange + 1);
    }

    public double GenerateRandomFloat(string contentType, double minRange, double maxRange)
    {
        if (!_randomGenerators.ContainsKey(contentType))
        {
            _randomGenerators[contentType] = new Random();
        }
        return _randomGenerators[contentType].NextDouble() * (maxRange - minRange) + minRange;
    }

    public void ProcessContent(List<string> contentItems, string category)
    {
        if (contentItems == null || category == null)
            throw new ArgumentException("Null pointer provided");

        var filteredContent = contentItems.Where(item => item.Contains(category)).ToList();
        _logger.Log($"Filtered {filteredContent.Count} items for category {category}");
    }

    public void ConstructSublists(int[] states, int numStates, FSA fsa, int lastState)
    {
        if (states == null || fsa == null || lastState < 0 || lastState >= numStates)
            throw new ArgumentException("Invalid state index or pointers");

        try
        {
            var newStateList = states.Skip(lastState + 1).ToList();
            fsa.next[lastState] = newStateList.ToArray();
        }
        catch (OutOfMemoryException ex)
        {
            _logger.LogError(ex, "Failed to allocate memory for new state list");
            throw;
        }
    }

    public List<string> ExtractContentMentions(string text, string language)
    {
        var patterns = GetRegexPatterns(language);
        return patterns.SelectMany(pattern => Regex.Matches(text, pattern).Cast<Match>().Select(m => m.Value)).ToList();
    }

    private IEnumerable<string> GetRegexPatterns(string language)
    {
        if (language == "English")
            return new[] { @"\b[A-Za-z]+\b" };
        else if (language == "Hebrew")
            return new[] { @"\p{Hebrew}+" };
        else
            throw new ArgumentException("Unsupported language");
    }
}
