<?php

class UEContext {
    public $ue_id;
    public $session_list = [];
    public $timestamp;

    public function __construct($ue_id) {
        $this->ue_id = $ue_id;
        $this->timestamp = time();
    }

    public function addSession($session) {
        if (!in_array($session, $this->session_list)) {
            $this->session_list[] = $session;
            $this->updateTimestamp();
        }
    }

    public function removeInactiveSessions($threshold) {
        $currentTime = time();
        foreach ($this->session_list as $key => $session) {
            if ($currentTime - $this->timestamp > $threshold) {
                unset($this->session_list[$key]);
            }
        }
        $this->updateTimestamp();
    }

    public function updateTimestamp() {
        $this->timestamp = time();
    }
}

$ue_contexts = [];

function addUEContext($ue_id) {
    global $ue_contexts;
    if (!isset($ue_contexts[$ue_id])) {
        $ue_contexts[$ue_id] = new UEContext($ue_id);
    }
}

function removeInactiveSessions($threshold) {
    global $ue_contexts;
    foreach ($ue_contexts as $ue_id => $ue_context) {
        $ue_context->removeInactiveSessions($threshold);
    }
}

// Example usage
