import hashlib
import os
from tqdm import tqdm
import requests
import asyncio

class FileHasher:
    supported_algorithms = ['md5', 'sha256']

    @staticmethod
    async def fetch_file_metadata(file_path):
        try:
            metadata = await asyncio.to_thread(requests.get, file_path)
            metadata.raise_for_status()
            return metadata.json()
        except requests.RequestException as e:
            print(f"Error fetching metadata: {e}")
            return None

    async def hash_file(self, file_path, algorithm='sha256', chunk_size=1024*1024):
        if algorithm not in self.supported_algorithms:
            raise ValueError("Unsupported hash algorithm")

        hasher = hashlib.new(algorithm)
        try:
            with open(file_path, 'rb') as f:
                while True:
                    data = f.read(chunk_size)
                    if not data:
                        break
                    hasher.update(data)
        except IOError as e:
            print(f"Error reading file: {e}")
            return None

        return hasher.hexdigest()

    async def process_files(self, file_paths, algorithm='sha256', chunk_size=1024*1024):
        tasks = [self.hash_file(path, algorithm, chunk_size) for path in file_paths]
        results = await asyncio.gather(*tasks)
        return results

async def convert_jpeg_to_pdf(jpeg_path, pdf_path, compression_level):
    if not os.path.isfile(jpeg_path) or not os.access(pdf_path, os.W_OK):
        print("Invalid file paths")
        return 1

    try:
        # Assuming 'convert' is a command-line utility for JPEG to PDF conversion
        command = f"convert -density 300 {jpeg_path} -compress jpeg {compression_level} {pdf_path}"
        result = os.system(command)
        if result == 0:
            print("Conversion successful")
        else:
            print("Conversion failed")
        return result
    except Exception as e:
        print(f"Error during conversion: {e}")
        return 1

# Example usage
async def main():
    file_paths = ['path/to/file1.jpg', 'path/to/file2.jpg']
    hasher = FileHasher()
    hash_results = await hasher.process_files(file_paths, algorithm='sha256')
    print(hash_results)

    jpeg_path = 'path/to/image.jpeg'
    pdf_path = 'path/to/output.pdf'
    conversion_result = await convert_jpeg_to_pdf(jpeg_path, pdf_path, compression_level=9)
    print(f"Conversion result: {conversion_result}")

asyncio.run(main())
