#include <stdio.h>
#include <stdlib.h>

int convert_jpeg_to_pdf(const char *jpeg_path, const char *pdf_path, int compression_level) {
    if (access(jpeg_path, F_OK) != 0 || access(pdf_path, W_OK) != 0) {
        fprintf(stderr, "Invalid file paths\n");
        return 1;
    }

    char command[512];
    snprintf(command, sizeof(command), "convert -density 300 %s -compress jpeg %d %s", jpeg_path, compression_level, pdf_path);

    int result = system(command);
    if (result == 0) {
        printf("Conversion successful\n");
    } else {
        printf("Conversion failed\n");
    }

    return result;
}

int main() {
    const char *jpeg_path = "path/to/image.jpeg";
    const char *pdf_path = "path/to/output.pdf";
    int compression_level = 9;

    convert_jpeg_to_pdf(jpeg_path, pdf_path, compression_level);
    return 0;
}
