                        if not data:
                            break
                        md5_hash.update(data)
                        if time.time() - start_time > timeout:
                            raise TimeoutError("File processing timed out")
                md5_hashes[file_name] = md5_hash.hexdigest()
            except Exception as e:
                print(f"Error processing file {file_path}: {e}")

    return md5_hashes
