import hashlib
import os
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from tqdm import tqdm

class FileHasher:
    def __init__(self, algorithms=['md5', 'sha256'], chunk_size=4096):
        self.algorithms = algorithms
        self.chunk_size = chunk_size

    def hash_file(self, file_path):
        hashes = {algo: hashlib.new(algo) for algo in self.algorithms}
        with open(file_path, 'rb') as f:
            while chunk := f.read(self.chunk_size):
                for algo_hash in hashes.values():
                    algo_hash.update(chunk)
        return {algo: algo_hash.hexdigest() for algo_hash, algo in zip(hashes.values(), self.algorithms)}

    def hash_url(self, url):
        response = requests.get(url, stream=True)
        hashes = {algo: hashlib.new(algo) for algo in self.algorithms}
        total_length = int(response.headers.get('content-length', 0))
        with tqdm(total=total_length, unit='B', unit_scale=True) as pbar:
            for chunk in response.iter_content(chunk_size=self.chunk_size):
                if chunk:
                    for algo_hash in hashes.values():
                        algo_hash.update(chunk)
                    pbar.update(len(chunk))
        return {algo: algo_hash.hexdigest() for algo_hash, algo in zip(hashes.values(), self.algorithms)}

def main():
    hasher = FileHasher()
    file_paths = ['path/to/local/file.txt', 'http://example.com/somefile.txt']
    with ThreadPoolExecutor(max_workers=2) as executor:
        results = list(tqdm(executor.map(hasher.hash_file, file_paths), total=len(file_paths)))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
