import hashlib
import os
from concurrent.futures import ThreadPoolExecutor, as_completed

def compute_hash(file_path, algorithm='sha256', chunk_size=8192):
    hasher = hashlib.new(algorithm)
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def progress_indicator(total_chunks, current_chunk, start_time):
    elapsed_time = (os.times()[4] - start_time) / 100
    percent_completed = (current_chunk + 1) / total_chunks * 100
    print(f"\rProgress: {percent_completed:.2f}% ({elapsed_time:.2f}s)", end="")

def process_files(file_paths, algorithm='sha256', chunk_size=8192):
    results = {}
    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = [executor.submit(compute_hash, file_path, algorithm, chunk_size) for file_path in file_paths]
        for future in as_completed(futures):
            file_path = future.args[0]
            try:
                hash_value = future.result()
                results[file_path] = hash_value
                progress_indicator(len(file_paths), futures.index(future), os.times()[4])
            except Exception as e:
                print(f"\nError processing {file_path}: {e}")
    return results

if __name__ == "__main__":
    file_paths = ['path/to/file1.txt', 'path/to/file2.jpg']
    hash_results = process_files(file_paths, algorithm='md5')
    for file_path, hash_value in hash_results.items():
        print(f"{file_path}: {hash_value}")
```

