#include <arpa/inet.h>

typedef struct DeviceConnection {
    int device_id;
    struct StreamNode* stream_list;
    time_t last_update;
} DeviceConnection;

typedef struct StreamNode {
    int stream_id;
    struct StreamNode* next;
} StreamNode;

typedef struct FrameHeader {
    uint32_t source_address;
    uint32_t destination_address;
    uint16_t protocol_type;
    uint16_t sequence_number;
} FrameHeader;

DeviceConnection* add_stream(DeviceConnection* device, int stream_id) {
    if (device == NULL || stream_id <= 0) return device;

    StreamNode* new_stream = (StreamNode*)malloc(sizeof(StreamNode));
    if (new_stream == NULL) return device; // Handle memory allocation failure

    new_stream->stream_id = stream_id;
    new_stream->next = device->stream_list;
    device->stream_list = new_stream;
    device->last_update = time(NULL);

    return device;
}

void remove_inactive_streams(DeviceConnection* device, time_t threshold) {
    if (device == NULL || device->stream_list == NULL) return;

    StreamNode* current = device->stream_list;
    StreamNode* prev = NULL;

    while (current != NULL) {
        if (time(NULL) - current->last_update > threshold) {
            if (prev == NULL) {
                device->stream_list = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

FrameHeader* generate_frame_headers(int num_headers) {
    FrameHeader* headers = (FrameHeader*)malloc(num_headers * sizeof(FrameHeader));
    if (headers == NULL) return NULL; // Handle memory allocation failure

    for (int i = 0; i < num_headers; ++i) {
        headers[i].source_address = inet_addr("127.0.0.1");
        headers[i].destination_address = inet_addr("192.168.1.1");
        headers[i].protocol_type = 1;
        headers[i].sequence_number = rand();
    }

    return headers;
}

void update_network_settings() {
    char buffer[INET_ADDRSTRLEN];
    struct ifaddrs* ifaddr, *ifa;
    int family, s;
    char host[NI_MAXHOST];

    if (getifaddrs(&ifaddr) == -1) {
        perror("getifaddrs");
        return;
    }

    for (ifa = ifaddr; ifa != NULL; ifa = ifa->ifa_next) {
        if (ifa->ifa_addr == NULL)
            continue;

        family = ifa->ifa_addr->sa_family;

        switch (family) {
            case AF_INET:
                s = getnameinfo(ifa->ifa_addr,
                               (family == AF_INET) ? sizeof(struct sockaddr_in) : sizeof(struct sockaddr_in6),
                               host, NI_MAXHOST,
                               NULL, 0, NI_NUMERICHOST);
                if (s != 0) {
                    printf("getnameinfo() failed: %s\n", gai_strerror(s));
                    continue;
                }
                printf("IP address of %s: %s\n", ifa->ifa_name, host);
                break;
            // Add cases for other address families as needed
        }
    }

    freeifaddrs(ifaddr);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE* file = fopen(argv[1], "r");
    if (file == NULL) {
