import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
from urllib.request import urlopen
from tqdm import tqdm

def hash_file(file_path, algorithm='md5', chunk_size=1024*1024):
    hasher = hashlib.new(algorithm)
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def hash_url(url, algorithm='md5', chunk_size=1024*1024):
    response = urlopen(url)
    hasher = hashlib.new(algorithm)
    while True:
        data = response.read(chunk_size)
        if not data:
            break
        hasher.update(data)
    return hasher.hexdigest()

def process_files(file_paths, algorithm='md5', chunk_size=1024*1024):
    with ThreadPoolExecutor() as executor:
        futures = {executor.submit(hash_file, file_path, algorithm, chunk_size): file_path for file_path in file_paths}
        results = {}
        for future in tqdm(as_completed(futures), total=len(futures)):
            file_path = futures[future]
            try:
                hash_value = future.result()
                results[file_path] = hash_value
            except Exception as e:
                print(f"Error processing {file_path}: {e}")
    return results

# Example usage
file_paths = ['path/to/file1', 'path/to/file2']
