        {
            return new Random().NextFloatInRange(floatRange.Item1, floatRange.Item2, floatRange.Item3, floatRange.Item4);
        }
        else if (intRanges.TryGetValue(key, out var intRange))
        {
            return new Random().NextIntInRange(intRange.Item1, intRange.Item2, intRange.Item3, intRange.Item4);
        }

