            return (float)rand.NextDouble() * (end - start + 1) + start;
        else if (inclusiveStart)
            return (float)rand.NextDouble() * (end - start) + start;
        else
            return (float)rand.NextDouble() * (end - start - 1) + start + 0.5f;
    }

    private static int NextIntInRange(int start, int end, bool inclusiveStart, bool inclusiveEnd)
