    {
        if (numbers == null || numbers.Length == 0)
        {
            throw new System.ArgumentException("Array must not be empty", nameof(numbers));
        }

        int largest = numbers[0];
        foreach (int num in numbers)
        {
            if (num > largest)
            {
                largest = num;
            }
        }
        return largest;
    }
