using System;
using System.Collections.Concurrent;
using System.Data.Common;
using System.Diagnostics;
using System.Linq;
using System.Threading;

public class DynamicResourceManager
{
    private readonly ConcurrentDictionary<int, DbConnection> _connectionPool = new();
    private int _currentConnections;
    private int _maxConnections;
    private Timer _monitoringTimer;
    private Stopwatch _responseTimeTracker = new();

    public DynamicResourceManager(int initialConnections, int maxConnections)
    {
        if (initialConnections < 1 || maxConnections < 1 || initialConnections > maxConnections)
            throw new ArgumentException("Invalid connection settings.");

        _maxConnections = maxConnections;
        for (int i = 0; i < initialConnections; i++)
        {
            var conn = CreateConnection();
            _connectionPool.TryAdd(i, conn);
            _currentConnections++;
        }

        _monitoringTimer = new Timer(MonitorConnections, null, TimeSpan.Zero, TimeSpan.FromSeconds(5));
    }

    private DbConnection CreateConnection()
    {
        // Placeholder for actual connection creation logic
        return DatabaseFactory.CreateConnection("DatabaseConnectionString");
    }

    public DbConnection AcquireConnection()
    {
        if (_currentConnections >= _maxConnections)
            throw new InvalidOperationException("Maximum connections reached.");

        int key = -1;
        while (!_connectionPool.TryAdd(key, null))
        {
            key--;
        }

        var conn = CreateConnection();
        _connectionPool[key] = conn;
        Interlocked.Increment(ref _currentConnections);

        return conn;
    }

    public void ReleaseConnection(DbConnection connection)
    {
        if (connection == null)
            throw new ArgumentNullException(nameof(connection));

        int? key = _connectionPool.FirstOrDefault(x => x.Value == connection).Key;
        if (!key.HasValue)
            throw new InvalidOperationException("Invalid or already released connection.");

        _connectionPool.TryRemove(key.Value, out _);
        Interlocked.Decrement(ref _currentConnections);
    }

    private void MonitorConnections(object state)
    {
        var activeConnections = _maxConnections - _currentConnections;
        var idleConnections = _currentConnections;
        var averageResponseTime = (double)_responseTimeTracker.ElapsedTicks / _currentConnections;

        // Placeholder for external monitoring service integration
        ExternalMonitoringService.LogMetrics(activeConnections, idleConnections, averageResponseTime);

        if (_currentConnections > 2 * activeConnections)
            AdjustMaxConnections(_maxConnections + 10);
    }

    private void AdjustMaxConnections(int newMaxConnections)
    {
        _maxConnections = Math.Min(newMaxConnections, 50); // Prevent excessive scaling
        while (_currentConnections < _maxConnections)
        {
            var conn = CreateConnection();
            _connectionPool.TryAdd(_currentConnections, conn);
            Interlocked.Increment(ref _currentConnections);
        }
    }

    public void Dispose()
    {
        _monitoringTimer?.Change(Timeout.Infinite, 0);
        foreach (var conn in _connectionPool.Values)
        {
            if (conn != null)
                conn.Dispose();
        }
        _connectionPool.Clear();
    }
}
