#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_SESSIONS 1024

typedef struct {
    int ue_id;
    int session_list[MAX_UE_SESSIONS];
    time_t timestamp;
} UEContext;

typedef struct {
    UEContext* contexts;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

void init_dynamic_array(DynamicArray* array) {
    array->contexts = (UEContext*)malloc(sizeof(UEContext) * 10);
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void add_session(DynamicArray* array, int ue_id, int session_id) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= 10) {
        // Resize array
        array->contexts = (UEContext*)realloc(array->contexts, sizeof(UEContext) * 20);
        memset(array->contexts + array->size, 0, sizeof(UEContext) * 10);
    }
    UEContext* ctx = &array->contexts[array->size];
    ctx->ue_id = ue_id;
    ctx->session_list[ctx->size] = session_id;
    ctx->timestamp = time(NULL);
    array->size++;
    pthread_mutex_unlock(&array->mutex);
}

void remove_inactive_sessions(DynamicArray* array, time_t threshold) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ) {
        if (time(NULL) - array->contexts[i].timestamp > threshold) {
            // Remove session
            for (int j = i; j < array->size - 1; j++) {
                array->contexts[j] = array->contexts[j + 1];
            }
            array->size--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void update_session_timestamp(DynamicArray* array, int ue_id) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; i++) {
        if (array->contexts[i].ue_id == ue_id) {
            array->contexts[i].timestamp = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void free_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->contexts);
    array->size = 0;
    pthread_mutex_destroy(&array->mutex);
}
