{
    private Dictionary<string, Tuple<Tuple<float, float>, Tuple<int, int>>> rangeConfigurations = new Dictionary<string, Tuple<Tuple<float, float>, Tuple<int, int>>>();
    private Random random = new Random();
    private static readonly object lockObject = new object();

    public void ConfigureRange(string name, (float min, float max) floatRange, (int min, int max) intRange)
    {
        rangeConfigurations[name] = Tuple.Create(Tuple.Create(floatRange.min, floatRange.max), Tuple.Create(intRange.min, intRange.max));
    }

    public float GenerateRandomFloat(string name)
    {
        if (!rangeConfigurations.ContainsKey(name))
            throw new ArgumentException("Range not configured for this name.");

        var (floatMin, floatMax) = rangeConfigurations[name].Item1;
        return random.NextSingle() * (floatMax - floatMin) + floatMin;
    }

    public int GenerateRandomInt(string name)
    {
        if (!rangeConfigurations.ContainsKey(name))
            throw new ArgumentException("Range not configured for this name.");

        var (intMin, intMax) = rangeConfigurations[name].Item2;
        return random.Next(intMin, intMax + 1);
    }

