// NetworkDataProcessor class definition
class NetworkDataProcessor {
private:
    std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<std::string> dataQueue_;
    std::vector<std::thread> threads_;
    std::atomic<bool> running_{true};
    MessageService* messageService_;
    MLAnomalyDetector anomalyDetector_;
    int retryAttempts;
    std::chrono::milliseconds backoffBase;

public:
    NetworkDataProcessor(MessageService* ms, int retries = 3, std::chrono::milliseconds baseBackoff = std::chrono::seconds(1))
        : messageService_(ms), retryAttempts(retries), backoffBase(baseBackoff) {
        // Initialize threads
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            threads_.emplace_back(&NetworkDataProcessor::processData, this);
        }
    }

    ~NetworkDataProcessor() {
        running_ = false;
        cv_.notify_all();
        for (auto& t : threads_) {
            if (t.joinable()) {
                t.join();
            }
        }
    }

    void addData(const std::string& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        dataQueue_.push(data);
        cv_.notify_one();
    }

    void processData() {
        while (running_) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !dataQueue_.empty() || !running_; });
            if (!running_ && dataQueue_.empty()) break;
            auto data = dataQueue_.front();
            dataQueue_.pop();
            lock.unlock();

            // Process data
            std::string processedData = processAndFilter(data);
            publishData(processedData);
        }
    }

private:
    std::string processAndFilter(const std::string& data) {
        // Placeholder for data processing and filtering logic
        return data;
    }

    void publishData(const std::string& data) {
        int attempts = 0;
        while (attempts < retryAttempts) {
            try {
                messageService_->publish(data);
                break; // Success
            } catch (const std::exception& e) {
                std::this_thread::sleep_for(backoffBase * (1 << attempts));
                ++attempts;
            }
        }
    }

    void adjustProcessingConfig() {
        // Placeholder for dynamic configuration adjustment logic
    }
};

