#include <pthread.h>
#include <time.h>

#define N 1024

typedef struct {
    uint64_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T buffer[N];
    int head;
    int tail;
    pthread_mutex_t mutex;
} CircularBuffer;

void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

int is_full(CircularBuffer *cb) {
    return (cb->tail + 1) % N == cb->head;
}

int is_empty(CircularBuffer *cb) {
    return cb->head == cb->tail;
}

void enqueue(CircularBuffer *cb, uint64_t rx_ue_information_tag, uint16_t rnti, uint8_t crc_indication_rel8_tag) {
    pthread_mutex_lock(&cb->mutex);
    if (is_full(cb)) {
        // Handle memory exhaustion
        fprintf(stderr, "Circular buffer is full\n");
        pthread_mutex_unlock(&cb->mutex);
        return;
    }
    cb->buffer[cb->tail].rx_ue_information_tag = rx_ue_information_tag;
    cb->buffer[cb->tail].rnti = rnti;
    cb->buffer[cb->tail].crc_indication_rel8_tag = crc_indication_rel8_tag;
    cb->tail = (cb->tail + 1) % N;
    pthread_mutex_unlock(&cb->mutex);
}

void dequeue(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&cb->mutex);
    if (is_empty(cb)) {
        // Handle empty buffer
        fprintf(stderr, "Circular buffer is empty\n");
        pthread_mutex_unlock(&cb->mutex);
        return;
    }
    *pdu = cb->buffer[cb->head];
    cb->head = (cb->head + 1) % N;
    pthread_mutex_unlock(&cb->mutex);
}

void iterate_forward(CircularBuffer *cb, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    int current = cb->head;
    while (current != cb->tail) {
        callback(cb->buffer[current]);
        current = (current + 1) % N;
    }
}

void iterate_reverse(CircularBuffer *cb, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    int current = (cb->tail - 1 + N) % N;
    while (current != cb->head) {
        callback(cb->buffer[current]);
        current = (current - 1 + N) % N;
    }
}

void log_event(uint64_t timestamp, uint64_t unique_id) {
    printf("Event at timestamp: %lu, Unique ID: %lu\n", timestamp, unique_id);
}

int main() {
    CircularBuffer cb;
    init_circular_buffer(&cb);

    // Simulate concurrent access
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, enqueue_thread, &cb);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (!is_empty(&cb)) {
        dequeue(&cb, &pdu);
        // Process the PDU
    }

    return 0;
}

