#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_BUFFER_SIZE 1024

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T buffer[MAX_BUFFER_SIZE];
    int head;
    int tail;
    int size;
    pthread_mutex_t mutex;
} CRCBuffer;

void initializeCRCBuffer(CRCBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->size = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

int addElementToBuffer(CRCBuffer *buffer, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&buffer->mutex);

    if ((buffer->head + 1) % MAX_BUFFER_SIZE == buffer->tail) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Buffer is full
    }

    buffer->buffer[buffer->head] = element;
    buffer->head = (buffer->head + 1) % MAX_BUFFER_SIZE;
    buffer->size++;

    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

int removeElementFromBuffer(CRCBuffer *buffer, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&buffer->mutex);

    if (buffer->head == buffer->tail) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Buffer is empty
    }

    *element = buffer->buffer[buffer->tail];
    buffer->tail = (buffer->tail + 1) % MAX_BUFFER_SIZE;
    buffer->size--;

    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Additional functions for iterating, logging, and purging can be implemented here
