<?php
// Define the UEContext structure
class UEContext {
    public $ue_id;
    public $session_list = [];
    public $last_update;

    function __construct($ue_id) {
        $this->ue_id = $ue_id;
        $this->last_update = time();
    }

    function addSession($session) {
        if (!in_array($session, $this->session_list)) {
            $this->session_list[] = $session;
            $this->last_update = time();
        }
    }

    function removeInactiveSessions($threshold) {
        $current_time = time();
        foreach ($this->session_list as $key => $session) {
            if (($current_time - $this->last_update) > $threshold) {
                unset($this->session_list[$key]);
            }
        }
    }
}

// Dynamic array of UEContext
$ue_contexts = [];

function addUEContext($ue_id) {
    global $ue_contexts;
    if (!isset($ue_contexts[$ue_id])) {
        $ue_contexts[$ue_id] = new UEContext($ue_id);
    }
}

function handleSessionActivity($ue_id, $session, $threshold = 3600) {
    addUEContext($ue_id);
    $ue_contexts[$ue_id]->addSession($session);
    $ue_contexts[$ue_id]->removeInactiveSessions($threshold);
}
?>
