class SensorDataTable:
    def __init__(self):
        self.data_table = {}
        self.lock = threading.Lock()

    def add_sensor(self, device_id, sensor_id):
        with self.lock:
            if device_id not in self.data_table:
                self.data_table[device_id] = []
            self.data_table[device_id].append(sensor_id)

    def remove_sensor(self, device_id, sensor_id):
        with self.lock:
