    va_list args;
    va_start(args, format);
    pthread_mutex_lock(&mutex);
    time_t now = time(NULL);
    fprintf(log_file, "%s ", ctime(&now));
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    fflush(log_file);
    pthread_mutex_unlock(&mutex);
    va_end(args);
}

int initialize_network_entries(int num_entries) {
