void garbage_collection() {
    pthread_mutex_lock(&mutex);
    for (int i = current_entries - 1; i >= 0; i--) {
        if (network_entries[i] != NULL) {
            free(network_entries[i]);
            network_entries[i] = NULL;
        }
    }
    current_entries = 0;
