#include <stdlib.h>
#include <pthread.h>

typedef struct Connection {
    int device_id;
    int health_status;
    // other connection details
} Connection;

typedef struct DeviceProfile {
    int device_id;
    Connection *connection_list;
    size_t connection_count;
    size_t connection_capacity;
    pthread_mutex_t lock;  // Mutex for thread safety
} DeviceProfile;

void initDeviceProfile(DeviceProfile *profile) {
    profile->device_id = -1;
    profile->connection_list = NULL;
    profile->connection_count = 0;
    profile->connection_capacity = 0;
    pthread_mutex_init(&profile->lock, NULL);
}

void freeDeviceProfile(DeviceProfile *profile) {
    pthread_mutex_lock(&profile->lock);
    if (profile->connection_list != NULL) {
        free(profile->connection_list);
        profile->connection_list = NULL;
        profile->connection_count = 0;
        profile->connection_capacity = 0;
    }
    pthread_mutex_unlock(&profile->lock);
    pthread_mutex_destroy(&profile->lock);
}

void addConnection(DeviceProfile *profile, Connection *new_conn) {
    pthread_mutex_lock(&profile->lock);
    if (profile->connection_count == profile->connection_capacity) {
        size_t new_capacity = (profile->connection_capacity == 0) ? 1 : profile->connection_capacity * 2;
        profile->connection_list = realloc(profile->connection_list, sizeof(Connection) * new_capacity);
        profile->connection_capacity = new_capacity;
    }
    profile->connection_list[profile->connection_count++] = *new_conn;
    pthread_mutex_unlock(&profile->lock);
}

void removeInactiveConnections(DeviceProfile *profile, int threshold) {
    pthread_mutex_lock(&profile->lock);
    size_t i = 0, j = 0;
    while (i < profile->connection_count) {
        if (profile->connection_list[i].health_status >= threshold) {
            profile->connection_list[j++] = profile->connection_list[i];
        }
        i++;
    }
    profile->connection_count = j;
    pthread_mutex_unlock(&profile->lock);
}

void updateConnectionStatus(DeviceProfile *profile, int device_id, int new_health) {
    pthread_mutex_lock(&profile->lock);
    for (size_t i = 0; i < profile->connection_count; i++) {
        if (profile->connection_list[i].device_id == device_id) {
            profile->connection_list[i].health_status = new_health;
            break;
        }
    }
    pthread_mutex_unlock(&profile->lock);
}
