void display_usage_info() {
    printf("Usage: program [options] file1 [file2 ...]\n");
    printf("Options:\n");
    printf("  --manpage     Display detailed usage instructions.\n");
    printf("  -cs          Enable case-sensitive line counting.\n");
    printf("  -o output_file Redirect the output to a specified file instead of the console.\n");
}

int main(int argc, char *argv[]) {
    int opt;
    FILE *output = stdout;
    int case_sensitive = 0;

    while ((opt = getopt(argc, argv, "cs:o:")) != -1) {
        switch (opt) {
            case 'c':
                case_sensitive = 1;
                break;
            case 's':
                output = fopen(optarg, "w");
                if (!output) {
                    perror("Error opening output file");
                    return EXIT_FAILURE;
                }
                break;
            case '?':
                if (optopt == 's') {
                    fprintf(stderr, "Option -%c requires an argument.\n", optopt);
                } else if (isprint(optopt)) {
                    fprintf(stderr, "Unknown option `-%c'.\n", optopt);
                } else {
                    fprintf(stderr, "Unknown option character `\\x%x'.\n", optopt);
                }
                display_usage_info();
                return EXIT_FAILURE;
            default:
                abort();
        }
    }

    if (argc - optind < 1) {
        fprintf(stderr, "No input file specified.\n");
        display_usage_info();
        return EXIT_FAILURE;
    }

    for (int i = optind; i < argc; i++) {
        FILE *file = fopen(argv[i], "r");
        if (!file) {
            perror("Error opening file");
            continue;
        }

        char buffer[BUFFER_SIZE];
        while (fgets(buffer, BUFFER_SIZE, file)) {
            // Process each line here
            printf("%s", buffer);
        }

        fclose(file);
    }

    if (output != stdout) {
        fclose(output);
    }

    return EXIT_SUCCESS;
}
