#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Connection {
    int id;
    // Other connection details
} Connection;

typedef struct DeviceProfile {
    int device_id;
    Connection *connection_list;
    int connection_count;
    int max_connections;
    int health_status;
    pthread_mutex_t lock;
} DeviceProfile;

DeviceProfile* createDeviceProfile(int device_id, int initial_capacity) {
    DeviceProfile *profile = (DeviceProfile *)malloc(sizeof(DeviceProfile));
    if (!profile) return NULL;

    profile->device_id = device_id;
    profile->connection_list = (Connection *)calloc(initial_capacity, sizeof(Connection));
    if (!profile->connection_list) {
        free(profile);
        return NULL;
    }

    profile->connection_count = 0;
    profile->max_connections = initial_capacity;
    profile->health_status = 1; // Assuming all devices are initially healthy
    pthread_mutex_init(&profile->lock, NULL);

    return profile;
}

void destroyDeviceProfile(DeviceProfile *profile) {
    if (!profile) return;

    free(profile->connection_list);
    pthread_mutex_destroy(&profile->lock);
    free(profile);
}

void addConnection(DeviceProfile *profile, Connection *new_conn) {
    pthread_mutex_lock(&profile->lock);
    if (profile->connection_count >= profile->max_connections) {
        profile->max_connections *= 2;
        profile->connection_list = (Connection *)realloc(profile->connection_list, sizeof(Connection) * profile->max_connections);
        if (!profile->connection_list) {
            pthread_mutex_unlock(&profile->lock);
            return; // Handle error
        }
    }
    profile->connection_list[profile->connection_count++] = *new_conn;
    pthread_mutex_unlock(&profile->lock);
}

void removeConnection(DeviceProfile *profile, int conn_id) {
    pthread_mutex_lock(&profile->lock);
    for (int i = 0; i < profile->connection_count; i++) {
        if (profile->connection_list[i].id == conn_id) {
            for (int j = i; j < profile->connection_count - 1; j++) {
                profile->connection_list[j] = profile->connection_list[j + 1];
            }
            profile->connection_count--;
            break;
        }
    }
    pthread_mutex_unlock(&profile->lock);
}

void updateConnectionStatus(DeviceProfile *profile, int conn_id, int new_status) {
    pthread_mutex_lock(&profile->lock);
    for (int i = 0; i < profile->connection_count; i++) {
        if (profile->connection_list[i].id == conn_id) {
            profile->connection_list[i].health_status = new_status;
            break;
        }
    }
    pthread_mutex_unlock(&profile->lock);
}

void cleanupInactiveConnections(DeviceProfile *profile, int health_threshold) {
    pthread_mutex_lock(&profile->lock);
    for (int i = 0; i < profile->connection_count;) {
        if (profile->connection_list[i].health_status < health_threshold) {
            for (int j = i; j < profile->connection_count - 1; j++) {
                profile->connection_list[j] = profile->connection_list[j + 1];
            }
            profile->connection_count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&profile->lock);
}
