void DocumentStorage::addDocument(const Document& doc) {
    std::lock_guard<std::mutex> lock(documentsMutex);
    documents[doc.id] = doc;
}

Document* DocumentStorage::getDocument(int id) {
    std::lock_guard<std::mutex> lock(documentsMutex);
    auto it = documents.find(id);
    if (it != documents.end()) return &it->second;
    return nullptr;
}

bool DocumentStorage::updateDocument(int id, const Document& newDoc) {
    std::lock_guard<std::mutex> lock(documentsMutex);
    auto it = documents.find(id);
