#include <stdlib.h>
#include <stdio.h>

#define MAX_ELEMENTS 10000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* array[MAX_ELEMENTS] = {NULL};
int count = 0;

void initialize_crypto() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_256_ecb());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest(EVP_sha256());
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void log_runtime_info() {
    printf("Memory usage: %zu bytes\n", count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    printf("Allocations: %d\n", count);
}

NFAPI_CRC_INDICATION_PDU_T* create_struct() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_memory(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Initialize fields with random values
    pdu->ue_info = rand();
    pdu->rnti = (uint32_t)rand();
    pdu->crc_indication.CRCFLAG = rand() % 2;
    return pdu;
}

void* allocate_elements(void* arg) {
    pthread_mutex_lock(&memory_lock);
    if (count < MAX_ELEMENTS) {
        array[count++] = create_struct();
    }
    pthread_mutex_unlock(&memory_lock);
    return NULL;
}

void simulate_memory_pressure() {
    for (int i = 0; i < count; i++) {
        free(array[i]);
        array[i] = NULL;
    }
    count = 0;
    sleep(1); // Simulate time delay
    for (int i = 0; i < MAX_ELEMENTS / 2; i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, allocate_elements, NULL);
        pthread_join(thread, NULL);
    }
}

void* simulate_failure(void* arg) {
    sleep(5); // Simulate time delay
    exit(EXIT_FAILURE);
}

int main() {
    initialize_crypto();
    pthread_t failure_thread;
    pthread_create(&failure_thread, NULL, simulate_failure, NULL);

    for (int i = 0; i < MAX_ELEMENTS / 2; i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, allocate_elements, NULL);
        pthread_join(thread, NULL);
    }

    simulate_memory_pressure();
    log_runtime_info();

    for (int i = 0; i < count; i++) {
        free(array[i]);
        array[i] = NULL;
    }
    count = 0;

    pthread_join(failure_thread, NULL);
    return 0;
}
