typedef struct NetworkEvent {
    int id;
    time_t timestamp;
    int status;
} NetworkEvent;

typedef struct EventList {
    NetworkEvent *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventList;

void init_event_list(EventList *list, size_t initial_capacity) {
    list->events = (NetworkEvent *)malloc(initial_capacity * sizeof(NetworkEvent));
    if (!list->events) {
        perror("Failed to allocate memory for event list");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

void add_event(EventList *list, int id, int status) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NetworkEvent *new_events = (NetworkEvent *)realloc(list->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            perror("Failed to reallocate memory for event list");
            pthread_mutex_unlock(&list->lock);
            exit(EXIT_FAILURE);
        }
        list->events = new_events;
        list->capacity = new_capacity;
    }
    list->events[list->count].id = id;
    list->events[list->count].timestamp = time(NULL);
    list->events[list->count].status = status;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void clean_old_events(EventList *list, time_t retention_period) {
    pthread_mutex_lock(&list->lock);
    size_t i = 0;
    while (i < list->count && difftime(list->events[i].timestamp, time(NULL)) > retention_period) {
        i++;
    }
    if (i < list->count) {
        memmove(list->events, list->events + i, (list->count - i) * sizeof(NetworkEvent));
        list->count -= i;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_event_list(EventList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->events);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
