#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdio.h>

#define MAX_EVENTS 1000
#define RETENTION_PERIOD 3600 // in seconds

typedef struct {
    int id;
    time_t timestamp;
    int status;
} NetworkEvent;

NetworkEvent events[MAX_EVENTS];
int event_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t last_cleanup_time;

void log_event(int result, const char* operation) {
    if (result == 0) {
        printf("SUCCESS: %s\n", operation);
    } else {
        printf("ERROR: Failed to %s due to memory allocation.\n", operation);
    }
}

int add_network_event(NetworkEvent new_event) {
    pthread_mutex_lock(&lock);

    if (event_count >= MAX_EVENTS) {
        log_event(-1, "add event");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    events[event_count++] = new_event;

    time_t current_time = time(NULL);
    if (current_time - last_cleanup_time > RETENTION_PERIOD) {
        cleanup_old_events();
        last_cleanup_time = current_time;
    }

    log_event(0, "add event");
    pthread_mutex_unlock(&lock);
    return 0;
}

void batch_add_network_events(NetworkEvent* new_events, int count) {
    for (int i = 0; i < count; i++) {
        if (add_network_event(new_events[i]) != 0) {
            printf("WARNING: Failed to add one of the events in the batch.\n");
            break;
        }
    }
}

void cleanup_old_events() {
    time_t current_time = time(NULL);
    int new_count = 0;

    for (int i = 0; i < event_count; i++) {
        if (current_time - events[i].timestamp <= RETENTION_PERIOD) {
            events[new_count++] = events[i];
        }
    }

    memmove(events, events + new_count, sizeof(NetworkEvent) * (event_count - new_count));
    event_count -= new_count;
}

void set_max_events(int max_events) {
    if (max_events > MAX_EVENTS) {
        printf("ERROR: Max events cannot exceed predefined limit.\n");
        return;
    }
    MAX_EVENTS = max_events;
}
