// Define the structure NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

class MemoryManager {
public:
    static MemoryManager& getInstance() {
        static MemoryManager instance;
        return instance;
    }

    NFAPI_CRC_INDICATION_PDU_T* allocate(int N) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (freeList_.empty()) {
            return new NFAPI_CRC_INDICATION_PDU_T[N];
        } else {
            NFAPI_CRC_INDICATION_PDU_T* ptr = freeList_.back();
            freeList_.pop_back();
            for (int i = 0; i < N; ++i) {
                new (&ptr[i]) NFAPI_CRC_INDICATION_PDU_T;
                ptr[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Random assignment
                ptr[i].RNTI = rand() % 256; // Random assignment
                ptr[i].CRC_INDICATION_REL8_TAG = rand() % 1000; // Random assignment
                ptr[i].CRCFLAG = rand() % 2; // Random assignment (0 or 1)
            }
            return ptr;
        }
    }

    void deallocate(NFAPI_CRC_INDICATION_PDU_T* ptr, int N) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (int i = 0; i < N; ++i) {
            ptr[i].~NFAPI_CRC_INDICATION_PDU_T();
        }
        freeList_.push_back(ptr);
    }

private:
    MemoryManager() {}
    ~MemoryManager() {}

    MemoryManager(const MemoryManager&) = delete;
    MemoryManager& operator=(const MemoryManager&) = delete;

    std::mutex mutex_;
    std::vector<NFAPI_CRC_INDICATION_PDU_T*> freeList_;
};

// Example usage
int main() {
    int N = 1000;
    NFAPI_CRC_INDICATION_PDU_T* pduArray = MemoryManager::getInstance().allocate(N);

    // Use the array...

    MemoryManager::getInstance().deallocate(pduArray, N);
    return 0;
}
