#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint8_t header[6];
    // Other MAC_HEADER fields
} MAC_HEADER;

typedef struct {
    uint16_t length;
    // Other MACSDU fields
} MACSDU;

typedef struct {
    MAC_HEADER header;
    int num_sdus;
    MACSDU *sdus;
    // Other MAC_PDU fields
} MAC_PDU;

typedef struct {
    MAC_PDU **pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->pdus = (MAC_PDU**)malloc(initial_capacity * sizeof(MAC_PDU*));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->pdus[i]->sdus);
        free(list->pdus[i]);
    }
    free(list->pdus);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void dynamic_list_add(DynamicList *list, MAC_PDU *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->pdus = (MAC_PDU**)realloc(list->pdus, list->capacity * sizeof(MAC_PDU*));
    }
    list->pdus[list->size++] = pdu;
    pthread_mutex_unlock(&list->mutex);
}

void dynamic_list_sort(DynamicList *list, int (*compare)(const void*, const void*)) {
    pthread_mutex_lock(&list->mutex);
    qsort(list->pdus, list->size, sizeof(MAC_PDU*), compare);
    pthread_mutex_unlock(&list->mutex);
}

int mac_pdu_compare_by_sequence_number(const void *a, const void *b) {
    MAC_PDU **pdu_a = (MAC_PDU**)a;
    MAC_PDU **pdu_b = (MAC_PDU**)b;
    // Assuming sequence number is stored in header
    return ((uint16_t*)((*pdu_a)->header))[0] - ((uint16_t*)((*pdu_b)->header))[0];
}

int mac_pdu_compare_by_sdu_length(const void *a, const void *b) {
    MAC_PDU **pdu_a = (MAC_PDU**)a;
    MAC_PDU **pdu_b = (MAC_PDU**)b;
    // Assuming SDU length is stored in sdus
    return (*pdu_b)->sdus[0].length - (*pdu_a)->sdus[0].length;
}

void dynamic_list_reverse_iterator(DynamicList *list, void (*callback)(MAC_PDU*)) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = list->size; i > 0; --i) {
        callback(list->pdus[i - 1]);
    }
    pthread_mutex_unlock(&list->mutex);
}
