typedef struct PDU_SESSION_CONTEXT {
    int pdu_session_id;
    char guti[20]; // Assuming maximum length of GUTI string is 20 characters
    char snssai[10]; // Assuming maximum length of SNSSAI string is 10 characters
} PDU_SESSION_CONTEXT;

typedef struct MEMORY_POOL {
    size_t pool_size;
    void* pool_memory;
    size_t block_size;
    size_t free_index;
} MEMORY_POOL;

PDU_SESSION_CONTEXT* allocate_pdu_session_context(MEMORY_POOL* pool) {
    if (pool->free_index >= pool->pool_size / pool->block_size) {
        // Resize the memory pool
        size_t new_pool_size = pool->pool_size * 2;
        void* new_pool_memory = realloc(pool->pool_memory, new_pool_size);
        if (!new_pool_memory) {
            return NULL; // Memory allocation failed
        }
        pool->pool_memory = new_pool_memory;
        pool->pool_size = new_pool_size;
    }

    PDU_SESSION_CONTEXT* block = (PDU_SESSION_CONTEXT*)(pool->pool_memory + pool->block_size * pool->free_index);
    pool->free_index++;
    return block;
}

void free_pdu_session_context(MEMORY_POOL* pool, PDU_SESSION_CONTEXT* context) {
    // Implement a way to reuse the block in the memory pool
}

int add_pdu_session_context_to_list(PDU_SESSION_CONTEXT** list, size_t* list_size, size_t max_unique_guti, MEMORY_POOL* pool, int pdu_session_id, const char* guti, const char* snssai) {
    // Check for race conditions and ensure no two consecutive elements have the same GUTI
    if (list_size > 0 && strcmp(list[list_size - 1]->guti, guti) == 0) {
        return -1; // Duplicate GUTI found
    }

    PDU_SESSION_CONTEXT* new_context = allocate_pdu_session_context(pool);
    if (!new_context) {
        return -2; // Memory allocation failed
    }

    new_context->pdu_session_id = pdu_session_id;
    snprintf(new_context->guti, sizeof(new_context->guti), "%s", guti);
    snprintf(new_context->snssai, sizeof(new_context->snssai), "%s", snssai);

    // Check the total number of unique GUTI values
    int unique_guti_count = 0;
    for (size_t i = 0; i < *list_size; i++) {
        if (strcmp(list[i]->guti, guti) != 0) {
            unique_guti_count++;
        }
        if (unique_guti_count > max_unique_guti) {
            free_pdu_session_context(pool, new_context);
            return -3; // Exceeded maximum unique GUTI count
        }
    }

    list[*list_size] = new_context;
    (*list_size)++;
    return 0; // Success
}

void verify_pdu_session_context_list(PDU_SESSION_CONTEXT** list, size_t list_size) {
    for (size_t i = 1; i < list_size; i++) {
        if (strcmp(list[i]->guti, list[i - 1]->guti) == 0) {
            printf("Error: Consecutive elements have the same GUTI\n");
            return;
        }
    }

    int unique_guti_count = 0;
    for (size_t i = 0; i < list_size; i++) {
        if (i > 0 && strcmp(list[i]->guti, list[i - 1]->guti) != 0) {
            unique_guti_count++;
        }
    }

    printf("Total unique GUTI values: %d\n", unique_guti_count);
}

int main() {
    size_t max_unique_guti = 5;
    PDU_SESSION_CONTEXT* list[10];
    size_t list_size = 0;

    MEMORY_POOL pool = {0, NULL, sizeof(PDU_SESSION_CONTEXT), 0};
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Example usage
    if (pthread_mutex_lock(&lock) != 0) {
        perror("Failed to lock mutex");
        return EXIT_FAILURE;
    }

    int result = add_pdu_session_context_to_list(list, &list_size, max_unique_guti, &pool, 1, "GUTI1", "SNSSAI1");
    if (result != 0) {
        printf("Error adding PDU session context: %d\n", result);
    }

    pthread_mutex_unlock(&lock);

    verify_pdu_session_context_list(list, list_size);

    // Free memory
    for (size_t i = 0; i < list_size; i++) {
        free_pdu_session_context(&pool, list[i]);
    }
    free(pool.pool_memory);

    return EXIT_SUCCESS;
}
