#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint32_t pdu_session_id;
    uint64_t guti;
    uint8_t snssai[3];
} PduSessionContext;

typedef struct MemoryPool {
    size_t block_size;
    size_t num_blocks;
    void* blocks;
    void* free_list;
} MemoryPool;

typedef struct {
    PduSessionContext** sessions;
    size_t count;
    size_t capacity;
    MemoryPool pool;
    pthread_mutex_t lock;
} PduSessionManager;

void memory_pool_init(MemoryPool* pool, size_t block_size, size_t num_blocks) {
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = malloc(block_size * num_blocks);
    pool->free_list = NULL;
    for (size_t i = 0; i < num_blocks - 1; ++i) {
        ((void**)pool->blocks)[i] = (void*)((char*)pool->blocks + block_size * (i + 1));
    }
    ((void**)pool->blocks)[num_blocks - 1] = NULL;
}

void* memory_pool_alloc(MemoryPool* pool) {
    void* block = pool->free_list;
    if (block != NULL) {
        pool->free_list = *(void**)block;
    } else {
        // Resize the memory pool
        size_t new_size = pool->num_blocks * 2;
        void* new_blocks = realloc(pool->blocks, pool->block_size * new_size);
        if (new_blocks == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        pool->blocks = new_blocks;
        for (size_t i = pool->num_blocks; i < new_size - 1; ++i) {
            ((void**)pool->blocks)[i] = (void*)((char*)pool->blocks + pool->block_size * (i + 1));
        }
        ((void**)pool->blocks)[new_size - 1] = NULL;
        pool->free_list = (void*)((char*)pool->blocks + pool->block_size * pool->num_blocks);
        pool->num_blocks = new_size;
    }
    return block;
}

void memory_pool_free(MemoryPool* pool, void* block) {
    *(void**)block = pool->free_list;
    pool->free_list = block;
}

PduSessionManager* pdu_session_manager_init(size_t initial_capacity) {
    PduSessionManager* manager = malloc(sizeof(PduSessionManager));
    manager->sessions = memory_pool_alloc(&manager->pool);
    manager->count = 0;
    manager->capacity = initial_capacity;
    memory_pool_init(&manager->pool, sizeof(PduSessionContext), initial_capacity * 2);
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void pdu_session_manager_add(PduSessionManager* manager, PduSessionContext* session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity - 1) {
        // Resize the sessions array
        size_t new_capacity = manager->capacity * 2;
        PduSessionContext** new_sessions = memory_pool_alloc(&manager->pool);
        for (size_t i = 0; i < manager->count; ++i) {
            new_sessions[i] = manager->sessions[i];
        }
        free(manager->sessions);
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }
    if (manager->count > 0 && manager->sessions[manager->count - 1]->guti == session->guti) {
        fprintf(stderr, "GUTI values cannot be consecutive\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    manager->sessions[manager->count++] = memory_pool_alloc(&manager->pool);
    *manager->sessions[manager->count - 1] = *session;
    pthread_mutex_unlock(&manager->lock);
}

void pdu_session_manager_free(PduSessionManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        memory_pool_free(&manager->pool, manager->sessions[i]);
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}
