#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>

#define MAX_GUTI_VALUES 1024
#define MEMORY_POOL_SIZE 4096

typedef struct PDU_Session_Context {
    int pdu_session_id;
    uint64_t guti;
    uint8_t snssai[5];
} PDU_Session_Context;

typedef struct Memory_Pool {
    PDU_Session_Context *pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} Memory_Pool;

Memory_Pool *create_memory_pool(size_t initial_size) {
    Memory_Pool *mp = malloc(sizeof(Memory_Pool));
    mp->pool = malloc(initial_size * sizeof(PDU_Session_Context));
    mp->size = initial_size;
    mp->used = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(Memory_Pool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

PDU_Session_Context *allocate_from_memory_pool(Memory_Pool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used >= mp->size) {
        size_t new_size = mp->size + MEMORY_POOL_SIZE;
        mp->pool = realloc(mp->pool, new_size * sizeof(PDU_Session_Context));
        mp->size = new_size;
    }
    PDU_Session_Context *ctx = &mp->pool[mp->used++];
    pthread_mutex_unlock(&mp->lock);
    return ctx;
}

void validate_pdu_session_list(PDU_Session_Context *list, size_t length) {
    for (size_t i = 1; i < length; ++i) {
        if (list[i].guti == list[i - 1].guti) {
            fprintf(stderr, "Error: Consecutive elements have the same GUTI.\n");
            exit(EXIT_FAILURE);
        }
    }

    uint64_t unique_guti[MAX_GUTI_VALUES] = {0};
    size_t unique_count = 0;
    for (size_t i = 0; i < length; ++i) {
        if (!unique_guti[list[i].guti]) {
            unique_guti[list[i].guti] = 1;
            unique_count++;
        }
    }

    if (unique_count > MAX_GUTI_VALUES) {
        fprintf(stderr, "Error: Number of unique GUTI values exceeds threshold.\n");
        exit(EXIT_FAILURE);
    }
}

void *calculate_md5_hashes(void *arg) {
    char **file_names = arg;
    size_t count = 0;
    while (file_names[count] != NULL) {
        count++;
    }

    for (size_t i = 0; i < count; ++i) {
        FILE *file = fopen(file_names[i], "rb");
        if (!file) {
            fprintf(stderr, "Error opening file %s: %s\n", file_names[i], strerror(errno));
            continue;
        }

        struct stat st;
        if (stat(file_names[i], &st) == -1) {
            fclose(file);
            fprintf(stderr, "Error getting file info for %s: %s\n", file_names[i], strerror(errno));
            continue;
        }

        uint64_t chunk_size = 8192;
        uint8_t *buffer = malloc(chunk_size);
        if (!buffer) {
            fclose(file);
            fprintf(stderr, "Error allocating memory for buffer.\n");
            continue;
        }

        MD5_CTX md5_ctx;
        MD5_Init(&md5_ctx);

        while (size_t bytes_read = fread(buffer, 1, chunk_size, file)) {
            MD5_Update(&md5_ctx, buffer, bytes_read);
        }

        fclose(file);
        free(buffer);

        uint8_t digest[MD5_DIGEST_LENGTH];
        MD5_Final(digest, &md5_ctx);

        printf("File: %s\n", file_names[i]);
        for (size_t j = 0; j < MD5_DIGEST_LENGTH; ++j) {
            printf("%02x", digest[j]);
        }
        printf("\n");
    }

    return NULL;
}

int main() {
    // Example usage of the functions
    Memory_Pool *mp = create_memory_pool(10);

    PDU_Session_Context *ctx1 = allocate_from_memory_pool(mp);
    ctx1->pdu_session_id = 1;
    ctx1->guti = 123456789;
    memcpy(ctx1->snssai, "\x01\x02\x03\x04\x05", 5);

    PDU_Session_Context *ctx2 = allocate_from_memory_pool(mp);
    ctx2->pdu_session_id = 2;
    ctx2->guti = 987654321;
    memcpy(ctx2->snssai, "\x05\x04\x03\x02\x01", 5);

    validate_pdu_session_list(mp->pool, mp->used);

    char *file_names[] = {"file1.txt", "file2.txt", NULL};
    pthread_t thread;
    pthread_create(&thread, NULL, calculate_md5_hashes, file_names);
    pthread_join(thread, NULL);

    destroy_memory_pool(mp);

    return 0;
}
