int processContentDirectoryMultithreaded(const char *directory, int bitrate, int numThreads) {
    DIR *dir;
    struct dirent *ent;
    TranscodingParameters *params = allocateParameters(numThreads);

    if ((dir = opendir(directory)) != NULL) {
        pthread_t threads[numThreads];
        int threadIndex = 0;

        while ((ent = readdir(dir)) != NULL && threadIndex < numThreads) {
            // Check for video files and create parameters
