            params[threadIndex].outputFile = formatOutputFileName(ent->d_name); // Custom function to generate output file name
            params[threadIndex].bitrate = bitrate;
            pthread_create(&threads[threadIndex], NULL, threadFunction, &params[threadIndex]);
            threadIndex++;
        }

        for (int i = 0; i < threadIndex; i++) {
            pthread_join(threads[i], NULL);
        }

        closedir(dir);
    } else {
        freeParameters(params, numThreads);
        return 1; // Directory could not be opened
    }

    freeParameters(params, numThreads);
    return 0;
