void* convert_jpeg_to_pdf(void* arg) {
    ConversionTask *task = (ConversionTask*)arg;
    char command[256];
    snprintf(command, sizeof(command), "convert %s -density 300 -quality %d %s", task->jpeg_path, task->compression_level, task->pdf_path);
    int result = system(command);
    if (result == 0) {
        task->status = 0;
    } else {
        task->status = -1;
    }
    return NULL;
}

int process_directory(char *input_dir, char *output_dir, int compression_level, int cache_size, char *log_file_path) {
    DIR *dir;
    struct dirent *entry;
    pthread_t threads[MAX_THREADS];
    ConversionTask tasks[MAX_THREADS];

    if ((dir = opendir(input_dir)) == NULL) {
        perror("Failed to open directory");
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, ".jpeg") || strstr(entry->d_name, ".jpg")) {
            char jpeg_path[256];
            char pdf_path[256];
            snprintf(jpeg_path, sizeof(jpeg_path), "%s/%s", input_dir, entry->d_name);
            snprintf(pdf_path, sizeof(pdf_path), "%s/%s.pdf", output_dir, entry->d_name);

            int task_index = 0;
            while (task_index < MAX_THREADS && pthread_create(&threads[task_index], NULL, convert_jpeg_to_pdf, &tasks[task_index]) != 0) {
                task_index++;
            }

            if (task_index == MAX_THREADS) {
                for (int i = 0; i < MAX_THREADS; i++) {
                    pthread_join(threads[i], NULL);
                }
            }

            tasks[task_index].jpeg_path = strdup(jpeg_path);
            tasks[task_index].pdf_path = strdup(pdf_path);
            tasks[task_index].compression_level = compression_level;
            tasks[task_index].status = -1;

            while (pthread_create(&threads[task_index], NULL, convert_jpeg_to_pdf, &tasks[task_index]) != 0) {
                task_index++;
            }
        }
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Log results and generate summary report

    closedir(dir);
    return 0;
