void* manage_conversions(void* arg) {
    ConversionTask* task = (ConversionTask*)arg;
    pthread_t threads[MAX_FILES];
    int thread_count = 0;

    DIR* dir = opendir(task->source_dir[0]);
    if (dir == NULL) {
        perror("Failed to open directory");
        return NULL;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char file_path[256];
        snprintf(file_path, sizeof(file_path), "%s/%s", task->source_dir[0], entry->d_name);

        pthread_t thread;
        if (pthread_create(&thread, NULL, process_image, file_path) != 0) {
            perror("Failed to create thread");
            continue;
        }

        threads[thread_count++] = thread;

        // Manage concurrent image processing requests
        if (thread_count >= MAX_FILES) {
            for (int i = 0; i < thread_count; i++) {
                pthread_join(threads[i], NULL);
            }
            thread_count = 0;
        }
    }

    closedir(dir);

    // Join any remaining threads
    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    return NULL;
}

void handle_conversion(ConversionTask* task) {
    if (pthread_t main_thread;
        pthread_create(&main_thread, NULL, manage_conversions, task) != 0) {
            perror("Failed to create main thread");
            return;
        }

    // Manage graceful shutdown and resource cleanup
    pthread_join(main_thread, NULL);
}

int main(int argc, char* argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s source_dir output_dir compression_level\n", argv[0]);
        return EXIT_FAILURE;
    }

    ConversionTask task = {argv[1], argv[2], atoi(argv[3])};

    handle_conversion(&task);

    return EXIT_SUCCESS;
}
