typedef struct pdu_session_context {
    uint32_t pdu_session_id;
    uint64_t guti;
    uint8_t snssai[5];
} PduSessionContext;

typedef struct mem_pool {
    void *pool;
    size_t pool_size;
    size_t used_size;
    pthread_mutex_t mutex;
} MemPool;

MemPool pdu_context_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};
PduSessionContext *pdu_session_list[MAX_GUTI_VALUES];
size_t list_size = 0;

void* mem_pool_alloc(size_t size) {
    pthread_mutex_lock(&pdu_context_pool.mutex);
    if (pdu_context_pool.pool == NULL || pdu_context_pool.used_size + size > pdu_context_pool.pool_size) {
        size_t new_size = pdu_context_pool.pool_size + MEM_POOL_SIZE;
        while (new_size < pdu_context_pool.used_size + size)
            new_size += MEM_POOL_SIZE;

        void *new_pool = realloc(pdu_context_pool.pool, new_size);
        if (new_pool == NULL) {
            pthread_mutex_unlock(&pdu_context_pool.mutex);
            return NULL;
        }

        pdu_context_pool.pool = new_pool;
        pdu_context_pool.pool_size = new_size;
    }

    void *ptr = (char *)pdu_context_pool.pool + pdu_context_pool.used_size;
    pdu_context_pool.used_size += size;
    pthread_mutex_unlock(&pdu_context_pool.mutex);
    return ptr;
}

PduSessionContext* create_pdu_session_context(uint32_t pdu_session_id, uint64_t guti, const uint8_t *snssai) {
    PduSessionContext *ctx = (PduSessionContext *)mem_pool_alloc(sizeof(PduSessionContext));
    if (ctx == NULL)
        return NULL;

    ctx->pdu_session_id = pdu_session_id;
    ctx->guti = guti;
    memcpy(ctx->snssai, snssai, 5);

    return ctx;
}

int add_pdu_session_context(uint32_t pdu_session_id, uint64_t guti, const uint8_t *snssai) {
    if (list_size >= MAX_GUTI_VALUES)
        return -1;

    for (size_t i = list_size - 1; i > 0; i--) {
        if (pdu_session_list[i]->guti == guti)
            return -2;
    }

    PduSessionContext *ctx = create_pdu_session_context(pdu_session_id, guti, snssai);
    if (ctx == NULL)
        return -3;

    pdu_session_list[list_size++] = ctx;
    return 0;
}

void free_pdu_session_context() {
    for (size_t i = 0; i < list_size; i++)
        free(pdu_session_list[i]);
    list_size = 0;
}

char* calculate_md5(const char *filename, size_t chunk_size) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL)
        return NULL;

    MD5_CTX md5;
    MD5_Init(&md5);

    char buffer[chunk_size];
    while (size_t bytes_read = fread(buffer, 1, chunk_size, file)) {
        MD5_Update(&md5, buffer, bytes_read);
    }

    fclose(file);

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &md5);

    static char hexdigest[2 * MD5_DIGEST_LENGTH + 1];
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++)
        sprintf(hexdigest + i * 2, "%02x", digest[i]);

    return hexdigest;
}

int process_directory(const char *directory, size_t timeout) {
    DIR *dir = opendir(directory);
    if (dir == NULL)
        return -1;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        const char *filename = entry->d_name;
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0)
            continue;

        char path[256];
        snprintf(path, sizeof(path), "%s/%s", directory, filename);

        struct stat file_stat;
        if (stat(path, &file_stat) != 0)
            continue;

        if ((file_stat.st_mode & S_IFMT) == S_IFREG) {
            if (timeout > 0) {
                time_t start = time(NULL);
                while (time(NULL) - start < timeout) {
                    char *hexdigest = calculate_md5(path, 4096);
                    if (hexdigest != NULL) {
                        printf("File: %s, MD5: %s\n", filename, hexdigest);
                        free(hexdigest);
                        break;
                    }
                }
            } else {
                char *hexdigest = calculate_md5(path, 4096);
                if (hexdigest != NULL) {
                    printf("File: %s, MD5: %s\n", filename, hexdigest);
                    free(hexdigest);
                }
            }
        }
    }

    closedir(dir);
    return 0;
}

int main() {
    // Example usage of the functions
    add_pdu_session_context(1, 0x123456789ABCDEF0, (uint8_t *)"Slice1");
    add_pdu_session_context(2, 0x0987654321FEDCBA, (uint8_t *)"Slice2");

    process_directory(".", -1);

    free_pdu_session_context();
    return 0;
}
```

