```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE_LENGTH 1024
#define MAX_WORDS 1000

typedef struct {
    char **words;
    int count;
} WordList;

void processFile(const char *filename, bool compressed) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    // Memory-mapped file implementation here...

    char line[MAX_LINE_LENGTH];
    WordList wordList;
    wordList.words = (char **)malloc(MAX_WORDS * sizeof(char *));
    wordList.count = 0;

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        char *token = strtok(strtok(line, "\n"), " .,-!?;:()[]{}");
        while (token) {
            if (!strchr(token, '\0')) {
                token[0] = tolower(token[0]);
                wordList.words[wordList.count++] = strdup(token);
            }
            token = strtok(NULL, " .,-!?;:()[]{}");
        }
    }

    qsort(wordList.words, wordList.count, sizeof(char *), strcmp);

    for (int i = 0; i < wordList.count; i++) {
        printf("%s\n", wordList.words[i]);
    }

    // Free memory...
    fclose(file);
}

void printUsage() {
    printf("Usage: ./text_processor [options] <filename>\n");
    printf("Options:\n");
    printf("  -c, --compressed   Process compressed files\n");
    printf("  -h, --help         Show this help message\n");
    printf("  -o, --output       Specify output format (plain/text)\n");
}

int main(int argc, char *argv[]) {
    bool compressed = false;
    const char *filename = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0 || strcmp(argv[i], "--compressed") == 0) {
            compressed = true;
        } else if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            printUsage();
            return 1;
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            // Handle output format option...
        } else {
            filename = argv[i];
        }
    }

    if (!filename) {
        printUsage();
        return 1;
    }

    processFile(filename, compressed);

    return 0;
}
