#include <string.h>
#include <pthread.h>
#include <openssl/md5.h>

#define MAX_GUTI_VALUES 1024
#define INITIAL_POOL_SIZE 32
#define POOL_GROWTH_RATE 1.5
#define MAX_FILE_PATH_LENGTH 1024

typedef struct PDU_Session_Context {
    uint64_t pdu_session_id;
    char guti[18]; // Format: MNC-MCC-RAI-PCI
    char snssai[32];
} PDU_Session_Context;

typedef struct Memory_Pool {
    PDU_Session_Context *blocks;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} Memory_Pool;

Memory_Pool *memory_pool_init() {
    Memory_Pool *pool = (Memory_Pool *)malloc(sizeof(Memory_Pool));
    if (!pool) return NULL;

    pool->blocks = (PDU_Session_Context *)malloc(INITIAL_POOL_SIZE * sizeof(PDU_Session_Context));
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    pool->allocated_size = INITIAL_POOL_SIZE;
    pool->used_size = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void memory_pool_free(Memory_Pool *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->blocks);
    pthread_mutex_unlock(&pool->lock);
    free(pool);
}

PDU_Session_Context *memory_pool_alloc(Memory_Pool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_size == pool->allocated_size) {
        size_t new_size = (size_t)(pool->allocated_size * POOL_GROWTH_RATE);
        PDU_Session_Context *new_blocks = realloc(pool->blocks, new_size * sizeof(PDU_Session_Context));

        if (!new_blocks) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }

        pool->blocks = new_blocks;
        pool->allocated_size = new_size;
    }

    PDU_Session_Context *block = &pool->blocks[pool->used_size++];
    pthread_mutex_unlock(&pool->lock);

    return block;
}

void calculate_md5(const char *filename, unsigned char digest[MD5_DIGEST_LENGTH]) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s\n", filename);
        return;
    }

    unsigned char buffer[1024];
    size_t bytes_read;
    MD5_CTX md5;
    MD5_Init(&md5);

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
        MD5_Update(&md5, buffer, bytes_read);
    }

    fclose(fp);
    MD5_Final(digest, &md5);
}

char *file_to_hexdigest(const char *filename) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    calculate_md5(filename, digest);

    char *hexdigest = (char *)malloc((2 * MD5_DIGEST_LENGTH + 1) * sizeof(char));
    if (!hexdigest) return NULL;

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&hexdigest[i * 2], "%02x", digest[i]);
    }

    hexdigest[2 * MD5_DIGEST_LENGTH] = '\0';
    return hexdigest;
}

void process_files_in_directory(const char *directory, int max_guti_values, Memory_Pool *pool) {
