    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_pdu_session(PduSessionList *list, PduSessionContext *session) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->session_count; i++) {
        if (!strcmp(session->guti, list->sessions[i]->guti)) {
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    if (list->unique_guti_count >= MAX_UNIQUE_GUTIs) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->unique_snssai_count >= MAX_UNIQUE_SNSSAIs) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    list->sessions[list->session_count++] = session;
    list->unique_guti_count++;
    list->unique_snssai_count++;
    pthread_mutex_unlock(&list->lock);
}

