#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_GUTI 1000
#define MAX_SNSSAI 50

typedef struct {
    uint64_t pdu_session_id;
    uint64_t guti;
    char snssai[MAX_SNSSAI];
} PDU_Session_Context;

typedef struct Node {
    PDU_Session_Context data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int unique_guti_count;
    int unique_snssai_count;
    bool is_active;
} PDU_Session_List;

PDU_Session_List* create_pdu_session_list() {
    PDU_Session_List* list = (PDU_Session_List*)malloc(sizeof(PDU_Session_List));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->unique_guti_count = 0;
    list->unique_snssai_count = 0;
    list->is_active = true;
    return list;
}

void destroy_pdu_session_list(PDU_Session_List* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool add_pdu_session(PDU_Session_List* list, PDU_Session_Context new_context) {
    if (!list || !new_context.pdu_session_id || !new_context.guti || strlen(new_context.snssai) >= MAX_SNSSAI) return false;

    pthread_mutex_lock(&list->lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    newNode->data = new_context;
    newNode->next = NULL;

    if (!list->head) {
        list->head = list->tail = newNode;
    } else {
        if (list->tail->data.guti == new_context.guti || list->unique_guti_count >= MAX_GUTI) {
            free(newNode);
            pthread_mutex_unlock(&list->lock);
            return false;
        }

        bool snssai_exists = false;
        Node* temp = list->head;
        while (temp) {
            if (strcmp(temp->data.snssai, new_context.snssai) == 0) {
                snssai_exists = true;
                break;
            }
            temp = temp->next;
        }

        if (snssai_exists || list->unique_snssai_count >= MAX_SNSSAI) {
            free(newNode);
            pthread_mutex_unlock(&list->lock);
            return false;
        }

        list->tail->next = newNode;
        list->tail = newNode;

        list->unique_guti_count++;
        if (!snssai_exists) list->unique_snssai_count++;
    }

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool verify_pdu_session_list(PDU_Session_List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    uint64_t last_guti = 0;

    while (current) {
        if (current->data.guti == last_guti || current->next && current->data.guti == current->next->data.guti) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        last_guti = current->data.guti;
        current = current->next;
    }

    if (list->unique_guti_count > MAX_GUTI || list->unique_snssai_count > MAX_SNSSAI) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    pthread_mutex_unlock(&list->lock);
    return true;
}
