typedef struct {
    unsigned int SEQUENCE_NUMBER;
    int TRANSMIT_POWER;
    unsigned int MODULATION_AND_CODING_SCHEME;
} TX_MESSAGE_PDU_T;

TX_MESSAGE_PDU_T* allocate_memory_for_pdu(unsigned int M, int power_range_start, int power_range_end) {
    if (M == 0 || power_range_start > power_range_end) {
        return NULL; // Invalid input
    }

    TX_MESSAGE_PDU_T* pdus = (TX_MESSAGE_PDU_T*)malloc(M * sizeof(TX_MESSAGE_PDU_T));
    if (pdus == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (unsigned int i = 0; i < M; i++) {
        pdus[i].SEQUENCE_NUMBER = SEQUENCE_NUMBER_DEFAULT;
        pdus[i].TRANSMIT_POWER = rand() % (power_range_end - power_range_start + 1) + power_range_start;
        pdus[i].MODULATION_AND_CODING_SCHEME = MODULATION_AND_CODING_SCHEME_DEFAULT;
    }

    return pdus;
}

void free_memory_for_pdu(TX_MESSAGE_PDU_T* pdus, unsigned int M) {
    if (pdus != NULL) {
        free(pdus);
    }
}

int main() {
    unsigned int M = 1000; // Example input size
    int power_range_start = -10;
    int power_range_end = 10;

    TX_MESSAGE_PDU_T* pdus = allocate_memory_for_pdu(M, power_range_start, power_range_end);
    if (pdus != NULL) {
        // Process the PDUs here
        free_memory_for_pdu(pdus, M);
    }

    return 0;
}
