using System;
using System.Collections.Concurrent;
using System.Linq;

public class ContentManager : IDisposable
{
    private readonly ConcurrentDictionary<string, object> _cache = new ConcurrentDictionary<string, object>();
    private readonly Random _random = new Random();

    public void GenerateContent(string contentType, int minRange, int maxRange)
    {
        lock (_cache)
        {
            if (!_cache.ContainsKey(contentType))
            {
                var value = _random.Next(minRange, maxRange);
                _cache[contentType] = value;
            }
        }
    }

    public T RetrieveContent<T>(string contentType) where T : IConvertible
    {
        if (_cache.TryGetValue(contentType, out var content))
        {
            return (T)Convert.ChangeType(content, typeof(T));
        }
        throw new ArgumentException("Invalid content type");
    }

    public void Dispose()
    {
        _cache.Clear();
    }
}
```

