import hashlib
import requests
from concurrent.futures import ThreadPoolExecutor
from tqdm import tqdm

class FileHasher:
    def __init__(self, algorithms=['md5', 'sha256'], chunk_size=1024*1024):
        self.algorithms = algorithms
        self.chunk_size = chunk_size
        self.executor = ThreadPoolExecutor(max_workers=5)

    def hash_file(self, file_path, url=False, metadata_service=None, validate_checksum=True, cache_metadata=True):
        if url:
            response = requests.get(file_path)
            file_data = response.content
        else:
            with open(file_path, 'rb') as f:
                file_data = f.read()

        if cache_metadata and metadata_service:
            file_attributes = self.fetch_file_attributes(file_path, metadata_service)
        else:
            file_attributes = None

        results = {}
        futures = {self.executor.submit(self._hash_chunk, data, alg): alg for alg in self.algorithms}

        with tqdm(total=len(self.algorithms)) as pbar:
            for future in tqdm(concurrent.futures.as_completed(futures), total=len(self.algorithms)):
                algorithm = futures[future]
                try:
                    hash_value = future.result()
                    results[algorithm] = hash_value
                except Exception as e:
                    print(f"Error hashing file: {e}")
                pbar.update(1)

        if url and metadata_service and validate_checksum and file_attributes.get('checksum'):
            expected_checksum = file_attributes['checksum']
            for alg, hash_value in results.items():
                if hash_value != expected_checksum:
                    raise ValueError(f"Checksum mismatch for algorithm {alg}")

        return results

    def _hash_chunk(self, data, algorithm):
        hasher = hashlib.new(algorithm)
        for i in range(0, len(data), self.chunk_size):
            chunk = data[i:i + self.chunk_size]
            hasher.update(chunk)
        return hasher.hexdigest()

    def fetch_file_attributes(self, file_path, metadata_service):
        # Simulated metadata fetch with retry logic
        for _ in range(3):
            try:
                response = requests.get(f"{metadata_service}/{file_path}")
                response.raise_for_status()
                return response.json()
            except requests.RequestException as e:
                print(f"Failed to fetch metadata: {e}. Retrying...")
        raise Exception("Failed to fetch file attributes after multiple attempts")

# Example usage
hasher = FileHasher(algorithms=['md5', 'sha256'], chunk_size=10*1024*1024)
results = hasher.hash_file('path/to/large/file', url=False, metadata_service='http://metadata-service.com')
print(results)
