            'retry_limit': 3,
        }

class MetadataService:
    def fetch_metadata(self, file_path):
        try:
            response = requests.get(file_path)
            response.raise_for_status()
            return response.json()
        except requests.RequestException as e:
            print(f"Failed to fetch metadata: {e}")
            return None

class FileHasher:
    @staticmethod
    def hash_file(file_path, algorithm='MD5', chunk_size=1024 * 1024):
        hasher = hashlib.new(algorithm)
        with open(file_path, 'rb') as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                hasher.update(data)
        return hasher.hexdigest()

class FileProcessor:
    def __init__(self, config):
        self.config = config
        self.metadata_service = MetadataService()
        self.executor = ThreadPoolExecutor(max_workers=5)

    def process_file(self, file_path):
        metadata = self.metadata_service.fetch_metadata(file_path)
        if not metadata:
            return

        chunk_size = self.config['chunk_size']
        algorithm = self.config['hash_algorithm']

        try:
            hash_value = FileHasher.hash_file(file_path, algorithm, chunk_size)
            print(f"Processed {file_path}: {hash_value}")
        except Exception as e:
            print(f"Failed to process {file_path}: {e}")

    def process_files_concurrently(self, file_paths):
        futures = {self.executor.submit(self.process_file, path): path for path in file_paths}
        for future in as_completed(futures):
            file_path = futures[future]
            try:
                result = future.result()
            except Exception as e:
                print(f"Error processing {file_path}: {e}")

if __name__ == "__main__":
    config = ConfigLoader.load_config('config.xml')
    processor = FileProcessor(config)
    files_to_process = ['path/to/file1.txt', 'path/to/file2.bin']
    processor.process_files_concurrently(files_to_process)
