    private Dictionary<string, List<int>> contentTypes = new Dictionary<string, List<int>>();
    private Random random = new Random();
    private ILogger logger;

    public ContentGenerator(ILogger logger)
    {
        this.logger = logger;
    }

    public void AddContentType(string contentType, int rangeStart, int rangeEnd, bool isExclusive)
    {
        if (!contentTypes.ContainsKey(contentType))
        {
            contentTypes[contentType] = new List<int>();
        }
        for (int i = rangeStart; isExclusive ? i < rangeEnd : i <= rangeEnd; i++)
        {
            contentTypes[contentType].Add(i);
        }
    }

    public int GenerateRandomValue(string contentType, bool isInclusive)
    {
        if (!contentTypes.ContainsKey(contentType) || !contentTypes[contentType].Any())
        {
            throw new ArgumentException("Invalid or empty content type");
        }

        int value;
        do
        {
            value = random.Next(contentTypes[contentType].Min(), contentTypes[contentType].Max() + 1);
        } while (!isInclusive && contentTypes[contentType].Contains(value));

        logger.Log($"Generated {value} for {contentType}");
        return value;
    }

    public void UpdateFSAStates(int[] states, int numStates, FSA fsa, int lastStateIndex)
    {
        try
        {
            var newStateList = new List<int>(numStates);
            Array.Copy(states, newStateList.ToArray(), numStates);

            if (lastStateIndex >= 0 && lastStateIndex < fsa.States.Length - 1)
            {
                fsa.States[lastStateIndex].Next = newStateList;
            }
        }
        catch (OutOfMemoryException)
        {
            logger.Log("Failed to allocate memory for new state list", LogLevel.Error);
        }
    }

    public void ProcessText(string text, Dictionary<string, string> regexPatterns)
    {
        foreach (var pattern in regexPatterns)
        {
            var matches = Regex.Matches(text, pattern.Value);
            foreach (Match match in matches)
            {
                logger.Log($"Found {match.Value} in category: {pattern.Key}");
            }
        }
    }

    public void SwitchLanguage(string language)
    {
        // Implement logic to switch between English and Hebrew regex patterns and FSA states
    }
}

public interface ILogger
{
    void Log(string message, LogLevel level = LogLevel.Info);
}

public enum LogLevel
{
    Info,
    Warning,
    Error
}

public class ConsoleLogger : ILogger
{
    public void Log(string message, LogLevel level)
    {
        string logPrefix = $"[{DateTime.Now}] [{level}]: ";
        switch (level)
        {
            case LogLevel.Warning:
                Console.ForegroundColor = ConsoleColor.Yellow;
                break;
            case LogLevel.Error:
                Console.ForegroundColor = ConsoleColor.Red;
                break;
        }
        Console.WriteLine(logPrefix + message);
        Console.ResetColor();
    }
}

