public class DynamicValueGenerator
{
    private ConcurrentDictionary<int, (float? minInclusive, float? maxExclusive)> floatRanges = new();
    private ConcurrentDictionary<long, (int? minInclusive, int? maxExclusive)> intRanges = new();

    public void SetFloatRange(int key, float? minInclusive, float? maxExclusive)
    {
        if (!minInclusive.HasValue && !maxExclusive.HasValue)
            throw new ArgumentException("At least one bound must be specified.");

        floatRanges[key] = (minInclusive, maxExclusive);
    }

    public void SetIntRange(long key, int? minInclusive, int? maxExclusive)
    {
        if (!minInclusive.HasValue && !maxExclusive.HasValue)
            throw new ArgumentException("At least one bound must be specified.");

        intRanges[key] = (minInclusive, maxExclusive);
    }

    public float GenerateFloat(int key)
    {
        var range = GetRange<float>(key, floatRanges);
        return GenerateValue(range.minInclusive, range.maxExclusive, GenerateRandomFloat);
    }

    public int GenerateInt(long key)
    {
        var range = GetRange<int>(key, intRanges);
        return GenerateValue(range.minInclusive, range.maxExclusive, GenerateRandomInt);
    }

    private T GenerateValue<T>(T? min, T? max, Func<T> valueGenerator)
    {
        while (true)
        {
            try
            {
                var value = valueGenerator();
                if ((min == null || value.CompareTo(min.Value) >= 0) &&
                    (max == null || value.CompareTo(max.Value) < 0))
                {
                    return value;
                }
            }
            catch (Exception ex)
            {
                LogError(ex);
            }
        }
    }

    private T GetRange<T>(long key, ConcurrentDictionary<long, (T? minInclusive, T? maxExclusive)> ranges)
    {
        if (!ranges.TryGetValue(key, out var range))
            throw new ArgumentException("Invalid key.");

        return range;
    }

    private float GenerateRandomFloat()
    {
        return (float)new Random().NextDouble();
    }

    private int GenerateRandomInt()
    {
        return new Random().Next();
    }

    private void LogError(Exception ex)
    {
        // Implement logging to external service with error handling and retries
    }
}
