using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private readonly ConcurrentDictionary<string, (float? min, float? max, bool isExclusive)> _rangeCache = new();
    private readonly ILoggerService _loggerService;

    public DynamicValueGenerator(ILoggerService loggerService)
    {
        _loggerService = loggerService;
    }

    public void SetRange(string key, float? min, float? max, bool isExclusive = false)
    {
        _rangeCache[key] = (min, max, isExclusive);
    }

    public float GetRandomFloat(string key)
    {
        if (!_rangeCache.TryGetValue(key, out var range))
        {
            throw new ArgumentException("Range not set", nameof(key));
        }

        return GenerateRandomValue(range.min, range.max, range.isExclusive);
    }

    private static float GenerateRandomValue(float? min, float? max, bool isExclusive)
    {
        var random = new Random();
        if (min.HasValue && max.HasValue)
        {
            if (isExclusive)
            {
                while (true)
                {
                    var value = random.NextSingle(min.Value, max.Value);
                    if (!value.Equals(min) && !value.Equals(max))
                    {
                        return value;
                    }
                }
            }
            else
            {
                return random.NextSingle(min.Value, max.Value);
            }
        }
        throw new ArgumentException("Invalid range", nameof(min));
    }

    public void LogValue(string key, float value)
    {
        _loggerService.Log(key, value);
    }
}

public interface ILoggerService
{
    void Log(string key, float value);
}

public class ExternalLoggerService : ILoggerService
{
    private readonly ConcurrentQueue<(string key, float value)> _queue = new();
    private readonly Task _workerTask;
    private readonly CancellationTokenSource _cancellationTokenSource;

    public ExternalLoggerService()
    {
        _cancellationTokenSource = new CancellationTokenSource();
        _workerTask = Task.Run(() => Worker(_cancellationTokenSource.Token));
    }

    public void Log(string key, float value)
    {
        _queue.Enqueue((key, value));
    }

    private async Task Worker(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            if (_queue.TryDequeue(out var item))
            {
                try
                {
                    // Simulate external logging service call with rate limits and latency
                    await Task.Delay(100); // Simulated delay
                }
                catch (Exception ex)
                {
                    // Handle logging failures gracefully, e.g., retry or log error
                    Console.WriteLine($"Logging failed: {ex.Message}");
                }
            }
        }
    }

    public void Dispose()
    {
        _cancellationTokenSource.Cancel();
        _workerTask.Wait();
    }
}

// Usage example:
public class Program
{
    public static async Task Main(string[] args)
    {
        var logger = new ExternalLoggerService();
        using (var generator = new DynamicValueGenerator(logger))
        {
            generator.SetRange("FloatRange", 0.0f, 1.0f);
            for (int i = 0; i < 100; i++)
            {
                float value = generator.GetRandomFloat("FloatRange");
                generator.LogValue("FloatRange", value);
            }
        }
    }
}
```

