        fprintf(stderr, "Error on line %d: %s\n", error.line, error.text);
        return 0;
    }

    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");
    json_t *refresh_token = json_object_get(root, "refresh_token");

    if (!json_is_string(access_token) ||
        !json_is_integer(expires_in) ||
        !json_is_string(token_type)) {
        fprintf(stderr, "Invalid JSON format\n");
        json_decref(root);
        return 0;
    }

    int expires_int = json_integer_value(expires_in);
    if (expires_int <= 0) {
        fprintf(stderr, "Expires_in must be a positive integer\n");
        json_decref(root);
        return 0;
    }

    const char *token_type_str = json_string_value(token_type);
    if (strcmp(token_type_str, "Bearer") != 0) {
        fprintf(stderr, "Token type must be 'Bearer'\n");
        json_decref(root);
        return 0;
    }

    if (refresh_token && !json_is_string(refresh_token)) {
        fprintf(stderr, "Refresh token must be a string\n");
        json_decref(root);
        return 0;
