// Memory pool for reuse
PDUSessionContext* memory_pool = NULL;
int pool_size = 0;
int pool_index = 0;

// Lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the memory pool
void init_memory_pool(int size) {
    pool_size = size;
    memory_pool = (PDUSessionContext*)malloc(size * sizeof(PDUSessionContext));
}

// Function to free the memory pool
void free_memory_pool() {
    free(memory_pool);
    memory_pool = NULL;
    pool_size = 0;
    pool_index = 0;
}

// Thread-safe function to allocate a PDU session context from the memory pool
PDUSessionContext* alloc_pdu_session_context() {
    pthread_mutex_lock(&lock);
    if (pool_index >= pool_size) {
        // Handle error or resize pool
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    PDUSessionContext* ctx = &memory_pool[pool_index++];
    pthread_mutex_unlock(&lock);
    return ctx;
}

// Thread-safe function to free a PDU session context back to the memory pool
void free_pdu_session_context(PDUSessionContext* ctx) {
    pthread_mutex_lock(&lock);
    if (ctx >= memory_pool && ctx < &memory_pool[pool_size]) {
        // Mark as free or reset for reuse
        ctx->pdu_session_id = 0;
        ctx->guti = 0;
        memset(ctx->snssai, 0, sizeof(ctx->snssai));
    }
    pthread_mutex_unlock(&lock);
}

// Function to add a new PDU session context to the list
void add_pdu_session_context(uint16_t pdu_session_id, uint64_t guti, uint8_t* snssai) {
    PDUSessionContext* ctx = alloc_pdu_session_context();
    if (ctx == NULL) return; // Handle error

    ctx->pdu_session_id = pdu_session_id;
    ctx->guti = guti;
    memcpy(ctx->snssai, snssai, sizeof(ctx->snssai));
