#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_CONTEXTS 1000
#define INACTIVITY_THRESHOLD 3600 // seconds

typedef struct {
    int ue_id;
    char session_list[10][256];
    time_t last_update;
} UEContext;

UEContext* ue_contexts[MAX_UE_CONTEXTS];
int ue_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_session(int ue_id, const char* session) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < ue_count; i++) {
        if (ue_contexts[i]->ue_id == ue_id) {
            snprintf(ue_contexts[i]->session_list[ue_contexts[i]->last_update % 10], sizeof(session), "%s", session);
            ue_contexts[i]->last_update = time(NULL);
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    if (ue_count < MAX_UE_CONTEXTS) {
        UEContext* new_context = malloc(sizeof(UEContext));
        new_context->ue_id = ue_id;
        snprintf(new_context->session_list[new_context->last_update % 10], sizeof(session), "%s", session);
        new_context->last_update = time(NULL);
        ue_contexts[ue_count++] = new_context;
    }
    pthread_mutex_unlock(&mutex);
}

void remove_inactive_sessions(int threshold) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < ue_count; ) {
        if ((time(NULL) - ue_contexts[i]->last_update) > threshold) {
            free(ue_contexts[i]);
            memmove(&ue_contexts[i], &ue_contexts[i+1], --ue_count * sizeof(UEContext*));
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void* sync_with_database(void* arg) {
    while (1) {
        remove_inactive_sessions(INACTIVITY_THRESHOLD);
        sleep(60); // synchronize every minute
    }
}

int main(int argc, char** argv) {
    if (argc < 2) {
        printf("Usage: %s input_file\n", argv[0]);
        return 1;
    }

    pthread_t sync_thread;
    pthread_create(&sync_thread, NULL, sync_with_database, NULL);

    FILE* file = fopen(argv[1], "r");
    if (!file) {
        perror("Failed to open file");
        return 1;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Process each line
        printf("%s", line);
    }

    fclose(file);
    pthread_join(sync_thread, NULL);

    for (int i = 0; i < ue_count; i++) {
        free(ue_contexts[i]);
    }

    return 0;
}
