    private ConcurrentDictionary<string, (float min, float max)> floatRanges = new();
    private ConcurrentDictionary<string, (int min, int max)> intRanges = new();
    private ILogger logger;
    private object lockObject = new();

    public void SetFloatRange(string key, float min, float max)
    {
        lock (lockObject)
        {
            if (min > max)
                throw new ArgumentException("Invalid range");
            floatRanges[key] = (min, max);
        }
    }

    public void SetIntRange(string key, int min, int max)
    {
        lock (lockObject)
        {
            if (min > max)
                throw new ArgumentException("Invalid range");
            intRanges[key] = (min, max);
        }
    }

    public float GenerateRandomFloat(string key)
    {
        var range = floatRanges.GetOrAdd(key, k => (0.0f, 1.0f));
        return (float)Random.NextDouble() * (range.max - range.min) + range.min;
    }

    public int GenerateRandomInt(string key)
    {
        var range = intRanges.GetOrAdd(key, k => (0, 1));
        return Random.Next(range.min, range.max);
    }
}

