using System;
using System.Collections.Concurrent;
using System.Diagnostics;

public class RandomValueGenerator
{
    private ConcurrentDictionary<string, (float min, float max, bool isExclusive)> _ranges = new();
    private readonly ConcurrentQueue<(string rangeKey, object value)> _logQueue = new();
    private readonly IExternalLoggingService _loggingService;
    private readonly Random _random = new();

    public RandomValueGenerator(IExternalLoggingService loggingService)
    {
        _loggingService = loggingService ?? throw new ArgumentNullException(nameof(loggingService));
    }

    public void AddRange(string rangeKey, float min, float max, bool isExclusive = false)
    {
        if (string.IsNullOrEmpty(rangeKey)) throw new ArgumentException("Range key cannot be null or empty", nameof(rangeKey));
        if (!isExclusive && max < min) throw new ArgumentException("Max must be greater than or equal to min when not exclusive");
        if (isExclusive && max <= min) throw new ArgumentException("Max must be greater than min when exclusive");

        _ranges[rangeKey] = (min, max, isExclusive);
    }

    public float GenerateRandomFloat(string rangeKey)
    {
        if (!_ranges.TryGetValue(rangeKey, out var range)) throw new KeyNotFoundException($"Range '{rangeKey}' not found");
        return GenerateRandomValue(range.min, range.max, range.isExclusive, typeof(float));
    }

    public int GenerateRandomInt(string rangeKey)
    {
        if (!_ranges.TryGetValue(rangeKey, out var range)) throw new KeyNotFoundException($"Range '{rangeKey}' not found");
        return (int)GenerateRandomValue(range.min, range.max, range.isExclusive, typeof(int));
    }

    private object GenerateRandomValue(float min, float max, bool isExclusive, Type valueType)
    {
        while (true)
        {
            var value = isExclusive ? _random.NextSingle() * (max - min) + min : _random.Next(min, (int)(max + 1));

            if (valueType == typeof(float))
            {
                return (float)value;
            }
            else if (valueType == typeof(int))
            {
                return (int)value;
            }

            // Should never reach here
            Debug.Assert(false, "Unsupported type for random value generation");
        }
    }

    public void LogValue(string rangeKey, object value)
    {
        _logQueue.Enqueue((rangeKey, value));
        ProcessLogQueue();
    }

    private async void ProcessLogQueue()
    {
        while (_logQueue.Count > 0 && await _loggingService.IsReadyAsync())
        {
            var (rangeKey, value) = _logQueue.Dequeue();
            try
            {
                await _loggingService.LogAsync(rangeKey, value);
            }
            catch (Exception ex)
            {
                // Handle logging failure gracefully
                Console.Error.WriteLine($"Failed to log value: {ex}");
            }
        }
    }
}

public interface IExternalLoggingService
{
    Task<bool> IsReadyAsync();
    Task LogAsync(string rangeKey, object value);
}
