using System;
using System.Collections.Concurrent;
using System.Linq;

public class DataGenerator
{
    private ConcurrentDictionary<(Type, object), (object min, object max, bool inclusive)> _ranges = new();
    private readonly ConcurrentQueue<string> _logQueue = new();
    private static readonly Random _random = new();

    public void AddRange<T>(T minValue, T maxValue, bool isInclusive)
    {
        if (!IsTypeSupported(typeof(T)))
            throw new ArgumentException($"Unsupported type: {typeof(T)}");

        var rangeKey = (typeof(T), Activator.CreateInstance(typeof(T)));
        _ranges.TryAdd(rangeKey, (minValue, maxValue, isInclusive));
    }

    public T GenerateRandom<T>()
    {
        if (!IsTypeSupported(typeof(T)))
            throw new ArgumentException($"Unsupported type: {typeof(T)}");

        var rangeKey = (typeof(T), Activator.CreateInstance(typeof(T)));
        if (!_ranges.TryGetValue(rangeKey, out var range))
            throw new InvalidOperationException("Range not set for the given type.");

        object value;
        do
        {
            switch (Type.GetTypeCode(typeof(T)))
            {
                case TypeCode.Int32:
                    int intValue = _random.Next((int)range.min, (int)range.max + (range.inclusive ? 1 : 0));
                    value = intValue;
                    break;
                case TypeCode.Single:
                    float floatValue = range.inclusive 
                        ? _random.NextSingle((float)range.min, (float)range.max) 
                        : (float)_random.NextDouble() * ((float)range.max - (float)range.min) + (float)range.min;
                    value = floatValue;
                    break;
                default:
                    throw new ArgumentException($"Unsupported type: {typeof(T)}");
            }
        } while (!IsWithinRange(value, range));

        _logQueue.Enqueue($"{DateTime.Now}: Generated {value} from range ({range.min}, {range.max})");

        return (T)value;
    }

    public void ProcessLog()
    {
        while (_logQueue.TryDequeue(out var logEntry))
        {
            try
            {
                // Simulate processing the log entry with an external service
                ExternalDataProcessingService.Process(logEntry);
            }
            catch (Exception ex)
            {
                _logQueue.Enqueue(logEntry); // Buffer for retry if the service is unavailable
                Console.WriteLine($"Failed to process log: {logEntry}. Retrying.");
            }
        }
    }

    private static bool IsTypeSupported(Type type)
    {
        return type == typeof(int) || type == typeof(float);
    }

    private static bool IsWithinRange(object value, (object min, object max, bool inclusive) range)
    {
        switch (Type.GetTypeCode(value.GetType()))
        {
            case TypeCode.Int32:
                int intValue = (int)value;
                return range.inclusive 
                    ? intValue >= (int)range.min && intValue <= (int)range.max
                    : intValue > (int)range.min && intValue < (int)range.max;
            case TypeCode.Single:
                float floatValue = (float)value;
                return range.inclusive 
                    ? floatValue >= (float)range.min && floatValue <= (float)range.max
                    : floatValue > (float)range.min && floatValue < (float)range.max;
            default:
                throw new ArgumentException($"Unsupported type: {value.GetType()}");
        }
    }

    public class ExternalDataProcessingService
    {
        public static void Process(string logEntry)
        {
            // Simulate processing with external service
            Console.WriteLine("Processing log entry...");
            System.Threading.Thread.Sleep(100); // Simulate delay
            Console.WriteLine($"Processed: {logEntry}");
        }
    }
}
