using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private readonly ConcurrentDictionary<(Type, string), (object, object)> _valueRanges = new ConcurrentDictionary<(Type, string), (object, object)>();
    private readonly HttpClient _loggerClient;
    private readonly CancellationTokenSource _cancellationTokenSource;
    private readonly ConcurrentQueue<string> _logQueue;

    public DynamicValueGenerator()
    {
        _loggerClient = new HttpClient();
        _cancellationTokenSource = new CancellationTokenSource();
        _logQueue = new ConcurrentQueue<string>();
        Task.Run(() => LogBufferedValuesAsync(), _cancellationTokenSource.Token);
    }

    ~DynamicValueGenerator()
    {
        _cancellationTokenSource.Cancel();
        _loggerClient.Dispose();
    }

    public void SetRange(Type type, string key, object min, object max)
    {
        if (type != typeof(int) && type != typeof(float))
            throw new ArgumentException("Only int and float types are supported.");

        if (min is null || max is null)
            throw new ArgumentException("Min and max values cannot be null.");

        _valueRanges[(type, key)] = (min, max);
    }

    public T GenerateValue<T>(string key)
    {
        if (!_valueRanges.TryGetValue((typeof(T), key), out var range))
            throw new InvalidOperationException($"Range for type {typeof(T)} and key '{key}' not set.");

        return GenerateRandomValue<T>(range.Item1, range.Item2);
    }

    private T GenerateRandomValue<T>(object minObj, object maxObj)
    {
        if (minObj is int min && maxObj is int max)
            return (T)(object)new Random().Next(min, max + 1);

        if (minObj is float minF && maxObj is float maxF)
            return (T)(object)new Random().NextFloat(minF, maxF);

        throw new InvalidOperationException("Invalid range types.");
    }

    private async Task LogBufferedValuesAsync()
    {
        while (!_cancellationTokenSource.Token.IsCancellationRequested)
        {
            if (_logQueue.TryDequeue(out var logMessage))
                await SendLogAsync(logMessage);
            else
                await Task.Delay(10, _cancellationTokenSource.Token);
        }
    }

    private async Task SendLogAsync(string logMessage)
    {
        try
        {
            var content = new StringContent(logMessage);
            var response = await _loggerClient.PostAsync("https://external-logging-service.com/log", content, _cancellationTokenSource.Token);

            if (!response.IsSuccessStatusCode)
                _logQueue.Enqueue(logMessage); // Requeue failed logs for retry
        }
        catch (HttpRequestException)
        {
            _logQueue.Enqueue(logMessage); // Requeue on network failure for retry
        }
    }
}
