public class DataAggregator<T> where T : IComparable<T>
{
    private readonly ConcurrentDictionary<string, List<T>> _dataStore = new ConcurrentDictionary<string, List<T>>();
    private readonly ExternalStorageService _externalStorageService;

    public DataAggregator(ExternalStorageService externalStorageService)
    {
        _externalStorageService = externalStorageService ?? throw new ArgumentNullException(nameof(externalStorageService));
    }

    public void AddData(string key, T dataPoint)
    {
        _dataStore.AddOrUpdate(key, new List<T> { dataPoint }, (k, v) => { v.Add(dataPoint); return v; });
    }

    public T GetAggregateValue(string key, Func<IEnumerable<T>, T> aggregationFunction)
    {
        if (!_dataStore.TryGetValue(key, out var dataList))
            return default;

        return aggregationFunction(dataList);
    }

    public async Task ExportDataAsync()
    {
        try
        {
            foreach (var dataGroup in _dataStore)
            {
                await _externalStorageService.StoreDataAsync(dataGroup.Key, dataGroup.Value);
            }
        }
        catch (Exception ex)
        {
            // Log the exception or handle it according to your application's error handling strategy
            Console.Error.WriteLine($"Failed to export data: {ex.Message}");
        }
    }
