using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public enum LogLevel { Error, Warning, Info }

public delegate void LogDelegate(LogLevel level, string message);

public struct NFAPI_CRC_INDICATION_PDU_T
{
    public RX_UE_INFORMATION_TAG rxUeInfoTag;
    public ushort rnti;
    public CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
}

public enum RX_UE_INFORMATION_TAG { /* Define your tags here */ }
public enum RNTI { /* Define your RNTIs here */ }
public enum CRC_INDICATION_REL8_TAG { /* Define your CRC indications here */ }

public class DynamicValueGenerator
{
    private readonly Random _random = new Random();
    private readonly ConcurrentDictionary<string, RangeConfig> _rangeConfigs = new ConcurrentDictionary<string, RangeConfig>();
    private readonly LogDelegate _log;
    private readonly object _syncObject = new object();

    public DynamicValueGenerator(LogDelegate log)
    {
        _log = log;
    }

    public void AddRange(string name, float min, float max, bool isExclusive)
    {
        _rangeConfigs.TryAdd(name, new RangeConfig { Min = min, Max = max, IsExclusive = isExclusive });
    }

    public void AddRange(string name, int min, int max, bool isExclusive)
    {
        _rangeConfigs.TryAdd(name, new RangeConfig { MinInt = min, MaxInt = max, IsExclusive = isExclusive });
    }

    public float GenerateRandomFloat(string rangeName)
    {
        if (!_rangeConfigs.TryGetValue(rangeName, out var config))
        {
            throw new ArgumentException("Range not found", nameof(rangeName));
        }

        return config.IsExclusive
            ? _random.NextSingle(config.Min, config.Max)
            : _random.NextSingle(config.Min, config.Max);
    }

    public int GenerateRandomInt(string rangeName)
    {
        if (!_rangeConfigs.TryGetValue(rangeName, out var config))
        {
            throw new ArgumentException("Range not found", nameof(rangeName));
        }

        return config.IsExclusive
            ? _random.Next(config.MinInt + 1, config.MaxInt)
            : _random.Next(config.MinInt, config.MaxInt);
    }

    public NFAPI_CRC_INDICATION_PDU_T[] GenerateCrcIndications(int count, float crcFlagProbability)
    {
        var nfaapiPduArray = new NFAPI_CRC_INDICATION_PDU_T[count];
        int crcFlagCount = 0;

        for (int i = 0; i < count; i++)
        {
            var pdu = new NFAPI_CRC_INDICATION_PDU_T
            {
                rxUeInfoTag = /* Initialize RX_UE_INFORMATION_TAG */,
                rnti = /* Initialize RNTI */,
                crcIndicationRel8Tag = /* Initialize CRC_INDICATION_REL8_TAG */
            };

            if (_random.NextDouble() < crcFlagProbability)
            {
                pdu.crcIndicationRel8Tag.CRCFLAG = true;
                crcFlagCount++;
            }
            else
            {
                pdu.crcIndicationRel8Tag.CRCFLAG = false;
            }

            nfaapiPduArray[i] = pdu;
        }

        return nfaapiPduArray;
    }

    public void UpdateCrcFlagProbability(NFAPI_CRC_INDICATION_PDU_T[] array, float targetRatio)
    {
        int actualRatio = array.Count(pdu => pdu.crcIndicationRel8Tag.CRCFLAG);
        float currentRatio = (float)actualRatio / array.Length;

        if (Math.Abs(currentRatio - targetRatio) > 0.01f)
        {
            lock (_syncObject)
            {
                float adjustmentFactor = targetRatio / currentRatio;
                float newProbability = Math.Max(0.01f, Math.Min(0.99f, adjustmentFactor * crcFlagProbability));
                _log(LogLevel.Info, $"Adjusted CRC flag probability to {newProbability}");
                // Update the actual probability if needed
            }
        }
    }

    private class RangeConfig
    {
        public float Min { get; set; }
        public float Max { get; set; }
        public int MinInt { get; set; }
        public int MaxInt { get; set; }
        public bool IsExclusive { get; set; }
    }
}
