public class DataAggregator<T>
{
    private readonly ConcurrentDictionary<string, List<T>> _dataStreams = new ConcurrentDictionary<string, List<T>>();
    private readonly HttpClient _httpClient;
    private readonly int _rateLimit;
    private readonly double _jitterFactor;
    private static Random _random = new Random();

    public DataAggregator(int rateLimit, double jitterFactor)
    {
        _rateLimit = rateLimit;
        _jitterFactor = jitterFactor;
        _httpClient = new HttpClient();
    }

    public void AddData(string streamName, T data)
    {
        _dataStreams.AddOrUpdate(streamName, new List<T> { data }, (key, oldList) => { oldList.Add(data); return oldList; });
    }

    public List<T> GetAggregatedData(string streamName, Func<List<T>, T> aggregationFunction)
    {
        if (!_dataStreams.TryGetValue(streamName, out var dataList))
            return new List<T>();

        return new List<T> { aggregationFunction(dataList) };
    }

    public async Task ExportToStorageAsync(string storageEndpoint, string streamName)
    {
        while (true)
        {
            try
            {
                if (!_dataStreams.TryRemove(streamName, out var dataList))
                    break;

                var aggregatedData = GetAggregatedData(streamName, data => data.FirstOrDefault());
                var content = new StringContent(JsonConvert.SerializeObject(aggregatedData), Encoding.UTF8, "application/json");
                await _httpClient.PostAsync(storageEndpoint, content);

                // Simulate rate limiting with exponential backoff and jitter
                int delayMilliseconds = (int)(_rateLimit + (_jitterFactor * _random.Next(0, 100)));
                await Task.Delay(delayMilliseconds);
            }
            catch (HttpRequestException ex)
            {
                Console.WriteLine($"Request failed: {ex.Message}");
                // Implement exponential backoff strategy here
                int delayMilliseconds = (int)(_rateLimit + (_jitterFactor * _random.Next(0, 100)));
                await Task.Delay(delayMilliseconds);
            }
        }
    }
}
