class NetworkDevice {
public:
    virtual void collectMetrics(int& bandwidth, int& latency, double& packetLoss, double& throughput) = 0;
    virtual ~NetworkDevice() {}
};

class NetworkMetricsMonitor {
private:
    std::vector<NetworkDevice*> devices;
    std::map<std::string, std::thread> threads;
    std::mutex dataMutex;
    std::condition_variable dataCondVar;
    int samplingInterval;
    double bandwidthThresholdWarning;
    double latencyThresholdWarning;
    double packetLossThresholdWarning;
    double throughputThresholdWarning;

public:
    NetworkMetricsMonitor(std::vector<NetworkDevice*>& _devices, int _samplingInterval,
                          double _bandwidthThresholdWarning, double _latencyThresholdWarning,
                          double _packetLossThresholdWarning, double _throughputThresholdWarning)
        : devices(_devices), samplingInterval(_samplingInterval),
          bandwidthThresholdWarning(_bandwidthThresholdWarning),
          latencyThresholdWarning(_latencyThresholdWarning),
          packetLossThresholdWarning(_packetLossThresholdWarning),
          throughputThresholdWarning(_throughputThresholdWarning) {

        for (auto& device : devices) {
            threads[device] = std::thread(&NetworkMetricsMonitor::monitorDevice, this, device);
        }
    }

    ~NetworkMetricsMonitor() {
        for (auto& thread : threads) {
            thread.second.join();
        }
    }

    void monitorDevice(NetworkDevice* device) {
        int bandwidth, latency;
        double packetLoss, throughput;

        while (true) {
            device->collectMetrics(bandwidth, latency, packetLoss, throughput);

            std::unique_lock<std::mutex> lock(dataMutex);
            dataCondVar.wait_for(lock, std::chrono::milliseconds(samplingInterval));

            // Check for thresholds and report alerts
            if (bandwidth > bandwidthThresholdWarning) {
                // Report warning on bandwidth
            }
            if (latency > latencyThresholdWarning) {
                // Report warning on latency
            }
            if (packetLoss > packetLossThresholdWarning) {
                // Report warning on packet loss
            }
            if (throughput > throughputThresholdWarning) {
                // Report warning on throughput
            }

            lock.unlock();
        }
    }

    void updateConfiguration(int newSamplingInterval, double newBandwidthThresholdWarning,
                              double newLatencyThresholdWarning, double newPacketLossThresholdWarning,
                              double newThroughputThresholdWarning) {
        std::unique_lock<std::mutex> lock(dataMutex);
        samplingInterval = newSamplingInterval;
        bandwidthThresholdWarning = newBandwidthThresholdWarning;
        latencyThresholdWarning = newLatencyThresholdWarning;
        packetLossThresholdWarning = newPacketLossThresholdWarning;
        throughputThresholdWarning = newThroughputThresholdWarning;

        dataCondVar.notify_all();
    }
};
