class ImageProcessor {
public:
    // Constructors and destructors
    ImageProcessor();
    ~ImageProcessor();

    // Methods for image transformations
    void applyGrayscale();
    void adjustBrightness(int value);
    void detectEdges();

    // Method to log transformation details
    void logTransformation(const std::string& details);

private:
    // Internal data structures and methods
    struct Image {
        std::vector<uint8_t> pixels;
        int width, height;
    };

    std::atomic<bool> running;
    std::mutex logMutex;
    std::condition_variable logCondition;
    std::queue<std::string> logQueue;

    void processLog();
};

ImageProcessor::ImageProcessor() : running(true) {
    // Start the background thread for processing logs
    std::thread([this]() { processLog(); }).detach();
}

ImageProcessor::~ImageProcessor() {
    running = false;
    logCondition.notify_all();
    // Wait for the log processing thread to finish
    std::unique_lock<std::mutex> lock(logMutex);
    logCondition.wait(lock, [this] { return logQueue.empty(); });
}

void ImageProcessor::applyGrayscale() {
    // Implement grayscale conversion logic here
}

void ImageProcessor::adjustBrightness(int value) {
    // Implement brightness adjustment logic here
}

void ImageProcessor::detectEdges() {
    // Implement edge detection logic here
}

void ImageProcessor::logTransformation(const std::string& details) {
    std::lock_guard<std::mutex> lock(logMutex);
    logQueue.push(details);
    logCondition.notify_one();
}

void ImageProcessor::processLog() {
    while (running) {
        std::unique_lock<std::mutex> lock(logMutex);
        logCondition.wait(lock, [this] { return !logQueue.empty() || !running; });
        if (!running && logQueue.empty()) break;

        std::string details = logQueue.front();
        logQueue.pop();
        lock.unlock();

        // Process the log entry (e.g., send to external logging service)
        std::cout << "Log: " << details << std::endl;
    }
}
```

