#include <stdio.h>
#include <time.h>

typedef struct {
    int customerId;
    char requestType[50];
    time_t timestamp;
    int payloadSize;
} APIRequest;

typedef struct {
    int customerId;
    double currentQuota;
    int requestCount;
} CustomerUsage;

CustomerUsage usageData[] = {
    {1, 1000.0, 0},
    // Add more customer data as needed
};

int checkAndEnforceThrottling(APIRequest request) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);

    int customerId = request.customerId;
    char *requestType = request.requestType;
    double payloadSize = request.payloadSize;

    for (int i = 0; i < sizeof(usageData) / sizeof(CustomerUsage); i++) {
        if (usageData[i].customerId == customerId) {
            // Check quota and enforce limits
            if (usageData[i].currentQuota < payloadSize || usageData[i].requestCount > 100) {
                printf("Request denied for customer %d due to exceeding quota or rate limit\n", customerId);
                return -1; // Deny request
            } else {
                // Allow request and update usage data
                usageData[i].currentQuota -= payloadSize;
                usageData[i].requestCount++;

                if (timeinfo->tm_hour < 8 || timeinfo->tm_hour > 20) {
                    printf("Request allowed during off-peak hours for customer %d\n", customerId);
                } else {
                    printf("Request allowed during peak hours for customer %d\n", customerId);
                }

                return 0; // Allow request
            }
        }
    }

    // If no matching customer found, deny request
    printf("Customer not found for ID: %d\n", customerId);
    return -1;
}

int main() {
    APIRequest request = {1, "GET", time(NULL), 500};
    int result = checkAndEnforceThrottling(request);

    if (result == 0) {
        printf("Request processed successfully.\n");
    } else {
        printf("Failed to process request.\n");
    }

    return 0;
}
```

