typedef struct UEContext {
    int ue_id;
    Session *session_list;
    int session_count;
} UEContext;

typedef struct MemoryPool {
    void *pool_start;
    void *current_pos;
    size_t pool_size;
    size_t item_size;
} MemoryPool;

UEContext* create_UEContext(int ue_id) {
    UEContext *ctx = malloc(sizeof(UEContext));
    if (ctx == NULL) return NULL;
    ctx->ue_id = ue_id;
    ctx->session_list = NULL;
    ctx->session_count = 0;
    return ctx;
}

void destroy_UEContext(UEContext *ctx) {
    free(ctx->session_list);
    free(ctx);
}

Session* create_Session(int session_id) {
    Session *sess = malloc(sizeof(Session));
    if (sess == NULL) return NULL;
    sess->session_id = session_id;
    sess->last_updated = time(NULL);
    return sess;
}

void destroy_Session(Session *sess) {
    free(sess);
}

MemoryPool* create_MemoryPool(size_t item_size, size_t initial_size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;
    pool->item_size = item_size;
    pool->pool_size = initial_size * item_size;
    pool->current_pos = malloc(pool->pool_size);
    if (pool->current_pos == NULL) {
        free(pool);
        return NULL;
    }
    pool->pool_start = pool->current_pos;
    return pool;
}

void destroy_MemoryPool(MemoryPool *pool) {
    free(pool->pool_start);
    free(pool);
}

void* memory_pool_alloc(MemoryPool *pool) {
    if ((char*)pool->current_pos + pool->item_size > (char*)pool->pool_start + pool->pool_size) {
        return NULL; // Out of memory
    }
    void *ptr = pool->current_pos;
    pool->current_pos = (char*)pool->current_pos + pool->item_size;
    return ptr;
}

