#include <unordered_map>
#include <memory>

class NetworkMonitor {
public:
    NetworkMonitor() : running(true) {}

    void addInterface(const std::string& interface, int bandwidthLimit, double latencyThreshold, double packetLossThreshold) {
        interfaces[interface] = {bandwidthLimit, latencyThreshold, packetLossThreshold};
        monitorThreads.push_back(std::thread(&NetworkMonitor::monitorInterface, this, interface));
    }

    void stop() {
        running.store(false);
        for (auto& thread : monitorThreads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

private:
    struct InterfaceConfig {
        int bandwidthLimit;
        double latencyThreshold;
        double packetLossThreshold;
    };

    std::unordered_map<std::string, InterfaceConfig> interfaces;
    std::vector<std::thread> monitorThreads;
    std::mutex queueMutex;
    std::condition_variable dataCondition;
    std::queue<NetworkData> dataQueue;
    std::atomic<bool> running;

    void monitorInterface(const std::string& interface) {
        while (running.load()) {
            // Simulate network monitoring logic
            NetworkData newData = fetchNetworkData(interface);
            if (newData.isValid()) {
                std::lock_guard<std::mutex> lock(queueMutex);
                dataQueue.push(newData);
                dataCondition.notify_one();
            }
        }
    }

    NetworkData fetchNetworkData(const std::string& interface) {
        // Simulate fetching network data
        return NetworkData(/* fetched data */);
    }

    void processNetworkData() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            dataCondition.wait(lock, [this] { return !dataQueue.empty() || !running.load(); });
            if (!running.load()) break;
            NetworkData newData = dataQueue.front();
            dataQueue.pop();
            lock.unlock();

            if (newData.isValid()) {
                analyzeNetworkData(newData);
            }
        }
    }

    void analyzeNetworkData(const NetworkData& data) {
        // Simulate anomaly detection
        for (const auto& [interface, config] : interfaces) {
            if (data.interface == interface) {
                if (data.bandwidthUsage > config.bandwidthLimit) {
                    alert("Bandwidth limit exceeded on " + interface);
                }
                if (data.latency > config.latencyThreshold) {
                    alert("Latency threshold exceeded on " + interface);
                }
                if (data.packetLoss > config.packetLossThreshold) {
                    alert("Packet loss threshold exceeded on " + interface);
                }
            }
        }
    }

    void alert(const std::string& message) {
        // Simulate sending an alert
        std::cout << "Alert: " << message << std::endl;
    }
};

struct NetworkData {
    std::string interface;
    int bandwidthUsage;
    double latency;
    double packetLoss;

    bool isValid() const {
        return !interface.empty();
    }
};
