#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_USERS 1000
#define MAX_SERVICES 50

typedef struct Service {
    char type[MAX_SERVICES];
} Service;

typedef struct UserConnection {
    int userId;
    time_t startTime;
    Service services[MAX_SERVICES];
    int serviceCount;
    pthread_mutex_t lock;
} UserConnection;

UserConnection connections[MAX_USERS];
int userCount = 0;
pthread_mutex_t globalLock;

void initConnectionSystem() {
    pthread_mutex_init(&globalLock, NULL);
}

int addUserConnection(int userId, time_t startTime) {
    pthread_mutex_lock(&globalLock);
    if (userCount >= MAX_USERS) {
        pthread_mutex_unlock(&globalLock);
        return -1; // Max users reached
    }

    for (int i = 0; i < userCount; i++) {
        if (connections[i].userId == userId) {
            pthread_mutex_unlock(&globalLock);
            return -2; // User already connected
        }
    }

    connections[userCount].userId = userId;
    connections[userCount].startTime = startTime;
    connections[userCount].serviceCount = 0;
    pthread_mutex_init(&connections[userCount].lock, NULL);

    userCount++;
    pthread_mutex_unlock(&globalLock);
    return 0;
}

int addService(int userId, const char *serviceType) {
    pthread_mutex_lock(&globalLock);
    for (int i = 0; i < userCount; i++) {
        if (connections[i].userId == userId && connections[i].serviceCount < MAX_SERVICES) {
            pthread_mutex_lock(&connections[i].lock);
            strcpy(connections[i].services[connections[i].serviceCount].type, serviceType);
            connections[i].serviceCount++;
            pthread_mutex_unlock(&connections[i].lock);
            pthread_mutex_unlock(&globalLock);
            return 0;
        }
    }
    pthread_mutex_unlock(&globalLock);
    return -1; // User not found or max services reached
}

void logConnectionChange(int userId, int action) {
    // Implement logging mechanism here
}

int main() {
    initConnectionSystem();
    addUserConnection(1, time(NULL));
    addService(1, "Email");
    addService(1, "Chat");

    return 0;
}
```

