#define MAX_HTML_SIZE 4096
#define CACHE_SIZE 1024

typedef struct {
    int session_id;
    int page_section_id;
    int element_id;
    char html_content[MAX_HTML_SIZE];
} HTTP_POST_DATA;

typedef struct {
    int element_id;
    char content[MAX_HTML_SIZE];
    time_t last_updated;
} CachedElement;

CachedElement cache[CACHE_SIZE];
int cache_count = 0;

pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to handle HTTP POST requests
int handle_http_post(HTTP_POST_DATA *data) {
    // Lock the cache for thread safety
    pthread_mutex_lock(&cache_mutex);

    // Check if the element is in the cache
    int index = -1;
    for (int i = 0; i < cache_count; ++i) {
        if (cache[i].element_id == data->element_id) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        // Element not found, add it to the cache
        if (cache_count >= CACHE_SIZE) {
            pthread_mutex_unlock(&cache_mutex);
            return -1; // Cache full
        }
        index = cache_count++;
    }

    // Update element content and timestamp
    strcpy(cache[index].content, data->html_content);
    time(&cache[index].last_updated);

    // Unlock the cache
    pthread_mutex_unlock(&cache_mutex);

    // Log operation details
    printf("Request Timestamp: %s", ctime(&data->last_updated));
    printf("Session ID: %d\n", data->session_id);
    printf("Page Section ID: %d\n", data->page_section_id);
    printf("Element ID: %d\n", data->element_id);
    printf("HTML Content Length: %zu\n", strlen(data->html_content));

