#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct record {
    char *key;
    float value;
} Record;

typedef struct node {
    Record *data;
    struct node *next;
} Node;

typedef struct linked_list {
    Node *head;
    Node *tail;
    int size;
} LinkedList;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

LinkedList* create_linked_list() {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        log_error("Failed to allocate memory for linked list.");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

Node* create_node(Record *record) {
    Node *node = (Node*)malloc(sizeof(Node));
    if (!node) {
        log_error("Failed to allocate memory for node.");
        exit(EXIT_FAILURE);
    }
    node->data = record;
    node->next = NULL;
    return node;
}

void insert_record(LinkedList *list, const char *key, float value) {
    Record *new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        log_error("Failed to allocate memory for record.");
        exit(EXIT_FAILURE);
    }
    new_record->key = strdup(key);
    new_record->value = value;

    Node *new_node = create_node(new_record);

    if (list->size == 0) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
}

Record* search_record(LinkedList *list, const char *key) {
    Node *current = list->head;
    while (current) {
        if (strcmp(current->data->key, key) == 0) {
            return current->data;
        }
        current = current->next;
    }
    return NULL;
}

void update_record(LinkedList *list, const char *key, float value) {
    Record *record = search_record(list, key);
    if (record) {
        record->value = value;
    } else {
        log_error("Record not found.");
    }
}

void traverse_forward(LinkedList *list) {
    Node *current = list->head;
    while (current) {
        printf("%s: %.2f\n", current->data->key, current->data->value);
        current = current->next;
    }
}

void traverse_backward(LinkedList *list) {
    Node *current = list->tail;
    while (current) {
        printf("%s: %.2f\n", current->data->key, current->data->value);
        current = current->prev;
    }
}

void free_list(LinkedList *list) {
    Node *current = list->head;
    while (current) {
        Node *temp = current;
        free(temp->data->key);
        free(temp->data);
        free(current);
        current = temp->next;
    }
    free(list);
}
