    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    // Add any other necessary members for thread safety and dynamic resizing
} SafeNFAPICRCStruct;

SafeNFAPICRCStruct *safe_nfa_pi_crc_list[MAX_STRUCTS];
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t current_size = 0;

int safe_nfa_pi_crc_init(void) {
    // Initialize the list and any necessary thread synchronization mechanisms
    pthread_mutex_lock(&list_mutex);
    for (size_t i = 0; i < MAX_STRUCTS; ++i) {
        safe_nfa_pi_crc_list[i] = NULL;
    }
    current_size = 0;
    pthread_mutex_unlock(&list_mutex);
    return 0; // Return success
}

int safe_nfa_pi_crc_add(RX_UE_INFORMATION_TAG rx_ue_info_tag, uint16_t rnti) {
    pthread_mutex_lock(&list_mutex);
    if (current_size >= MAX_STRUCTS) {
        pthread_mutex_unlock(&list_mutex);
        return -1; // Error: List is full
    }

    SafeNFAPICRCStruct *new_struct = malloc(sizeof(SafeNFAPICRCStruct));
    if (!new_struct) {
        pthread_mutex_unlock(&list_mutex);
        return -2; // Error: Memory allocation failed
    }

    new_struct->rx_ue_info_tag = rx_ue_info_tag;
    new_struct->rnti = rnti;
    new_struct->crc_ind_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG

    safe_nfa_pi_crc_list[current_size++] = new_struct;

    pthread_mutex_unlock(&list_mutex);
    return 0; // Success
}

int safe_nfa_pi_crc_dynamic_resize(void) {
    if (current_size < DYNAMIC_RESIZE_THRESHOLD) {
        return 0; // No need to resize
    }

    SafeNFAPICRCStruct **new_list = realloc(safe_nfa_pi_crc_list, MAX_STRUCTS * sizeof(SafeNFAPICRCStruct *));
    if (!new_list) {
        return -1; // Error: Memory reallocation failed
    }

    safe_nfa_pi_crc_list = new_list;
    MAX_STRUCTS *= 2; // Double the capacity for next potential resize

    return 0; // Success
}

