#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LogBuffer {
    NFAPI_CRC_INDICATION_PDU_T *data;
    int front, rear, size, capacity;
    sem_t full, empty;
    pthread_mutex_t mutex;
} LogBuffer;

LogBuffer* createLogBuffer(int capacity) {
    LogBuffer *buffer = (LogBuffer*)malloc(sizeof(LogBuffer));
    buffer->capacity = capacity;
    buffer->front = 0;
    buffer->rear = capacity - 1;
    buffer->size = 0;
    buffer->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    sem_init(&buffer->full, 0, 0);
    sem_init(&buffer->empty, 0, capacity);
    pthread_mutex_init(&buffer->mutex, NULL);
    return buffer;
}

void deleteLogBuffer(LogBuffer *buffer) {
    free(buffer->data);
    sem_destroy(&buffer->full);
    sem_destroy(&buffer->empty);
    pthread_mutex_destroy(&buffer->mutex);
    free(buffer);
}

void enqueue(LogBuffer *buffer, NFAPI_CRC_INDICATION_PDU_T item) {
    sem_wait(&buffer->empty);
    pthread_mutex_lock(&buffer->mutex);

    buffer->rear = (buffer->rear + 1) % buffer->capacity;
    buffer->data[buffer->rear] = item;
    buffer->size++;

    pthread_mutex_unlock(&buffer->mutex);
    sem_post(&buffer->full);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(LogBuffer *buffer) {
    NFAPI_CRC_INDICATION_PDU_T item;
    sem_wait(&buffer->full);
    pthread_mutex_lock(&buffer->mutex);

    item = buffer->data[buffer->front];
    buffer->front = (buffer->front + 1) % buffer->capacity;
    buffer->size--;

    pthread_mutex_unlock(&buffer->mutex);
    sem_post(&buffer->empty);

    return item;
}

void* logProcessor(void *arg) {
    LogBuffer *buffer = (LogBuffer*)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T item = dequeue(buffer);
        // Process the item, e.g., store in external data storage
        printf("Processed: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
               item.RX_UE_INFORMATION_TAG, item.RNTI, item.CRC_INDICATION_REL8_TAG);
    }
}

int main() {
    int N = 2000;
    LogBuffer *buffer = createLogBuffer(N);

    pthread_t processor_thread;
    pthread_create(&processor_thread, NULL, logProcessor, buffer);

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T item;
        item.RX_UE_INFORMATION_TAG = rand() % 1000;
        item.RNTI = rand() % 256;
        item.CRC_INDICATION_REL8_TAG = rand() % 4;
        item.CRCFLAG = rand() % 2;
        enqueue(buffer, item);
    }

    pthread_join(processor_thread, NULL);
    deleteLogBuffer(buffer);

    return 0;
}
