using UnityEngine;
using System;

public class ValueGenerator : ICloneable
{
    private float minValueFloat;
    private float maxValueFloat;
    private int minValueInt;
    private int maxValueInt;

    public ValueGenerator(float minValue, float maxValue)
    {
        SetRange(minValue, maxValue);
    }

    public ValueGenerator(int minValue, int maxValue)
    {
        SetRange(minValue, maxValue);
    }

    private void SetRange<T>(T min, T max) where T : IComparable
    {
        if (min.CompareTo(max) > 0)
        {
            var temp = min;
            min = max;
            max = temp;
        }

        if (typeof(T) == typeof(float))
        {
            minValueFloat = (float)Convert.ChangeType(min, typeof(float));
            maxValueFloat = (float)Convert.ChangeType(max, typeof(float));
        }
        else if (typeof(T) == typeof(int))
        {
            minValueInt = (int)Convert.ChangeType(min, typeof(int));
            maxValueInt = (int)Convert.ChangeType(max, typeof(int));
        }
    }

    public float GetRandomFloatInclusive()
    {
        return UnityEngine.Random.Range(minValueFloat, maxValueFloat + 1);
    }

    public float GetRandomFloatExclusive()
    {
        return UnityEngine.Random.Range(minValueFloat, maxValueFloat);
    }

    public int GetRandomIntInclusive()
    {
        return UnityEngine.Random.Range(minValueInt, maxValueInt + 1);
    }

    public int GetRandomIntExclusive()
    {
        return UnityEngine.Random.Range(minValueInt, maxValueInt);
    }

    public override string ToString()
    {
        if (typeof(T) == typeof(float))
        {
            return $"Range: [{minValueFloat}, {maxValueFloat}]";
        }
        else
        {
            return $"Range: [{minValueInt}, {maxValueInt}]";
        }
    }

    public object Clone()
    {
        return MemberwiseClone();
    }
}
```

This solution provides a utility class `ValueGenerator` that generates random values within specified ranges for both integer and float types using the `UnityEngine.Random.Range` function. It includes methods to handle inclusive and exclusive ranges, swaps boundaries if necessary, and implements a thread-safe cloning method. The class is designed to be efficient and flexible while handling potential exceptions gracefully.']

