public class DataProcessor
{
    private readonly Random _random = new Random();
    private Dictionary<string, List<object>> _dataStreams = new Dictionary<string, List<object>>();

    /// <summary>
    /// Adds a new data point to the specified stream.
    /// </summary>
    /// <param name="streamId">The identifier for the stream.</param>
    /// <param name="data">The data point to add.</param>
    public void AddDataPoint(string streamId, object data)
    {
        if (string.IsNullOrEmpty(streamId))
            throw new ArgumentException("Stream ID cannot be null or empty.", nameof(streamId));

        if (_dataStreams.ContainsKey(streamId))
            _dataStreams[streamId].Add(data);
        else
            _dataStreams.Add(streamId, new List<object> { data });
    }

    /// <summary>
    /// Retrieves the latest data point from the specified stream.
    /// </summary>
    /// <param name="streamId">The identifier for the stream.</param>
    /// <returns>The most recent data point or null if the stream is empty.</returns>
    public object GetLatestDataPoint(string streamId)
    {
        if (string.IsNullOrEmpty(streamId))
            throw new ArgumentException("Stream ID cannot be null or empty.", nameof(streamId));

        if (_dataStreams.ContainsKey(streamId) && _dataStreams[streamId].Count > 0)
            return _dataStreams[streamId][_dataStreams[streamId].Count - 1];

        return null;
    }

    /// <summary>
    /// Removes all data points from the specified stream.
    /// </summary>
    /// <param name="streamId">The identifier for the stream.</param>
    public void ClearStream(string streamId)
    {
        if (string.IsNullOrEmpty(streamId))
            throw new ArgumentException("Stream ID cannot be null or empty.", nameof(streamId));

        _dataStreams.Remove(streamId);
    }

    /// <summary>
    /// Validates the data stream to ensure no null or invalid data points are present.
    /// </summary>
    /// <param name="streamId">The identifier for the stream.</param>
    public void ValidateStream(string streamId)
    {
        if (string.IsNullOrEmpty(streamId))
            throw new ArgumentException("Stream ID cannot be null or empty.", nameof(streamId));

        if (_dataStreams.ContainsKey(streamId))
        {
            for (int i = _dataStreams[streamId].Count - 1; i >= 0; i--)
            {
                if (_dataStreams[streamId][i] == null || !IsValidDataPoint(_dataStreams[streamId][i]))
                    _dataStreams[streamId].RemoveAt(i);
            }
        }
    }

    /// <summary>
    /// Determines if the data point is valid.
    /// </summary>
    /// <param name="data">The data point to validate.</param>
    /// <returns>True if the data point is valid, otherwise false.</returns>
    private bool IsValidDataPoint(object data)
    {
        // Implement your validation logic here
        return data != null;
    }

    /// <summary>
    /// Returns a string representation of the current state of the stream.
    /// </summary>
    /// <returns>A string representing the stream's data points and most recent value.</returns>
    public override string ToString()
    {
        StringBuilder sb = new StringBuilder();
        foreach (var kvp in _dataStreams)
        {
            if (kvp.Value.Count > 0)
                sb.AppendLine($"{kvp.Key}: {kvp.Value[kvp.Value.Count - 1]}");
