    int count;
    int capacity;
    pthread_mutex_t mutex;
} DataBuffer;

void initialize_buffer(DataBuffer *db, int initial_capacity) {
    db->buffer = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!db->buffer) {
        fprintf(stderr, "Failed to allocate memory for buffer\n");
        exit(1);
    }
    db->count = 0;
    db->capacity = initial_capacity;
    pthread_mutex_init(&db->mutex, NULL);
}

void resize_buffer(DataBuffer *db) {
    int new_capacity = db->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_buffer = (NFAPI_CRC_INDICATION_PDU_T *)realloc(db->buffer, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_buffer) {
        fprintf(stderr, "Failed to reallocate memory for buffer\n");
        exit(1);
    }
    db->buffer = new_buffer;
    db->capacity = new_capacity;
}

void add_struct(DataBuffer *db, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&db->mutex);
    if (db->count >= db->capacity) {
        resize_buffer(db);
    }
    db->buffer[db->count++] = *pdu;
    pthread_mutex_unlock(&db->mutex);
}

void process_data(DataBuffer *db, void (*process_func)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&db->mutex);
    for (int i = 0; i < db->count; ++i) {
        process_func(&db->buffer[i]);
    }
    pthread_mutex_unlock(&db->mutex);
}

void free_buffer(DataBuffer *db) {
    pthread_mutex_destroy(&db->mutex);
    free(db->buffer);
}
