    pthread_mutex_lock(&rm->lock);
    if (rm->size == rm->capacity) {
        // Handle dynamic resizing logic here
        printf("Dynamic resizing required.\n");
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = value;
    newNode->key = key;
    newNode->next = NULL;

    int index = key % rm->capacity;
    if (rm->records[index] != NULL) {
        // Handle collision resolution logic here
        printf("Collision detected.\n");
    }
    rm->records[index] = newNode;
    rm->size++;
    pthread_mutex_unlock(&rm->lock);
}

void deleteRecord(RecordManager *rm, int key) {
    pthread_mutex_lock(&rm->lock);
    int index = key % rm->capacity;
    Node* current = rm->records[index];
    Node* previous = NULL;

    while (current != NULL && current->key != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("Key not found.\n");
    } else {
        if (previous == NULL) {
            rm->records[index] = current->next;
        } else {
            previous->next = current->next;
