#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 2000
#define MAX_RECORDS 10000

typedef struct {
    int RNTI;
    int CRCFLAG;
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned long offset;
    int key;
    RX_UE_INFORMATION_TAG tag;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node** records;
    int size;
    pthread_mutex_t lock;
} RecordBuffer;

RecordBuffer* create_buffer() {
    RecordBuffer* buffer = (RecordBuffer*)malloc(sizeof(RecordBuffer));
    if (!buffer) return NULL;
    buffer->records = (Node**)calloc(MAX_RECORDS, sizeof(Node*));
    if (!buffer->records) {
        free(buffer);
        return NULL;
    }
    buffer->size = 0;
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void destroy_buffer(RecordBuffer* buffer) {
    for (int i = 0; i < buffer->size; i++) {
        Node* current = buffer->records[i];
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    free(buffer->records);
    pthread_mutex_destroy(&buffer->lock);
    free(buffer);
}

void insert_record(RecordBuffer* buffer, Record record) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->size < MAX_RECORDS) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            pthread_mutex_unlock(&buffer->lock);
            return;
        }
        new_node->record = record;
        new_node->next = NULL;
        buffer->records[buffer->size++] = new_node;
    }
    pthread_mutex_unlock(&buffer->lock);
}

Record* get_record(RecordBuffer* buffer, int key) {
    pthread_mutex_lock(&buffer->lock);
    Record* result = NULL;
    for (int i = 0; i < buffer->size; i++) {
        Node* current = buffer->records[i];
        while (current) {
            if (current->record.key == key) {
                result = &current->record;
                break;
            }
            current = current->next;
        }
        if (result) break;
    }
    pthread_mutex_unlock(&buffer->lock);
    return result;
}

int main() {
    RecordBuffer* buffer = create_buffer();
    if (!buffer) {
        fprintf(stderr, "Failed to create record buffer\n");
        return 1;
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_STRUCTS; i++) {
        Record record;
        record.tag.RNTI = rand() % 1000;
        record.tag.CRCFLAG = rand() % 2;
        record.offset = rand();
        record.key = i % MAX_RECORDS;
        insert_record(buffer, record);
    }

    // Example of getting a record
    Record* retrieved_record = get_record(buffer, 500);
    if (retrieved_record) {
        printf("Retrieved RNTI: %d, CRCFLAG: %d\n", retrieved_record->tag.RNTI, retrieved_record->tag.CRCFLAG);
    } else {
        printf("Record not found\n");
    }

    destroy_buffer(buffer);
    return 0;
}
