import hashlib
import time
from multiprocessing import Lock, Manager

class DeviceStatus:
    def __init__(self, dev_id):
        self.dev_id = dev_id
        self.sensor_list = []
        self.last_update = 0
        self.lock = Lock()

    def add_sensor(self, sensor_id):
        with self.lock:
            if sensor_id not in self.sensor_list:
                self.sensor_list.append(sensor_id)
                self.last_update = time.time()

    def remove_sensor(self, sensor_id):
        with self.lock:
            if sensor_id in self.sensor_list:
                self.sensor_list.remove(sensor_id)

    def update_timestamp(self):
        with self.lock:
            self.last_update = time.time()

def validate_sensor_data(data):
    try:
        return hashlib.sha256(data.encode()).hexdigest()
    except Exception as e:
        print(f"Error validating sensor data: {e}")
        return None

def add_device_status(dev_id, sensor_list):
    with device_manager.lock:
        if dev_id not in device_manager.devices:
            new_device = DeviceStatus(dev_id)
            for sensor_id in sensor_list:
                new_device.add_sensor(sensor_id)
            device_manager.devices[dev_id] = new_device
        else:
            device_manager.devices[dev_id].update_timestamp()

def remove_disconnected_sensors(threshold):
    with device_manager.lock:
        current_time = time.time()
        for dev_id, device in list(device_manager.devices.items()):
            if current_time - device.last_update > threshold:
                del device_manager.devices[dev_id]

if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser(description="Device status manager")
    parser.add_argument("input_file", nargs="?")
    parser.add_argument("--help", action="help")
    parser.add_argument("-q", "--quiet", action="store_true")
    parser.add_argument("-o", "--output_file", type=argparse.FileType('w'))

    args = parser.parse_args()

    device_manager = Manager()
    device_manager.devices = {}

    if args.input_file:
        with open(args.input_file, 'r') as file:
            lines = file.readlines()
            print(f"Number of lines: {len(lines)}")
    else:
        print("No input file provided. Usage: python script.py <input_file> [--help] [-q] [-o output_file]")
