class AuthenticationManager {
  constructor(apiUrl, sessionTimeout) {
    this.apiUrl = apiUrl;
    this.sessionTimeout = sessionTimeout;
    this.sessions = {};
    this.lockedAccounts = new Set();
  }

  async authenticate(userId, token, encryptedPasswordHash) {
    if (this.lockedAccounts.has(userId)) {
      throw new Error('Account temporarily locked due to multiple failed attempts.');
    }

    try {
      const response = await fetch(`${this.apiUrl}/verify`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, token, encryptedPasswordHash })
      });

      if (!response.ok) {
        throw new Error('Invalid credentials.');
      }

      const data = await response.json();
      this.sessions[userId] = setTimeout(() => {
        delete this.sessions[userId];
      }, this.sessionTimeout);

      return data;
    } catch (error) {
      console.error(error);
      if (error.message.includes('Invalid credentials.')) {
        this.lockAccount(userId, 5 * 60 * 1000); // Lock for 5 minutes
      }
      throw error;
    }
  }

  async verifyUserSession(userId) {
    if (!this.sessions[userId]) {
      return false;
    }

    const response = await fetch(`${this.apiUrl}/session`, {
      method: 'GET',
      headers: { 'Authorization': `Bearer ${this.sessions[userId]}` }
    });

    if (!response.ok) {
      delete this.sessions[userId];
      return false;
    }

    return true;
  }

  lockAccount(userId, duration) {
    this.lockedAccounts.add(userId);
    setTimeout(() => {
      this.lockedAccounts.delete(userId);
    }, duration);
  }

  traverseDOM(selector) {
    const elements = [];
    function recurse(node) {
      if (node.matches(selector)) {
        elements.push(node);
      }
      node.querySelectorAll('*').forEach(child => recurse(child));
    }
    recurse(document.body);
    return elements;
  }
