#define MAX_LINE_LENGTH 1024
#define CONFIG_FILE "config.txt"

typedef struct {
    char *input_file;
    char *output_file;
    regex_t regex;
    int filter_lines;
    int concurrent_processing;
} Config;

Config config = {NULL, NULL, {}, 0, 0};

void parse_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) return;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), fp)) {
        char key[256], value[256];
        sscanf(line, "%s %s", key, value);
        if (strcmp(key, "output_file") == 0) config.output_file = strdup(value);
        else if (strcmp(key, "filter_lines") == 0 && strcmp(value, "true") == 0) config.filter_lines = 1;
        else if (strcmp(key, "concurrent_processing") == 0 && strcmp(value, "true") == 0) config.concurrent_processing = 1;
    }

    fclose(fp);
}

void print_usage() {
    printf("Usage: program [options] input_file\n");
    printf("Options:\n");
    printf("  --manpage     Display manual page.\n");
    printf("  -cs          Count spaces and tabs only.\n");
    printf("  -o output_file Specify output file for results.\n");
    printf("  -f regex       Filter lines using regular expression.\n");
}

void process_file(char *file_path) {
    FILE *fp = fopen(file_path, "r");
    if (!fp) {
        perror("Failed to open input file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    int line_count = 0;
    while (fgets(line, sizeof(line), fp)) {
        line_count++;
        // Apply filtering if enabled
        if (config.filter_lines && regexec(&config.regex, line, 0, NULL, 0) != 0) continue;

        // Process line here (e.g., count spaces/tabs)
    }

    fclose(fp);
}

void *thread_func(void *arg) {
    char *file_path = (char *)arg;
    process_file(file_path);
    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    parse_config();

    if (argc < 2) {
        print_usage();
        return 1;
    }

    if (strcmp(argv[1], "--manpage") == 0) {
        printf("Manual page content here.\n");
        return 0;
    }

    config.input_file = argv[1];
    regcomp(&config.regex, ".*", REG_EXTENDED); // Default regex to match all lines

    int thread_count = 0;
    pthread_t threads[argc - 2];

    for (int i = 2; i < argc; i++) {
        if (pthread_create(&threads[i - 2], NULL, thread_func, argv[i]) != 0) {
            perror("Failed to create thread");
            return 1;
        }
        thread_count++;
    }

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    regfree(&config.regex);

    return 0;
}
