#define MAX_UE_CONTEXTS 1000
#define SESSION_INACTIVITY_THRESHOLD 60

typedef struct Session {
    int session_id;
    time_t last_update;
    struct Session* next;
} Session;

typedef struct UEContext {
    int ue_id;
    Session* session_list;
    time_t last_session_update;
} UEContext;

typedef struct LTE_PHY_MIB_TABLE {
    int cell_id;
    // Other fields
} LTE_PHY_MIB_TABLE;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

void add_session(UEContext* ue, int session_id) {
    Session* new_session = (Session*)malloc(sizeof(Session));
    new_session->session_id = session_id;
    new_session->last_update = time(NULL);
    new_session->next = NULL;

    if (!ue->session_list) {
        ue->session_list = new_session;
    } else {
        Session* current = ue->session_list;
        while (current->next) {
            current = current->next;
        }
        current->next = new_session;
    }
}

void remove_inactive_sessions(UEContext* ue, int threshold) {
    time_t now = time(NULL);
    Session** prev = &ue->session_list;

    while (*prev) {
        if (now - (*prev)->last_update > threshold) {
            Session* temp = *prev;
            *prev = (*prev)->next;
            free(temp);
        } else {
            prev = &(*prev)->next;
        }
    }

    if (ue->session_list) {
        ue->last_session_update = now;
    }
}

void update_session_timestamps(UEContext* ue) {
    time_t now = time(NULL);
    Session* current = ue->session_list;

    while (current) {
        current->last_update = now;
        current = current->next;
    }

    if (ue->session_list) {
        ue->last_session_update = now;
    }
}

LTE_PHY_MIB_TABLE* create_lte_phy_mib_table(int cell_id) {
