using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private readonly ConcurrentDictionary<int, (float min, float max)> _floatRanges = new();
    private readonly ConcurrentDictionary<int, (int min, int max)> _intRanges = new();
    private readonly HttpClient _httpClient;
    private const string LogUrl = "https://api.externallogservice.com/log";
    private static readonly Random _random = new();

    public DynamicValueGenerator(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
    }

    public void AddOrUpdateRange(int id, (float min, float max) range)
    {
        if (range.min >= range.max) throw new ArgumentException("Min cannot be greater than or equal to Max", nameof(range));

        _floatRanges[id] = range;
    }

    public void AddOrUpdateRange(int id, (int min, int max) range)
    {
        if (range.min >= range.max) throw new ArgumentException("Min cannot be greater than or equal to Max", nameof(range));

        _intRanges[id] = range;
    }

    public async Task<float> GenerateRandomFloatAsync(int id, CancellationToken cancellationToken)
    {
        var range = GetRange(_floatRanges, id);
        return GenerateRandomValue(range.min, range.max);
    }

    public async Task<int> GenerateRandomIntAsync(int id, CancellationToken cancellationToken)
    {
        var range = GetRange(_intRanges, id);
        return GenerateRandomValue(range.min, range.max);
    }

    private static float GenerateRandomValue(float min, float max)
    {
        if (min == max) return min;

        var scale = max - min;
        return (float)(_random.NextDouble() * scale + min);
    }

    private static int GenerateRandomValue(int min, int max)
    {
        if (min == max) return min;

        return _random.Next(min, max + 1);
    }

    private (T min, T max) GetRange<T>(ConcurrentDictionary<int, (T min, T max)> ranges, int id)
    {
        if (!ranges.TryGetValue(id, out var range)) throw new ArgumentException("No range found for the given ID", nameof(id));

        return range;
    }

    public async Task LogAsync(string message, CancellationToken cancellationToken)
    {
        var content = new StringContent(message);
        var response = await _httpClient.PostAsync(LogUrl, content, cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            // Implement retry and backoff strategy
            await RetryLogAsync(message, 3, TimeSpan.FromSeconds(1), cancellationToken);
        }
    }

    private async Task RetryLogAsync(string message, int retries, TimeSpan delay, CancellationToken cancellationToken)
    {
        for (int i = 0; i < retries; i++)
        {
            var response = await _httpClient.PostAsync(LogUrl, new StringContent(message), cancellationToken);

            if (response.IsSuccessStatusCode) break;

            await Task.Delay(delay, cancellationToken);
        }
    }

    private static ConcurrentDictionary<int, (T min, T max)> GetRanges<T>(ConcurrentDictionary<int, (T min, T max)> ranges)
    {
        return ranges;
    }

