            scheduler.scheduleAtFixedRate(this::collectData, 0, intervalMillis, TimeUnit.MILLISECONDS);
        }
    }

    public void stopMonitoring() {
        running.set(false);
        scheduler.shutdown();
    }

    private void collectData() {
        for (Sensor sensor : sensors.values()) {
