typedef struct log_record {
    char tag;
    NFAPI_LOGGING_PDU_T pdu;
    struct log_record *next;
} LogRecord;

typedef struct {
    size_t *offsets;
    char *tags;
    LogRecord *head;
    size_t count;
    size_t capacity;
} LogBuffer;

void init_log_buffer(LogBuffer *buffer, size_t initial_capacity) {
    buffer->offsets = (size_t *)malloc(initial_capacity * sizeof(size_t));
    buffer->tags = (char *)malloc(initial_capacity * sizeof(char));
    if (!buffer->offsets || !buffer->tags) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    buffer->head = NULL;
    buffer->count = 0;
    buffer->capacity = initial_capacity;
}

void resize_log_buffer(LogBuffer *buffer, size_t new_capacity) {
    size_t *new_offsets = (size_t *)realloc(buffer->offsets, new_capacity * sizeof(size_t));
    char *new_tags = (char *)realloc(buffer->tags, new_capacity * sizeof(char));
    if (!new_offsets || !new_tags) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    buffer->offsets = new_offsets;
    buffer->tags = new_tags;
    buffer->capacity = new_capacity;
}

void add_log_record(LogBuffer *buffer, char tag, NFAPI_LOGGING_PDU_T pdu) {
    if (buffer->count >= buffer->capacity) {
        resize_log_buffer(buffer, buffer->capacity * 2);
    }
    buffer->offsets[buffer->count] = sizeof(NFAPI_LOGGING_PDU_T) + buffer->count;
    buffer->tags[buffer->count] = tag;
    buffer->head = (LogRecord *)realloc(buffer->head, (buffer->count + 1) * sizeof(LogRecord));
    buffer->head[buffer->count].tag = tag;
    buffer->head[buffer->count].pdu = pdu;
    buffer->head[buffer->count].next = NULL;
    buffer->count++;
}

void compress_log_buffer(LogBuffer *buffer) {
    // Implement compression logic here
}

void process_logs(LogBuffer *buffer, void (*store_data)(NFAPI_LOGGING_PDU_T *)) {
    LogRecord *current = buffer->head;
    while (current) {
        store_data(&current->pdu);
        current = current->next;
    }
}

void generate_random_log(LogBuffer *buffer, char (*tag_set)[], int tag_count) {
    NFAPI_LOGGING_PDU_T log_pdu = {0};
    log_pdu.EVENT_ID = rand() % 100000;
    log_pdu.TIMESTAMP = time(NULL);
    log_pdu.LOG_LEVEL = (LogLevel)(rand() % 4);

    char random_tag = tag_set[rand() % tag_count];
    while ((current = buffer->head) && current->tag == random_tag) {
        random_tag = tag_set[rand() % tag_count];
    }

    add_log_record(buffer, random_tag, log_pdu);
}

void store_data(NFAPI_LOGGING_PDU_T *pdu) {
    // Implement data storage logic here
}

int main() {
    srand(time(NULL));
    char tag_set[4][5] = {"D", "I", "W", "E"};
