#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 1024

typedef struct {
    char ip[16];
    char method[8];
    time_t timestamp;
    // Add additional headers as needed
} ConnectionRequest;

typedef struct {
    ConnectionRequest requests[MAX_CONNECTIONS];
    int count;
    pthread_mutex_t lock;
} ConnectionList;

void initialize_connection_list(ConnectionList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_request_to_list(ConnectionList *list, const char *ip, const char *method) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    strncpy(list->requests[list->count].ip, ip, sizeof(list->requests[list->count].ip) - 1);
    strncpy(list->requests[list->count].method, method, sizeof(list->requests[list->count].method) - 1);
    list->requests[list->count].timestamp = time(NULL);
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void *handle_request(void *arg) {
    ConnectionList *list = (ConnectionList *)arg;
    // Process the request
    add_request_to_list(list, "127.0.0.1", "GET");
    return NULL;
}

int main() {
    int M; // Number of concurrent connections
    printf("Enter the number of concurrent connections: ");
    scanf("%d", &M);

    ConnectionList connection_list;
    initialize_connection_list(&connection_list);

    pthread_t threads[M];
    for (int i = 0; i < M; i++) {
        pthread_create(&threads[i], NULL, handle_request, &connection_list);
    }

    for (int i = 0; i < M; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&connection_list.lock);

    return 0;
}
```

