using System.Threading.Tasks;

public class DataAggregator
{
    private ConcurrentBag<object> dataStream = new ConcurrentBag<object>();
    private ConcurrentDictionary<string, int> memoryPool = new ConcurrentDictionary<string, int>();

    public void AddData(object data)
    {
        dataStream.Add(data);
    }

    public IEnumerable<T> AggregateData<T>(Func<IEnumerable<T>, T> aggregator)
    {
        return dataStream.OfType<T>().Aggregate(aggregator);
    }

    public async Task ExportToStorageAsync(IEnumerable<object> data, string storageServiceUrl, int batchSize = 100, TimeSpan? rateLimit = null)
    {
        var tasks = new List<Task>();

        foreach (var batch in data.Batch(batchSize))
        {
            var task = Task.Run(() => SendBatchToStorage(batch, storageServiceUrl, rateLimit));
            tasks.Add(task);
        }

        await Task.WhenAll(tasks);
    }

    private async Task SendBatchToStorage(IEnumerable<object> batch, string storageServiceUrl, TimeSpan? rateLimit)
    {
        try
        {
            // Simulate sending data to storage service
            Console.WriteLine($"Sending batch of {batch.Count()} items to {storageServiceUrl}");

            if (rateLimit.HasValue)
            {
                await Task.Delay(rateLimit.Value);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error exporting data: {ex.Message}");
            // Implement exponential backoff and retry logic with jitter here
        }
    }

    public Dictionary<string, string> CalculateFileHashes(string directoryPath, int maxFileSizeInBytes = 1024 * 1024)
    {
        var fileHashes = new Dictionary<string, string>();

        try
        {
            Parallel.ForEach(Directory.GetFiles(directoryPath), filePath =>
            {
                using (var md5 = MD5.Create())
                using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 8192, true))
                {
                    var buffer = new byte[4096];
                    int bytesRead;
                    while ((bytesRead = stream.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        md5.TransformBlock(buffer, 0, bytesRead, null, 0);
                    }
                    md5.TransformFinalBlock(Array.Empty<byte>(), 0, 0);

                    var hexDigest = BitConverter.ToString(md5.Hash).Replace("-", "").ToLower();
                    fileHashes[filePath] = hexDigest;
                }
            });
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error calculating file hashes: {ex.Message}");
        }

        return fileHashes;
    }

    public void VerifyList(List<string> list, int maxConsecutiveGuti = 10, int maxUniqueGutiCount = 1000)
    {
        var gutiCounter = new Dictionary<string, int>();

        for (int i = 0; i < list.Count; i++)
        {
            if (i > 0 && list[i] == list[i - 1])
            {
                Console.WriteLine($"Consecutive GUTI detected: {list[i]}");
            }

            if (gutiCounter.ContainsKey(list[i]))
            {
                gutiCounter[list[i]]++;
            }
            else
            {
                gutiCounter[list[i]] = 1;
            }

            if (gutiCounter.Count > maxUniqueGutiCount)
            {
                Console.WriteLine($"Exceeded maximum unique GUTI count: {maxUniqueGutiCount}");
            }
        }
    }
}

public static class EnumerableExtensions
{
    public static IEnumerable<IEnumerable<T>> Batch<T>(this IEnumerable<T> source, int batchSize)
    {
        var buffer = new List<T>();
        int count = 0;

        foreach (var item in source)
        {
            if (count >= batchSize)
            {
                yield return buffer;
                buffer.Clear();
                count = 0;
            }

            buffer.Add(item);
            count++;
        }

        if (buffer.Count > 0)
        {
            yield return buffer;
        }
    }
}
