pthread_mutex_t ue_context_mutex = PTHREAD_MUTEX_INITIALIZER;
UEContext* ue_array[MAX_UE_SESSIONS];
int ue_count = 0;

void add_session(int ue_id, int session_id) {
    pthread_mutex_lock(&ue_context_mutex);
    for (int i = 0; i < ue_count; ++i) {
        if (ue_array[i]->ue_id == ue_id) {
            for (int j = 0; j < MAX_UE_SESSIONS; ++j) {
                if (ue_array[i]->session_list[j] == -1) {
                    ue_array[i]->session_list[j] = session_id;
                    time(&ue_array[i]->last_update_time);
                    pthread_mutex_unlock(&ue_context_mutex);
                    return;
                }
            }
        }
    }
    // Handle error: No available slot for new session
    pthread_mutex_unlock(&ue_context_mutex);
}

void remove_inactive_sessions(time_t threshold) {
    pthread_mutex_lock(&ue_context_mutex);
    for (int i = 0; i < ue_count; ++i) {
        if (time(NULL) - ue_array[i]->last_update_time > threshold) {
            memset(ue_array[i], 0, sizeof(UEContext));
        }
    }
    pthread_mutex_unlock(&ue_context_mutex);
}

void update_session_timestamp(int ue_id) {
    pthread_mutex_lock(&ue_context_mutex);
    for (int i = 0; i < ue_count; ++i) {
        if (ue_array[i]->ue_id == ue_id) {
            time(&ue_array[i]->last_update_time);
            break;
        }
    }
    pthread_mutex_unlock(&ue_context_mutex);
}

