#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_THREADS 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryNode {
    void *data;
    struct MemoryNode *next;
} MemoryNode;

typedef struct {
    MemoryNode *head;
    pthread_mutex_t lock;
} MemoryPool;

void initializeMemoryPool(MemoryPool *pool) {
    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
}

void* allocateFromPool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->head == NULL) {
        MemoryNode *newNode = (MemoryNode *)malloc(sizeof(MemoryNode));
        if (newNode == NULL) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        newNode->data = malloc(size);
        if (newNode->data == NULL) {
            free(newNode);
            perror("Memory allocation failed");
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        newNode->next = NULL;
        pool->head = newNode;
    }
    MemoryNode *temp = pool->head;
    pool->head = pool->head->next;
    pthread_mutex_unlock(&pool->lock);
    return temp->data;
}

void deallocateToPool(MemoryPool *pool, void *ptr) {
    pthread_mutex_lock(&pool->lock);
    MemoryNode *newNode = (MemoryNode *)malloc(sizeof(MemoryNode));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&pool->lock);
        return;
    }
    newNode->data = ptr;
    newNode->next = pool->head;
    pool->head = newNode;
    pthread_mutex_unlock(&pool->lock);
}

void compactMemoryPool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    MemoryNode *current = pool->head;
    while (current != NULL && current->next != NULL) {
        if (current->data == NULL) {
            MemoryNode *temp = current->next;
            free(current);
            current = temp;
            pool->head = current;
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void* createNFAPI_Crc_Indication_PDU(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T *newPdu = (NFAPI_CRC_INDICATION_PDU_T *)allocateFromPool(&memoryPool, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newPdu == NULL) {
        return NULL;
    }
    newPdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newPdu->RNTI = RNTI;
    newPdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newPdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return (void *)newPdu;
}

void freeNFAPI_Crc_Indication_PDU(void *pdu) {
    deallocateToPool(&memoryPool, pdu);
}

int main() {
    initializeMemoryPool(&memoryPool);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, createNFAPI_Crc_Indication_PDU, &i);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    compactMemoryPool(&memoryPool);

    return 0;
}
