    size_t size;
    int used;
    struct BufferPool* next;
} BufferPool;

BufferPool* pool = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_buffer() {
    pthread_mutex_lock(&mutex);
    if (pool && !pool->used) {
        NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)pool->buffer;
        pool->used = 1;
        pthread_mutex_unlock(&mutex);
        return result;
    } else {
        pthread_mutex_unlock(&mutex);
        return NULL; // Allocation failed
    }
}

void deallocate_buffer(NFAPI_CRC_INDICATION_PDU_T* buffer) {
    pthread_mutex_lock(&mutex);
    buffer->RNTI = 0; // Clear RNTI to indicate free
    pool = (BufferPool*)buffer;
    pool->used = 0;
    pthread_mutex_unlock(&mutex);
}

void resize_pool(size_t new_size) {
    pthread_mutex_lock(&mutex);
    if (new_size > pool->size) {
        void* new_buffer = realloc(pool, NFAPI_CRC_INDICATION_PDU_T_SIZE * new_size);
        if (new_buffer) {
            pool = (BufferPool*)new_buffer;
            pool->size = new_size;
        }
    } else if (new_size < pool->size / 2) {
        void* new_buffer = realloc(pool, NFAPI_CRC_INDICATION_PDU_T_SIZE * new_size);
        if (new_buffer) {
            pool = (BufferPool*)new_buffer;
            pool->size = new_size;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void validate_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    // Perform validation checks
    if (structure->RNTI == 0 || structure->CRCFLAG > 1) {
        printf("Validation failed for structure\n");
    } else {
        printf("Structure is valid\n");
    }
}

void compact_pool() {
    pthread_mutex_lock(&mutex);
    size_t used_count = 0;
    BufferPool* current = pool;
    while (current) {
        if (!current->used) {
            // Reorganize memory
            memmove((char*)pool + NFAPI_CRC_INDICATION_PDU_T_SIZE * used_count, 
                    current, 
                    NFAPI_CRC_INDICATION_PDU_T_SIZE);
            current = (BufferPool*)((char*)pool + NFAPI_CRC_INDICATION_PDU_T_SIZE * used_count);
        } else {
            used_count++;
            current = current->next;
        }
    }
    pool->size = used_count;
    pthread_mutex_unlock(&mutex);
}

void* allocate_pool(size_t size) {
    pool = (BufferPool*)malloc(NFAPI_CRC_INDICATION_PDU_T_SIZE * size);
    if (!pool) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    for (size_t i = 0; i < size; i++) {
        pool[i].buffer = (void*)((char*)pool + NFAPI_CRC_INDICATION_PDU_T_SIZE * i);
        pool[i].size = NFAPI_CRC_INDICATION_PDU_T_SIZE;
        pool[i].used = 0;
    }
    return pool;
}

void free_pool() {
    pthread_mutex_lock(&mutex);
    free(pool);
    pool = NULL;
    pthread_mutex_unlock(&mutex);
}
