NR_UE_Measurement_List* nr_ue_measurement_list_init() {
    NR_UE_Measurement_List *list = (NR_UE_Measurement_List*)malloc(sizeof(NR_UE_Measurement_List));
    if (!list) return NULL;

    list->reports = (NR_UE_Measurement_Report**)malloc(MAX_UE_REPORTS * sizeof(NR_UE_Measurement_Report*));
    if (!list->reports) {
        free(list);
        return NULL;
    }

    memset(list->reports, 0, MAX_UE_REPORTS * sizeof(NR_UE_Measurement_Report*));
    list->count = 0;
    list->capacity = MAX_UE_REPORTS;

    return list;
}

int nr_ue_measurement_list_insert(NR_UE_Measurement_List *list, NR_UE_Measurement_Report *report) {
    if (!list || !report || list->count >= list->capacity) return -1;

    list->reports[list->count++] = report;
    return 0;
}

NR_UE_Measurement_Report* nr_ue_measurement_list_get(NR_UE_Measurement_List *list, int nr_ue_id) {
    if (!list || nr_ue_id < 0) return NULL;

    for (size_t i = 0; i < list->count; ++i) {
        if (list->reports[i]->nr_ue_id == nr_ue_id) {
            return list->reports[i];
        }
    }

    return NULL;
}

void nr_ue_measurement_list_free(NR_UE_Measurement_List *list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        free(list->reports[i]->report);
        free(list->reports[i]);
    }

    free(list->reports);
    free(list);
}
