void insert_record(DistributedList *dlist, const char *key, float value) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->data.key = strdup(key);
    new_node->data.value = value;
    new_node->next = NULL;
    new_node->prev = dlist->tail;

    if (dlist->head == NULL) {
