#include <string.h>
#include <pthread.h>

typedef struct {
    char sessionId[100];
    char userId[50];
    double dataTransferRate;
    int sessionDuration;
    int networkLatency;
} UserSessionLog;

typedef struct SessionNode {
    UserSessionLog log;
    struct SessionNode* next;
} SessionNode;

typedef struct {
    pthread_mutex_t lock;
    SessionNode* head;
    int activeSessions;
} UserSessionManager;

void initializeUserSessionManager(UserSessionManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->head = NULL;
    manager->activeSessions = 0;
}

int insertUserSessionLog(UserSessionManager* manager, const char* sessionId, const char* userId, double dataTransferRate, int sessionDuration, int networkLatency) {
    pthread_mutex_lock(&manager->lock);

    SessionNode* newNode = (SessionNode*)malloc(sizeof(SessionNode));
    if (!newNode) {
        return -1; // Memory allocation failed
    }

    strcpy(newNode->log.sessionId, sessionId);
    strcpy(newNode->log.userId, userId);
    newNode->log.dataTransferRate = dataTransferRate;
    newNode->log.sessionDuration = sessionDuration;
    newNode->log.networkLatency = networkLatency;

    newNode->next = manager->head;
    manager->head = newNode;
    manager->activeSessions++;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

UserSessionLog* retrieveUserSessionLog(UserSessionManager* manager, const char* sessionId) {
    pthread_mutex_lock(&manager->lock);

    SessionNode* current = manager->head;
    while (current != NULL) {
        if (strcmp(current->log.sessionId, sessionId) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return &current->log;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Session not found
}

void cleanupUserSessionLogs(UserSessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    SessionNode* current = manager->head;
    while (current != NULL) {
        SessionNode* temp = current;
        current = current->next;
        free(temp);
    }
    manager->head = NULL;
    manager->activeSessions = 0;

    pthread_mutex_unlock(&manager->lock);
}

void destroyUserSessionManager(UserSessionManager* manager) {
    cleanupUserSessionLogs(manager);
    pthread_mutex_destroy(&manager->lock);
}
