#[derive(Debug)]
enum AppError {
    Io(std::io::Error),
    Reqwest(reqwest::Error),
    Config(String),
}

impl From<std::io::Error> for AppError {
    fn from(err: std::io::Error) -> Self {
        AppError::Io(err)
    }
}

impl From<reqwest::Error> for AppError {
    fn from(err: reqwest::Error) -> Self {
        AppError::Reqwest(err)
    }
}

async fn create_directory_and_authenticate(
    dir_name: &str,
    config_service: &ConfigService,
    client_id: &str,
    client_secret: &str,
) -> Result<(), AppError> {
    let existing_dir = env::var(dir_name).map_or(false, |path| fs::metadata(path).is_ok());

    if !existing_dir {
        let path = config_service.validate_and_get_path(dir_name)?;
        fs::create_dir_all(&path)?;
        env::set_var(dir_name, &path);
    }

    let token = authenticate_user(client_id, client_secret, &config_service.get_auth_config()).await?;
    let user_info = get_user_information(&token).await?;

    println!("Directory: {:?}, User Info: {:?}", path, user_info);

    Ok(())
}

async fn authenticate_user(
    client_id: &str,
    client_secret: &str,
    auth_config: &AuthConfig,
) -> Result<String, AppError> {
    let client = Client::new();
    let response = client.post(&auth_config.token_url)
        .form(&[
            ("client_id", client_id),
            ("client_secret", client_secret),
            ("grant_type", "client_credentials"),
        ])
        .send()
        .await?;
    let token_response: TokenResponse = response.json().await?;
    Ok(token_response.access_token)
}

async fn get_user_information(access_token: &str) -> Result<UserInfo, AppError> {
    let client = Client::new();
    let response = client.get("https://api.example.com/user")
        .header("Authorization", format!("Bearer {}", access_token))
        .send()
        .await?;
    let user_info: UserInfo = response.json().await?;
    Ok(user_info)
}

fn md5_hash(input: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(input);
    let result = hasher.finalize();
    format!("{:x}", result)
}

