#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 100000

typedef struct {
    int session_id;
    int user_identifier;
    char activity_log[256];
} UserSessionLog;

typedef struct {
    UserSessionLog *logs;
    int size;
    pthread_mutex_t lock;
} SessionManager;

int initialize_session_manager(SessionManager *manager) {
    manager->logs = malloc(sizeof(UserSessionLog) * MAX_SESSIONS);
    if (manager->logs == NULL) {
        return -1; // Memory allocation failed
    }
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return 0;
}

int add_session(SessionManager *manager, int session_id, int user_identifier, const char *activity_log) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= MAX_SESSIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Maximum sessions reached
    }
    manager->logs[manager->size].session_id = session_id;
    manager->logs[manager->size].user_identifier = user_identifier;
    strncpy(manager->logs[manager->size].activity_log, activity_log, 256);
    manager->size++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int get_session(SessionManager *manager, int session_id, UserSessionLog *result) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->size; i++) {
        if (manager->logs[i].session_id == session_id) {
            *result = manager->logs[i];
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

void cleanup_session_manager(SessionManager *manager) {
    free(manager->logs);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    SessionManager manager;
    if (initialize_session_manager(&manager) != 0) {
        printf("Failed to initialize session manager\n");
        return 1;
    }

    UserSessionLog new_session = {1, 12345, "Data transfer rate: 100Mbps"};
    if (add_session(&manager, 1, 12345, new_session.activity_log) != 0) {
        printf("Failed to add session\n");
        cleanup_session_manager(&manager);
        return 1;
    }

    UserSessionLog retrieved_session;
    if (get_session(&manager, 1, &retrieved_session) == 0) {
        printf("Retrieved session: ID=%d, User=%d, Activity=%s\n", retrieved_session.session_id, retrieved_session.user_identifier, retrieved_session.activity_log);
    } else {
        printf("Failed to retrieve session\n");
    }

    cleanup_session_manager(&manager);
    return 0;
}
