#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint32_t packetID;
    char sourceIP[16];
    char destinationIP[16];
    struct PacketMetrics_TAG {
        size_t packetSize;
        double transmissionTime;
        double errorRate;
    } metrics;
} NetworkPacketBuffer;

typedef struct {
    NetworkPacketBuffer *buffer;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PacketCollection;

int initPacketCollection(PacketCollection *collection, size_t initialCapacity) {
    collection->buffer = malloc(initialCapacity * sizeof(NetworkPacketBuffer));
    if (!collection->buffer) return -1;
    collection->capacity = initialCapacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return 0;
}

int insertPacket(PacketCollection *collection, NetworkPacketBuffer *packet) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        NetworkPacketBuffer *newBuffer = realloc(collection->buffer, newCapacity * sizeof(NetworkPacketBuffer));
        if (!newBuffer) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->buffer = newBuffer;
        collection->capacity = newCapacity;
    }
    collection->buffer[collection->count++] = *packet;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

NetworkPacketBuffer* retrievePacket(PacketCollection *collection, uint32_t packetID) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->buffer[i].packetID == packetID) {
            pthread_mutex_unlock(&collection->lock);
            return &collection->buffer[i];
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

int cleanupPackets(PacketCollection *collection, double timeThreshold) {
    pthread_mutex_lock(&collection->lock);
    size_t newCount = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->buffer[i].metrics.transmissionTime > timeThreshold) {
            continue;
        }
        collection->buffer[newCount++] = collection->buffer[i];
    }
    collection->count = newCount;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void destroyPacketCollection(PacketCollection *collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->buffer);
}

int main() {
    PacketCollection collection;
    initPacketCollection(&collection, 1024);

    NetworkPacketBuffer packet = { .packetID = 1, .sourceIP = "192.168.1.1", .destinationIP = "192.168.1.2" };
    insertPacket(&collection, &packet);

    NetworkPacketBuffer *retrievedPacket = retrievePacket(&collection, 1);
    if (retrievedPacket) {
        printf("Retrieved packet ID: %u\n", retrievedPacket->packetID);
    }

    cleanupPackets(&collection, 0.5);

    destroyPacketCollection(&collection);
    return 0;
}
