using System;
using System.Collections.Concurrent;
using System.Threading;

public class DynamicValueGenerator
{
    private readonly ConcurrentDictionary<string, Range> ranges = new ConcurrentDictionary<string, Range>();
    private readonly ILoggerService loggerService;
    private readonly Random random;

    public DynamicValueGenerator(ILoggerService loggerService)
    {
        this.loggerService = loggerService;
        this.random = new Random();
    }

    public void SetRange(string key, Range range)
    {
        ranges[key] = range;
    }

    public int GenerateRandomInt(string key)
    {
        if (ranges.TryGetValue(key, out var range) && range.IsValid())
        {
            return random.Next(range.MinValue, range.MaxValue + 1);
        }
        else
        {
            loggerService.LogError("Invalid range for key: " + key);
            throw new ArgumentException("Invalid range");
        }
    }

    public float GenerateRandomFloat(string key)
    {
        if (ranges.TryGetValue(key, out var range) && range.IsValid())
        {
            return (float)(random.NextDouble() * (range.MaxValue - range.MinValue)) + range.MinValue;
        }
        else
        {
            loggerService.LogError("Invalid range for key: " + key);
            throw new ArgumentException("Invalid range");
        }
    }

    public void GenerateAndLogPduStructures(int n)
    {
        var pduArray = new NFAPI_CRC_INDICATION_PDU_T[n];
        int crcFlagCount = 0;
        double targetRatio = 0.1;

        for (int i = 0; i < n; i++)
        {
            var pdu = new NFAPI_CRC_INDICATION_PDU_T
            {
                RX_UE_INFORMATION_TAG = GenerateRandomInt("RX_UE_INFORMATION_TAG"),
                RNTI = GenerateRandomInt("RNTI")
            };

            double probability = random.NextDouble();
            if (probability < targetRatio)
            {
                pdu.CRCFLAG = 1;
                crcFlagCount++;
            }
            else
            {
                pdu.CRCFLAG = 0;
            }

            pduArray[i] = pdu;

            // Adjust the probability threshold dynamically based on achieved ratio
            double currentRatio = (double)crcFlagCount / (i + 1);
            if (currentRatio < targetRatio - 0.05)
            {
                targetRatio -= 0.01;
            }
            else if (currentRatio > targetRatio + 0.05)
            {
                targetRatio += 0.01;
            }

            loggerService.LogInfo($"Generated PDU {i}: RX_UE_INFORMATION_TAG = {pdu.RX_UE_INFORMATION_TAG}, RNTI = {pdu.RNTI}, CRCFLAG = {pdu.CRCFLAG}");
        }
    }
}

public class Range
{
    public int MinValue { get; set; }
    public int MaxValue { get; set; }

    public bool IsValid()
    {
        return MinValue <= MaxValue;
    }
}

public class NFAPI_CRC_INDICATION_PDU_T
{
    public int RX_UE_INFORMATION_TAG { get; set; }
    public int RNTI { get; set; }
    public int CRCFLAG { get; set; }
}
