typedef struct {
    MAC_PDU_T *pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} PacketCollection;

// Function to initialize the packet collection
void init_packet_collection(PacketCollection *collection) {
    collection->capacity = MAX_PACKETS;
    collection->size = 0;
    collection->pdus = (MAC_PDU_T *)malloc(collection->capacity * sizeof(MAC_PDU_T));
    if (!collection->pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&collection->lock, NULL);
}

// Function to insert a new packet into the collection
int insert_packet(PacketCollection *collection, NetworkPacketBuffer *packet) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        fprintf(stderr, "Packet buffer is full\n");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    // Copy packet data into the array
    memcpy(&collection->pdus[collection->size], packet, sizeof(MAC_PDU_T));
    collection->size++;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Function to retrieve a packet by its ID
MAC_PDU_T *get_packet(PacketCollection *collection, int packet_id) {
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->pdus[i].PREAMBLE_TAG == packet_id) {
            return &collection->pdus[i];
        }
    }
    return NULL;
}

// Function to perform periodic cleanup of the packet collection
void cleanup_packets(PacketCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    size_t i = 0;
    while (i < collection->size) {
        // Implement cleanup logic based on specific criteria
        if (/* Cleanup condition */) {
            memcpy(&collection->pdus[i], &collection->pdus[collection->size - 1], sizeof(MAC_PDU_T));
            collection->size--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

// Function to destroy the packet collection
void destroy_packet_collection(PacketCollection *collection) {
    free(collection->pdus);
    pthread_mutex_destroy(&collection->lock);
}
```

This code snippet provides a basic implementation of a `PacketCollection` structure with functions for initialization, insertion, retrieval, cleanup, and destruction. The use of a mutex ensures thread-safe operations, and the function handles memory allocation failures gracefully by terminating the program if memory cannot be allocated. Additional error checking mechanisms should be added as needed to handle invalid inputs and edge cases.']

