#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000000

typedef struct {
    int packetID;
    char sourceIP[16];
    char destinationIP[16];
    // Add other fields as needed
} PacketMetrics_TAG;

typedef struct {
    char PREAMBLE_TAG[8];
    unsigned short SCHID;
    unsigned short SEQUENCE_NUMBER;
    PacketMetrics_TAG metrics;
} MAC_PDU_T;

typedef struct {
    MAC_PDU_T** packets;
    int size;
    int capacity;
    pthread_mutex_t lock;
} NetworkPacketBufferManager;

NetworkPacketBufferManager* createPacketBufferManager() {
    NetworkPacketBufferManager* manager = (NetworkPacketBufferManager*)malloc(sizeof(NetworkPacketBufferManager));
    if (!manager) return NULL;

    manager->packets = (MAC_PDU_T**)malloc(MAX_PACKETS * sizeof(MAC_PDU_T*));
    if (!manager->packets) {
        free(manager);
        return NULL;
    }

    manager->size = 0;
    manager->capacity = MAX_PACKETS;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroyPacketBufferManager(NetworkPacketBufferManager* manager) {
    for (int i = 0; i < manager->size; i++) {
        free(manager->packets[i]);
    }
    free(manager->packets);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int insertPacket(NetworkPacketBufferManager* manager, MAC_PDU_T* packet) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        int newCapacity = manager->capacity * 2;
        MAC_PDU_T** newPackets = (MAC_PDU_T**)realloc(manager->packets, newCapacity * sizeof(MAC_PDU_T*));
        if (!newPackets) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->packets = newPackets;
        manager->capacity = newCapacity;
    }

    for (int i = 0; i < manager->size; i++) {
        if (strcmp(manager->packets[i]->PREAMBLE_TAG, packet->PREAMBLE_TAG) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Duplicate PREAMBLE_TAG found
        }
    }

    manager->packets[manager->size++] = packet;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

MAC_PDU_T* getPacket(NetworkPacketBufferManager* manager, int packetID) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->size; i++) {
        if (manager->packets[i]->metrics.packetID == packetID) {
            MAC_PDU_T* result = manager->packets[i];
            pthread_mutex_unlock(&manager->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Packet not found
}

int cleanupExpiredPackets(NetworkPacketBufferManager* manager, time_t currentTime) {
    int removedCount = 0;

    pthread_mutex_lock(&manager->lock);

    for (int i = manager->size - 1; i >= 0; i--) {
        if (currentTime - manager->packets[i]->metrics.transmissionTime > 60) { // Example: Remove packets older than 60 seconds
            free(manager->packets[i]);
            memmove(&manager->packets[i], &manager->packets[i + 1], (manager->size - i - 1) * sizeof(MAC_PDU_T*));
            manager->size--;
            removedCount++;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return removedCount;
}
