using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading.Tasks;

public class SecureAuthValueGenerator : IDisposable
{
    private readonly ConcurrentQueue<NFAPI_CRC_INDICATION_PDU_T> _queue = new();
    private readonly Random _random = new();
    private readonly ILogger _logger;
    private int _crcFlagCount;
    private double _targetRatio = 0.1;

    public SecureAuthValueGenerator(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        Task.Run(ProcessQueue);
    }

    public void GenerateAndLogValues(int count, float minValue, float maxValue, int minRnti, int maxRnti)
    {
        if (count <= 0 || minValue >= maxValue || minRnti >= maxRnti)
        {
            _logger.LogWarning("Invalid range specified. Generating default values.");
            GenerateAndLogValues(count, 0f, 1f, 0, 1023);
            return;
        }

        for (int i = 0; i < count; i++)
        {
            var pdu = new NFAPI_CRC_INDICATION_PDU_T
            {
                RX_UE_INFORMATION_TAG = GenerateRandomValue(minValue, maxValue),
                RNTI = GenerateRandomInt(minRnti, maxRnti)
            };

            if (_random.NextDouble() < _targetRatio)
            {
                pdu.CRCFLAG = 1;
                Interlocked.Increment(ref _crcFlagCount);
            }

            _queue.Enqueue(pdu);
        }
    }

    private double GenerateRandomValue(float minValue, float maxValue)
    {
        return _random.NextDouble() * (maxValue - minValue) + minValue;
    }

    private int GenerateRandomInt(int min, int max)
    {
        return _random.Next(min, max + 1);
    }

    private void ProcessQueue()
    {
        while (true)
        {
            if (_queue.TryDequeue(out var pdu))
            {
                // Simulate processing and logging
                _logger.LogInfo($"Processed PDU: {pdu}");
            }
        }
    }

    public double GetCrcFlagRatio()
    {
        return Interlocked.Read(ref _crcFlagCount) / (double)_queue.Count;
    }

    public void Dispose()
    {
        // Cleanup resources if necessary
    }
}
