#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 1000

typedef struct NetworkEvent {
    int id;
    time_t timestamp;
    int status_flag;
} NetworkEvent;

typedef struct EventList {
    NetworkEvent events[MAX_EVENTS];
    int count;
    pthread_mutex_t mutex;
} EventList;

void initialize_event_list(EventList *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_event_to_list(EventList *list, NetworkEvent event) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_EVENTS) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List full
    }
    list->events[list->count++] = event;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void cleanup_old_events(EventList *list, time_t retention_period) {
    pthread_mutex_lock(&list->mutex);
    int i = 0;
    while (i < list->count) {
        if ((time(NULL) - list->events[i].timestamp) > retention_period) {
            for (; i + 1 < list->count; i++) {
                list->events[i] = list->events[i + 1];
            }
            list->count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void *process_events(void *arg) {
    EventList *list = (EventList *)arg;
    NetworkEvent event;
    while (1) {
        pthread_mutex_lock(&list->mutex);
        if (list->count > 0) {
            event = list->events[--list->count];
        }
        pthread_mutex_unlock(&list->mutex);
        // Process the event
    }
}

void generate_report(EventList *list, FILE *output_file) {
    pthread_mutex_lock(&list->mutex);
    int total_events = list->count;
    time_t start_time = list->events[0].timestamp;
    time_t end_time = list->events[list->count - 1].timestamp;
    double average_duration = 0.0;
    int event_type_distribution[10] = {0};

    for (int i = 0; i < list->count; i++) {
        average_duration += difftime(list->events[i + 1].timestamp, list->events[i].timestamp);
        event_type_distribution[list->events[i].status_flag]++;
    }

    average_duration /= (list->count - 1);

    fprintf(output_file, "Total Events: %d\n", total_events);
    fprintf(output_file, "Average Event Duration: %.2f seconds\n", average_duration);
    for (int i = 0; i < 10; i++) {
        fprintf(output_file, "Event Type %d Count: %d\n", i, event_type_distribution[i]);
    }
    pthread_mutex_unlock(&list->mutex);
}

void set_max_events(EventList *list, int max_events) {
    pthread_mutex_lock(&list->mutex);
    MAX_EVENTS = max_events;
    pthread_mutex_unlock(&list->mutex);
}
