```javascript
async function authenticateUser(userId, sessionToken, encryptedPasswordHash) {
  try {
    // Validate input parameters
    if (!userId || !sessionToken || !encryptedPasswordHash) {
      throw new Error('Missing required parameters');
    }

    // Fetch user data from external API
    const userData = await fetchUserDataFromAPI(userId, sessionToken);

    // Verify credentials using a service class
    const isCredentialValid = await verifyCredentials(userData, encryptedPasswordHash);

    if (isCredentialValid) {
      applyStylesToAuthenticatedElements();
    } else {
      handleAuthenticationFailure();
    }
  } catch (error) {
    console.error('Authentication failed:', error);
    handleAuthenticationFailure();
  }
}

async function fetchUserDataFromAPI(userId, sessionToken) {
  const response = await fetch(`/api/user/${userId}`, {
    headers: {
      'Authorization': `Bearer ${sessionToken}`
    }
  });
  if (!response.ok) {
    throw new Error('Failed to fetch user data');
  }
  return response.json();
}

async function verifyCredentials(userData, encryptedPasswordHash) {
  // Assume a service class for credential verification
  const authService = new AuthService();
  return authService.verify(encryptedPasswordHash, userData.passwordHash);
}

function applyStylesToAuthenticatedElements() {
  const elements = document.querySelectorAll('.authenticated, #user-specific');
  elements.forEach(element => {
    element.style.backgroundColor = 'lightgreen';
  });
}

function handleAuthenticationFailure() {
  alert('Invalid credentials. Please try again.');
}
```

### Python Function for MD5 Hash of a File

```python
import hashlib
import os
from time import time, sleep

def calculate_md5_hash(file_path):
    start_time = time()
    md5_hash = hashlib.md5()
    total_size = os.path.getsize(file_path)
    chunk_size = 8192
    chunks_processed = 0

    with open(file_path, 'rb') as file:
        while True:
            data = file.read(chunk_size)
            if not data:
                break
            md5_hash.update(data)

            # Progress indicator
            chunks_processed += 1
            progress = (chunks_processed * chunk_size) / total_size
            if progress % 0.1 == 0:
                estimated_time_left = ((time() - start_time) / progress) * (1 - progress)
                print(f"Processed {progress * 100:.2f}% in {int(estimated_time_left)} seconds")

    end_time = time()
    total_processing_time = end_time - start_time
    return md5_hash.hexdigest(), f"Total processing time: {total_processing_time} seconds"

# Example usage
file_path = 'path/to/large/file.txt'
hash_value, log_message = calculate_md5_hash(file_path)
print(f"MD5 Hash: {hash_value}")
print(log_message)
