#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <regex.h>
#include <sys/types.h>
#include <dirent.h>

#define MAX_LINE_LENGTH 1024

void print_usage() {
    printf("Usage: program_name [options] file1 file2 ...\n");
    printf("Options:\n");
    printf("  --manpage     Display help and exit\n");
    printf("  -cs           Case-sensitive pattern matching\n");
    printf("  -o output_file Redirect output to a specific file\n");
    printf("  -p pattern     Use regular expression for filtering\n");
}

int process_file(const char *filename, regex_t *pattern, FILE *output) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    int line_count = 0;
    size_t total_chars = 0;
    char buffer[MAX_LINE_LENGTH];

    while (fgets(buffer, sizeof(buffer), file)) {
        line_count++;
        total_chars += strlen(buffer);
        if (pattern) {
            regmatch_t matches[256];
            int match_result = regexec(pattern, buffer, 256, matches, 0);
            if (match_result == 0) {
                fprintf(output, "Match found in line %d\n", line_count);
            }
        }
    }

    fclose(file);
    fprintf(output, "File: %s, Lines: %d, Total Characters: %zu\n", filename, line_count, total_chars);
    return 0;
}

int main(int argc, char *argv[]) {
    regex_t pattern;
    int case_sensitive = 0;
    FILE *output = stdout;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            print_usage();
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0) {
            case_sensitive = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output = fopen(argv[++i], "w");
            if (!output) {
                perror("Failed to open output file");
                return -1;
            }
        } else if (strcmp(argv[i], "-p") == 0 && i + 1 < argc) {
            int ret = regcomp(&pattern, argv[++i], REG_EXTENDED | (case_sensitive ? 0 : REG_ICASE));
            if (ret != 0) {
                char msgbuf[100];
                regerror(ret, &pattern, msgbuf, sizeof(msgbuf));
                fprintf(stderr, "Could not compile regex: %s\n", msgbuf);
                return -1;
            }
        } else if (argv[i][0] == '-') {
            fprintf(stderr, "Unknown option: %s\n", argv[i]);
            print_usage();
            return -1;
        } else {
            break; // Stop processing options and start processing files
        }
    }

    for (; i < argc; i++) {
        if (process_file(argv[i], pattern ? &pattern : NULL, output) != 0) {
            fprintf(stderr, "Error processing file: %s\n", argv[i]);
        }
    }

    if (output != stdout) {
        fclose(output);
    }

    regfree(&pattern);
    return 0;
}
