#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CONNECTIONS 1000

typedef struct {
    int page_section_id;
    int element_id;
    char *new_html_content;
} UpdateRequest;

typedef struct {
    UpdateRequest requests[MAX_CONNECTIONS];
    pthread_mutex_t mutex;
    sem_t available_slots;
} NetworkServiceClass;

void init_service(NetworkServiceClass *service) {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        service->requests[i].new_html_content = NULL;
    }
    pthread_mutex_init(&service->mutex, NULL);
    sem_init(&service->available_slots, 0, MAX_CONNECTIONS);
}

void update_element(NetworkServiceClass *service, int page_section_id, int element_id, const char *new_html_content) {
    sem_wait(&service->available_slots);
    UpdateRequest *request = NULL;
    pthread_mutex_lock(&service->mutex);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (service->requests[i].new_html_content == NULL) {
            request = &service->requests[i];
            break;
        }
    }
    if (request != NULL) {
        request->page_section_id = page_section_id;
        request->element_id = element_id;
        request->new_html_content = strdup(new_html_content);
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Set CRC flag and update HTML content
        pthread_mutex_unlock(&service->mutex);
        sem_post(&service->available_slots);
        send_confirmation_message();
    } else {
        pthread_mutex_unlock(&service->mutex);
        sem_post(&service->available_slots);
        log_error("No available slots for new request");
    }
}

void *handle_request(void *arg) {
    NetworkServiceClass *service = (NetworkServiceClass *)arg;
    while (1) {
        UpdateRequest request;
        pthread_mutex_lock(&service->mutex);
        for (int i = 0; i < MAX_CONNECTIONS; i++) {
            if (service->requests[i].new_html_content != NULL) {
                memcpy(&request, &service->requests[i], sizeof(UpdateRequest));
                service->requests[i].new_html_content = NULL;
                break;
            }
        }
        pthread_mutex_unlock(&service->mutex);
        if (request.new_html_content != NULL) {
            update_element_on_web_app(request.page_section_id, request.element_id, request.new_html_content);
            free((void *)request.new_html_content);
        }
    }
}

int main() {
    NetworkServiceClass service;
    init_service(&service);
    pthread_t threads[MAX_CONNECTIONS];
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pthread_create(&threads[i], NULL, handle_request, &service);
    }
    // Simulate incoming requests
    update_element(&service, 1, 2, "<p>New content</p>");
    update_element(&service, 3, 4, "<div>Updated div</div>");
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
