#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <regex.h>
#include <sys/types.h>
#include <sys/stat.h>

#define MAX_WORD_LENGTH 1024

typedef struct {
    int word_count;
    int unique_word_count;
    double average_word_length;
} FileReport;

void process_file(const char *file_path, FileReport *report) {
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    // Read file and count words
    char buffer[MAX_WORD_LENGTH];
    int word_count = 0;
    int unique_word_count = 0;
    regex_t re;
    regcomp(&re, "[a-zA-Z]+", REG_EXTENDED);

    while (fgets(buffer, sizeof(buffer), file)) {
        char *token = strtok(buffer, " \t\n");
        while (token != NULL) {
            word_count++;
            // Check if the token is a unique word
            int match;
            regexec(&re, token, 0, NULL, 0);
            if (match == 0) {
                unique_word_count++;
            }
            token = strtok(NULL, " \t\n");
        }
    }

    fclose(file);
    report->word_count = word_count;
    report->unique_word_count = unique_word_count;
    // Calculate average word length
    report->average_word_length = (double)word_count / unique_word_count;

    regfree(&re);
}

void generate_summary_report(const char *directory_path, const char *output_file, int min_size, regex_t *pattern) {
    DIR *dir;
    struct dirent *entry;
    if ((dir = opendir(directory_path)) == NULL) {
        perror("Error opening directory");
        return;
    }

    FILE *report_file = fopen(output_file, "w");
    if (report_file == NULL) {
        perror("Error opening report file");
        closedir(dir);
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        char file_path[1024];
        snprintf(file_path, sizeof(file_path), "%s/%s", directory_path, entry->d_name);

        struct stat file_stat;
        if (stat(file_path, &file_stat) == -1) {
            perror("Error getting file stats");
            continue;
        }

        if (file_stat.st_size < min_size) {
            continue;
        }

        FileReport report;
        process_file(file_path, &report);

        if (pattern != NULL) {
            // Check if the file content matches the pattern
            FILE *content_file = fopen(file_path, "r");
            char buffer[1024];
            int match_found = 0;
            while (fgets(buffer, sizeof(buffer), content_file)) {
                if (regexec(pattern, buffer, 0, NULL, 0) == 0) {
                    match_found = 1;
                    break;
                }
            }
            fclose(content_file);

            if (!match_found) {
                continue;
            }
        }

        fprintf(report_file, "File: %s\nWord Count: %d\nUnique Words: %d\nAverage Word Length: %.2f\n\n",
                entry->d_name, report.word_count, report.unique_word_count, report.average_word_length);
    }

    fclose(report_file);
    closedir(dir);
}

int main(int argc, char *argv[]) {
    // Parse command line options
    const char *directory_path = NULL;
    int min_size = 0;
    regex_t *pattern = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s -d directory_path [-s min_size] [-w pattern] [-o output_file]\n", argv[0]);
            exit(0);
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            directory_path = argv[++i];
        } else if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            min_size = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-w") == 0 && i + 1 < argc) {
            pattern = (regex_t *)malloc(sizeof(regex_t));
            if (regcomp(pattern, argv[++i], REG_EXTENDED) != 0) {
                fprintf(stderr, "Error compiling regular expression\n");
                exit(1);
            }
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            // Output file handling is already done in generate_summary_report
        } else {
            printf("Invalid option: %s\n", argv[i]);
            return 1;
        }
    }

    if (directory_path == NULL) {
        fprintf(stderr, "Directory path not specified\n");
        return 1;
    }

    const char *output_file = "summary_report.txt";
    generate_summary_report(directory_path, output_file, min_size, pattern);

    // Free memory for regular expression
    if (pattern != NULL) {
        regfree(pattern);
        free(pattern);
    }

    return 0;
}
