    manager->allocated_contexts = initial_size;
    manager->context_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->total_active_sessions = 0;
    return 0;
}

void destroy_session_manager(SessionManager *manager) {
    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
}

int add_session(SessionManager *manager, int ue_id, const char *session_id) {
    pthread_mutex_lock(&manager->lock);
    if (manager->context_count >= manager->allocated_contexts) {
        size_t new_size = manager->allocated_contexts * 2;
        UEContext *new_contexts = realloc(manager->contexts, new_size * sizeof(UEContext));
        if (!new_contexts) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Failed to allocate memory
        }
        manager->contexts = new_contexts;
        manager->allocated_contexts = new_size;
    }

    UEContext *context = &manager->contexts[manager->context_count];
    context->ue_id = ue_id;
    strncpy(context->session_list[0], session_id, 255);
    context->last_update = time(NULL);
    manager->total_active_sessions++;
    manager->context_count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void remove_inactive_sessions(SessionManager *manager, time_t inactivity_threshold) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->context_count;) {
        if (time(NULL) - manager->contexts[i].last_update > inactivity_threshold) {
            memmove(&manager->contexts[i], &manager->contexts[i + 1],
                    (manager->context_count - i - 1) * sizeof(UEContext));
            manager->total_active_sessions--;
        } else {
            i++;
        }
    }
    manager->context_count = manager->context_count > 0 ? manager->context_count : 0;
    pthread_mutex_unlock(&manager->lock);
}

size_t get_total_active_sessions(SessionManager *manager) {
    pthread_mutex_lock(&manager->lock);
    size_t total_sessions = manager->total_active_sessions;
    pthread_mutex_unlock(&manager->lock);
    return total_sessions;
}
```
