#define MAX_SLICES 10
#define MAX_SESSIONS_PER_SLICE 100
#define LOG_BUFFER_SIZE 1024

typedef struct Session {
    int session_id;
    time_t timestamp;
} Session;

typedef struct UEContext {
    int ue_id;
    Session *session_list;
    int session_count;
    pthread_mutex_t mutex;
} UEContext;

typedef struct SliceConfig {
    UEContext contexts[MAX_SESSIONS_PER_SLICE];
    int threshold;
    size_t limit;
    int in_use;
} SliceConfig;

typedef struct LogEntry {
    time_t timestamp;
    char message[256];
} LogEntry;

LogEntry log_buffer[LOG_BUFFER_SIZE];
int log_head = 0, log_tail = 0;
pthread_mutex_t log_mutex;

SliceConfig slices[MAX_SLICES];
int slice_count = 0;
pthread_mutex_t slice_mutex;

void log_event(const char *message) {
    pthread_mutex_lock(&log_mutex);
    log_entry = (LogEntry){time(NULL), message};
    log_buffer[log_head] = log_entry;
    log_head = (log_head + 1) % LOG_BUFFER_SIZE;
    pthread_mutex_unlock(&log_mutex);
}

int add_session(int slice_id, int ue_id, int session_id) {
    pthread_mutex_lock(&slice_mutex);
    if (slice_id >= slice_count || slices[slice_id].in_use == MAX_SESSIONS_PER_SLICE) {
        pthread_mutex_unlock(&slice_mutex);
        return -1; // Error: Invalid slice ID or no space in slice
    }

    UEContext *ue_context = &slices[slice_id].contexts[slices[slice_id].in_use];
    ue_context->ue_id = ue_id;
    ue_context->session_list = realloc(ue_context->session_list, (ue_context->session_count + 1) * sizeof(Session));
    if (!ue_context->session_list) {
        pthread_mutex_unlock(&slice_mutex);
        return -2; // Error: Memory allocation failed
    }

    Session new_session = {session_id, time(NULL)};
    ue_context->session_list[ue_context->session_count++] = new_session;
    log_event("Session added");
    slices[slice_id].in_use++;
    pthread_mutex_unlock(&slice_mutex);
    return 0; // Success
}

