using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;

public class DynamicValueGenerator
{
    private ConcurrentDictionary<string, ValueRange> _ranges = new ConcurrentDictionary<string, ValueRange>();
    private ILoggerService _logger;

    public DynamicValueGenerator(ILoggerService logger)
    {
        _logger = logger;
    }

    public void AddOrUpdateRange(string key, RangeType rangeType, float? min, float? max, bool inclusiveMin, bool inclusiveMax)
    {
        _ranges[key] = new ValueRange(rangeType, min, max, inclusiveMin, inclusiveMax);
    }

    public float GenerateRandomFloat(string key)
    {
        if (!_ranges.TryGetValue(key, out var range))
        {
            throw new ArgumentException("Invalid range key");
        }
        return GenerateRandomValue(range);
    }

    public int GenerateRandomInt(string key)
    {
        if (!_ranges.TryGetValue(key, out var range))
        {
            throw new ArgumentException("Invalid range key");
        }
        return (int)GenerateRandomValue(range);
    }

    private object _lock = new object();
    private Random _random = new Random();

    private float GenerateRandomValue(ValueRange range)
    {
        lock (_lock)
        {
            var value = 0.0f;
            do
            {
                if (range.RangeType == RangeType.Float)
                {
                    value = range.InclusiveMin ? _random.NextSingle() : _random.NextDouble();
                }
                else if (range.RangeType == RangeType.Int)
                {
                    value = _random.Next((int)range.Min, (int)range.Max);
                }
            } while ((value < range.Min || (value > range.Min && !range.InclusiveMin)) ||
                      (value > range.Max || (value < range.Max && !range.InclusiveMax)));

            _logger.Log(value);

            return value;
        }
    }

    public void CreateAndPopulateNFAPICRCIndicationPDU(int n, float crcProbability)
    {
        if (n <= 0) throw new ArgumentException("N must be greater than zero");

        var array = new NFAPI_CRC_INDICATION_PDU_T[n];
        int setCrcCount = 0;

        for (int i = 0; i < n; i++)
        {
            var pdu = new NFAPI_CRC_INDICATION_PDU_T
            {
                RX_UE_INFORMATION_TAG = GenerateRandomInt("RxUeInfo"),
                RNTI = GenerateRandomInt("Rnti"),
                CRC_INDICATION_REL8_TAG = _random.NextDouble() < crcProbability ? 1 : 0
            };

            array[i] = pdu;

            if (pdu.CRC_INDICATION_REL8_TAG == 1)
            {
                setCrcCount++;
            }
        }

        var achievedRatio = (float)setCrcCount / n;
        var memoryUsage = GC.GetTotalMemory(false);
        var executionTime = DateTime.Now - startTime;

        _logger.Log($"Set CRCFLAG ratio: {achievedRatio}, Memory Usage: {memoryUsage} bytes, Execution Time: {executionTime}");
    }
}

public enum RangeType
{
    Float,
    Int
}

public class ValueRange
{
    public RangeType RangeType { get; }
    public float? Min { get; }
    public float? Max { get; }
    public bool InclusiveMin { get; }
    public bool InclusiveMax { get; }

    public ValueRange(RangeType rangeType, float? min, float? max, bool inclusiveMin, bool inclusiveMax)
    {
        RangeType = rangeType;
        Min = min;
        Max = max;
        InclusiveMin = inclusiveMin;
        InclusiveMax = inclusiveMax;
    }
}

public interface ILoggerService
{
    void Log(object message);
}
