using System;
using System.Collections.Concurrent;
using System.Linq;

public class DynamicValueGenerator : IDisposable
{
    private Random _random = new Random();
    private ConcurrentDictionary<string, Range<float>> _floatRanges = new ConcurrentDictionary<string, Range<float>>();
    private ConcurrentDictionary<string, Range<int>> _intRanges = new ConcurrentDictionary<string, Range<int>>();
    private IExternalLoggingService _loggingService;
    private CancellationTokenSource _cancellationTokenSource;

    public DynamicValueGenerator(IExternalLoggingService loggingService)
    {
        _loggingService = loggingService;
        _cancellationTokenSource = new CancellationTokenSource();
    }

    public void AddFloatRange(string key, float start, float end, bool isExclusiveEnd)
    {
        if (start >= end) throw new ArgumentException("Invalid range");
        _floatRanges[key] = new Range<float>(start, end, isExclusiveEnd);
    }

    public void AddIntRange(string key, int start, int end, bool isExclusiveEnd)
    {
        if (start >= end) throw new ArgumentException("Invalid range");
        _intRanges[key] = new Range<int>(start, end, isExclusiveEnd);
    }

    public float GenerateRandomFloat(string key)
    {
        if (!_floatRanges.TryGetValue(key, out var range)) throw new KeyNotFoundException();
        return GenerateRandomValue(range);
    }

    public int GenerateRandomInt(string key)
    {
        if (!_intRanges.TryGetValue(key, out var range)) throw new KeyNotFoundException();
        return GenerateRandomValue(range);
    }

    private T GenerateRandomValue<T>(Range<T> range) where T : IComparable
    {
        var min = range.Min;
        var max = range.Max;
        var step = range.IsExclusiveEnd ? 1 : 0;

        while (_cancellationTokenSource.Token.IsCancellationRequested == false)
        {
            dynamic randomValue;
            if (typeof(T) == typeof(float))
                randomValue = _random.NextSingle(min, max);
            else
                randomValue = _random.Next((int)min, (int)(max + step));

            if (range.IsInRange(randomValue))
                return (T)randomValue;
        }

        throw new OperationCanceledException();
    }

    public void Dispose()
    {
        _cancellationTokenSource.Cancel();
        _loggingService.Dispose();
    }
}

public class Range<T> where T : IComparable
{
    public T Min { get; }
    public T Max { get; }
    public bool IsExclusiveEnd { get; }

    public Range(T min, T max, bool isExclusiveEnd)
    {
        Min = min;
        Max = max;
        IsExclusiveEnd = isExclusiveEnd;
    }

    public bool IsInRange(T value)
    {
        if (typeof(T) == typeof(float))
            return !IsExclusiveEnd
                ? Min.CompareTo(value) <= 0 && Max.CompareTo(value) >= 0
                : Min.CompareTo(value) < 0 && Max.CompareTo(value) > 0;
        else
            return !IsExclusiveEnd
                ? Min.CompareTo(value) <= 0 && Max.CompareTo(value) >= 0
                : Min.CompareTo(value) < 0 && Max.CompareTo(value) > 0;
    }
}

public interface IExternalLoggingService : IDisposable
{
    void Log(string message);
}
