    private readonly ILogger _logger;
    private readonly RateLimiter _rateLimiter;
    private readonly Random _random = new Random();

    public SecureAuthValueGenerator(ILogger logger, RateLimiter rateLimiter)
    {
        _logger = logger;
        _rateLimiter = rateLimiter;
    }

    public void SetRange(string key, float min, float max, bool inclusiveMin, bool inclusiveMax)
    {
        if (max < min) throw new ArgumentException("Max must be greater than or equal to Min.");
        var range = new ValueRange(min, max, inclusiveMin, inclusiveMax);
        _ranges[key] = range;
    }

    public float GenerateRandomFloat(string key)
    {
        if (!_ranges.TryGetValue(key, out var range))
            throw new ArgumentException("Key not found.");

        if (_rateLimiter.IsRateLimited())
        {
            _logger.LogWarning("Rate limit exceeded. Retrying...");
            return GenerateRandomFloat(key);
        }

        var value = _random.NextSingle();
        float result;
        if (range.InclusiveMin) result = range.Min * value + (1 - value) * range.Max;
        else result = range.Min + (range.Max - range.Min) * value;

        if (range.InclusiveMax && result == range.Max)
            return GenerateRandomFloat(key);

        _logger.LogValue(result);
        return result;
    }

