using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class DynamicRangeValueGenerator
{
    private ConcurrentDictionary<string, Range<float>> floatRanges = new ConcurrentDictionary<string, Range<float>>();
    private ConcurrentDictionary<string, Range<int>> intRanges = new ConcurrentDictionary<string, Range<int>>();

    public void SetFloatRange(string rangeName, float start, float end, bool isExclusiveEnd)
    {
        if (rangeName == null || start > end) throw new ArgumentException("Invalid range.");
        floatRanges[rangeName] = new Range<float>(start, end, isExclusiveEnd);
    }

    public void SetIntRange(string rangeName, int start, int end, bool isExclusiveEnd)
    {
        if (rangeName == null || start > end) throw new ArgumentException("Invalid range.");
        intRanges[rangeName] = new Range<int>(start, end, isExclusiveEnd);
    }

    public float GenerateFloatValue(string rangeName)
    {
        if (!floatRanges.ContainsKey(rangeName)) throw new ArgumentException("Range not set.");
        var range = floatRanges[rangeName];
        return GenerateRandomFloat(range.Start, range.End, range.IsExclusiveEnd);
    }

    public int GenerateIntValue(string rangeName)
    {
        if (!intRanges.ContainsKey(rangeName)) throw new ArgumentException("Range not set.");
        var range = intRanges[rangeName];
        return GenerateRandomInt(range.Start, range.End, range.IsExclusiveEnd);
    }

    private float GenerateRandomFloat(float start, float end, bool isExclusiveEnd)
    {
        Random rng = new Random();
        while (true)
        {
            float value = (float)rng.NextDouble() * (end - start) + start;
            if (!isExclusiveEnd && value >= end) continue; // Adjust to include the exclusive end
            return value;
        }
    }

    private int GenerateRandomInt(int start, int end, bool isExclusiveEnd)
    {
        Random rng = new Random();
        while (true)
        {
            int value = rng.Next(start, isExclusiveEnd ? end : end + 1);
            if (!isExclusiveEnd && value >= end) continue; // Adjust to include the exclusive end
            return value;
        }
    }

    public void LogValue(string rangeName, object value)
    {
        try
        {
            // Assuming a method to log values
            ExternalLoggingService.Log($"Range: {rangeName}, Value: {value}");
        }
        catch (Exception ex)
        {
            // Handle logging failures with retry logic and exponential backoff
            RetryWithExponentialBackoff(() => ExternalLoggingService.Log($"Range: {rangeName}, Value: {value}"), 10);
        }
    }

    private void RetryWithExponentialBackoff(Action action, int maxRetries)
    {
        for (int i = 0; i < maxRetries; i++)
        {
            try
            {
                action();
                return;
            }
            catch (Exception)
            {
                if (i == maxRetries - 1) throw;
                Thread.Sleep((int)Math.Pow(2, i));
            }
        }
    }
}

public class Range<T> where T : IComparable<T>
{
    public T Start { get; set; }
    public T End { get; set; }
    public bool IsExclusiveEnd { get; set; }

    public Range(T start, T end, bool isExclusiveEnd)
    {
        Start = start;
        End = end;
        IsExclusiveEnd = isExclusiveEnd;
    }
}

public static class ExternalLoggingService
{
    public static void Log(string message) => Console.WriteLine(message); // Mock logging service
}
