import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

public class NetworkRequestHandler {
    private final HttpClient httpClient;
    private final ExecutorService executorService;
    private final ConcurrentHashMap<String, CompletableFuture<String>> requestCache;
    private final AtomicInteger retryCount = new AtomicInteger(0);

    public NetworkRequestHandler(int poolSize) {
        this.httpClient = HttpClient.newBuilder()
                .connectTimeout(Duration.ofSeconds(10))
                .build();
        this.executorService = Executors.newFixedThreadPool(poolSize);
        this.requestCache = new ConcurrentHashMap<>();
    }

    public CompletableFuture<String> sendRequestAsync(String url) {
        if (requestCache.containsKey(url)) {
            return requestCache.get(url);
        }

        CompletableFuture<String> future = CompletableFuture.supplyAsync(() -> {
            for (int i = 0; i < 3; i++) { // Retry logic with exponential backoff
                try {
                    HttpRequest request = HttpRequest.newBuilder()
                            .uri(URI.create(url))
                            .timeout(Duration.ofSeconds(5))
                            .build();
                    HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
                    if (response.statusCode() == 200) {
                        return response.body();
                    } else {
                        throw new RuntimeException("Request failed with status code: " + response.statusCode());
                    }
                } catch (Exception e) {
                    retryCount.incrementAndGet();
                    System.out.println("Retry attempt " + i + ": " + e.getMessage());
                    try {
                        Thread.sleep((long) Math.pow(2, i) * 1000); // Exponential backoff
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        return null;
                    }
                }
            }
            throw new RuntimeException("Request failed after maximum retries");
        }, executorService);

        future.whenComplete((result, exception) -> requestCache.remove(url));

        return future;
    }

    public void shutdown() {
        executorService.shutdown();
    }

    public static void main(String[] args) {
        NetworkRequestHandler handler = new NetworkRequestHandler(10);
        CompletableFuture<String> responseFuture = handler.sendRequestAsync("https://api.example.com/data");
        responseFuture.thenAccept(System.out::println).exceptionally(e -> {
            System.err.println("Request failed: " + e.getMessage());
            return null;
        });

        try {
            Thread.sleep(5000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        handler.shutdown();
    }
}
