#define MAX_STRUCTURES 1000

NFAPI_CRC_INDICATION_PDU_T *allocate_structures(int N, int *error) {
    if (N > MAX_STRUCTURES) {
        *error = -1;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        *error = -2;
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    *error = 0;
    return array;
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T *array, int N) {
    if (array) {
        free(array);
    }
}

int validate_structures(NFAPI_CRC_INDICATION_PDU_T *array, int N) {
    for (int i = 0; i < N; i++) {
        if (array[i].RX_UE_INFORMATION_TAG == 0 || array[i].RNTI == 0 || array[i].CRC_INDICATION_REL8_TAG > 255) {
            return -1;
        }
    }
    return 0;
}

void *thread_function(void *arg) {
    int N = *(int *)arg;
    int error;
    NFAPI_CRC_INDICATION_PDU_T *array = allocate_structures(N, &error);
    if (error != 0) {
        printf("Failed to allocate structures\n");
        return NULL;
    }

    if (validate_structures(array, N) != 0) {
        printf("Invalid structure detected\n");
    } else {
        printf("Structures are valid\n");
    }

    free_structures(array, N);
    return NULL;
}

int main() {
    pthread_t threads[MAX_STRUCTURES];
    int N = 5;

    for (int i = 0; i < N; i++) {
        if (pthread_create(&threads[i], NULL, thread_function, &N) != 0) {
            printf("Failed to create thread\n");
            return 1;
        }
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
