import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;

public class NetworkRequestHandler {
    private final HttpClient httpClient;
    private final ExecutorService executorService;
    private final Semaphore semaphore;
    private final ConcurrentHashMap<String, String> memoryCache;

    public NetworkRequestHandler(int maxConnections, int maxConcurrentRequests) {
        this.httpClient = HttpClient.newBuilder()
                .version(HttpClient.Version.HTTP_2)
                .connectTimeout(Duration.ofSeconds(10))
                .build();
        this.executorService = Executors.newFixedThreadPool(maxConcurrentRequests);
        this.semaphore = new Semaphore(maxConnections);
        this.memoryCache = new ConcurrentHashMap<>();
    }

    public CompletableFuture<String> sendRequestAsync(String url, String method) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                semaphore.acquire();
                HttpRequest request = HttpRequest.newBuilder()
                        .uri(URI.create(url))
                        .method(method, HttpRequest.BodyPublishers.noBody())
                        .build();
                HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
                return response.body();
            } catch (IOException | InterruptedException e) {
                throw new RuntimeException("Request failed", e);
            } finally {
                semaphore.release();
            }
        }, executorService);
    }

    public String sendRequestSync(String url, String method) throws IOException, InterruptedException {
        semaphore.acquire();
        try {
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create(url))
                    .method(method, HttpRequest.BodyPublishers.noBody())
                    .build();
            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
            return response.body();
        } finally {
            semaphore.release();
        }
    }

    public String getFromCache(String url) {
        return memoryCache.get(url);
    }

    public void putInCache(String url, String data) {
        memoryCache.put(url, data);
    }
}
