#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <memory>
#include <atomic>
#include <chrono>

// Mock network library for demonstration purposes
class NetworkLibrary {
public:
    bool sendPacket(const std::string& packet) {
        // Simulate network transmission with a 10% chance of failure
        return (rand() % 10 != 0);
    }
};

class PacketProcessor {
private:
    static const int MAX_RETRIES = 5;
    static const std::chrono::milliseconds RETRY_DELAY(100);

    NetworkLibrary& networkLib;
    std::queue<std::string> packetQueue;
    std::mutex queueMutex;
    std::condition_variable dataCondition;
    std::atomic<bool> running{true};

public:
    PacketProcessor(NetworkLibrary& lib) : networkLib(lib) {}

    void startProcessing() {
        std::thread worker(&PacketProcessor::processPackets, this);
        worker.detach();
    }

    void stopProcessing() {
        running.store(false);
        dataCondition.notify_all();
    }

    void addPacket(const std::string& packet) {
        std::lock_guard<std::mutex> lock(queueMutex);
        packetQueue.push(packet);
        dataCondition.notify_one();
    }

private:
    void processPackets() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            dataCondition.wait(lock, [this] { return !packetQueue.empty() || !running.load(); });

            if (!running.load()) break;

            std::string packet = packetQueue.front();
            packetQueue.pop();

            lock.unlock();

            int retries = 0;
            while (retries < MAX_RETRIES) {
                if (networkLib.sendPacket(packet)) {
                    std::cout << "Packet sent successfully: " << packet << std::endl;
                    break;
                } else {
                    ++retries;
                    std::this_thread::sleep_for(RETRY_DELAY);
                    std::cout << "Transmission failed. Retrying..." << std::endl;
                }
            }

            if (retries == MAX_RETRIES) {
                std::cerr << "Failed to send packet after " << MAX_RETRIES << " retries: " << packet << std::endl;
            }
        }
    }
