#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_ID 1000
#define FRESHNESS_THRESHOLD 60

typedef struct {
    int ue_id;
    float rssi;
    time_t timestamp;
    char *decoded_packets;
} LTEPHYRXINFO_T;

typedef struct {
    int n_rnti;
    char decoded_payload[256];
} NFAPI_RX_FRAME_PDU_T;

typedef struct {
    LTEPHYRXINFO_T *list[MAX_UE_ID];
    int count;
    pthread_mutex_t mutex;
} DynamicList;

void init_list(DynamicList *dl) {
    dl->count = 0;
    pthread_mutex_init(&dl->mutex, NULL);
}

void add_packet(DynamicList *dl, LTEPHYRXINFO_T *packet) {
    pthread_mutex_lock(&dl->mutex);
    if (dl->count < MAX_UE_ID) {
        dl->list[dl->count] = packet;
        dl->count++;
    }
    pthread_mutex_unlock(&dl->mutex);
}

void remove_outdated_packets(DynamicList *dl, time_t current_time) {
    pthread_mutex_lock(&dl->mutex);
    for (int i = 0; i < dl->count; ) {
        if (current_time - dl->list[i]->timestamp > FRESHNESS_THRESHOLD) {
            free(dl->list[i]);
            for (int j = i; j < dl->count - 1; j++) {
                dl->list[j] = dl->list[j + 1];
            }
            dl->count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&dl->mutex);
}

void update_packet_timestamp(DynamicList *dl, int ue_id, time_t new_time) {
    pthread_mutex_lock(&dl->mutex);
    for (int i = 0; i < dl->count; i++) {
        if (dl->list[i]->ue_id == ue_id) {
            dl->list[i]->timestamp = new_time;
            break;
        }
    }
    pthread_mutex_unlock(&dl->mutex);
}

void free_list(DynamicList *dl) {
    for (int i = 0; i < dl->count; i++) {
        free(dl->list[i]);
    }
    pthread_mutex_destroy(&dl->mutex);
}

int main(int argc, char *argv[]) {
    // Command line argument parsing and error handling
    if (argc < 2) {
        fprintf(stderr, "Usage: %s input_file\n", argv[0]);
        return 1;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Failed to open file");
        return 1;
    }

    DynamicList dl;
    init_list(&dl);

    // Read and process lines from the file
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse line and create LTEPHYRXINFO_T structure
        LTEPHYRXINFO_T *packet = malloc(sizeof(LTEPHYRXINFO_T));
        sscanf(line, "%d %f", &packet->ue_id, &packet->rssi);
        time(&packet->timestamp);
        packet->decoded_packets = strdup("Decoded Packet");

        add_packet(&dl, packet);
    }

    // Close file and free resources
    fclose(file);
    remove_outdated_packets(&dl, time(NULL));
    free_list(&dl);

    return 0;
}
