using System;

public class RandomValueGenerator
{
    private int _minInt;
    private int _maxInt;
    private float _minFloat;
    private float _maxFloat;
    private Random _random;

    public RandomValueGenerator(float minFloat, float maxFloat)
    {
        ValidateRange(minFloat, maxFloat);
        _minFloat = minFloat;
        _maxFloat = maxFloat;
        _minInt = (int)minFloat;
        _maxInt = (int)maxFloat;
        _random = new Random();
    }

    public void SetSeed(int seed)
    {
        _random = new Random(seed);
    }

    private void ValidateRange(float min, float max)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }
    }

    public float GenerateRandomFloatInclusive()
    {
        return _random.NextSingle() * (_maxFloat - _minFloat) + _minFloat;
    }

    public float GenerateRandomFloatExclusive()
    {
        return _random.NextDouble() * (_maxFloat - _minFloat) + _minFloat;
    }

    public int GenerateRandomIntInclusive()
    {
        return _random.Next(_minInt, _maxInt + 1);
    }

    public int GenerateRandomIntExclusive()
    {
        return _random.Next(_minInt, _maxInt);
    }

    public override string ToString()
    {
        return $"Range: {_minFloat}-{_maxFloat}, Seed: {_random == null ? "None" : _random.ToString()}";
    }
}
