using System;
using System.Threading.Tasks;

public class AsyncRandomValueGenerator
{
    private int _minValue;
    private int _maxValue;
    private Random _random;

    public AsyncRandomValueGenerator(int minValue, int maxValue)
    {
        ValidateRange(minValue, maxValue);
        _minValue = minValue;
        _maxValue = maxValue;
        _random = new Random();
    }

    private void ValidateRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Invalid range: minimum value should not be greater than maximum value.");
        }
    }

    public async Task GenerateRandomFloatInclusive(Action<float, float> callback)
    {
        while (true)
        {
            var randomFloat = _random.NextDouble() * (_maxValue - _minValue + 1) + _minValue;
            await Task.Delay(0); // Simulate asynchronous operation
            callback(randomFloat, randomFloat);
        }
    }

    public async Task GenerateRandomFloatExclusive(Action<float, float> callback)
    {
        while (true)
        {
            var randomFloat = _random.NextDouble() * (_maxValue - _minValue) + _minValue;
            await Task.Delay(0); // Simulate asynchronous operation
            callback(randomFloat, randomFloat);
        }
    }

    public async Task GenerateRandomIntInclusive(Action<int, int> callback)
    {
        while (true)
        {
            var randomInt = _random.Next(_minValue, _maxValue + 1);
            await Task.Delay(0); // Simulate asynchronous operation
            callback(randomInt, randomInt);
        }
    }

    public async Task GenerateRandomIntExclusive(Action<int, int> callback)
    {
        while (true)
        {
            var randomInt = _random.Next(_minValue, _maxValue);
            await Task.Delay(0); // Simulate asynchronous operation
            callback(randomInt, randomInt);
        }
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}, Seed: {_random.GetHashCode()}";
    }

    public void SetSeed(int seed)
    {
        _random = new Random(seed);
    }
}
