#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <random>

class NetworkPacketProcessor {
public:
    NetworkPacketProcessor(int maxThreads)
        : running(true), threads(maxThreads) {
        for (int i = 0; i < maxThreads; ++i) {
            workers.emplace_back([this, i]() {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex);
                        condition.wait(lock, [this] { return !running || !tasks.empty(); });
                        if (!running && tasks.empty()) return;
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    ~NetworkPacketProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            running = false;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void processPacket(const std::vector<uint8_t>& packet) {
        tasks.push([this, packet]() { handlePacket(packet); });
        condition.notify_one();
    }

private:
    void handlePacket(const std::vector<uint8_t>& packet) {
        // Simulate processing delay
        std::this_thread::sleep_for(std::chrono::milliseconds(100));

        // Simulate random failure
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(0, 9);
        if (dis(gen) == 0) {
            std::cerr << "Failed to process packet: simulation error" << std::endl;
            return;
        }

        // Simulate transmission
        transmitPacket(packet);
    }

    void transmitPacket(const std::vector<uint8_t>& packet) {
        static std::atomic<int> retryCount(0);
        int maxRetries = 5;

        while (retryCount < maxRetries) {
            try {
                // Simulate network transmission
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
                std::cout << "Packet transmitted successfully" << std::endl;
                break;
            } catch (...) {
                retryCount++;
                if (retryCount >= maxRetries) {
                    std::cerr << "Failed to transmit packet after " << maxRetries << " retries" << std::endl;
                    return;
                }

                // Exponential backoff with jitter
                int delay = std::pow(2, retryCount - 1) * 100 + std::rand() % 50;
                std::this_thread::sleep_for(std::chrono::milliseconds(delay));
            }
        }
    }

    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool running;
};
