void add_connection(LTE_RRC_INST *rrc_instance) {
    if (current_connections >= MAX_CONNECTIONS) return; // Prevent buffer overflow
    connection_array[current_connections].rrc_instance = rrc_instance;
    connection_array[current_connections].last_updated = time(NULL);
    current_connections++;
}

void remove_inactive_connections(time_t inactivity_threshold) {
    for (int i = 0; i < current_connections;) {
        if (time(NULL) - connection_array[i].last_updated > inactivity_threshold) {
            free(connection_array[i].rrc_instance); // Free the RRC instance memory
            for (int j = i; j < current_connections - 1; j++) {
                connection_array[j] = connection_array[j + 1]; // Shift entries to fill gap
            }
            current_connections--;
        } else {
            i++;
        }
    }
}

void update_connection_timestamp(int instance_id) {
    for (int i = 0; i < current_connections; i++) {
