class NetworkPacketProcessor {
public:
    NetworkPacketProcessor() : running(true), backoffFactor(2), jitterRange(100) {}

    void startProcessing() {
        processingThread = std::thread(&NetworkPacketProcessor::processPackets, this);
    }

    void stopProcessing() {
        running.store(false);
        if (processingThread.joinable()) {
            processingThread.join();
        }
    }

    void addPacket(const std::string& packet) {
        std::lock_guard<std::mutex> lock(packetQueueMutex);
        packetQueue.push(packet);
        packetCondition.notify_one();
    }

private:
    bool running;
    int backoffFactor;
    int jitterRange;
    std::queue<std::string> packetQueue;
    std::mutex packetQueueMutex;
    std::condition_variable packetCondition;
    std::thread processingThread;

    void processPackets() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(packetQueueMutex);
            packetCondition.wait(lock, [this]{ return !packetQueue.empty() || !running.load(); });

            if (!running.load()) {
                break;
            }

            std::string packet = packetQueue.front();
            packetQueue.pop();
            lock.unlock();

            processPacket(packet);
        }
    }

    void processPacket(const std::string& packet) {
        // Simulate packet processing
        std::this_thread::sleep_for(std::chrono::milliseconds(100));

        if (shouldRetry()) {
            retryPacket(packet);
        } else {
            transmitPacket(packet);
        }
    }

    bool shouldRetry() {
