typedef struct {
    int ue_id;
    char session_list[MAX_UE_SESSIONS][256];
    time_t last_update;
} UEContext;

typedef struct {
    int rx_ue_info_tag;
    int rnti;
    char crc_indication_rel8_tag[128];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    UEContext *ue_contexts;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *array) {
    array->count = 0;
    array->capacity = 16; // Initial capacity
    array->ue_contexts = (UEContext *)malloc(array->capacity * sizeof(UEContext));
    pthread_mutex_init(&array->lock, NULL);
}

void free_dynamic_array(DynamicArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        // Free session_list if necessary
    }
    free(array->ue_contexts);
    pthread_mutex_destroy(&array->lock);
}

int add_session(DynamicArray *array, int ue_id, const char *session_id) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        UEContext *new_array = (UEContext *)realloc(array->ue_contexts, new_capacity * sizeof(UEContext));
        if (!new_array) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->ue_contexts = new_array;
        array->capacity = new_capacity;
    }

    for (size_t i = 0; i < array->count; ++i) {
        if (array->ue_contexts[i].ue_id == ue_id) {
            // Add session to existing UE context
            strncpy(array->ue_contexts[i].session_list[array->ue_contexts[i].count], session_id, sizeof(array->ue_contexts[i].session_list[array->ue_contexts[i].count]) - 1);
            array->ue_contexts[i].last_update = time(NULL);
            pthread_mutex_unlock(&array->lock);
            return 0; // Success
        }
    }

    // Create new UE context
    array->ue_contexts[array->count].ue_id = ue_id;
    strncpy(array->ue_contexts[array->count].session_list[0], session_id, sizeof(array->ue_contexts[array->count].session_list[0]) - 1);
    array->ue_contexts[array->count].last_update = time(NULL);
    array->count++;
    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

int remove_inactive_sessions(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    size_t new_count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (difftime(time(NULL), array->ue_contexts[i].last_update) > INACTIVITY_THRESHOLD) {
            // Remove inactive session
        } else {
            array->ue_contexts[new_count++] = array->ue_contexts[i];
        }
    }
    array->count = new_count;
    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

int generate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->rx_ue_info_tag = rand() % 1000;
    pdu->rnti = rand() % 65535;
    snprintf(pdu->crc_indication_rel8_tag, sizeof(pdu->crc_indication_rel8_tag), "CRCFLAG_%d", rand() % 2);
    return 0; // Success
}

void log_event(const char *message) {
    printf("LOG: %s\n", message);
}

int parse_command_line(int argc, char *argv[], DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T **pdu_list, size_t *pdu_count) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [input_file]\n", argv[0]);
        return -1; // Invalid usage
    }

    FILE *input_file = fopen(argv[1], "r");
    if (!input_file) {
