    fclose(input_file);
    *pdu_count = 10; // Example count
    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(*pdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdu_list) {
        perror("Failed to allocate memory for CRC indications");
        return -1; // Memory allocation failed
    }

    for (size_t i = 0; i < *pdu_count; ++i) {
        generate_crc_indication_pdu(&(*pdu_list)[i]);
    }

    return 0; // Success
}

int main(int argc, char *argv[]) {
    DynamicArray ue_array;
    NFAPI_CRC_INDICATION_PDU_T *crc_pdu_list = NULL;
    size_t pdu_count = 0;

