RandomValueGenerator* RandomValueGenerator_new(int size, long min_offset, long max_offset, int min_key, int max_key) {
    RandomValueGenerator *generator = (RandomValueGenerator*)malloc(sizeof(RandomValueGenerator));
    generator->values = (RandomValue*)malloc(size * sizeof(RandomValue));
    pthread_mutex_init(&generator->mutex, NULL);
    // Initialize the random value generator with the provided range
    for (int i = 0; i < size; i++) {
        generator->values[i].offset = min_offset + rand() % (max_offset - min_offset + 1);
        generator->values[i].key = min_key + rand() % (max_key - min_key + 1);
    }
    return generator;
}

void RandomValueGenerator_free(RandomValueGenerator *generator) {
    pthread_mutex_destroy(&generator->mutex);
    free(generator->values);
    free(generator);
}

int RandomValueGenerator_get_value(RandomValueGenerator *generator, int key) {
    pthread_mutex_lock(&generator->mutex);
    for (int i = 0; i < generator->size; i++) {
        if (generator->values[i].key == key) {
            pthread_mutex_unlock(&generator->mutex);
            return generator->values[i].offset;
        }
    }
    pthread_mutex_unlock(&generator->mutex);
