#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_PACKETS 5000

typedef struct {
    int frameNumber;
    TX_MODE txMode;
    float channelFrequency;
    uint8_t packetData[256];
    uint16_t checksum;
} PHY_LAYER_PACKETS;

typedef struct {
    PHY_LAYER_PACKETS *packets;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->packets = (PHY_LAYER_PACKETS*)calloc(MAX_PACKETS, sizeof(PHY_LAYER_PACKETS));
    array->size = 0;
    array->capacity = MAX_PACKETS;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void freeDynamicArray(DynamicArray *array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->packets);
    free(array);
}

bool addPacket(DynamicArray *array, int frameNumber, TX_MODE txMode, float channelFrequency, uint8_t packetData[], size_t dataLength) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        pthread_mutex_unlock(&array->mutex);
        return false;
    }
    array->packets[array->size].frameNumber = frameNumber;
    array->packets[array->size].txMode = txMode;
    array->packets[array->size].channelFrequency = channelFrequency;
    memcpy(array->packets[array->size].packetData, packetData, dataLength);
    array->packets[array->size].checksum = calculateChecksum(&array->packets[array->size]);
    array->size++;
    pthread_mutex_unlock(&array->mutex);
    return true;
}

bool updatePacket(DynamicArray *array, int frameNumber, TX_MODE txMode, float channelFrequency, uint8_t packetData[], size_t dataLength) {
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->size; i++) {
        if (array->packets[i].frameNumber == frameNumber) {
            array->packets[i].txMode = txMode;
            array->packets[i].channelFrequency = channelFrequency;
            memcpy(array->packets[i].packetData, packetData, dataLength);
            array->packets[i].checksum = calculateChecksum(&array->packets[i]);
            pthread_mutex_unlock(&array->mutex);
            return true;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return false;
}

bool getPacket(DynamicArray *array, int frameNumber, PHY_LAYER_PACKETS *packet) {
