['```csharp
using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;

public class DynamicValueGenerator<T> where T : struct
{
    private readonly ConcurrentDictionary<string, (T Min, T Max, bool IsInclusive)> _ranges = new();
    private readonly Random _random = new();
    private readonly ILogger _logger;

    public DynamicValueGenerator(ILogger logger)
    {
        _logger = logger;
    }

    public void AddRange(string name, T min, T max, bool isInclusive)
    {
        _ranges[name] = (min, max, isInclusive);
    }

    public T GenerateRandomValue(string rangeName)
    {
        if (!_ranges.TryGetValue(rangeName, out var range))
            throw new ArgumentException("Invalid range name.");

        return GenerateRandomValueInRange(range.Min, range.Max, range.IsInclusive);
    }

    private T GenerateRandomValueInRange(T min, T max, bool isInclusive)
    {
        while (true)
        {
            if (typeof(T) == typeof(int))
            {
                var intValue = _random.Next((int)Convert.ChangeType(min, typeof(int)), (int)Convert.ChangeType(max, typeof(int)) + (isInclusive ? 1 : 0));
                return (T)Convert.ChangeType(intValue, typeof(T));
            }
            else if (typeof(T) == typeof(float))
            {
                var floatValue = _random.NextDouble() * ((float)Convert.ChangeType(max, typeof(float)) - (float)Convert.ChangeType(min, typeof(float))) + (float)Convert.ChangeType(min, typeof(float));
                return (T)Convert.ChangeType(floatValue, typeof(T));
            }
            else
            {
                throw new NotSupportedException("Unsupported type.");
            }
        }
    }

    public void UpdateRange(string name, T min, T max, bool isInclusive)
    {
        _ranges[name] = (min, max, isInclusive);
    }

    public void LogValue(string rangeName, T value)
    {
        _logger.Log($"Generated value for {rangeName}: {value}");
    }
}

public interface ILogger
{
    void Log(string message);
}
```

