    char sql[512];

    // Start a transaction
    if (sqlite3_exec(db, "BEGIN TRANSACTION", 0, 0, 0) != SQLITE_OK) {
        fprintf(stderr, "Failed to start transaction: %s\n", sqlite3_errmsg(db));
        return NULL;
    }

    // Prepare the SQL statement
    snprintf(sql, sizeof(sql), 
             "INSERT INTO PDU_SESSION_REQUESTS (PDU_SESSION_ID, SNSSAI, REQUESTED_QOS_FLOWS) VALUES (?, ?, ?)");
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, 0) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare SQL statement: %s\n", sqlite3_errmsg(db));
        return NULL;
    }

    // Execute the batch insert
    for (int i = 0; i < count; ++i) {
        PduSessionRequest* request = &requests[i];

        // Validate SNSSAI format (example validation)
        if (strlen(request->snssai) != 10 || !isdigit(request->snssai[0])) {
            fprintf(stderr, "Invalid SNSSAI format for session ID %d\n", request->pdu_session_id);
            continue;
        }

        // Bind parameters
        sqlite3_bind_int(stmt, 1, request->pdu_session_id);
        sqlite3_bind_text(stmt, 2, request->snssai, strlen(request->snssai), SQLITE_STATIC);
        sqlite3_bind_text(stmt, 3, request->requested_qos_flows, strlen(request->requested_qos_flows), SQLITE_STATIC);

        // Execute the insert
        if (sqlite3_step(stmt) != SQLITE_DONE) {
            fprintf(stderr, "Failed to insert session ID %d: %s\n", request->pdu_session_id, sqlite3_errmsg(db));
        } else {
            sqlite3_reset(stmt); // Reset for next iteration
        }
    }

    // Finalize the statement and commit the transaction
    if (sqlite3_finalize(stmt) != SQLITE_OK) {
        fprintf(stderr, "Failed to finalize SQL statement: %s\n", sqlite3_errmsg(db));
        return NULL;
    }
    if (sqlite3_exec(db, "COMMIT", 0, 0, 0) != SQLITE_OK) {
        fprintf(stderr, "Failed to commit transaction: %s\n", sqlite3_errmsg(db));
        return NULL;
    }

