using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private Random random = new Random();
    private readonly object lockObject = new object();
    private Dictionary<string, (float minInclusive, float maxExclusive)> floatRanges;
    private Dictionary<string, (int minInclusive, int maxExclusive)> intRanges;
    private IExternalLoggingService loggingService;

    public DynamicValueGenerator(IExternalLoggingService loggingService)
    {
        this.loggingService = loggingService;
        floatRanges = new Dictionary<string, (float minInclusive, float maxExclusive)>();
        intRanges = new Dictionary<string, (int minInclusive, int maxExclusive)>();
    }

    public void SetFloatRange(string key, float minInclusive, float maxExclusive)
    {
        lock (lockObject)
        {
            if (minInclusive > maxExclusive)
                throw new ArgumentException("Min value must be less than or equal to max value.");

            floatRanges[key] = (minInclusive, maxExclusive);
        }
    }

    public void SetIntRange(string key, int minInclusive, int maxExclusive)
    {
        lock (lockObject)
        {
            if (minInclusive > maxExclusive)
                throw new ArgumentException("Min value must be less than or equal to max value.");

            intRanges[key] = (minInclusive, maxExclusive);
        }
    }

    public async Task<float> GenerateRandomFloatAsync(string key)
    {
        lock (lockObject)
        {
            if (!floatRanges.ContainsKey(key))
                throw new ArgumentException("Range not set for the provided key.");
        }

        return await Task.Run(() =>
        {
            var range = floatRanges[key];
            float randomValue = random.NextSingle() * (range.maxExclusive - range.minInclusive) + range.minInclusive;
            LogValue(randomValue, "float");
            return randomValue;
        });
    }

    public async Task<int> GenerateRandomIntAsync(string key)
    {
        lock (lockObject)
        {
            if (!intRanges.ContainsKey(key))
                throw new ArgumentException("Range not set for the provided key.");
        }

        return await Task.Run(() =>
        {
            var range = intRanges[key];
            int randomValue = random.Next(range.minInclusive, range.maxExclusive);
            LogValue(randomValue, "int");
            return randomValue;
        });
    }

    private void LogValue(object value, string type)
    {
        try
        {
            loggingService.Log(value.ToString(), type);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to log {type} value: {ex.Message}");
        }
    }
}

public interface IExternalLoggingService
{
    Task Log(string message, string valueType);
}
```

