    if (argc < 2) {
        print_usage(prog_name);
        return EXIT_FAILURE;
    }

    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "--help")) {
            print_usage(prog_name);
            return EXIT_SUCCESS;
        } else if (!strcmp(argv[i], "-c")) {
            count_chars = 1;
        } else if (!strncmp(argv[i], "-o", 2)) {
            output_file = argv[++i];
        } else if (input_file == NULL) {
            input_file = argv[i];
        }
    }

    FILE *in_file = fopen(input_file, "r");
    if (in_file == NULL) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    FILE *out_file = fopen(output_file, "w");
    if (out_file == NULL) {
        perror("Failed to open output file");
        fclose(in_file);
        return EXIT_FAILURE;
    }

    char buffer[1024];
    size_t line_number = 0;
    ssize_t bytes_read;

    while ((bytes_read = getline(&buffer, &sizeof(buffer), in_file)) != -1) {
        ++line_number;
        if (count_chars) {
            fprintf(out_file, "%zu\t%s", strlen(buffer), buffer);
