#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Connection {
    int conn_id;
    time_t last_updated;
} Connection;

typedef struct NetworkElement {
    int ne_id;
    Connection** connection_list;
    size_t connection_count;
    size_t connection_capacity;
    pthread_mutex_t lock;
} NetworkElement;

NetworkElement* create_network_element(int ne_id) {
    NetworkElement *element = (NetworkElement*)malloc(sizeof(NetworkElement));
    if (!element) return NULL;

    element->ne_id = ne_id;
    element->connection_list = NULL;
    element->connection_count = 0;
    element->connection_capacity = 0;
    pthread_mutex_init(&element->lock, NULL);

    return element;
}

void destroy_network_element(NetworkElement *element) {
    if (!element) return;

    for (size_t i = 0; i < element->connection_count; ++i) {
        free(element->connection_list[i]);
    }
    free(element->connection_list);
    pthread_mutex_destroy(&element->lock);
    free(element);
}

void add_connection(NetworkElement *element, Connection *new_conn) {
    pthread_mutex_lock(&element->lock);

    if (element->connection_count >= element->connection_capacity) {
        size_t new_capacity = element->connection_capacity > 0 ? element->connection_capacity * 2 : 1;
        Connection** new_list = realloc(element->connection_list, sizeof(Connection*) * new_capacity);
        if (!new_list) {
            pthread_mutex_unlock(&element->lock);
            return; // Handle memory allocation failure
        }
        element->connection_list = new_list;
        element->connection_capacity = new_capacity;
    }

    element->connection_list[element->connection_count] = new_conn;
    element->connection_count++;

    pthread_mutex_unlock(&element->lock);
}

void remove_stale_connections(NetworkElement *element, time_t latency_threshold) {
    pthread_mutex_lock(&element->lock);

    for (size_t i = 0; i < element->connection_count; ) {
        if (time(NULL) - element->connection_list[i]->last_updated > latency_threshold) {
            free(element->connection_list[i]);
            memmove(&element->connection_list[i], &element->connection_list[i + 1], sizeof(Connection*) * (--element->connection_count - i));
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&element->lock);
}

void update_connection_timestamp(NetworkElement *element, int conn_id) {
    pthread_mutex_lock(&element->lock);

    for (size_t i = 0; i < element->connection_count; ++i) {
        if (element->connection_list[i]->conn_id == conn_id) {
            element->connection_list[i]->last_updated = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&element->lock);
}
