#include <pthread.h>

typedef struct Connection {
    int conn_id;
    time_t last_updated;
} Connection;

typedef struct NetworkElement {
    int ne_id;
    Connection **connection_list;
    size_t connection_count;
    pthread_mutex_t lock;
} NetworkElement;

NetworkElement *create_network_element(int ne_id) {
    NetworkElement *element = malloc(sizeof(NetworkElement));
    element->ne_id = ne_id;
    element->connection_list = NULL;
    element->connection_count = 0;
    pthread_mutex_init(&element->lock, NULL);
    return element;
}

void add_connection(NetworkElement *element, Connection *new_conn) {
    pthread_mutex_lock(&element->lock);
    element->connection_list = realloc(element->connection_list, sizeof(Connection*) * (element->connection_count + 1));
    element->connection_list[element->connection_count] = new_conn;
    element->connection_count++;
    pthread_mutex_unlock(&element->lock);
}

void remove_stale_connections(NetworkElement *element, time_t now, time_t latency_threshold) {
    pthread_mutex_lock(&element->lock);
    size_t i = 0;
    while (i < element->connection_count) {
        if (now - element->connection_list[i]->last_updated > latency_threshold) {
            free(element->connection_list[i]);
            for (size_t j = i; j < element->connection_count - 1; j++) {
                element->connection_list[j] = element->connection_list[j + 1];
            }
            element->connection_count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&element->lock);
}

void update_connection_timestamp(NetworkElement *element, int conn_id, time_t now) {
    pthread_mutex_lock(&element->lock);
    for (size_t i = 0; i < element->connection_count; i++) {
        if (element->connection_list[i]->conn_id == conn_id) {
            element->connection_list[i]->last_updated = now;
            break;
        }
    }
    pthread_mutex_unlock(&element->lock);
}

void destroy_network_element(NetworkElement *element) {
    pthread_mutex_lock(&element->lock);
    for (size_t i = 0; i < element->connection_count; i++) {
        free(element->connection_list[i]);
    }
    free(element->connection_list);
    pthread_mutex_destroy(&element->lock);
    free(element);
}
