    if (cs_flag) {
        printf("Number of lines: %zu\n", line_count);
    }

    if (output_file) {
        // Handle output file redirection
    }

    pthread_t thread;
    NetworkFrameHeader** headers = malloc((line_count + 1) * sizeof(NetworkFrameHeader*));
    if (!headers) {
        perror("Memory allocation failed");
        return 1;
    }
    headers[0] = malloc(sizeof(NetworkFrameHeader));
    headers[0]->payloadSize = line_count;

    pthread_create(&thread, NULL, process_frame_headers, (void*)headers);

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    // Free allocated memory
    for (size_t i = 1; i <= line_count; ++i) {
        free(headers[i]);
    }
    free(headers[0]);
    free(headers);

    return 0;
}
